window.__D("text/zohar-hebrew-translation/c001",{"p":[[9522011049,"<p>פָּתַח עוֹד רַבִּי שִׁמְעוֹן וְאָמַר, (דברים לב) רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא וְאֵין אֱלֹהִים עִמָּדִי וְגוֹ'. אָמַר, חֲבֵרִים שִׁמְעוּ דְבָרִים עַתִּיקִים שֶׁרָצִיתִי לְגַלּוֹת אַחַר שֶׁנִּתְּנָה (לי) רְשׁוּת עֶלְיוֹנָה לוֹמַר. מִי זֶה שֶׁאָמַר רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא? אֶלָּא זֶהוּ עִלַּת עַל כָּל הָעֶלְיוֹנִים, אוֹתוֹ שֶׁנִּקְרָא עִלַּת הָעִלּוֹת, עִלַּת מֵהָעִלּוֹת הָאֵלֶּה, שֶׁלֹּא יַעֲשֶׂה אֶחָד מֵהָעִלּוֹת הַלָּלוּ שׁוּם מַעֲשֶׂה עַד שֶׁיִּקַּח רְשׁוּת מֵאוֹתוֹ שֶׁעָלָיו, כְּמוֹ שֵׁבֵּאַרְנוּ לְמַעְלָה בְּנַעֲשֶׂה אָדָם.</p>\n<p>נַעָֹשֶׂה וַדַּאי. עַל שְׁנַיִם נֶאֱמַר. שֶׁאָמַר זֶה לְאוֹתוֹ שֶׁלְּמַעְלָה מִמֶּנּוּ נַעֲשֶׂה. וְלֹא עוֹשֶׂה דָבָר אֶלָּא בִּרְשׁוּת וַאֲמִירָה מֵאוֹתוֹ שֶׁלְּמַעְלָה מִמֶּנּוּ. וְאוֹתוֹ שֶׁלְּמַעְלָה מִמֶּנּוּ לֹא עוֹשֶׂה דָבָר עַד שֶׁלּוֹקֵחַ עֵצָה מֵחֲבֵרוֹ. אֲבָל אוֹתוֹ שֶׁנִּקְרָא עִלַּת עַל כָּל עִלּוֹת, שֶׁאֵין לְמַעְלָה מִמֶּנּוּ וְלֹא לְמַטָּה שָׁוֶה לוֹ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה מ) וְאֶל מִי תְדַמְּיוּנִי וְאֶשְׁוֶה יֹאמַר קָדוֹשׁ. אָמַר, רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא וְאֵין אֱלֹהִים עִמָּדִי, שֶׁלּוֹקֵחַ מִמֶּנּוּ עֵצָה, כְּמוֹ שֶׁאוֹתוֹ שֵׁאָמַר וַיּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם.</p>\n<p>קָֹמוּ כָּל הַחֲבֵרִים וְאָמְרוּ, רַבִּי, תֵּן לָנוּ רְשׁוּת לְדַבֵּר בְּמָקוֹם זֶה. אָמְרוּ, וַהֲרֵי לֹא בֵאַרְתָּ לְמַעְלָה שֶׁעִלַּת הָעִלּוֹת אָמַר לְכת\"ר נַעֲשֶׂה אָדָם? אָמַר לָהֶם, הֱיוּ שׁוֹמְעִים אָזְנֵיכֶם מַה שֶּׁפִּיכֶם מְדַבֵּר! וַהֲרֵי לֹא אָמַרְתִּי לָכֶם עַכְשָׁו שֶׁיֵּשׁ מִי שֶׁנִּקְרָא עִלַּת הָעִלּוֹת, וְזֶה אֵינוֹ אוֹתוֹ שֶׁנִּקְרָא עִלַּת עַל כָּל עִלּוֹת, שֶׁלְּעִלַּת עַל כָּל עִלּוֹת אֵין לוֹ שֵׁנִי שֶׁלּוֹקֵחַ מִמֶּנּוּ עֵצָה, שֶׁהוּא יָחִיד לִפְנֵי הַכֹּל, וְאֵין לוֹ שֻׁתָּף.</p>\n<p>וְלָכֵן אָמַר רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא וְאֵין אֱלֹהִים עִמָּדִי, שֶׁלּוֹקֵחַ מִמֶּנּוּ עֵצָה, שֶׁאֵין לוֹ שֵׁנִי וְלֹא שֻׁתָּף וְלֹא חֶשְׁבּוֹן. שֶׁיֵּשׁ אֶחָד בְּשִׁתּוּף כְּמוֹ זָכָר וּנְקֵבָה, וְנֶאֱמַר בָּהֶם (שם נא) כִּי אֶחָד קְרָאתִיו, אֲבָל הוּא אֶחָד בְּלִי חֶשְׁבּוֹן וְלֹא שִׁתּוּף, וְלָכֵן אָמַר וְאֵין אֱלֹהִים עִמָּדִי. קָמוּ כֻלָּם וְהִשְׁתַּטְּחוּ לְפָנָיו וְאָמְרוּ, אַשְׁרֵי הָאִישׁ שֶׁרִבּוֹנוֹ מַסְכִּים עִמּוֹ לְגַלּוֹת סוֹדוֹת טְמִירִים שֶׁלֹּא הָיוּ מִתְגַּלִּים לְמַלְאָכִים קְדוֹשִׁים.</p>\n<p>אָמַר לָהֶם, חֲבֵרִים, יֵשׁ לָנוּ לְהַשְׁלִים הַפָּסוּק, שֶׁכַּמָּה סוֹדוֹת טְמִירִים יֵשׁ בַּפָּסוּק הַזֶּה (דברים לב) אֲנִי אָמִית וַאֲחַיֶּה וְגוֹ'. אֲנִי אָמִית וַאֲחַיֶּה - בַּסְּפִירוֹת. אֲחַיֶּה - מִצַּד שֶׁל הַיָּמִין חַיִּים, וּמִצַּד הַשְּׂמֹאל מָוֶת. וְאִם לֹא מַסְכִּימִים שְׁנֵיהֶם עִם עַמּוּד הָאֶמְצָעִי, לֹא מִתְקַיֵּם הַדִּין, שֶׁהֵם בְּמוֹשָׁב שְׁלֹשָׁה כְּאֶחָד.</p>\n<p>וְלִפְעָמִים מַסְכִּימִים שְׁלֹשָׁה לַעֲשׂוֹת דִּין, וְיָבֹא יָ\"ד (ימין) שֶׁהִיא פְשׁוּטָה לְקַבֵּל שָׁבִים, שֶׁהוּא יהו\"ה יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וְזוֹ שְׁכִינָה נִקְרֵאת יַד יָמִין מִצַּד הַחֶסֶ\"ד. יַד שְׂמֹאל מִצַּד הַגְּבוּרָה. יַד יהו\"ה מִצַּד עַמּוּד הָאֶמְצָעִי. כְּשֶׁבֶּן אָדָם שָׁב בִּתְשׁוּבָה, הַיָּד הַזּוֹ מַצִּילָה אוֹתוֹ מֵהַדִּין. אֲבָל כְּשֶׁדָּן עִלַּת עַל כָּל הָעִלּוֹת, נֶאֱמַר בּוֹ וְאֵין מִיָּדִי מַצִּיל.</p>\n<p>וְעוֹד, שָׁלֹשׁ פְּעָמִים נֶאֱמַר בְּפָסוּק זֶה אֲנִי אֲנִי אֲנִי, שֶׁיֵּשׁ בָּהֶם א' א' א' י' י' י', שֶׁנִּרְמְזוּ בְּיוֹ\"ד הֵ\"י וָא\"ו הֵ\"י יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וְיֵשׁ בָּהֶם שָׁלֹשׁ וָוִים, ו' ו' ו' - וַ'אֲחַיֶּה וַ'אֲנִי וְ'אֵין - שֶׁנִּרְמְזוּ בַּשֵּׁמוֹת הָאֵלֶּה.</p>\n<p>וְעִם כָּל זֶה שֶׁהֲרֵי בֵּאֲרוּ אֶת הַפָּסוּק הַזֶּה הַחֲבֵרִים אֵצֶל אֱלֹהִים אֲחֵרִים, כְּמוֹ שֶׁנֶּאֱמַר רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ שֶׁנֶּאֱמַר בָּהֶם אֲנִי וָה\"וּ. וְאֵין אֱלֹהִים עִמָּדִי - זֶה סמא\"ל וְנָחָ\"שׁ. אֲנִי אָמִית וַאֲחַיֶּה - אֲנִי אָמִית בִּשְׁכִינָתִי לְמִי שֶׁהוּא רָשָׁע, וַאֲנִי אֲחַיֶּה בָּהּ אֶת מִי שֶׁהוּא צַדִּיק. וְאֵין מִיָּדִי מַצִּיל - זֶה יַ\"ד יהו\"ה שֶׁהוּא יהו\"ה יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, וְהוּא כוז\"ו במוכס\"ז כוז\"ו, וְהַכֹּל אֱמֶת. אֲבָל מַה שֶּׁנִּתְבָּאֵר לְמַעְלָה עִלַּת הָעֶלְיוֹן שֶׁהוּא עִלַּת עַל כָּל הָעִלּוֹת, וְהַסּוֹד הַזֶּה לֹא נִמְסָר לְכָל חָכָם וְנָבִיא (נ\"א אבל מה שנאמר למעלה על עליון שהוא על העלות, הסוד הזה לא נמסר אלא לכל חכם ונביא).</p>\n<p>בֹּא רְאֵה כַּמָּה עִלּוֹת הֵם נִסְתָּרִים שֶׁהֵם מִתְלַבְּשִׁים וְהֵם מֻרְכָּבִים בַּסְּפִירוֹת, וְהַסְּפִירוֹת מֶרְכָּבָה לָהֶם, שֶׁהֵם טְמִירִים מִמַּחֲשֶׁבֶת בְּנֵי אָדָם, וַעֲלֵיהֶם נֶאֱמַר (קהלת ה) כִּי גָבֹהַּ מֵעַל גָּבֹהַּ שֹׁמֵר וְגוֹ'. אוֹרוֹת מְצֻחְצָחִים אֵלֶּה עַל אֵלֶּה. וְאֵלֶּה שֶׁמְּקַבְּלִים הֵם חֲשׁוּכִים מֵאֲחֵרִים שֶׁעֲלֵיהֶם שֶׁמְּקַבְּלִים מֵהֶם. וּלְעִלַּת (על כל) הָעִלּוֹת אֵין אוֹר עוֹמֵד לְפָנָיו, שֶׁכָּל הָאוֹרוֹת חֲשׁוּכִים לְפָנָיו.</p>"],[9522011050,"<p>דָּבָר אַחֵר נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ - הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים עַל מַלְאֲכֵי הַשָּׁרֵת שֶׁהֵם אוֹמְרִים אֶת הַפָּסוּק הַזֶּה. אָמַר לָהֶם, אַחַר שֶׁהָיוּ יוֹדְעִים מַה שֶּׁהָיָה וּמַה שֶּׁעָתִיד לִהְיוֹת וְהֵם הָיוּ יוֹדְעִים שֶׁעָתִיד לַחֲטֹא, לָמָּה רָצוּ לַעֲשׂוֹת אוֹתוֹ?</p>\n<p>וְלֹא עוֹד, אֶלָּא שֶׁעֲזָא וַעֲזָאֵל הָיוּ מְקַטְרְגִים עָלָיו בִּזְמַן שֶׁאָמְרָה שְׁכִינָה לַקָּדוֹשׁ-בָּרוּךְ- הוּא נַעֲשֶׂה אָדָם. אָמְרוּ, מָה אָדָם וַתֵּדָעֵהוּ? מָה אַתָּה רוֹצֶה לִבְרֹא אָדָם, וַתֵּדָעֵהוּ שֶׁעָתִיד לַחֲטֹא לְפָנֶיךְ בְּאִשְׁתּוֹ שֶׁהִיא חֹשֶׁךְ? שֶׁאוֹר הוּא זָכָר, וְחֹשֶׁךְ נְקֵבָה, שְׂמֹאל חֹשֶׁךְ שֶׁל בְּרִיאָה. בְּאוֹתוֹ זְמַן אָמְרָה לָהֶם הַשְּׁכִינָה: בָּזֶה שֶׁאַתֶּם מְקַטְרְגִים, אַתֶּם עֲתִידִים לִנְפֹּל, כְּמוֹ שֶׁכָּתוּב וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם כִּי טֹבֹת הֵנָּה וְגוֹ'. (חשקו בהם) וְטָעוּ בָהֶם, וְהִפִּילָה אוֹתָם הַשְּׁכִינָה מִקְּדֻשָּׁתָם.</p>\n<p>אָמְרוּ הַחֲבֵרִים, רַבִּי רַבִּי, בֵּין כָּךְ (נ\"א: אם כך), עֲזָא וַעֲזָאֵל לֹא הָיוּ מְשַׁקְּרִים בְּדִבְרֵיהֶם, שֶׁוַּדַּאי בַּנְּקֵבָה עָתִיד אָדָם לַחֲטֹא. אָמַר לָהֶם, כָּךְ אָמְרָה הַשְּׁכִינָה: אַתֶּם הִזְדַּמַּנְתֶּם לְקַטְרֵג לְפָנַי יוֹתֵר מִצְּבָא הַמָּרוֹם. אִם אַתֶּם הֱיִיתֶם יָפִים מֵאָדָם בְּמַעֲשֵׂיכֶם, נָאֶה לָכֶם לְקַטְרֵג עָלָיו, אֲבָל הוּא עָתִיד לַחֲטֹא בְּאִשָּׁה אַחַת, וְאַתֶּם בְּנָשִׁים רַבּוֹת. הַחִבָּה שֶׁלָּכֶם יוֹתֵר מִבְּנֵי אָדָם, כְּמוֹ שֶׁכָּתוּב וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם. אֶת בַּת הָאָדָם לֹא נֶאֱמַר, אֶלָּא אֶת בְּנוֹת הָאָדָם. וְלֹא עוֹד, אֶלָּא אִם אָדָם חוֹטֵא, הֲרֵי מַקְדִּים לוֹ תְּשׁוּבָה לַחֲזֹּר לְרִבּוֹנוֹ לְתַקֵּן בְּמַה שֶּׁחָטָא.</p>\n<p>אָמְרוּ לוֹ הַחֲבֵרִים, (רבי רבי), אִם כָּךְ, לָמָּה כָּל זֶה? אָמַר רַבִּי שִׁמְעוֹן לַחֲבֵרִים, אִם לֹא הָיָה כָּךְ שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא יֵצֶר טוֹב וָרַע, שֶׁהֵם אוֹר וְחֹשֶׁךְ, לֹא הָיְתָה זְכוּת וְחוֹבָה לְאָדָם שֶׁל בְּרִיאָה, אֶלָּא (בגלל) שֶׁנִּבְרָא מִשְּׁנֵיהֶם, וְלָכֵן (דברים ל) רְאֵה נָתַתִּי לְפָנֶיךְ הַיּוֹם אֶת הַחַיִּים וְגוֹ'. אָמְרוּ לוֹ, כָּל זֶה לָמָּה? וְלֹא הָיָה יָפֶה שֶׁלֹּא נִבְרָא וְשֶׁלֹּא לַחֲטֹא וְלִגְרֹם כָּל מַה שֶּׁגָּרַם לְמַעְלָה, וְלֹא הָיָה לוֹ לֹא עֹנֶשׁ וְלֹא שָׂכָר?!</p>\n<p>אָמַר לָהֶם, מִן הַדִּין הָיָה לוֹ לְבָרְאוֹ כָּךְ, בִּגְלַל שֶׁהַתּוֹרָה בִּגְלָלוֹ נִבְרְאָה, שֶׁכָּתוּב בָּהּ עֹנֶשׁ לָרְשָׁעִים וְשָׂכָר לַצַּדִּיקִים, וְלֹא הָיָה שָׂכָר לַצַּדִּיקִים וְעֹנֶשׁ לָרְשָׁעִים אֶלָּא בִּגְלַל אָדָם שֶׁל בְּרִיאָה, (ישעיה מה) לֹא תֹהוּ בְרָאָהּ לָשֶׁבֶת יְצָרָהּ. אָמְרוּ, וַדַּאי כָּעֵת שָׁמַעְנוּ מַה שֶּׁלֹּא שָׁמַעְנוּ עַד עַכְשָׁו, שֶׁוַּדַּאי לֹא בָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא דָּבָר שֶׁלֹּא צָרִיךְ,</p>\n<p>וְלֹא עוֹד, אֶלָּא הַתּוֹרָה שֶׁל בְּרִיאָה הִיא לְבוּשׁ הַשְּׁכִינָה, וְאִם אָדָם לֹא הָיָה עָתִיד לְהִבָּרֹאת (לחטא), הָיְתָה הַשְּׁכִינָה בְּלִי כִסּוּי כְּמוֹ עָנִי. וְלָכֵן כָּל מִי שֶׁחָטָא, כְּאִלּוּ הִפְשִׁיט לַשְּׁכִינָה אֶת מַלְבּוּשֶׁיהָ, וְזֶהוּ עֹנֶשׁ הָאָדָם.</p>\n<p>וְכָל מִי שֶׁמְּקַיֵּם מִצְווֹת הַתּוֹרָה, כְּאִלּוּ הִלְבִּישׁ לַשְּׁכִינָה אֶת מַלְבּוּשֶׁיהָ. וְלָכֵן פֵּרְשׁוּהָ בְּכִסּוּי הַצִּיצִית (ותפלין) (שמות כב) כִּי הִיא כְסוּתֹה לְבַדָּהּ הִוא שִׂמְלָתוֹ לְעֹרוֹ בַּמֶּה יִשְׁכָּב, בַּגָּלוּת? וַהֲרֵי פֵּרְשׁוּהָ. בּא רְאֵה, חֹשֶׁךְ הוּא שָׁחֹר שֶׁל הַתּוֹרָה, אוֹר הַלֹּבֶן שֶׁל הַתּוֹרָה.</p>"],[9522011051,"<p>(ואם תפלה אינה שלמה, כמה מלאכי חבלה רודפים אחריה, כמו שנאמר (איכה א) כל רדפיה השיגוה בין המצרים, ולכן מתפללים (תהלים עח) והוא רחום יְכַפֵּר עָון - זֶה סמא\"ל שֶׁהוּא נָחָשׁ. וְלֹא יַשְׁחִית - זֶה הַמַּשְׁחִית. וְהִרְבָּה לְהָשִׁיב אַפּוֹ - זֶה אַף. וְלֹא יָעִיר כָּל חֲמָתוֹ - זוֹ חֵמָה, כְּדֵי שֶׁלֹּא יִרְדְּפוּ אַחַר הַתְּפִלָּה. וְכַמָּה מַלְאֲכֵי חַבָּלָה תְּלוּיִים מֵהֶם. שִׁבְעָה מְמֻנִּים הֵם, וּתְלוּיִים מֵהֶם שִׁבְעִים, וּבְכָל רָקִיעַ וְרָקִיעַ הֵם מְקַטְרְגִים, וּתְלוּיִים מֵהֶם עֲשֶׂרֶת אֲלָפִים רִבּוֹא.</p>\n<p>וְאִם תְּפִלָּה עוֹלָה שְׁלֵמָה בְּעִטּוּף שֶׁל מִצְוָה וּתְפִלִּין עַל הָרֹאשׁ וְהַזְּרוֹעַ, נֶאֱמַר בָּהֶם (דברים כח) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יהו\"ה נִקְרָא עָלֶיךְ וְיָרְאוּ מִמֶּךָּ. שֵׁם ה' פֵּרְשׁוּהָ שֶׁהִיא תְפִלִּין שֶׁל רֹאשׁ. וּמִי שֶׁרוֹאֶה שֵׁם יהו\"ה עַל הָרֹאשׁ בַּתְּפִלָּה שֶׁהִיא אדנ\"י (יהו\"ה), מִיָּד כֻּלָּם בּוֹרְחִים. זֶהוּ שֶׁכָּתוּב (תהלים צא) יִפּוֹל מִצִּדְּךְ אֶלֶף וְגוֹ'.)</p>\n<p>וְיַעָקֹב, בִּגְלַל שֶׁרָאָה בְּרוּחַ הַקֹּדֶשׁ דּחַק שֶׁל הַגָּלוּת הָאַחֲרוֹנָה בְּסוֹף הַיָּמִים, (אמר (בראשית כח) ויפגע במקום וילן שם כי בא השמש, ובא הלילה של הגלות, ואמר) (שם לב) וַיִּירָא יַעֲקֹב מְאֹד וַיֵּצֶר לוֹ. וְחִלֵּק אֶת הָעָם הַקָּדוֹשׁ בַּגָּלוּת לִשְׁלֹשָׁה צְדָדִים, כְּמוֹ שֶׁנֶּאֱמַר (שם לג) וַיָּשֶׂם אֶת הַשְּׁפָחוֹת וְאֶת יַלְדֵיהֶן רִאשֹׁנָה, בָּרֹאשׁ בְּגָלוּת אֱדוֹם. וְאֶת לֵאָה וִילָדֶיהָ אַחֲרֹנִים וְאֶת רָחֵל וְאֶת יוֹסֵף אַחֲרֹנִים. וּבִגְלַל שֶׁרָאָה אַחַר כָּךְ עֲנִיּוּת וְצַעַר שֶׁלָּהֶם, אָמַר (שם כח) וְשַׁבְתִּי בְשָׁלוֹם אֶל בֵּית אָבִי. וְאָמַר, וְנָתַן לִי לֶחֶם לֶאֱכֹל וּבֶגֶד לִלְבֹּשׁ.</p>\n<p>וְדָוִד, בִּגְלַל הַגָּלוּת אָמַר (שמואל ב יז) רָעֵב וְעָיֵף וְצָמֵא בַּמִּדְבָּר. בִּגְלַל שֶׁרָאָה שְׁכִינָה חֲרֵבָה יְבֵשָׁה, הָיָה נוֹטֵל צַעַר בִּגְלָלָהּ. אַחַר שֶׁרָאָה שֶׁיִּשְׂרָאֵל חוֹזְרִים (בתשובה) בְּחֶדְוָה, תִּקֵּן עֲשָׂרָה מִינֵי נִגּוּנִים, וּבְסוֹף כֻּלָּם אָמַר (תהלים קב) תְּפִלָּה לְעָנִי כִי יַעֲטֹף (נ\"א: תקן עשרה מיני תלים, ובסוף כלם תפלה לדוד הטה ה' אזנך ענני, אחת שכל התפלות שבגללן מתעטפים לפני המלך, ולא היו נכנסות עד שתכנס תפלת העני, אמר תפלה לעני כי יעטף), וְהִיא תְפִלָּה שֶׁעוֹטֶפֶת כָּל הַתְּפִלּוֹת לְפָנֶיהָ עַד שֶׁתִּכָּנֵס תְּפִלָּתוֹ, לָכֵן הִקְדִּים עָנִי לְכֻלָּם.</p>\n<p>מַהִי תְּפִלַּת הֶעָנִי? זוֹ תְפִלַּת עַרְבִית שֶׁהִיא רְשׁוּת בִּפְנֵי עַצְמָהּ בְּלִי בַעְלָהּ, וּמִשּׁוּם שֶׁהִיא בְּלִי בַעְלָהּ, הִיא עֲנִיָּה וִיבֵשָׁה, וְצַדִּיק עָנִי יָבֵשׁ זֶה זֶרַע יַעֲקֹב, שֶׁהוּא בִּרְשׁוּת כָּל אֻמּוֹת הָעוֹלָם, וְדוֹמֶה לִתְפִלַּת עַרְבִית שֶׁהִיא לַיְלָה שֶׁל הַגָּלוּת.</p>\n<p>וּתְפִלַּת שַׁבָּת הִיא צְדָקָה לֶעָנִי, כְּמוֹ שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, שֶׁמֶשׁ בְּשַׁבָּת צְדָקָה לַעֲנִיִּים (שעניים מתנחמים בדרך של שמש של שבת). וְלָכֵן צָרִיךְ אָדָם לִהְיוֹת כְּמוֹ עָנִי לְשַׁעַר הַמֶּלֶךְ בִּתְפִלַּת עֲמִידָה בְּכָל שֵׁשֶׁת יְמֵי הַחֹל בִּשְׁבִיל הַשְּׁכִינָה, וּמִתְעַטֵּף לָהּ בְּעִטּוּף שֶׁל מִצְוָה שֶׁל צִיצִית כְּמוֹ עָנִי, וְיִהְיֶה בִּתְפִלִּין כְּמוֹ אֶבְיוֹן אֵצֶל הַשַּׁעַר שֶׁהוּא אדנ\"י. שֶׁכָּךְ עוֹלֶה לְחֶשְׁבּוֹן הֵיכָ\"ל. וְזֶהוּ אֲדֹנָ\"י שְׂפָתַי תִּפְתָּח.</p>\n<p>וּכְשֶׁפּוֹתֵחַ פִּיו בִּתְפִלַּת עַרְבִית, נוֹחֵת נֶשֶׁר בִּימֵי הַחֹל לְקַבֵּל בִּכְנָפָיו תְּפִלַּת הַלַּיְלָה. וְזֶה נוֹרִיאֵ\"ל נִקְרָא אוֹרִיאֵ\"ל מִצַּד שֶׁל חֶסֶ\"ד, וְנוֹרִיאֵ\"ל מִצַּד שֶׁל גְּבוּרָה, שֶׁהוּא נֵר דּוֹלֵק, שֶׁנֶּאֱמַר בּוֹ (דניאל ז) נְהַר דִּינוּר וְגוֹ'.</p>\n<p>וּבִתְפִלַּת שַׁחֲרִית אַרְיֵה נוֹחֵת לְקַבֵּל תְּפִלָּה בִּזְרוֹעוֹתָיו וּכְנָפָיו, שֶׁאַרְבַּע כְּנָפַיִם (יש) לְכָל חַיָּה, זֶה מִיכָאֵל. וּבִתְפִלַּת מִנְחָה שׁוֹר נוֹחֵת לְקַבֵּל (נ\"א: תפלה) בְּקַרְנָיו וּכְנָפָיו, וְזֶה גַבְרִיאֵל.</p>\n<p>וּבְשַׁבָּת נוֹחֵת הַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁלֹשֶׁת הָאָבוֹת לְקַבֵּל הַבַּת יְחִידָה שֶׁלּוֹ בָּהֶם, וְזֶה סוֹד שֶׁל שַׁבָּת, ש' בַּת יְחִידָה שֶׁלּוֹ. בְּאוֹתוֹ זְמַן הַחַיּוֹת הָעֶלְיוֹנוֹת שֶׁנִּקְרְאוּ בַּשֵּׁם שֶׁל יי', פּוֹתְחִים וְאוֹמְרִים, (תהלים כד) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְהִנָּשְׂאוּ פִּתְחֵי עוֹלָם.</p>\n<p>בְּאוֹתוֹ זְמַן נִפְתָּחִים שִׁבְעָה הֵיכָלוֹת. הֵיכָל הָרִאשׁוֹן - הֵיכַל הָאַהֲבָה. שֵׁנִי - הֵיכַל הַיִּרְאָה. שְׁלִישִׁי - הֵיכַל הָרַחֲמִים. רְבִיעִי - הֵיכַל הַנְּבוּאָה בְּאַסְפַּקְלַרְיָה הַמְּאִירָה. חֲמִישִׁי - הֵיכַל הַנְּבוּאָה בְּאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה. שִׁשִּׁי - הֵיכַל הַצֶּדֶק. שְׁבִיעִי - הֵיכַל הַדִּין.</p>\n<p>וַעָלֵיהֶם נֶאֱמַר בְּרֵאשִׁית - בָּרָא שִׁי\"ת. אֱלֹהִים הֵיכָל שְׁבִיעִי. וְכָךְ הֵם שִׁבְעָה הֵיכָלוֹת לְמַטָּה, וּכְנֶגְדָּם שִׁבְעָה קוֹלוֹת שֶׁל הָבוּ לַה', וּשְׁמוֹנֶה עֶשְׂרֵה אַזְכָּרוֹת שֶׁבָּהֶן מְשׁוֹטֵט הַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁמוֹנָה עָשָׂר עוֹלָמוֹת (תהלים סח) בְּרֶכֶב אֱלֹהִים רִבּתַיִם אַלְפֵי שִׁנְאָן, שֶׁהֵם שְׁמוֹנָה עָשָׂר רִבּוֹא עוֹלָמוֹת, וְכַמָּה שׁוֹמְרֵי שְׁעָרִים יֵשׁ לַהֵיכָלוֹת שֶׁמְּקַבְּלִים תְּפִלּוֹת, וְכָל תְּפִלָּה לֹא תִכָּנֵס אֶלָּא בְּמִדָּה בְּמִשְׁקָל,</p>\n<p>וְאֵין מִי שֶׁעוֹמֵד לִפְנֵי שַׁעַר הַתְּפִלָּה, וְעָלָיו נֶאֱמַר (שם קכז) לֹא יֵבשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָּׁעַר, שֶׁהִיא שַׁעַר הַמֶּלֶךְ. בִּגְלַל שֶׁתְּפִלָּה הִיא מִצְוָה, וְזוֹ שְׁכִינָה, וְהַתּוֹרָה זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא - לֹא צָרִיךְ בֵּינֵיהֶם הַפְסָקָה. וְצָרִיךְ לְהַעֲלוֹת תּוֹרָה וּמִצְוָה בְּאַהֲבָה וְיִרְאָה.</p>\n<p>שֶׁכָּל מִצְווֹת עֲשֵׂה וְלֹא תַעֲשֶׂה כֻּלָּן תְּלוּיוֹת מִשֵּׁם יְהֹוָ\"ה. כְּמוֹ שֶׁבֵּאַרְנוּ סוֹד זֶה שְּׁמִי עִם י\"ה - שס\"ה מִצְווֹת לֹא תַעֲשֶׂה. וְזֶה זִכְרִי עִם ו\"ה - רמ\"ח מִצְווֹת עֲשֵׂה. וַהֲרֵי כָּאן שס\"ה וְרמ\"ח, וְהֵם רמ\"ח תֵּבוֹת שֶׁבִּקְרִיאַת שְׁמַע, וְנִתְּנוּ מֵאַהֲבָה (של אות י') וְיִרְאָה שֶׁל אוֹת ה'. וְלָכֵן תִּקְּנוּ הַבּוֹחֵר בְּעַמּוֹ יִשְׂרָאֵל בְּאַהֲבָה, וְהֵם כְּלוּלִים בְּאַבְרָהָם, שֶׁנֶּאֱמַר בּוֹ זֶרַע אַבְרָהָם אוֹהֲבִי.</p>\n<p>יִשְׂרָאֵל שֶׁעוֹלֶה בְּיוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, וְסוֹד הַדָּבָר - יִשְׂרָאֵל עָלָה בְּמַחֲשָׁבָה לְהִבָּרֹאת. מַחֲשָׁבָה - חָשַׁ\"ב מָ\"ה, וּבוֹ תִּמְצָא אֶת הַשֵּׁם הַקָּדוֹשׁ. וּמִשּׁוּם שֶׁיַּעֲקֹב שֶׁהוּא יִשְׂרָאֵל, נֶאֱמַר וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ, בִּדְמוּת רִבּוֹנוֹ.</p>\n<p>בָּנִים חַיִּים וּמְזוֹנוֹת מִצַּד עַמּוּד הָאֶמְצָעִי, שֶׁהוּא בְּנִ\"י בְּכוֹרִי יִשְׂרָאֵל. וְהוּא עֵץ הַחַיִּי\"ם, וְהוּא עֵץ שֶׁמָּזוֹ\"ן בּוֹ לַכֹּל. וְלָכֵן יִשְׂרָאֵל הֵם הַמָּזוֹן שֶׁלּוֹ תְּפִלָּה שֶׁנֶּחְשֶׁבֶת לְקָרְבָּן.</p>\n<p>וּבַגָּלוּת נֶאֱמַר (בראשית ל) הָבָה לִּי בָנִים וְאִם אַיִן מֵתָה אָנֹכִי. וּשְׁכִינָה הִיא קָרְבָּן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִמֶּנּוּ בְּיָמִין וּשְׂמֹאל וְגוּף. וּכְשֶׁעוֹלָה אֵלָיו, צָרִיךְ לְהַכְלִיל עִמָּהּ כָּל עֶשֶׂר הַסְּפִירוֹת, שֶׁאֵין קְדֻשָּׁה פָּחוֹת מֵעֶשֶׂר, שֶׁהוּא קְדֻשָּׁתוֹ. וְלָכֵן כְּשֶׁבֶּן אָדָם רוֹצֶה לְהַעֲלוֹת תְּפִלָּה בְּכָל תְּנוּעָתוֹ, (אם) נָחָשׁ רוֹצֶה לְקַטְרֵג לַתְּפִלָּה, צָרִיךְ לַעֲשׂוֹת לוֹ מַקְלֵעַ, וְסוֹד הַדָּבָר - זַרְקָא מַקָּף שׁוֹפָר הוֹלֵךְ סֶגוֹלְתָּא.</p>"],[9522011052,"<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, עֶלְיוֹנִים שִׁמְעוּ, תַּחְתּוֹנִים הִתְכַּנְּסוּ, אֵלֶּה מוֹרֵי הַיְשִׁיבָה שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה. אֵלִיָּהוּ, בִּשְׁבוּעָה עָלֶיךְ, קַח רְשׁוּת וְרֵד לְכָאן, שֶׁהֲרֵי קְרָב גָּדוֹל הִזְדַּמֵּן. חֲנוֹךְ הַמְמֻנֶּה, רֵד לְכָאן אַתָּה וְכָל מוֹרֵי הַיְשִׁיבָה שֶׁתַּחַת יָדְךְ, שֶׁלֹּא לִכְבוֹדִי עָשִׂיתִי, אֶלָּא לִכְבוֹד הַשְּׁכִינָה.</p>\n<p>פָּתַח כְּמִקֹּדֶם וְאָמַר, זַרְקָא וַדַּאי. בְּבוֹאֲךְ לְהַעֲלוֹת תְּפִלָּה לְאוֹתוֹ מָקוֹם יָדוּעַ. כְּמוֹ שֶׁאוֹתָהּ אֶבֶן הַקֶּלַע שֶׁנִּזְרְקָה לְמָקוֹם יָדוּעַ, כָּךְ צָרִיךְ לְהַעֲלוֹת מַחֲשַׁבְתּוֹ בַּתְּפִלָּה בְּאוֹתוֹ כֶתֶר אֶבֶן מֻכְלֶלֶת וּמְעֻטֶּרֶת, שֶׁנֶּאֱמַר בָּהּ כָּל הַזּוֹקֵף זוֹקֵף בַּשֵּׁם, שֶׁצָּרִיךְ לְהַעֲלוֹתָהּ לְשָׁם.</p>\n<p>וּבְאוֹתוֹ מָקוֹם שֶׁמַּעֲלֶה אוֹתָהּ לְבַעְלָהּ, אֲפִלּוּ נָחָשׁ כָּרוּךְ עַל עֲקֵבוֹ לֹא יַפְסִיק, אַף עַל גַּב שֶׁנֶּאֱמַר בּוֹ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב. אוֹתָהּ הָאֶבֶן שֶׁהִיא י' שֶׁל יַעֲקֹב, שֶׁנֶּאֱמַר בָּהּ (בראשית מט) מִשָּׁם רֹעֶה אֶבֶן יִשְׂרָאֵל, לֹא יַפְסִיק. וְצָרִיךְ לְהַעֲלוֹתָהּ (נ\"א אותה) עַד אֵין סוֹף. וּכְשֶׁמּוֹרִיד אוֹתָהּ, נֶאֱמַר בּוֹ כָּל הַכּוֹרֵעַ כּוֹרֵעַ בְּבָרוּךְ, שֶׁצָּרִיךְ לְהוֹרִידָהּ עַד אֵין תַּכְלִית, וְלֹא יַפְסִיק (נ\"א: אותה) מִמֶּנּוּ לֹא לְמַעְלָה וְלֹא לְמַטָּה.</p>\n<p>לִפְעָמִים בַּעְלָהּ הוּא ו' בְּצַדִּיק בְּשִׁשָּׁה פְרָקִים שֶׁל שְׁתֵּי שׁוֹקַיִם יוֹרֵד אֵלֶיהָ בִּשְׁתֵּי שׁוֹקַיִם. לִפְעָמִים בַּעְלָהּ הוּא ו' בִּשְׁתֵּי (נ\"א זרועות), שִׁשָּׁה פְרָקִים שֶׁעוֹלָה אֵלָיו בִּשְׁתֵּי זְרוֹעוֹת. לִפְעָמִים הוּא בֶּן אַבָּא וְאִמָּא, בֶּן י\"ה, צָרִיךְ לְהַעֲלוֹת (לה למעלה וכאשר) לְמַעְלָה לְה'. וּכְשֶׁעוֹלֶה שָׁם, לִפְעָמִים הִיא בְּהִפּוּךְ ו' וּבֵין י' י' כְּמוֹ זֶה א צָרִיךְ לְהַעֲלוֹתָהּ אֵלָיו, שֶׁנֶּאֱמַר בָּהּ (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה.</p>\n<p>וּכְשֶׁהִיא עוֹלָה לְמַעְלָה, בְּרֹאשׁ כָּל הָרָאשִׁים הִיא עוֹלָה, וּבִגְלָלָהּ הַמַּלְאָכִים אוֹמְרִים אַיֵּ\"ה מְקוֹם כְּבוֹדוֹ. וּכְשֶׁעוֹלָה לָא' (למעלה) כְּמוֹ זֶה א, הִיא כֶּתֶר בָּרֹאשׁ שֶׁל א' עֲטָרָה עַל רֹאשׁוֹ כֶּתֶ\"ר. וּכְשֶׁיּוֹרֶדֶת נְקֻדָּה לְמַטָּה וּמִתְעַטֶּרֶת, יוֹרֶדֶת בָּהּ כְּמוֹ זֶה (א קמץ). וּכְשֶׁעוֹלָה נִקְרֵאת כֶּתֶר בְּסוֹד הַטְּעָמִים, וּכְשֶׁיּוֹרֶדֶת נִקְרֵאת נְקֻדָּה. וּכְשֶׁמִּתְיַחֵד עִמָּהּ הִיא (נקראת אות) ז', הִיא כְלוּלָה מִמֶּנּוּ אוֹת בְּרִי\"ת, שֶׁהוּא שְׁבִיעִי שֶׁל הַכֹּל.</p>\n<p>וּבְוַדַּאי שֶׁאֶבֶן זוֹ הִיא בִּנְיַן כָּל הָעוֹלָמוֹת, וְלָכֵן (דברים כה) אֶבֶן שְׁלֵמָה וָצֶדֶק יִהְיֶה לָּךְ. הִיא מִדָּה בֵּין כָּל סְפִירָה, וּסְפִירָה שֶׁל כָּל סְפִירָה, (נ\"א: וכל ספירה) בָּהּ עוֹלָה לְעֶשֶׂר, הַשִּׁעוּר שֶׁלָּהּ. וּבָהּ נַעֲשֵׂית אַמָּה עֶשֶׂר אַמּוֹת אֹרֶךְ בֵּין כָּל סְפִירָה וּסְפִירָה. וְסוֹד הַדָּבָר - עֶשֶׂר אַמּוֹת אֹרֶךְ הַקָּרֶשׁ, וּבֵין הַכֹּל מֵאָה. י' הִיא בֵּין פֶּרֶק וּפֶרֶק עֶשֶׂר פְּעָמִים עוֹלֶה לְמִדָּה (בעל) שֶׁל מֵאָה אַמָּה.</p>\n<p>כָּל מִדָּה וּמִדָּה נִקְרֵאת עוֹלָם, וְי\"ו הֵם שִׁעוּר וּמִדָּה. ו' שֶׁקֶל, י' מִדָּה שֶׁלָּהּ. וְשִׁעוּר הַמִּדָּה חָמֵשׁ אַמּוֹת אֹרֶךְ וְחָמֵשׁ אַמּוֹת רֹחַב. וְהֵם כְּנֶגֶד שִׁעוּר שֶׁל כָּל רָקִיעַ שֶׁמַּהֲלַךְ חֲמֵשׁ מֵאוֹת אָרְכּוֹ וַחֲמֵשׁ מֵאוֹת רָחְבּוֹ, וְהֵם ה\"ה.</p>\n<p>הֲרֵי לְךְ שִׁעוּר קוֹמָה בְּאוֹתִיּוֹת יהו\"ה. שֶׁאוֹת ו' הוּא רְקִיעַ הַשָּׁמַיִם. חֲמִשָּׁה רְקִיעִים שֶׁלּוֹ ה' אֵלֶּה נִקְרְאוּ ה' שָׁמַיִם. ה' חֲמִשָּׁה רְקִיעִים שֶׁכְּלוּלִים בַּשָּׁמַיִם, חֲמִשָּׁה עֶלְיוֹנִים שְׁמֵי הַשָּׁמַיִם. וְהֵם ה\"ה חָמֵשׁ עִם חָמֵשׁ. ו' רָקִיעַ שִׁשִּׁי לָהֶם. י' שְׁבִיעִי לָהֶם. י' שִׁבְעָה בְּשִׁבְעָה וְעוֹלִים י\"ד. וְכֵן הֵם הָאֲרָצוֹת שִׁבְעָה עַל גַּבֵּי שִׁבְעָה כְּמוֹ גִּלְדֵי בְצָלִים, וְכֻלָּם רְמוּזִים בִּשְׁתֵּי עֵינַיִם.</p>\n<p>י' נִקְרָא עוֹלָם קָטָן, ו' עוֹלָם אָרֹךְ. וְכָל מִי שֶׁרוֹצֶה לִשְׁאֹל שְׁאֵלוֹת לְעוֹלָם אָרֹךְ, צָרִיךְ לְהַאֲרִיךְ בּוֹ. וְכָל מִי שֶׁשּׁוֹאֵל בְּעוֹלָם קָצָר, צָרִיךְ לְקַצֵּר. וְעַל זֶה בֵּאֲרוּ, בְּמָקוֹם שֶׁאָמְרוּ לְקַצֵּר - אֵין אָדָם רַשַּׁאי לְהַאֲרִיךְ.</p>\n<p>לְקַצֵר בַּתְּפִלּוֹת - (במדבר יב) אֵל נָא רְפָא נָא לָהּ. בַּנְּקֻדָּה שֶׁל י' לְהַאֲרִיךְ (מצד של אות ו'). וּלְהִתְנַפֵּל - (דברים ט) (באות פ', והכל פ\"ו) וָאֶתְנַפַּל לִפְנֵי ה' כָּרִאשֹׁנָה אַרְבָּעִים יוֹם וְאַרְבָּעִים לַיְלָה. הַכֹּל (אחד). מֵ\"ם, י' נְקֻדָּה בָּאֶמְצַע נַעֲשֵׂית מַיִ\"ם מִצַּד הַחֶסֶ\"ד צָרִיךְ לְהַאֲרִיךְ בַּתְּפִלָּה</p>\n<p>וּבַשֵּׁם הַקָּדוֹשׁ, וְעוֹלֶה יהו\"ה בִּרְבִיעַ (וצריך) לְהַאֲרִיךְ בִּתְנוּעָה זוֹ שֶׁהוּא סוֹד הַתְּקִיעָה. לְקַצֵּר מִצַּד הַשְּׁבָרִים. בֵּינוֹנִי - לֹא בְקִצּוּר וְלֹא בַאֲרִיכוּת, בַּתְּרוּעָה שֶׁל הָעַמּוּד הָאֶמְצָעִי שֶׁהִיא שַׁלְשֶׁלֶת, שֶׁשְּׁנֵיהֶם שֶׁקֶל הַקֹּדֶשׁ.</p>\n<p>כְּנֶגֶד רְבִיעַ שֶׁהוּא עוֹלֶה חֹלָם. שְׁבָרִים כְּנֶגֶד שְׁבָא. זֶה צָרִיךְ לְהַעֲלוֹת קוֹל, וְזֶה צָרִיךְ לְהוֹרִיד אוֹתוֹ. וְלָכֵן אוֹתָם שְׁבָרִים בַּחֲשַׁאי שְׁכִינָה תַחְתּוֹנָה, וְקוֹל לֹא יִשָּׁמַע, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א א) וְקוֹלָהּ לֹא יִשָּׁמֵעַ. תְּרוּעָה זוֹ שַׁלְשֶׁלֶת אָחוּז בִּשְׁנֵיהֶם.</p>\n<p>וְיֵשׁ כְּמוֹ הָרָקִיעַ הַמַּאֲרִיךְ בּוֹ תֵּבָה, וְהִיא נְקוּדָה חִירִיק כְּמוֹ חֹלָם. אֵין נְקֻדָּה שֶׁאֵין כְּמוֹתָהּ בַּטְּעָמִים. סֶגּוֹל אֶל סֶגוֹלְתָּא. שְׁבָא אֶל זָקֵף גָּדוֹל. כֻּלָּם תִּמְצָא לָהֶם נְקֻדּוֹת אֵצֶל הַטְּעָמִים לְמִי שֶׁיּוֹדֵעַ סוֹדוֹת טְמִירִים.</p>\n<p>פָּתַח וְאָמַר, זַרְקָא מַקָּף שׁוֹפָר הוֹלֵךְ סֶגוֹלְתָּא. (פתח נקדת ימין ה' מלך, נקדת סגול שמאל ה' מלך, באמצע ה' ימלוך למטה, רבי אחא אמר, ה' מלך זה עולם עליון, ה' מלך זה תפארת, ה' ימלוך זה ארון הברית).</p>"],[9522011053,"<p>אֵלֶּה תּ'וֹלְדוֹת הַ'שָּׁמַיִם וְ'הָאָרֶץ (ר\"ת תה\"ו), הֲרֵי פֵּרְשׁוּהָ, כָּל מָקוֹם שֶׁכָּתוּב אֵלֶּה - פָּסַל אֶת הָרִאשׁוֹנִים. וְאֵלֶּה תּוֹלָדוֹת שֶׁל תֹּהוּ שֶׁנִּרְמְזוּ בַּפָּסוּק הַשֵּׁנִי וְהָאָרֶץ הָיְתָה תֹהוּ, וְאֵלֶּה הֵם שֶׁנִּתְבָּאֵר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹרֵא עוֹלָמוֹת וּמַחֲרִיבָן. וְלָכֵן הָאָרֶץ הָיְתָה תוֹהָה וּבוֹהָה,</p>\n<p>אֵיךְ בּוֹרֵא הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹלָמוֹת לְהַחֲרִיבָם? יָפֶה הָיָה שֶׁלֹּא לִבְרֹא אוֹתָם! אֶלָּא וַדַּאי כָּאן יֵשׁ סוֹד. מַה זֶּה וּמַחֲרִיבָן? שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא יַשְׁמִיד אֶת מַעֲשֵׂי יָדָיו, וְלֹא עוֹד, אֶלָּא זֶה הַשָּׁמַיִם שֶׁנֶּאֱמַר בָּהֶם (ישעיה נא) כִּי שָׁמַיִם כֶּעָשָׁן נִמְלָחוּ וְגוֹ'. אִם כֵּן, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה וּמַכֶּה?!</p>\n<p>אֶלָּא סוֹד הַדָּבָר, כָּךְ הוּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא אֶת הָעוֹלָם וּבָרָא אוֹתוֹ בַּתּוֹרָה, כְּמוֹ שֶׁבֵּאֲרוּהָ בְּרֵאשִׁית, שֶׁנֶּאֱמַר בָּהּ (משלי ח) ה' קָנָנִי רֵאשִׁית דַּרְכּוֹ. וּבָרֵאשִׁית הַזּוֹ בָּרָא אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וְהוּא סָמַךְ אוֹתָם בָּהּ, בִּגְלַל שֶׁבְּרִית כְּתוּבָה בּוֹ בִּבְ'רֵ'אשִׁי'ת', וְנֶאֱמַר בָּהּ (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה וְגוֹ'. וְאֵלּוּ הֵם שֶׁנֶּאֱמַר בָּהֶם (תהלים קטו) הַשָּׁמַיִם שָׁמַיִם לַה' וְגוֹ'. וְאֶרֶץ הַחַיִּים הִיא כְּלוּלָה מִשֶּׁבַע אֲרָצוֹת, שֶׁעֲלֵיהֶם אָמַר דָּוִד הַמֶּלֶךְ (שם קיו) אֶתְהַלֵּךְ לִפְנֵי ה' בְּאַרְצוֹת הַחַיִּים.</p>\n<p>וּבָרָא שָׁמַיִם וָאָרֶץ אַחַר כָּךְ עַל תֹּהוּ, וְאֵין שָׁם יְסוֹד שֶׁהוּא בְּרִי\"ת שֶׁסּוֹמֵךְ אוֹתָם, לָכֵן רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת תּוֹרָה לְאֻמּוֹת הָעוֹלָם עוֹבְדֵי עַכּוּ\"ם, שֶׁהוּא בְּרִית מִילָה מַמָּשׁ, וְלֹא רָצוּ לְקַבְּלָהּ, וְנִשְׁאֲרָה הָאָרֶץ חֲרֵבָה וִיבֵשָׁה.</p>\n<p>וְזְהִוּ יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד וְתֵרָאֶה הַיַּבָּשָׁה. יִקָּווּ הַמַּיִם - זוֹ הַתּוֹרָה. אֶל מָקוֹם אֶחָד - אֵלּוּ יִשְׂרָאֵל, מִשּׁוּם שֶׁנִּשְׁמוֹתֵיהֶם תְּלוּיוֹת מֵאוֹתוֹ מָקוֹם שֶׁנֶּאֱמַר בּוֹ בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. כְּבוֹד ה' - שְׁכִינָה תַחְתּוֹנָה. מִמְּקוֹמוֹ - שְׁכִינָה עֶלְיוֹנָה. וְכֵיוָן שֶׁאוֹתָם נִשְׁמוֹתֵיהֶם מִשָּׁם, שׁוֹרָה עֲלֵיהֶם בְּוַדַּאי יהו\"ה, וְנֶאֱמַר בָּהֶם (דברים לב) כִּי חֵלֶק ה' עַמּוֹ. וְזֶהוּ יִקָּווּ הַמַּיִם אֶל מָקוֹם אֶחָד.</p>\n<p>וְהַתּוֹרָה הִיא יִשּׁוּב הָעוֹלָם. וְאֻמּוֹת הָעוֹלָם, שֶׁהֵם עוֹבְדֵי עַכּוּ\"ם, שֶׁלֹּא קִבְּלוּ אוֹתָהּ, נִשְׁאֲרוּ חֲרֵבִים וִיבֵשִׁים, וְזֶהוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹרֵא עוֹלָמוֹת וּמַחֲרִיבָן, אֵלֶּה שֶׁלֹּא שׁוֹמְרִים מִצְווֹת הַתּוֹרָה. לֹא שֶׁיַּשְׁמִיד הוּא מַעֲשָׂיו כְּמוֹ שֶׁחוֹשְׁבִים בְּנֵי אָדָם. וְלָמָּה יַשְׁמִיד אוֹתָם אֶת בָּנָיו, שֶׁנֶּאֱמַר בָּהֶם בְּהִבָּרְאָם, בְּה' בְּרָאָם?</p>\n<p>וְאֵלֶּה אוֹתָם שֶׁמִּתְגַּיְּרִים מֵאֻמּוֹת הָעוֹלָם, בִּגְלָלָם נָפְלָה ה' קְטַנָּה שֶׁל אַבְרָהָם בָּאֶלֶף הַחֲמִישִׁי שֶׁהוּא ה', שֶׁהוּא חָרֵב וְיָבֵשׁ. חָרֵב בְּבַיִת רִאשׁוֹן, וְיָבֵשׁ בְּבַיִת שֵׁנִי.</p>\n<p>וּמֹשֶׁה, מִשּׁוּם שֶׁרָצָה לְהַכְנִיס גֵּרִים תַּחַת כַּנְפֵי הַשְּׁכִינָה, וְחָשַׁב שֶׁהָיוּ מֵאֵלֶּה שֶׁנִּבְרְאוּ בְּה' וְנָתַן בָּהֶם אוֹת ה' שֶׁל אַבְרָהָם, גָּרְמוּ לוֹ יְרִידָה, כְּמוֹ שֶׁנֶּאֱמַר (שמות לב) לֶךְ רֵד כִּי שִׁחֵת עַמְּךְ. מִשּׁוּם שֶׁלֹּא קִבְּלוּ אֶת הָאוֹת ה' בְּיִרְאָה שֶׁל יוֹ\"ד וּבְאַהֲבָה שֶׁל ה', הוּא יָרַד מִדַּרְגָּתוֹ שֶׁהוּא ו'.</p>\n<p>וְאוֹת ו' יָרְדָה עִמּוֹ כְּדֵי שֶׁלֹּא יֹאבַד בֵּינֵיהֶם, שֶׁעָתִיד הוּא בְּסוֹד הַגִּלְגּוּל לְהִתְעָרֵב בֵּינֵיהֶם בַּגָּלוּת בֵּין עֵרֶב רַב, שֶׁהֵם נִשְׁמוֹתֵיהֶם מִצַּד אֵלֶּה שֶׁנֶּאֱמַר בָּהֶם (ישעיה נא) כִּי שָׁמַיִם כֶּעָשָׁן נִמְלָחוּ וְגוֹ'. וְאֵלֶּה אוֹתָם שֶׁלֹּא בִקֵּשׁ נֹחַ רַחֲמִים עֲלֵיהֶם, וְנֶאֱמַר בָּהֶם וַיִּמָּחוּ מִן הָאָרֶץ, בִּגְלַל שֶׁהָיוּ מֵאֵלֶּה שֶׁנֶּאֱמַר בָּהֶם (דברים כה) תִּמְחֶה אֶת זֵכֶר עֲמָלֵק. וּמֹשֶׁה לֹא נִשְׁמַר מֵהֶם, וְהִפִּיל ה' בֵּינֵיהֶם, וְלָכֵן הוּא לֹא יִכָּנֵס לְאֶרֶץ יִשְׂרָאֵל עַד שֶׁתָּשׁוּב ה' לִמְקוֹמָהּ. וְלָכֵן יָרַד הוּא מִדַּרְגָּתוֹ, וְיָרַד בּוֹ ו'. וְלָכֵן ה' נָפְלָה, ו' יָקִים אוֹתָהּ, ו' שֶׁל מֹשֶׁה.</p>\n<p>וּמִשּׁוּם שֶׁהֵ\"א קְטַנָּה, ה' שֶׁל אַבְרָהָם, שֶׁהִיא שֶׁל הִבָּרְאָם, נִקְטַן הוּא בִּגְלָלָהּ, וְנֶאֱמַר בּוֹ (ישעיה סג) מוֹלִיךְ לִימִין מֹשֶׁה וְגוֹ'. וְהוֹצִיא אוֹתָהּ מִשָּׁם בְּכֹחַ שֶׁל ו' וְהֵבִיא אוֹתָהּ עִמּוֹ. מִיָּד שָׁרְתָה עָלָיו י\"ה וְנִשְׁלְמָה הַשְּׁבוּעָה, (שנאמר) (שמות יז) כִּי יָד עַל כֵּס יָהּ מִלְחָמָה לַה' וְגוֹ'. מַה זֶּה מִדֹּר דֹּר? זֶה מֹשֶׁה, שֶׁנֶּאֱמַר בּוֹ (קהלת א) דּוֹר הֹלֵךְ וְדוֹר בָּא. וַהֲרֵי פֵּרְשׁוּהָ שֶׁאֵין דּוֹר פָּחוֹת מִשִּׁשִּׁים רִבּוֹא, וְזֶה מֹשֶׁה, שֶׁנֶּאֱמַר בּוֹ שֶׁאִשָּׁה אַחַת יָלְדָה שִׁשִּׁים רִבּוֹא בְּכֶרֶס אַחַת.</p>"],[9522011054,"<p>וַחֲמִשָּׁה מִינִים הֵם בְּעֵרֶב רַב, וְהֵם: נְ'פִילִים גִּ'בּוֹרִים עֲ'נָקִים רְ'פָאִים עֲ'מָלֵקִים. וּבִגְלָלָם נָפְלָה ה' קְטַנָּה מִמְּקוֹמָהּ. בִּלְעָם וּבָלָק הָיוּ מִצַּד שֶׁל עֲמָלֵק. תִּקַּח ע\"ם מִן בִּלְעָם, ל\"ק מִן בָּלָק, יִשָּׁאֵר בָּבֶל, (בראשית יא) כִּי שָׁם בָּלַל ה' שְׂפַת כָּל הָאָרֶץ.</p>\n<p>וְאֵלֶּה אוֹתָם שֶׁנִּשְׁאֲרוּ מֵאוֹתָם שֶׁנֶּאֱמַר בָּהֶם (שם ז) וַיִּמַח אֶת כָּל הַיְקוּם. וּמֵאֵלֶּה שֶׁנִּשְׁאֲרוּ מֵהֶם בְּגָלוּת רְבִיעִית, הֵם רָאשִׁים בְּקִיּוּם רַב, וְהֵם מַעֲמִידִים עַל יִשְׂרָאֵל כְּלֵי חָמָס, וַעֲלֵיהֶם נֶאֱמַר (שם ו) כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם. אֵלֶּה אוֹתָם עֲמָלֵקִים.</p>\n<p>הַנְּפִילִים, עֲלֵיהֶם נֶאֱמַר (שם) וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם כִּי טֹבוֹת הֵנָּה. וְאֵלֶּה הֵם מִין שֵׁנִי מֵהַנְּפִילִים הָאֵלֶּה מִלְמַעְלָה. שֶׁכְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת אָדָם, שֶׁאָמַר נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ וְגוֹ', רָצָה לַעֲשׂוֹת אוֹתוֹ רֹאשׁ לְכָל הָעֶלְיוֹנִים לִהְיוֹת מְמֻנֶּה עַל כֻּלָּם וְשֶׁיִּהְיוּ מִתְמַנִּים עַל יָדוֹ, כְּמוֹ שֶׁיּוֹסֵף שֶׁנֶּאֱמַר בּוֹ (שם מא) וְיַפְקֵד פְּקִדִים עַל הָאָרֶץ,</p>\n<p>הֵם רָצוּ לְקַטְרְגוֹ וְאָמְרוּ (תהלים ה) מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ וְגוֹ', שֶׁעָתִיד לַחֲטֹא לְפָנֶיךְ. אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא: אִם אַתֶּם הֱיִיתֶם לְמַטָּה כְּמוֹתוֹ, הֱיִיתֶם חוֹטְאִים יוֹתֵר מִמֶּנּוּ. מִיָּד - וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם וְגוֹ', חָשְׁקוּ בָהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִפִּילָם לְמַטָּה בְּשַׁלְשְׁלָאוֹת.</p>\n<p>וְהֵם עֲזָ\"א וַעֲזָאֵ\"ל, שֶׁמֵּהֶם הַנְּשָׁמוֹת שֶׁל הָעֵרֶב רַב, שֶׁהֵם הַנְּפִילִים, שֶׁהִפִּילוּ עַצְמָם לִזְנוֹת אַחַר נָשִׁים שֶׁהֵן טוֹבוֹת, וְלָכֵן הִפִּילָם הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהָעוֹלָם הַבָּא שֶׁלֹּא יִהְיֶה לָהֶם חֵלֶק שָׁם, וְנָתַן לָהֶם שְׂכָרָם בָּעוֹלָם הַזֶּה, כְּמוֹ שֶׁנֶּאֱמַר (דברים ז) וּמְשַׁלֵּם לְשּׁנְאָיו אֶל פָּנָיו לְהַאֲבִידוֹ וְגוֹ'.</p>\n<p>הַגִּבּוֹרִים - מִין שְׁלִישִׁי, עֲלֵיהֶם נֶאֱמַר (בראשית ז) הֵמָּה הַגִּבּרִים וְגוֹ' אַנְשֵׁי הַשֵּׁם, וְהֵם מִצַּד אֵלֶּה שֶׁנֶּאֱמַר בָּהֶם (שם יא) הָבָה נִבְנֶה לָּנוּ עִיר וְגוֹ' וְנַעֲשֶׂה לָּנוּ שֵׁם. וּבוֹנִים בָּתֵּי כְּנֵסִיּוֹת וּמִדְרָשׁוֹת, וְשָׂמִים בָּהֶם סֵפֶר תּוֹרָה וַעֲטָרָה עַל רֹאשׁוֹ, וְלֹא לְשֵׁם ה', אֶלָּא לַעֲשׂוֹת לָהֶם שֵׁם. זֶהוּ שֶׁכָּתוּב וְנַעֲשֶׂה לָּנוּ שֵׁם. וְצַד אַחֵר מִתְגַּבְּרִים עַל יִשְׂרָאֵל שֶׁהֵם כַּעֲפַר הָאָרֶץ, וְגוֹזְלִים אוֹתָם וּמִתְבַּטֶּלֶת הָעֲבוֹדָה, וַעֲלֵיהֶם נֶאֱמַר (שם ז) וְהַמַּיִם גָּבְרוּ מְאֹד מְאֹד עַל הָאָרֶץ.</p>\n<p>הָרְפָאִים - מִין רְבִיעִי, אִם יִרְאוּ אֶת יִשְׂרָאֵל בְּדחַק, מִתְרַפִּים מֵהֶם, וְיֵשׁ לָהֶם רְשׁוּת לְהַצִּילָם וְלֹא רוֹצִים. וּמִתְרַפִּים מֵהַתּוֹרָה וּמֵאֵלֶּה שֶׁמִּשְׁתַּדְּלִים בָּהּ לַעֲשׂוֹת טוֹב עִם עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. עֲלֵיהֶם נֶאֱמַר (ישעיה כו) רְפָאִים בַּל יָקֻמוּ. בִּזְמַן שֶׁתָּבֹא פְקִידָה לְיִשְׂרָאֵל, נֶאֱמָר בָּהֶם (שם) וַתְּאַבֵּד כָּל זֵכֶר לָמוֹ.</p>\n<p>הָעָנָקִים - מִין חֲמִישִׁי, שֶׁהֵם מְזַלְזְלִים לְאוֹתָם שֶׁנֶּאֱמַר בָּהֶם (משלי א) וַעֲנָקִים לְגַרְגְּרֹתֶיךְ, וַעֲלֵיהֶם נֶאֱמַר (דברים ב) רְפָאִים יֵחָשְׁבוּ אַף הֵם כַּעֲנָקִים. שְׁקוּלִים זֶה לָזֶה. אֵלֶּה אוֹתָם שֶׁמַּחֲזִירִים אֶת הָעוֹלָם לְתֹהוּ וָבהוּ. וְסוֹד הַדָּבָר, (שבגללם) נֶחֱרַב בֵּית הַמִּקְדָּשׁ וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ, שֶׁהִיא עִקַּר וְיִשּׁוּב הָעוֹלָם. מִיָּד כְּשֶׁיָּבא הָאוֹר, שֶׁהוּא הַקָּדוֹשׁ בָּרוּךְ הוּא, יִמָּחוּ מִן הָעוֹלָם וְיֹאבֵדוּ. אֲבָל הַגְּאֻלָּה אֵינָהּ תְּלוּיָה אֶלָּא בָּעֲמָלֵק עַד שֶׁיִּמָּחֶה, שֶׁבּוֹ הַשְּׁבוּעָה, וַהֲרֵי פֵּרְשׁוּהָ.</p>"],[9522011055,"<p>דָּבָר אַחֵר אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְגוֹ', אֵלֶּה אוֹתָם שֶׁנֶּאֱמַר בָּהֶם (שמות לב) אֵלֶּה אֱלֹהֶיךְ יִשְׂרָאֵל. בַּיּוֹם שֶׁיִּמָּחוּ אֵלֶּה, כְּאִלּוּ אוֹתוֹ יוֹם עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁמַיִם וָאָרֶץ. זֶהוּ שֶׁכָּתוּב (בראשית ב) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. בְּאוֹתוֹ זְמַן יִהְיֶה הַקָּדוֹשׁ בָּרוּךְ הוּא עִם שְׁכִינָתוֹ וְיִתְחַדֵּשׁ הָעוֹלָם, זֶהוּ שֶׁכָּתוּב (ישעיה סו) כִּי כַאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה וְגוֹ'. זֶהוּ בְּיוֹם עֲשׂוֹת.</p>\n<p>בְּאוֹתוֹ זְמַן, וַיַּצְמַח ה' אֱלֹהִים מִן הָאֲדָמָה כָּל עֵץ נֶחְמָד וְגוֹ'. אֲבָל בַּהַתְחָלָה, עַד שֶׁיִּמָּחוּ אֵלֶּה, לֹא יוֹרֵד גֶּשֶׁם שֶׁל הַתּוֹרָה, וְיִשְׂרָאֵל שֶׁדּוֹמִים לָעֲשָׂבִים וְלָאִילָנוֹת לֹא יִצְמְחוּ, וְסוֹד הַדָּבָר - וְכֹל שִׂיחַ הַשָּׂדֶה טֶרֶם יִהְיֶה בָאָרֶץ וְכָל עֵשֶׂב הַשָּׂדֶה וְגוֹ'. בִּגְלַל שֶׁאָדָם אַיִן לַעֲבֹד אֶת הָאֲדָמָה, שֶׁהֵם יִשְׂרָאֵל בְּבֵית הַמִּקְדָּשׁ לַעֲבֹד אֶת הָאֲדָמָה בְּקָרְבָּנוֹת.</p>\n<p>דָּבָר אַחֵר, וְכֹל שִׂיחַ הַשָּׂדֶה - זֶה מָשִׁיחַ רִאשׁוֹן - טֶרֶם יִהְיֶה בָאָרֶץ. וְכָל עֵשֶׂב הַשָּׂדֶה טֶרֶם יִצְמָח - זֶה מָשִׁיחַ שֵׁנִי. וְלָמָּה? מִשּׁוּם שֶׁאֵין שָׁם מֹשֶׁה לַעֲבֹד אֶת הַשְּׁכִינָה, שֶׁעָלָיו נֶאֱמַר וְאָדָם אַיִן לַעֲבֹד אֶת הָאֲדָמָה. וְסוֹד הַדָּבָר - (בראשית מט) לֹא יָסוּר שֵׁבֶט מִיהוּדָה - זֶה מָשִׁיחַ בֶּן דָּוִד. וּמְחֹקֵק מִבֵּין רַגְלָיו, זֶה מָשִׁיחַ בֶּן יוֹסֵף. עַד כִּי יָבֹא שִׁילֹ\"ה - זֶה מֹשֶׁה. חֶשְׁבּוֹן זֶה כָּזֶה. וְלוֹ יִקְּהַת עַמִּים - אוֹתִיּוֹת וְלֵוִ\"י קְהָ\"ת.</p>\n<p>דָּבָר אַחֵר, וְכֹל שִׂיחַ הַשָּׂדֶה - אֵלּוּ הַצַּדִּיקִים שֶׁהֵם מִצַּד שֶׁל צַדִּיק חַ\"י הָעוֹלָמִים. שִׂיחַ - ש' חַי. ש שְׁלֹשֶׁת עַנְפֵי הָאִילָן, וְהֵם שְׁלֹשָׁה אָבוֹת וּמִן חַ\"י עוֹלָמִים.</p>\n<p>לָשׁוֹן אַחֵר וְכָל עֵשֶׂב הַשָּׂדֶה - ע\"ב שי\"ן. שְׁלֹשָׁה עָלִים שֶׁהֵם ש יאהדונה\"י, וְהֵם ע\"ב עֲנָפִים שֶׁתְּלוּיִים בָּהֶם בְּחֶשְׁבּוֹן ע\"ב. כֻּלָּם לֹא נֶאֱחָזִים בְּמָקוֹם שֶׁהִיא שְׁכִינָה עַד שֶׁיָּבא אוֹתוֹ שֶׁנִּקְרָא אָדָ\"ם, שֶׁהוּ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. וְזֶהוּ וְאָדָ\"ם אַיִן לַעֲבֹד אֶת הָאֲדָמָה.</p>\n<p>וְלָכֵן נֶאֱמַר בּוֹ וְכָל עֵשֶׂב הַשָּׂדֶה טֶרֶם יִצְמָח, עַד שֶׁיִּצְמַח צַדִּי\"ק. וּמִמֶּנּוּ (תהלים פה) אֱמֶת מֵאֶרֶץ תִּצְמָח, שֶׁנֶּאֱמַר בּוֹ (דניאל ח) וְתַשְׁלֵךְ אֱמֶת אַרְצָה. וְתַלְמִידֵי חֲכָמִים, שֶׁהֵם דְּשָׁאִים, לֹא צוֹמְחִים בַּגָּלוּת עַד שֶׁאֱמֶת מֵאֶרֶץ תִּצְמָח, וְזֶה מֹשֶׁה שֶׁנֶּאֱמַר בּוֹ (מלאכי ב) תּוֹרַת אֱמֶת הָיְתָה בְּפִיהוּ, שֶׁלֹּא יִהְיֶה מִי שֶׁדּוֹרֵשׁ אֶת הַשְּׁכִינָה כְּמוֹתוֹ, וּבִגְלַל זֶה וְאָדָם אַיִן לַעֲבֹד.</p>\n<p>וּמִיָּד שֶׁהוּא יָבא, מִיָּד - וְאֵ\"ד יַעֲלֶה מִן הָאָרֶץ. א\"ד מִן אדנ\"י עוֹלֶה לוֹ ו' וְנַעֲשֶׂה בָּהּ אֲדוֹן כָּל הָאָרֶץ. מִיָּד - וְהִשְׁקָה אֶת פְּנֵי כָּל הָאֲדָמָה, מִמֶּנּוּ מֻשְׁקִים יִשְׂרָאֵל לְמַטָּה בְּשִׁבְעִים פָּנִים שֶׁל הַתּוֹרָה.</p>\n<p>דָּבָר אַחֵר וְאֵד יַעֲלֶה מִן הָאָרֶץ, תַּרְגּוּמוֹ עָנָן יַעֲלֶה מִן הָאָרֶץ. אוֹתָהּ שֶׁנֶּאֱמַר בָּהּ (שמות מ) כִּי עֲנַן ה' עַל הַמִּשְׁכָּן וְגוֹ', וּבוֹ מֻשְׁקִים תַּלְמִידֵי חֲכָמִים בָּאָרֶץ בְּאוֹתוֹ זְמַן.</p>\n<p>וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם - אֵלּוּ יִשְׂרָאֵל. בְּאוֹתוֹ זְמַן הַקָּדוֹשׁ בָּרוּךְ הוּא צִיֵּר אוֹתָם בְּצִיּוּרִים שֶׁל הָעוֹלָם הַזֶּה וְהָעוֹלָם הַבָּא. וַיִּיצֶר, בְּאוֹתוֹ זְמַן הַקָּדוֹשׁ בָּרוּךְ הוּא הִכְנִיסָם בִּשְׁמוֹ בְּצִיּוּר שֶׁל שְׁנֵי יוֹדִי\"ן י' י', ו' בֵּינֵיהֶם, שֶׁהֵם עוֹלִים לְחֶשְׁבּוֹן יהו\"ה. וְיִהְיוּ מְצֻיָּרִים בְּפָנָיו בַּפָּנִים שֶׁלָּהֶם בִּשְׁנֵי יוֹדִי\"ן בַּחֹטֶם שֶׁלָּהֶם בָּאוֹת ו'.</p>\n<p>וְלָכֵן אָמַר הַכָּתוּב (במדבר כג) כִּי מֵרֹאשׁ צוּרִים אֶרְאֶנּוּ. אֵלֶּה אוֹתָם צִיּוּרִים שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וְיִהְיוּ מְצֻיָּרִים בִּפְנֵיהֶם בִּשְׁנֵי לוּחוֹת נִכְבָּדִים, שֶׁהֵם י' י', שֶׁו' הוּא חָרוּת עֲלֵיהֶם.</p>\n<p>וְעוֹד צִיֵּר אוֹתָם לְכָל דּוֹר בְּבַת זוּגוֹ הָעֶלְיוֹנָה, זוֹ י\"ה, וְו' הֵם הַיִּחוּד שֶׁל שְׁנֵיהֶם. וְצִיֵּר אוֹתָם בְּאוֹתָם שֶׁל צִיּוּר שֶׁלְּמַעְלָה, שֶׁהוּא יִשְׂרָאֵל עַמּוּד הָאֶמְצָעִי, כּוֹלֵל שְׁכִינָה עֶלְיוֹנָה וְתַחְתּוֹנָה, שֶׁהֵם קְרִיאַת שְׁמַע עַרְבִית וּקְרִיאַת שְׁמַע שַׁחֲרִית, וַעֲלֵיהֶם נֶאֱמַר עֶצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי.</p>\n<p>וּמִיָּד בְּאוֹתוֹ זְמַן נָטַע אֶת יִשְׂרָאֵל בְּגַן הָעֵדֶן הַקָּדוֹשׁ. זֶהוּ שֶׁכָּתוּב וַיִּטַּע ה' אֱלֹהִים, אַבָּ\"א וְאִמָּ\"א. גַּ\"ן - זוֹ הַשְּׁכִינָה הַתַּחְתּוֹנָה. עֵדֶ\"ן - זוֹ הָאֵם הָעֶלְיוֹנָה. אֶת הָאָדָם - זֶה הָעַמּוּד הָאֶמְצָעִי. הִיא תִהְיֶה נֶטַע שֶׁלּוֹ בַּת זוּגוֹ, וְלֹא תָזוּז מִמֶּנּוּ לְעוֹלָם, וְתִהְיֶה הָעִדּוּן שֶׁלּוֹ. וְיִשְׂרָאֵל נָטַע אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתוֹ זְמַן נֶטַע קָדוֹשׁ בָּעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ס) נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר.</p>\n<p>וַיַּצְמַח יהו\"ה אֱלֹהִים - אַבָּא וְאִמָּא. כָּל עֵץ נֶחְמָד - זֶה צַדִּי\"ק. וְטוֹב לְמַאֲכָל - זֶה הָעַמּוּד הָאֶמְצָעִי, שֶׁבּוֹ הוּא מַזְמִין מָזוֹן לַכֹּל, שֶׁהַכֹּל בּוֹ. וְלֹא מִתְפַּרְנֵס הַצַּדִּיק אֶלָּא מִמֶּנּוּ וּשְׁכִינָה מִמֶּנּוּ, וְלֹא צְרִיכִים אֶת הַתַּחְתּוֹנִים (שלהם), אֶלָּא כֻּלָּם נִזּוֹנִים לְמַטָּה עַל יָדוֹ. שֶׁבַּגָּלוּת לֹא הָיָה לַשְּׁכִינָה וּלְחַ\"י הָעוֹלָמִים מָזוֹן אֶלָּא בְּח\"י בְּרָכוֹת שֶׁל הַתְּפִלָּה. אֲבָל בְּאוֹתוֹ זְמַן הוּא יִהְיֶה מָזוֹן לַכֹּל.</p>\n<p>וְעֵץ הַחַיִּים, שֶׁהוּא עֵץ הַחַיִּים, יִהְיֶה נָטוּעַ בְּתוֹךְ הַגָּן, שֶׁנֶּאֱמַר בּוֹ (בראשית ג) וְלָקַח גַּם מֵעֵץ הַחַיִּים וְאָכַל וָחַי לְעֹלָם. וְעַל הַשְּׁכִינָה לֹא שׁוֹלֵט הָעֵץ שֶׁל צַד הָאַחֵר, שֶׁהֵם עֵרֶב רַב שֶׁהֵם עֵץ הַדַּעַת טוֹב וָרָע, וְלֹא תְקַבֵּל בָּהּ עוֹד טָמֵא. זֶהוּ שֶׁכָּתוּב (דברים לב) ה' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר. וְלָכֵן לֹא מְקַבְּלִים גֵּרִים לִימוֹת הַמָּשִׁיחַ, וְתִהְיֶה הַשְּׁכִינָה כְּמוֹ גֶפֶן שֶׁלֹּא מְקַבֶּלֶת נֶטַע מִמִּין אַחֵר.</p>\n<p>וְיִשְׂרָאֵל יִהְיוּ כָּל עֵץ נֶחְמָד לְמַרְאֶה, וְיַחֲזר עֲלֵיהֶם יֹפִי, שֶׁנֶּאֱמַר בּוֹ (איכה ב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ תִּפְאֶרֶת יִשְׂרָאֵל. וְעֵץ הַדַּעַת טוֹב וָרָע נִדְחִים מֵהֶם, וְלֹא מִתְדַּבְּקִים וְלֹא מִתְעָרְבִים בָּהֶם, שֶׁהֲרֵי נֶאֱמַר בְּיִשְׂרָאֵל וּמֵעֵץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ, שֶׁהֵם עֵרֶב רַב. וְגִלָּה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבְּיוֹם אָכְלוֹ מִמֶּנּוּ, גָּרְמוּ שֶׁאִבְּדוּ שְׁתֵּי אֲבֵדוֹת, שֶׁהֵם בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי. זֶהוּ כִּי בְּיוֹם אֲכָלְךְ מִמֶּנּוּ מוֹת תָּמוּת, פַּעֲמַיִם. וְהֵם שֶׁגָּרְמוּ שֶׁצַּדִּיק יֶחֱרַב וְיָבֵשׁ בְּבַיִת רִאשׁוֹן, שֶׁהִיא שְׁכִינָה עֶלְיוֹנָה, וּבְבַיִת שֵׁנִי, שֶׁהִיא שְׁכִינָה תַחְתּוֹנָה. זֶהוּ (ישעיה יט) וְנָהָר יֶחֱרַב וְיָבֵשׁ. וְנָהָר זֶה יֶחֱרַב בְּה' תַּחְתּוֹנָה, בִּגְלַל שֶׁתִּסְתַּלֵּק מִמֶּנוּ שֶׁפַע הַי' לְאֵין סוֹף.</p>\n<p>וּמִיָּד כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מֵהַגָּלוּת, הָעָם הַקָּדוֹשׁ לְחוּד, מִיָּד נָהָר שֶׁהָיָה חָרֵב וְיָבֵשׁ נֶאֱמַר בּוֹ וְנָהָר יצֵא מֵעֵדֶן, זֶה ו', לְהַשְׁקוֹת אֶת הַגָּן. וְנָהָר - זֶה הָעַמּוּד הָאֶמְצָעִי. יֹצֵא מֵעֵדֶן - זוֹ אִמָּא הָעֶלְיוֹנָה. לְהַשְׁקוֹת אֶת הַגָּן - זוֹ שְׁכִינָה תַחְתּוֹנָה.</p>\n<p>שֶׁבְּאוֹתוֹ זְמַן נֶאֱמַר בְּמֹשֶׁה וּבְיִשְׂרָאֵל (שם נח) אָז תִּתְעַנַּג עַל ה'. בְּעֹנֶג, שֶׁהוּא ע' עֵדֶן, נ' נָהָר, ג' גַּן. וְיִתְקַיֵּם הַכָּתוּב (שמות טו) אָז יָשִׁיר מֹשֶׁה וְגוֹ'. שָׁר לֹא נֶאֱמַר, אֶלָּא יָשִׁיר. וְיִתְהַפֵּךְ לְעֵרֶב רַב עֹנֶ\"ג לְנֶגַ\"ע, וּלְאֻמּוֹת הָעוֹלָם עוֹבְדֵי עַכּוּ\"ם, כְּמוֹ שֶׁפַּרְעֹה וְהַמִּצְרִים שֶׁפָּרַח בָּהֶם שְׁחִין אֲבַעְבּוּעוֹת, אֲבָל לְיִשְׂרָאֵל יִהְיֶה עֹנֶ\"ג.</p>\n<p>וְזְהִוּ וְנָהָר יצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים, שֶׁהֵם חֶסֶ\"ד זְרוֹעַ יָמִין. וּבְאוֹתוֹ זְמַן הָרוֹצֶה לְהַחְכִּים יַדְרִים, וּמַחֲנֵה מִיכָאֵ\"ל מְקַבֵּל מִמֶּנּוּ, וְעִמּוֹ מַטֵּה יְהוּדָה וּשְׁנֵי שְׁבָטִים. גְּבוּרָ\"ה זְרוֹעַ שְׂמֹאל. וּבְאוֹתוֹ זְמַן הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין, וּמַחֲנֵה גַבְרִיאֵ\"ל מְקַבֵּל מִמֶּנּוּ, וְעִמּוֹ מַטֵּה דָן וּשְׁנֵי שְׁבָטִים. נֶצַ\"ח שׁוֹק יָמִין, וּמִמֶּנּוּ מְקַבֵּל מַחֲנֶה שֶׁל נוּרִיאֵ\"ל, וְעִמּוֹ מַטֵּה רְאוּבֵן וּשְׁנֵי שְׁבָטִים עִמּוֹ. הוֹ\"ד שׁוֹק שְׂמֹאל, שֶׁעָלֶיהָ נֶאֱמַר לְיַעֲקֹב (בראשית לב) וְהוּא צֹלֵעַ עַל יְרֵכוֹ, וּמִמֶּנּוּ מְקַבֵּל מַחֲנֵה רְפָאֵ\"ל, שֶׁהוּא מְמֻנֶּה עַל רְפוּאַת הַגָּלוּת, וְעִמּוֹ מַטֵּה אֶפְרַיִם וּשְׁנֵי שְׁבָטִים.</p>\n<p>דָּבָר אַחֵר וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים - אֵלֶּה אוֹתָם אַרְבָּעָה שֶׁנִּכְנְסוּ לַפַּרְדֵּס. אֶחָד נִכְנַס בְּפִישׁוֹ\"ן, שֶׁהוּא פִּי שׁוֹנֶה הֲלָכוֹת. הַשֵּׁנִי נִכְנַס בְּגִיחוֹ\"ן, וְשָׁם הוּא קָבוּר, אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ (ויקרא יא) כֹּל הוֹלֵךְ עַל גָּחוֹן. גַּבְרִיאֵ\"ל - גָּבַר אֵל, עָלָיו נֶאֱמַר (איוב ג) לְגֶבֶר אֲשֶׁר דַּרְכּוֹ נִסְתָּרָה וַיָּסֶךְ אֱלוֹהַּ בַּעֲדוֹ. וְלֹא יָדַע אִישׁ אֶת קְבוּרָתוֹ עַד הַיּוֹם הַזֶּה שֶׁהִתְגַּלָּה שָׁם, וְזֶהוּ רֶמֶז, וְדַי לַחֲכִימָא בִּרְמִיזָא.</p>\n<p>שְׁלִישִׁי נִכְנַס בְּחִדֶּקֶ\"ל - חַד קַל, וְזוֹ לָשׁוֹן מְחֻדֶּדֶת קַלָּה לִדְרָשָׁה. רְבִיעִי נִכְנַס בִּפְרָ\"ת, שֶׁהוּא הַמֹּחַ, שֶׁבּוֹ פְּרִיָּה וּרְבִיָּה. בֶּן זוֹמָא וּבֶן עַזַּאי שֶׁנִּכְנְסוּ לַקְּלִפּוֹת שֶׁל הַתּוֹרָה, הָיוּ לוֹקִים בָּהֶם. רַבִּי עֲקִיבָא שֶׁנִּכְנַס בַּמֹּחַ, נֶאֱמַר בּוֹ שֶׁנִּכְנַס בְּשָׁלוֹם וְיָצָא בְשָׁלוֹם.</p>"],[9522011056,"<p>(אמר רבי אלעזר, אבא, יום אחד הייתי בבית המדרש, ושאלו החברים, מהו שאמר רבי עקיבא לתלמידיו, כשתגיעו לאבני שיש טהור אל תאמרו מים מים שמא תסתכנו בעצמכם, שכתוב (תהלים קא) דבר שקרים לא יכון לנגד עיני? בין כך הנה זקן הזקנים. ירד ואמר להם, רבנן, במה אתם משתדלים? אמרו לו, ודאי בזה שאמר רבי עקיבא לתלמידיו כשתגיעו לאבני שיש וכו'. אמר להם, ודאי סוד עליון יש כאן, והרי פרשוה בישיבה העליונה, וכדי שלא תטעו ירדתי לכם, וכדי לגלות סוד זה ביניכם, שהוא סוד עליון טמיר מבני הדור).</p>\n<p>(בודאי אבני שיש טהור הם שמהם יוצאים מים זכים, והם רמוזים באות א' בראש ובסוף. ו' שהוא נטוי ביניהם הוא עץ החיים. מי שאוכל ממנו - וחי לעולם. ושני היודי\"ם האלה רמוזים בוייצר, והם שתי יצירות, יצירה של העליונים ויצירה של התחתונים. והם חכמה בראש וחכמה בסוף. תעלומות חכמה. ודאי הם תעלומות מחכמה עליונה שתחת כתר עליון).</p>\n<p>(והם כנגד שתי עינים שבהם שתי דמעות יורדות לים הגדול. ולמה ירדו? בגלל שהתורה משני הלוחות הללו היה משה מוריד לישראל, ולא זכו בהם, ונשברו ונפלו, וזה גרם אבדן בית ראשון ושני. ולמה נפלו? בגלל שפרח ו' מהם, שהוא ו' של וייצר, ונתן להם אחרים מצד של עץ הדעת טוב ורע, שמשם נתנה תורה באסור והתר. מימין חיים, ומשמאל מות).</p>\n<p>(ולכן אמר רבי עקיבא לתלמידיו, כשתגיעו לאבני שיש טהור אל תאמרו מים מים. לא תהיו שוקלים אבני שיש טהור (נ\"א: שהם שני יודי\"ן של ויּיצּר, חָכמָה עליונָה וחָכמָה תחתונָה) לאבנים אחרות שהן חיים ומות, שמשם (קהלת י) לב חכם לימינו ולב כסיל לשמאלו. ולא עוד, אלא אתם תסכנו עצמכם, בגלל שאלה של עץ הדעת טוב ורע הם בפרוד, ואבני שיש טהור הן ביחוד בלי פרוד כלל. ואם תאמרו שהרי הסתלק עץ החיים מהם ונפלו ויש ביניהם פרוד - דבר שקרים לא יכון לנגד עיני, שהרי אין שם פרוד למעלה. שאלה שנשברו היו מאלה. באו לנשק אותו, פרח והסתלק מהם).</p>"],[9522011057,"<p>דבר אחר ונהר יצא מעדן - בודאי למעלה בעץ החיים שם אין קלפות נכריות. זהו שכתוב (תהלים ה) לֹא יְגוּרְךְ רָע. אֲבָל בָּעֵץ שֶׁלְּמַטָּה יֵשׁ בְּוַדַּאי קְלִפּוֹת נָכְרִיּוֹת, וְהוּא נָטוּעַ בְּגַן עֵדֶן שֶׁל זְעֵיר אַנְפִּין, שֶׁהוּא חֲנוֹךְ, מטטרו\"ן, שֶׁגַּן הָעֵדֶן הָעֶלְיוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵין שָׁם עִרְבּוּב שֶׁל קְלִפּוֹת לִהְיוֹת שָׁם נִפְתָּל וְעִקֵּשׁ. וּבִגְלַל זֶה וְנָהָר יֹצֵא מֵעֵדֶן וְגוֹ', וְיָכֹלְנוּ לוֹמַר בְּמטטרו\"ן יֹצֵא מֵעֵדֶן - מֵעִדּוּן שֶׁלּוֹ. לְהַשְׁקוֹת אֶת הַגָּן - הַגָּן שֶׁלּוֹ, הַפַּרְדֵּס שֶׁלּוֹ שֶׁנִּכְנְסוּ לְשָׁם בֶּן עַזַּאי וּבֶן זוֹמָא וֶאֱלִישָׁע. וּקְלִפּוֹת שֶׁלּוֹ מִצַּד זֶה טוֹ\"ב וּמִצַּד זֶה רַע. וְזֶה אִסּוּר וְהֶתֵּר, כָּשֵׁר וּפָסוּל, טֻמְאָה וְטָהֳרָה.</p>\n<p>עָמַד זָקֵן אֶחָד וְאָמַר, רַבִּי רַבִּי, כָּךְ זֶה וַדַּאי! אֲבָל עֵץ הַחַיִּים הוּא לֹא נִקְרָא. אֶלָּא כָּךְ הוּא סוֹד הַדָּבָר, וַיִּיצֶר - יְצִירָה אַחַת לְטוֹב וִיצִירָה אַחַת לְרָע. זֶה עֵץ הַדַּעַת טוֹב וָרָע. עֵץ זֶה אָדָם קָטָן, מִצַּד הַחַיִּים מִמֶּנּוּ וּמִצַּד הַמָּוֶת מִמֶּנּוּ. שָׁם שְׁתֵּי יְצִירוֹת שֶׁלּוֹ שֶׁהֵם אִסּוּר וְהֶתֵּר, וְעָלָיו נֶאֱמַר וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה.</p>\n<p>וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים - זוֹ שְׁכִינָה עֶלְיוֹנָה. עֵדֶן - תְּשׁוּבָה. וְעָלֶיהָ נֶאֱמַר וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן. זֶה הָעַמּוּד הָאֶמְצָעִי. הַגָּ\"ן שְׁכִינָה תַחְתּוֹנָה. שְׁלֹשָׁה קְשָׁרִים הֵם, נְשָׁמָה רוּחַ וְנֶפֶשׁ אֶצְלוֹ, וּבָהֶם וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה, שֶׁהוּא מַמָּשׁ מִפִּיו נִקְרָא לַשְּׁכִינָה שֶׁהִיא נִשְׁמַת חַיִּים. מִיָּד שֶׁאָמַר דְּבָרִים אֵלּוּ, עָלָה לְמַעְלָה. אָמַר רַבִּי שִׁמְעוֹן, חֲבֵרִים, בְּוַדַּאי זֶה הָיָה מַלְאָךְ, וּבְוַדַּאי תּוֹמֵךְ יֵשׁ לָנוּ מִכָּל מָקוֹם.</p>"],[9522011058,"<p>פָּתַח הַפָּסוּק אַחֲרָיו: וַיִּקַּח ה' אֱלֹהִים אֶת הָאָדָם וַיַּנִּחֵהוּ בְגַן עֵדֶן וְגוֹ'. וַיִּקַּח - מֵאַיִן לָקַח אוֹתוֹ? אֶלָּא לָקַח אוֹתוֹ מֵאַרְבָּעָה יְסוֹדוֹת שֶׁנֶּאֱמַר בָּהֶם וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים. הִפְרִידוֹ מֵהֶם, וְשָׂם אוֹתוֹ בְּגַן עֵדֶן.</p>\n<p>כְּמוֹ זֶה יַעֲשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְבֶן אָדָם שֶׁנִּבְרָא מֵאַרְבָּעָה יְסוֹדוֹת. בִּזְמַן שֶׁשָּׁב בִּתְשׁוּבָה וּמִתְעַסֵּק בַּתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹטְלוֹ מִשָּׁם, וַעֲלֵיהֶם נֶאֱמַר וּמִשָּׁם יִפָּרֵד. הִפְרִיד נַפְשׁוֹ מִתַּאֲוָתָם, וְשָׂם אוֹתוֹ בַּגַּן שֶׁלּוֹ שֶׁהִיא שְׁכִינָה, לְעָבְדָהּ - בְּמִצְווֹת עֲשֵׂה, וּלְשָׁמְרָהּ - בְּמִצְווֹת לֹא תַעֲשֶׂה. אִם זָכָה לִשְׁמֹר אוֹתָהּ, הוּא יִהְיֶה רֹאשׁ עַל אַרְבָּעָה יְסוֹדוֹת, וְיֵעָשֶׂה נָהָר שֶׁמֻּשְׁקִים עַל יָדוֹ וְלֹא עַל יְדֵי אַחֵר, וּמַכִּירִים בּוֹ שֶׁהוּא רִבּוֹן וְשׁוֹלֵט עֲלֵיהֶם.</p>\n<p>וְאִם עָבַר עַל הַתּוֹרָה, הֵם מֻשְׁקִים מִמְּרִירוּת הָעֵץ שֶׁל רָע שֶׁהוּא יֵצֶר הָרָע. וְכָל הָאֵיבָרִים שֶׁהֵם מֵאַרְבָּעָה יְסוֹדוֹת, נֶאֱמַר בָּהֶם (שמות א) וַיְמָרֲרוּ אֶת חַיֵּיהֶם וְגוֹ'. וַיְמָרֲרוּ - בִּמְרִירוּת שֶׁל מָרָה. וּלְגַבֵּי אֵיבָרִים קְדוֹשִׁים שֶׁל הַגּוּף שֶׁהֵם מִצַּד הַטּוֹב, עֲלֵיהֶם נֶאֱמַר (שם טו) וַיָּבֹאוּ מָרָתָה וְלֹא יָכְלוּ לִשְׁתֹּת מַיִם מִמָּרָה וְגוֹ'. כְּגוֹן זֶה אָמְרוּ בַּעֲלֵי הַמִּשְׁנָה, וַיְמֲרָרוּ אֶת חַיֵּיהֶם בַּעֲבֹדָה קָשָׁה - בְּקֻשְׁיָא. בְּחֹמֶר - בְּקַל וָחֹמֶר. וּבִלְבֵנִים - בְּלִבּוּן הֲלָכָה. וּבְכָל עֲבֹדָה בַּשָּׂדֶה - זוֹ בָּרַיְתָא. אֵת כָּל עֲבֹדָתָם וְגוֹ' - זוֹ מִשְׁנָה.</p>\n<p>אִם שָׁבִים בִּתְשׁוּבָה, נֶאֱמַר בָּהֶם (שם) וַיּוֹרֵהוּ ה' עֵץ, וְזֶה עֵץ הַחַיִּים, וּבוֹ וַיִּמְתְּקוּ הַמָּיִם. וְזֶה מֹשֶׁה מָשִׁיחַ, שֶׁנֶּאֱמַר בּוֹ (שם יז) וּמַטֵּה הָאֱלֹהִים בְּיָדוֹ. מַטֶּ\"ה זֶה מטטרו\"ן, מִצִּדּוֹ חַיִּים וּמִצִּדּוֹ מִיתָה. כְּשֶׁמִּתְהַפֵּךְ לְמַטֶּה הוּא עֵזֶר מִצַּד הַטּוֹב. כְּשֶׁמִּתְהַפֵּךְ לְנָחָשׁ הוּא כְּנֶגְדּוֹ. מִיָּד (שם יד) וַיָּנָס מֹשֶׁה מִפָּנָיו.</p>\n<p>וְהַקָּדוֹשׁ בָּרוּךָ הוּא מְסָרוֹ בְּיַד מֹשֶׁה, וְהִיא תוֹרָה שֶׁבְּעַל פֶּה, שֶׁבָּהּ אִסּוּר וְהֶתֵּר. מִיָּד שֶׁהִכָּה בּוֹ בַּסֶּלַע, לָקַח אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיָדוֹ, וְנֶאֱמַר בּוֹ (שמואל ב כג) וַיֵּרֶד אֵלָיו בַּשָּׁבֶט, לְהַכּוֹת אוֹתוֹ בּוֹ. וְשֵׁבֶ\"ט הוּא יֵצֶר הָרָע נָחָשׁ, וְהַכֹּל הוּא בַּגָּלוּת מֵחֲמָתוֹ.</p>\n<p>וְעוֹד, וּמִשָּׁם יִפָּרֵד. אַשְׁרֵי הָאִישׁ שֶׁיִּשְׁתַּדֵּל בַּתּוֹרָה, שֶׁבִּזְמַן שֶׁיִּקַּח אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהַגּוּף הַזֶּה מֵאַרְבָּעָה יְסוֹדוֹת, נִפְרָד מִשָּׁם וְהוֹלֵךְ לִהְיוֹת רֹאשׁ בְּאַרְבַּע חַיּוֹת, וְנֶאֱמַר בָּהֶם עַל כַּפַּיִם יִשָּׂאוּנְךְ וְגוֹ'.</p>"],[9522011059,"<p>וַיְצַו ה' אֱלֹהִים וְגוֹ', הֲרֵי פֵּרְשׁוּהָ אֵין צַו אֶלָּא עֲבוֹדָה זָרָה, שֶׁמִּשָּׁם אֱלֹהִים אֲחֵרִים, וְהִיא בַּכָּבֵד, שֶׁמִּמֶּנָּה תִּכְבַּד הָעֲבוֹדָה, שֶׁהִיא עֲבוֹדָה זָרָה לוֹ, וְהַכָּבֵד כּוֹעֵס. וַהֲרֵי פֵּרְשׁוּהָ, כָּל הַכּוֹעֵס כְּאִלּוּ עוֹבֵד עֲבוֹדָה זָרָה. זֶהוּ וַיְצַו.</p>\n<p>עַל הָאָדָם - זוֹ שְׁפִיכוּת דָּמִים, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ט) בָּאָדָם דָּמוֹ יִשָּׁפֵךְ. וְזוֹ מָרָה, הַחֶרֶב שֶׁל מַלְאַךְ הַמָּוֶת, כְּמוֹ שֶׁנֶּאֱמַר (משלי ה) וְאַחֲרִיתָהּ מָרָה כַלַּעֲנָה חַדָּה כְּחֶרֶב פִּיּוֹת. לֵאמֹר - זֶה גִלּוּי עֲרָיוֹת, וְזֶה טְחוֹל, עָלָיו נֶאֱמַר (שם ל) אָכְלָה וּמָחֲתָה פִיהָ וְגוֹ', שֶׁלַּטְּחוֹל אֵין פֶּה וָעֳרָקִים, וּמֻשְׁקֶה מֵעֲכִירוּת הַדָּם הַשָּׁחֹר שֶׁל הַכָּבֵד, וְלֹא מָצָאנוּ לוֹ פֶּה. וְזֶהוּ אָכְלָה וּמָחֲתָה פִיהָ וְגוֹ'. כָּל שׁוֹפְכֵי דָמִים הֵם מִמָּרָה, שֶׁעָרְקֵי הַדָּם שֶׁל הַלֵּב, מִיָּד כְּשֶׁרוֹאִים מָרָה, כֻּלָּם בּוֹרְחִים מִלְּפָנֶיהָ.</p>\n<p>וְכָל הָעֲרָיוֹת מִתְכַּסִּים בַּחֹשֶׁךְ בְּדָם שָׁחֹר שֶׁל הַטְּחוֹל. מִי שֶׁעוֹבֵר עַל שְׁפִיכוּת דָּמִים וַעֲבוֹדָה זָרָה וְגִלּוּי עֲרָיוֹת, גּוֹלָה נִשְׁמָתוֹ בְּכָבֵד מָרָה טְחוֹל, וְדָנִים אוֹתוֹ בַּגֵּיהִנֹּם. וּשְׁלֹשָׁה מְמֻנִּים עֲלֵיהֶם - מַשְׁחִית אַף וְחֵמָה.</p>\n<p>ט\"ו עֲרָיוֹת הֵם כְּחֶשְׁבּוֹן י\"ה, וְשִׁשָּׁה אֲחֵרִים כְּחֶשְׁבּוֹן ו'. לִפְנֵי שֶׁגָּלוּ יִשְׂרָאֵל בַּגָּלוּת וּשְׁכִינָה עִמָּם, צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל, (ויקרא יח) עֶרְוַת אִמְּךְ לֹא תְגַלֵּה. וְהַגָּלוּת הַזּוֹ הִיא גִּלּוּי עֶרְוַת הַשְּׁכִינָה. זֶהוּ שֶׁכָּתוּב (ישעיה נ) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. וְעַל גִּלּוּי עֲרָיוֹת גָּלוּ יִשְׂרָאֵל וּשְׁכִינָה בַּגָּלוּת, וְזוֹהִי עֶרְוַת הַשְּׁכִינָה. וְעֶרְוָה זוֹ הִיא לִילִית, אִמָּם שֶׁל עֵרֶב רַב. וְעֵרֶב רַב הֵם עֲרָיוֹת שֶׁלָּהּ וַעֲרָיוֹת שֶׁל יִשְׂרָאֵל שֶׁלְּמַעְלָה, שֶׁעָלָיו נֶאֱמַר (ויקרא יח) עֶרְוַת אָבִיךְ וְגוֹ' לֹא תְגַלֵּה.</p>\n<p>וְהֵם הִפְרִידוּ בֵּין ה' ה' שֶׁלֹּא תִתְקָרֵב ו' בֵּינֵיהֶם. זֶהוּ שֶׁכָּתוּב (שם) עֶרְוַת אִשָּׁה וּבִתָּהּ לֹא תְגַלֵּה. וְהֵם שְׁכִינָה עֶלְיוֹנָה וְתַחְתּוֹנָה. שֶׁבִּזְמַן שֶׁהָעֵרֶב רַב, שֶׁהֵם: נְ'פִילִים גִּ'בּוֹרִים עֲ'מָלֵקִים רְ'פָאִים עֲ'נָקִים, בֵּין ה' לְה', אֵין רְשׁוּת לַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְקָרֵב בֵּינֵיהֶם, וְסוֹד הַדָּבָר - (ישעיה יט) וְנָהָר יֶחֱרַב וְיָבֵשׁ. יֶחֱרַב בְּה' עֶלְיוֹנָה, וְיָבֵשׁ בְּה' תַּחְתּוֹנָה. כְּדֵי שֶׁלֹּא יִתְפַּרְנְסוּ עֵרֶב רַב מִו' שֶׁהִיא עֵץ הַחַיִּים. וְלָכֵן אֵין הִתְקָרְבוּת לְו' בֵּין ה' ה' בִּזְמַן שֶׁעֵרֶב רַב בֵּינֵיהֶם.</p>\n<p>וְאֵין רְשׁוּת לָאוֹת י' לְהִתְקָרֵב לַה' הַשְּׁנִיָּה. זֶהוּ שֶׁכָּתוּב עֶרְוַת כַּלָּתְךְ לֹא תְגַלֵּה. וְהֵם הִפְרִידוּ בֵּין ו' לַה' הָעֶלְיוֹנָה. זֶהוּ שֶׁכָּתוּב עֶרְוַת אֵשֶׁת אָבִיךְ לֹא תְגַלֵּה. שֶׁי' הִיא אָב, ה' אֵם, ו' בֵּן, ה' בַּת. וְלָכֵן צִוָּה אֵלָיו ה' עֶלְיוֹנָה. עֶרְוַת אֵשֶׁת אָבִיךְ לֹא תְגַלֵּה. עֶרְוַת אֲחוֹתְךְ בַּת אָבִיךְ - זוֹ ה' תַּחְתּוֹנָה. אֶת בַּת בְּנָהּ וְאֶת בַּת בִּתָּהּ - הֵם הֵ\"א הֵ\"א, שֶׁהֵם תּוֹלָדוֹת שֶׁל ה'. עֶרְוַת אֲחִי אָבִיךְ - זוֹ יוֹ\"ד, שֶׁהוּא תּוֹלָדָה שֶׁל אוֹת י', וְהוּא אָח לְוָא\"ו.</p>\n<p>סוֹף סוֹף בִּזְמַן שֶׁעֵרֶב רַב מְעֹרָבִים בְּיִשְׂרָאֵל, אֵין קִרְבָה וְיִחוּד בְּאוֹתִיּוֹת שֵׁם יהו\"ה. וּמִיָּד שֶׁיִּמָּחוּ מֵהָעוֹלָם, נֶאֱמַר בָּאוֹתִיּוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה יהו\"ה אֶחָד וּשְׁמוֹ אֶחָד. וְלָכֵן אָדָם, שֶׁהֵם יִשְׂרָאֵל, יֵשׁ לָהֶם יִחוּד בַּתּוֹרָה, שֶׁנֶּאֱמַר בָּהּ (משלי ג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ, וְהִיא הַגְּבִירָה מַלְכוּ\"ת, שֶׁמִּצִּדָּהּ נִקְרְאוּ יִשְׂרָאֵל בְּנֵי מְלָכִים.</p>\n<p>וְלָכֵן אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ אֶעֱשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ. זוֹ מִשְׁנָה, אִשְׁתּוֹ שֶׁל אוֹתוֹ נַעַר, וְהוּא (והיא) שִׁפְחַת הַשְּׁכִינָה. אִם זָכוּ יִשְׂרָאֵל - הִיא עוֹזֶרֶת לָהֶם בַּגָּלוּת מִצַּד שֶׁל הֶתֵּר טָהוֹר כָּשֵׁר. וְאִם לֹא - הִיא כְּנֶגְדּוֹ מִצַּד שֶׁל טָמֵא פָּסוּל אָסוּר. טָהוֹר הֶתֵּר וְכָשֵׁר הוּא יֵצֶר הַטּוֹב. פָּסוּל טָמֵא אָסוּר הוּא יֵצֶר הָרָע.</p>\n<p>וְאִשָּׁה שֶׁיֵּשׁ לָהּ דַּם טֹהַר וְדַם נִדָּה מִצַּד שֶׁל הַמִּשְׁנָה הִיא שָׂמָה אוֹתוֹ וְאֵינָהּ בַּת זוּגוֹ, הַיִּחוּד שֶׁלּוֹ, שֶׁאֵין יִחוּד עַד שֶׁעֵרֶב רַב יִמָּחוּ מֵהָעוֹלָם. וְלָכֵן נִקְבַּר מֹשֶׁה מִחוּץ לָאָרֶץ הַקְּדוֹשָׁה, וּקְבוּרָתוֹ הִיא מִשְׁנָה, וְלֹא יָדַע אִישׁ אֶת קְבוּרָתוֹ עַד הַיּוֹם הַזֶּה. קְבוּרָתוֹ מִשְׁנָה שֶׁשּׁוֹלֶטֶת עַל הַגְּבִירָה, שֶׁהִיא קַבָּלָה לְמֹשֶׁה וּמֶלֶךְ. וּגְבִירָה מִתְפָּרֶדֶת מִבַּעְלָהּ. וְלָכֵן (משלי ל) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ וְכוּ' תַּחַת עֶבֶד כִּי יִמְלוֹךְ - זֶהוּ עֶבֶד הַיָּדוּעַ. וְשִׁפְחָה - זוֹ מִשְׁנָה. וְנָבָל כִּי יִשְׂבַּע לָחֶם - זֶה עֵרֶב רַב. עַם נָבָל וְלֹא חָכָם.</p>"],[9522011060,"<p>עוֹד פָּתַח וְאָמַר, וַיִּצֶר ה' אֱלֹהִים מִן הָאֲדָמָה כָּל חַיַּת הַשָּׂדֶה וְאֵת כָּל עוֹף הַשָּׁמַיִם. אוֹי לָעוֹלָם שֶׁהֵם אֲטוּמֵי לֵב וּסְתוּמֵי עֵינַיִם שֶׁלֹּא מִסְתַּכְּלִים בְּסוֹדוֹת הַתּוֹרָה וְלֹא יוֹדְעִים. שֶׁוַּדַּאי חַיַּת הַשָּׂדֶה וְעוֹף הַשָּׁמַיִם הֵם עַמֵּי הָאָרֶץ, וַאֲפִלּוּ בְּאֵלּוּ, שֶׁהֵם נֶפֶשׁ חַיָּה, לֹא נִמְצָא בָהֶם עֵזֶר (בגלות) לַשְּׁכִינָה בַּגָּלוּת, וְלֹא לְמֹשֶׁה שֶׁהוּא עִמָּהּ, שֶׁבְּכָל זְמַן שֶׁגָּלְתָה שְׁכִינָה לֹא זָז מִמֶּנָּה.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, וַהֲרֵי מִי נָתַן מַעֲשֶׂה שֶׁל אָדָם בְּיִשְׂרָאֵל וּבְמֹשֶׁה? אָמַר לוֹ: בְּנִי, וְאַתָּה אָמַרְתָּ כָּךְ? וְכִי לֹא לָמַדְתָּ (ישעיה מו) מַגִּיד מֵרֵאשִׁית אַחֲרִית!? אָמַר לוֹ, כָּךְ הוּא וַדַּאי.</p>\n<p>וְלָכֵן מֹשֶׁה לֹא מֵת, וְהוּא נִקְרָא אָדָם, וּבִגְלָלוֹ נֶאֱמַר בַּגָּלוּת הָאַחֲרוֹנָה וּלְאָדָם לֹא מָצָא עֵזֶר, אֶלָּא כֻּלָּם כְּנֶגְדּוֹ. וְכֵן נֶאֱמַר בָּעַמּוּד הָאֶמְצָעִי וּלְאָדָם לֹא מָצָא עֵזֶר שֶׁיּוֹצִיא שְׁכִינָה מֵהַגָּלוּת. זֶהוּ שֶׁכָּתוּב (שמות ב) וַיִּפֶן כֹּה וָכֹה וַיַּרְא כִּי אֵין אִישׁ. וּמֹשֶׁה הוּא בִדְמוּתוֹ מַמָּשׁ, שֶׁנֶּאֱמַר בּוֹ לֹא מָצָא עֵזֶר כְּנֶגְדּוֹ.</p>\n<p>בְּאוֹתוֹ זְמַן וַיַּפֵּל ה' אֱלֹהִים תַּרְדֵּמָה עַל הָאָדָם. ה' אֱלֹהִים - אַבָּא וְאִמָּא. תַּרְדֵּמָה - זוֹ הַגָּלוּת, שֶׁנֶּאֱמַר בָּהּ (בראשית טו) וְתַרְדֵּמָה נָפְלָה עַל אַבְרָם. הִפִּילוֹ עַל מֹשֶׁה וַיִּישַׁן. אֵין שֵׁנָה אֶלָּא גָלוּת. וַיִּקַּח אַחַת מִצַּלְעֹתָיו - מִצַּלְעוֹתָיו שֶׁל מִי? אֶלָּא מֵאוֹתָם עֲלָמוֹת שֶׁל הַגְּבִירָה נָטְלוּ אַבָּא וְאִמָּא אֶחָד מֵהֶם, וְהוּא צַד לָבָן, יָפֶה כַּלְּבָנָה. וַיִּסְגֹּר בָּשָׂר תַּחְתֶּנָּה - זֶה בָּשָׂר שֶׁנֶּאֱמַר בּוֹ (שם ו) בְּשַׁגַּם הוּא בָשָׂר. בָּשָׂר שֶׁל מֹשֶׁה אָדם, וְעָלָיו נֶאֱמַר פְּנֵי מֹשֶׁה כִּפְנֵי חַמָּה, וְלָכֵן (שיר ו) יָפָה כַלְּבָנָה בָּרָה כַּחַמָּה.</p>\n<p>דָּבָר אַחֵר וַיִּסְגֹּר בָּשָׂר - רָצוּ לְהָגֵן עָלָיו בָּהּ. זֶהוּ שֶׁכָּתוּב וַיִּסְגֹּר ה' בַּעֲדוֹ. דָּבָר אַחֵר וַיִּסְגֹּר - כְּמוֹ שֶׁנֶּאֱמַר (שמות כה) לְעֻמַּת הַמִּסְגֶּרֶת, מִסְגֶּרֶת מִתְקַיֶּמֶת, שֶׁבָּהּ הַגְּבִירָה (יחזקאל מו) יִהְיֶה סָגוּר שֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה.</p>"],[9522011061,"<p>וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע. כָּאן נִרְמָז סוֹד הַיִּבּוּם, שֶׁאָמְרוּ בוֹ, כֵּיוָן שֶׁלֹּא בָנָה, שׁוּב לֹא יִבְנֶה. זֶהוּ שֶׁכָּתוּב (דברים כה) אֲשֶׁר לֹא יִבְנֶה אֶת בֵּית אָחִיו. אֲבָל לְגַבֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא נֶאֱמַר בּוֹ וַיִּבֶן ה' אֱלֹהִים. אַבָּא וְאִמָּא בּוֹנִים אוֹתָהּ אֵלָיו. זֶהוּ שֶׁכָּתוּב בּוֹנֵה יְרוּשָׁלַיִם ה'. ו' שֶׁהוּא בֶּן י\"ה, אַבָּא וְאִמָּא, עֲלֵיהֶם נֶאֱמַר וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע. אֲשֶׁר לָקַח מִן הָאָדָם - זֶה הָעַמּוּד הָאֶמְצָעִי. וַיְבִאֶהָ אֶל הָאָדָם - הֵבִיא אוֹתוֹ אֶל הַצֵּלַע שֶׁלָּקַח מֵה', הָעַלְמָה שֶׁלָּהּ.</p>\n<p>וְעָלֶיהָ נֶאֱמַר (זכריה ב) וַאֲנִי אֶהְיֶה לָּהּ נְאֻם ה' חוֹמַת אֵשׁ סָבִיב. וְלָכֵן בְּהַר זֶה יִבָּנֶה בֵּית הַמִּקְדָּשׁ עַל יְדֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, יִהְיֶה קַיָּם לְדוֹרֵי דוֹרוֹת, וְעָלָיו נֶאֱמַר (חגי ב) גָּדוֹל יִהְיֶה כְּבוֹד הַבַּיִת הַזֶּה הָאַחֲרוֹן מִן הָרִאשׁוֹן. שֶׁהָרִאשׁוֹן נִבְנָה עַל יְדֵי אָדָם - וְזֶה עַל יְדֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְלָכֵן (תהלים קכז) אִם ה' לֹא יִבְנֶה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ.</p>\n<p>וְכֵן נֶאֱמַר בְּמֹשֶׁה וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע, כְּמוֹ שֶׁנֶּאֱמַר (שמות כו) וּלְצֶלַע הַמִּשְׁכָּן הַשֵּׁנִית. צֶלַע וַדַּאי מִצַּד שֶׁל חֶסֶד לָבָן, מִשָּׁם נִקְרֵאת לְבָנָה. וַיִּסְגֹּר בָּשָׂר תַּחְתֶּנָּה - בָּשָׂר שֶׁהוּא אָדם מִצַּד הַגְּבוּרָה וְנִכְלָל בִּשְׁנֵיהֶם. בְּאוֹתוֹ זְמַן (שיר ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי.</p>\n<p>זֹאת הַפַּעַם עֶצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי - זוֹ שְׁכִינָה נַעֲרָה הַמְאֹרָסָה לָעַמּוּד הָאֶמְצָעִי, נֶאֱמַר בָּהּ זאת הַפַּעַם וְגוֹ' אֲנִי יָדַעְתִּי שֶׁהִיא עֶצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי. לְזֹאת וַדַּאי יִקָּרֵא אִשָּׁה - מִצַּד עֶלְיוֹן שֶׁהִיא אִמָּ\"א (בינה). כִּי מֵאִישׁ לֻקָּחָה זֹאת - מִצַּד שֶׁל אַבָּ\"א (חכמה) שֶׁהוּא י'. וְכֵן מֹשֶׁה בִּדְמוּתוֹ לְמַטָּה.</p>\n<p>בְּאוֹתוֹ זְמַן יִזְכּוּ יִשְׂרָאֵל כָּל אֶחָד וְאֶחָד לְבַת זוּגוֹ, וְזֶהוּ שֶׁכָּתוּב (יחזקאל לו) וְנָתַתִּי לָכֶם לֵב חָדָשׁ וְרוּחַ חֲדָשָׁה אֶתֵּן בְּקִרְבְּכֶם, וְכָתוּב (יואל ג) וְנִבְּאוּ בְּנֵיכֶם וּבְנֹתֵיכֶם וְגוֹ', וְאֵלּוּ הֵם נְשָׁמוֹת חֲדָשׁוֹת שֶׁעֲתִידִים לִהְיוֹת עַל יִשְׂרָאֵל, כְּמוֹ שֶׁפֵּרְשׁוּהָ אֵין בֶּן דָּוִד בָּא עַד שֶׁיִּכְלוּ כָּל נְשָׁמוֹת שֶׁבַּגּוּף, וְאָז הַחֲדָשׁוֹת יָבוֹאוּ.</p>\n<p>בְּאוֹתוֹ זְמַן יֻעַבְרוּ עֵרֶב רַב מֵהָעוֹלָם, וְנֶאֱמַר בְּיִשְׂרָאֵל וּבְמֹשֶׁה, כָּל אֶחָד בְּבַת זוּגוֹ, וַיִּהְיוּ שְׁנֵיהֶם עֲרוּמִּים הָאָדָם וְאִשְׁתּוֹ וְלֹא יִתְבֹּשָׁשׁוּ. שֶׁתַּעֲבֹר עֶרְוָה מֵהָעוֹלָם, שֶׁאֵלֶּה הֵם שֶׁגָּרְמוּ גָּלוּת, עֵרֶב רַב וַדַּאי.</p>"],[9522011062,"<p>וַעָלֵיהֶם נֶאֱמַר וְהַנָּחָשׁ הָיָה עָרוּם מִכֹּל חַיַּת הַשָּׂדֶה וְגוֹ'. עָרוּם לְרַע מִכָּל הַחַיּוֹת שֶׁל אֻמּוֹת הָעוֹלָם עוֹבְדֵי עַכּוּ\"ם, וְהֵם בְּנֵי הַנָּחָשׁ הַקַּדְמוֹנִי שֶׁפִּתָּה אֶת חַוָּה. וְעֵרֶב רַב וַדַּאי הֵם הָיוּ זֻהֲמָא שֶׁהִטִּיל נָחָשׁ בְּחַוָּה, וּמֵאוֹתָהּ זֻהֲמָא יָצָא קַיִן וְהָרַג אֶת הֶבֶל רוֹעֵה צֹאן, שֶׁנֶּאֱמַר בּוֹ בְּשַׁגַּם הוּא בָשָׂר. בְּשַׁגַּם זֶה הֶבֶל. בְּשַׁגַּ\"ם וַדַּאי הוּא מֹשֶׁה. וְהָרַג אוֹתוֹ, וְהוּא הָיָה בֵּן בְּכוֹר שֶׁל אָדָם.</p>\n<p>וְעִם כָּל זֶה, מֹשֶׁה, כְּדֵי לְכַסּוֹת עַל עֶרְוַת אָבִיו, לָקַח אֶת בַּת יִתְרוֹ שֶׁנֶּאֱמַר בָּהּ (שופטים א) וּבְנֵי קֵינִי חֹתֵן מֹשֶׁה. וַהֲרֵי פֵּרְשׁוּהָ, לָמָּה נִקְרָא קֵינִי? שֶׁנִּפְרַד מִקַּיִן, כְּמוֹ שֶׁנֶּאֱמַר (שם ד) וְחֶבֶר הַקֵּינִי נִפְרָד מִקַּיִן. אַחַר כָּךְ רָצָה לְהַחֲזִיר עֵרֶב רַב בִּתְשׁוּבָה לְכַסּוֹת אֶת עֶרְוַת אָבִיו, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְצָרֵף מַחֲשָׁבָה טוֹבָה לְמַעֲשֶׂה, וְאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: הֵם מִגֶּזַע רַע, תִּשָּׁמֵר מֵהֶם. אֵלֶּה הֵם חֵטְא שֶׁל אָדָם שֶׁאָמַר לוֹ וּמֵעֵץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ. אֵלֶּה הֵם חֵטְא שֶׁל מֹשֶׁה וְיִשְׂרָאֵל.</p>\n<p>וּבִגְלָלָם גָּלוּ יִשְׂרָאֵל בַּגָּלוּת וְגֹרְשׁוּ מִשָּׁם. זֶהוּ שֶׁכָּתוּב וַיְגָרֶשׁ אֶת הָאָדָם. וְאָדָם יִשְׂרָאֵל בְּוַדַּאי. וּמֹשֶׁה בִּגְלָלָם גֹּרַשׁ מִמְּקוֹמוֹ וְלֹא זָכָה לְהִכָּנֵס לְאֶרֶץ יִשְׂרָאֵל, שֶׁבִּגְלָלָם עָבַר עַל מַאֲמַר הַקָּדוֹשׁ בָּרוּךְ הוּא וְחָטָא בַסֶּלַע שֶׁהִכָּה בּוֹ, וְלֹא אָמַר לוֹ אֶלָּא רַק (במדבר כ) וְדִבַּרְתֶּם אֶל הַסֶּלַע, וְהֵם גָּרְמוּ. וְעִם כָּל זֶה, מַחֲשָׁבָה טוֹבָה הַקָּדוֹשׁ בָּרוּךְ הוּא מְצָרְפָהּ לְמַעֲשֶׂה, שֶׁהוּא לֹא קִבֵּל אוֹתָם, וְנָתַן בָּהֶם אוֹת בְּרִית אֶלָּא לְכַסּוֹת עֶרְוַת אָבִיו. וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לוֹ (שם יד) וְאֶעֱשֶׂה אֹתְךְ לְגוֹי גָּדוֹל וְעָצוּם מִמֶּנּוּ, וּבִגְלָלָם אָמַר (שמות לב) מִי אֲשֶׁר חָטָא לִי אֶמְחֶנּוּ מִסִּפְרִי, שֶׁהֵם מִזֶּרַע עֲמָלֵק שֶׁנֶּאֱמַר בּוֹ (דברים כה) תִּמְחֶה אֶת זֵכֶר עֲמָלֵק, וְהֵם גָּרְמוּ לִשְׁבֹּר אֶת שְׁנֵי הַלּוּחוֹת שֶׁל הַתּוֹרָה.</p>\n<p>וּמִיָּד - וַתִּפָּקַחְנָה עֵינֵי שְׁנֵיהֶם וַיֵּדְעוּ יִשְׂרָאֵל כִּי עֵירֻמִּם הֵם. בַּשִּׁעְבּוּד שֶׁל מִצְרַיִם שֶׁהָיוּ בְּלִי תוֹרָה, וְנֶאֱמַר בָּהֶם (יחזקאל טז) וְאַתְּ עֵרוֹם וְעֶרְיָה. וְאִיּוֹב בִּגְלַל זֶה אָמַר פַּעֲמַיִם (איוב א) עָרֹם יָצָתִי מִבֶּטֶן אִמִּי וְעָרֹם אָשׁוּב שָׁמָּה. מַה שֶּׁהָיָה מֹשֶׁ\"ה, הִתְהַפֵּךְ לְעֵרֶב רַב לְשַׁמָּ\"ה וְלִשְׁנִינָה. אָשׁוּב שָׁמָּה - כָּאן רָמַז שֶׁעָתִיד לַחֲזֹר בֵּינֵיהֶם בַּגָּלוּת הָאַחֲרוֹנָה, וְהוֹלֵךְ בֵּינֵיהֶם לְשַׁמָּ\"ה, וְהוּא אָמַר (שם) ה' נָתַן וַה' לָקָח יְהִי שֵׁם ה' מְבֹרָךְ.</p>\n<p>וּבִזְמַן שֶׁנִּשְׁבְּרוּ שְׁנֵי לוּחוֹת הַתּוֹרָה, וְתוֹרָה שֶׁבְּעַל פֶּה, נֶאֱמַר בָּהֶם וַיִּתְפְּרוּ עֲלֵה תְאֵנָה. הִתְכַּסּוּ בְּכַמָּה קְלִפּוֹת מֵעֵרֶב רַב מִשּׁוּם כִּי עֵירֻמִּם הֵם, שֶׁלֹּא תִתְגַּלֶּה עֶרְוָתָם. וְכִסּוּי שֶׁלָּהֶם כַּנְפֵי צִיצִית וּרְצוּעוֹת הַתְּפִלִּין, עֲלֵיהֶם נֶאֱמַר וַיַּעַשׂ ה' אֱלֹהִים לְאָדָם וּלְאִשְׁתּוֹ כָּתְנוֹת עוֹר וַיַּלְבִּשֵׁם. אֲבָל לְגַבֵּי צִיצִית - וַיִּתְפְּרוּ עֲלֵה תְאֵנָה וַיַּעֲשׂוּ לָהֶם חֲגֹרֹת. זֶהוּ (תהלים מה) חֲגוֹר חַרְבְּךְ עַל יָרֵךְ גִּבּוֹר, וְזוֹ קְרִיאַת שְׁמַע שֶׁנֶּאֱמַר בָּהּ (שם קמט) רוֹמְמוֹת אֵל בִּגְרוֹנָם. זֶהוּ וַיַּעֲשׂוּ לָהֶם חֲגֹרֹת.</p>"],[9522011063,"<p>וַיִּשְׁמְעוּ אֶת קוֹל ה' אֱלֹהִים וְגוֹ', כְּשֶׁקָּרְבוּ לְהַר סִינַי. זֶהוּ שֶׁכָּתוּב (דברים ד) הֲשָׁמַע עָם קוֹל אֱלֹהִים מְדַבֵּר מִתּוֹךְ הָאֵשׁ וְגוֹ'. וְעֵרֶב רַב מֵתוּ. וְהֵם הָיוּ שֶׁאָמְרוּ לְמֹשֶׁה (שמות כ) וְאַל יְדַבֵּר עִמָּנוּ אֱלֹהִים פֶּן נָמוּת, וּמָצְאוּ אֶת הַתּוֹרָה. וְאֵלֶּה הֵם עַמֵּי הָאָרֶץ שֶׁנֶּאֱמַר בָּהֶם (דברים כז) אָרוּר שֹׁכֵב עִם כָּל בְּהֵמָה, בִּגְלַל שֶׁהֵם מִצַּד אוֹתוֹ שֶׁנֶּאֱמַר בּוֹ אָרוּר אַתָּה מִכָּל הַבְּהֵמָה.</p>\n<p>וַהֲרֵי כַּמָּה הֵם עֵרֶב רַב רָעִים בְּהֵמוֹת וְחַיּוֹת, אֲבָל יֵשׁ עֵרֶב רַב מִצַּד שֶׁל הַנָּחָשׁ, וְיֵשׁ עֵרֶב רַב מִצַּד שֶׁל אֻמּוֹת עַכּוּ\"ם שֶׁדּוֹמִים לְחַיּוֹת וּבַהֲמוֹת הַשָּׂדֶה, וְיֵשׁ עֵרֶב רַב מִצַּד שֶׁל מַזִּיקִים, שֶׁנִּשְׁמָתָם שֶׁל רְשָׁעִים הֵם מַזִּיקִים שֶׁל הָעוֹלָם מַמָּשׁ, וְיֵשׁ עֵרֶב רַב שֶׁל שֵׁדִים וְרוּחוֹת וְלִילִין, וְהַכֹּל מְעֻרְבָּבִים בְּיִשְׂרָאֵל, וְאֵין בְּכֻלָּם מְקֻלָּל כַּעֲמָלֵק, שֶׁהוּא נָחָשׁ רַע אֵל אַחֵר. הוּא גִלּוּי לְכָל הָעֲרָיוֹת שֶׁל הָעוֹלָם, רוֹצֵחַ הוּא, וּבַת זוּגוֹ סַם מָוֶת עֲבוֹדָה זָרָה, וְהַכֹּל סמא\"ל. וְיֵשׁ סמא\"ל וְיֵשׁ סמא\"ל, וְלֹא הַכֹּל שָׁוִים. אֲבָל אוֹתוֹ צַד שֶׁל הַנָּחָשׁ הוּא מְקֵלָּל עַל הַכֹּל.</p>\n<p>וַיִּקְרָא ה' אֱלֹהִים אֶל הָאָדָם וַיֹּאמֶר לוֹ אַיֶּכָּה. כָּאן רָמַז לוֹ שֶׁעָתִיד לְהַחֲרִיב בֵּית הַמִּקְדָּשׁ וְלִבְכּוֹת בּוֹ אֵיכָה. זֶהוּ שֶׁכָּתוּב (איוב א) אֵיכָה יָשְׁבָה בָדָד. אֵ\"י כָ\"ה. וְלֶעָתִיד לָבא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַעֵר כָּל הַמִּינִים הָרָעִים מֵהָעוֹלָם, כְּמוֹ שֶׁכָּתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח. וְאָז שָׁב הַכֹּל לִמְקוֹמוֹ, כְּמוֹ שֶׁכָּתוּב (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>"],[9522011064,"<p>שָׁנִינוּ, כָּל שְׁלֹמֹה שֶׁנֶּאֱמַר בְּשִׁיר הַשִּׁירִים, בְּמֶלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ, בְּמֶלֶךְ (ס\"א בנקבות המלך) סְתָם בִּנְקֵבָה מִלָּה (מלך) תַּחְתּוֹנָה בָעֶלְיוֹנָה. וְסוֹד הַדָּבָר - דִּירָה תַחְתּוֹנָה לָעֶלְיוֹנָה שְׁתֵּיהֶן כְּאַחַת. וְהַיְנוּ בַּיִ\"ת, שֶׁכָּתוּב (משלי כד) בְּחָכְמָה יִבָּנֶה בָּיִת. כָּתוּב (שיר ג) אַפִּרְיוֹן עָשָׂה לוֹ הַמֶּלֶךְ שְׁלֹמֹה מֵעֲצֵי הַלְּבָנוֹן. אַפִּרְיוֹן זֶה תִּקּוּן שֶׁל הָעוֹלָם הַתַּחְתּוֹן מֵהָעוֹלָם הָעֶלְיוֹן.</p>\n<p>שֶׁעַד שֶׁלֹּא בָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הָיָה נִסְתָּר בּוֹ שְׁמוֹ, וְלֹא (היה) הוּא שְׁמוֹ נִסְתָּר בְּתוֹכוֹ אֶחָד, וְלֹא עָמַד דָּבָר, (והוא היה בלבדו) עַד שֶׁעָלָה בְרָצוֹן (של המחשבה להעמיד הכל בשביל סממנים) לִבְרֹא עוֹלָם, וְהָיָה רָשׁוּם וּבָנוּי וְלֹא עוֹמֵד, עַד שֶׁהִתְעַטֵּף בְּעִטּוּף אֶחָד שֶׁל זֹהַר (עליון של מחשבה) וּבָרָא עוֹלָם (נ\"א: ימין של העולם הקדמון),</p>\n<p>וְהוֹצִיא (אילנות) אֲרָזִים עֶלְיוֹנִים גְּדוֹלִים מֵאוֹתוֹ הָאוֹר (וזיו גדול) זהַר עֶלְיוֹן (נ\"א: אחד של זהר ימין העליון), וְשָׂם מֶרְכַּבְתּוֹ עַל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת רְשׁוּמוֹת, שֶׁנֶּחְקְקוּ בְּעֶשֶׂר אֲמִירוֹת וְהִתְיַשְּׁבוּ. זֶהוּ שֶׁכָּתוּב מֵעֲצֵי הַלְּבָנוֹן, וְכָתוּב (תהלים קד) אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע. (שהרי מאלו עשה את האפריון ההוא).</p>\n<p>עָשָׂה לוֹ הַמֶּלֶךְ שְׁלֹמֹה. לוֹ - לְעַצְמוֹ, לוֹ - לְתִקּוּנוֹ, לוֹ - לְהַרְאוֹת כָּבוֹד עֶלְיוֹן, לוֹ - לְהוֹדִיעַ שֶׁהוּא אֶחָד וּשְׁמוֹ אֶחָד, כְּמוֹ שֶׁנֶּאֱמַר (זכריה יד) (יהיה יהו\"ה אחָד וּשמו אחָד, וכָתוּב) (תהלים פג) וידעו כי אתה שמך ה' לבדך.</p>\n<p>בְּהַגִּיעַ הַהַכָּאָה, הֵיכָלוֹת יְדוּעִים, נוֹטֶה לְצַד זֶה לְמַעְלָה. נוֹטֶה לְיָמִין. סוֹטֶה לִשְׂמֹאל. יוֹרֵד לְמַטָּה. וְכֵן לְאַרְבָּעָה קְצָווֹת. מַלְכוּת נִפְרְדָה לְמַעְלָה וּלְמַטָּה וּלְאַרְבָּעָה קְצָווֹת לִהְיוֹת נָהָר עֶלְיוֹן אֶחָד</p>\n<p>יוֹרֵד לְמַטָּה, וְעוֹשֵׂהוּ לַיָּם הַגָּדוֹל, כְּמוֹ שֶׁנֶּאֱמַר (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא. שֶׁהֲרֵי הוּא כּוֹנֵס הַכֹּל וְשׁוֹאֵב אוֹתוֹ לְתוֹכוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שיר ב) אֲנִי חֲבַצֶּלֶת הַשָּׁרוֹן שׁוֹשַׁנַּת הָעֲמָקִים. וְאֵין שָׁרוֹן אֶלָּא מְקוֹם הַיָּם הַגָּדוֹל שֶׁשּׁוֹאֵב כָּל מֵימֵי הָעוֹלָם, שֶׁמּוֹצִיא וְשׁוֹאֵב וּמֵאִיר (ונכנסים בו, משום כך זה מוציא וזה שואב, מאיר) זֶה בָּזֶה בִּדְרָכִים יְדוּעוֹת (נחלים רעב עליו), וְאָז כָּתוּב עֲלֵיהֶם (משלי כד) בְּחָכְמָה יִבָּנֶה בָּיִת, וְעַל זֶה בֵּית בְּרֵאשִׁית (נ\"א: ועל זה בית של העולם מלך סתם) (בית עליון נבנה בחכמה, וכן אף כך התחתון). אֲבָל בַּיִת עֶלְיוֹן הַגָּדוֹל - יִשּׁוּב הָעוֹלָם. מֶלֶךְ סְתָם - בַּיִת תַּחְתּוֹן.</p>\n<p>(תהלים סג) וְהַמֶּלֶךְ יִשְׂמַח בֵּאלֹהִים, (כשמתעוררת גבורה) עֶלְיוֹנָה לֶאֱחֹז בּוֹ תַּחַת רֹאשׁוֹ וּלְקָרְבוֹ בְּחֶדְוָה לִהְיוֹת הַכֹּל אֶחָד. וְהַמֶּלֶךְ יִשְׂמַח בֵּאלֹהִים - שִׂמְחָה, אוֹר (באור) (שמאיר) שֶׁהוֹצִיא בִּשְׁבִיל אֶחָד טָמִיר וְגָנוּז וְנִכְנָס בּוֹ בִּשְׁנַיִם שֶׁהֵם אֶחָד, וְעַל זֶה הָעוֹלָם נִתְקַן בְּקִיּוּם שָׁלֵם.</p>\n<p>וְהַמֶּלֶךָ יִשְׂמַח בֵּאלֹהִים - עוֹלָם (אור עליון) הַתַּחְתּוֹן שָׂמֵחַ בָּעוֹלָם הָעֶלְיוֹן (נ\"א: נסתר אותו ששלח) עָמֹק (שמחה ששופעת ויוצאת באיזה מקום שמח? באלהים, בו שמח, בו שולח) חַיִּים לַכֹּל. נִקְרָאִים חַיֵּי הַמֶּלֶךְ. זֶה עִקַּר הַבַּיִת. בַּיִת זֶה בּוֹנֶה בַּיִת שֶׁל הָעוֹלָם וּבוֹנֶה הָעוֹלָם. וְזֶהוּ בְּרֵאשִׁית בָּרָא אֱלֹהִים, ב' רֵאשִׁית. רֵאשִׁית חָכְמָה כְּשֶׁכּוֹנֵס הַכֹּל לְתוֹכוֹ וְנַעֲשֶׂה יָם גָּדוֹל לִשְׁאֹב הַכֹּל.</p>\n<p>יָם שֶׁקָּפְאוּ מֵימָיו שׁוֹאֵב כָּל מֵימוֹת הָעוֹלָם וְכוֹנֵס אוֹתָם לְתוֹכוֹ, וְהַמַּיִם הוֹלְכִים וְשָׁטִים וְנִשְׁאָבִים בּוֹ, וְזֶה יוֹצֵא מִתּוֹךְ הָעֶלְיוֹן. וְסִימָן שֶׁל הַסּוֹד הַזֶּה - (איוב לח) מִבֶּטֶן מִי יָצָא הַקָּרַח, שֶׁמֵּימָיו גְּלוּדִים (קפואים) בּוֹ לִשְׁאֹב אֲחֵרִים.</p>\n<p>הַקֶּרַח הַזֶּה יָם שֶׁקּוֹפֵא, לֹא שׁוֹפְעִים מֵימָיו אֶלָּא בְּשָׁעָה שֶׁחֹזֶק הַדָּרוֹם מַגִּיעַ אֵלָיו וּמְקָרֵב אוֹתוֹ אֶצְלוֹ, וְאָז הַמַּיִם שֶׁהָיוּ גְּלוּדִים בְּצַד הַצָּפוֹן מַפְשִׁירִים וְשׁוֹפְעִים, שֶׁהֲרֵי מִצַּד הַצָּפוֹן הַמַּיִם מַגְלִידִים, וּמִצַּד הַדָּרוֹם הֵם מַפְשִׁירִים וְשׁוֹפְעִים לְהַשְׁקוֹת כָּל אוֹתָן חַיּוֹת הַשָּׂדֶה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי וְגוֹ', וְאֵלּוּ נִקְרָאִים הָרֵי בָתֶר, הָרֵי הַפֵּרוּד. שֶׁכֻּלָּם מֻשְׁקִים כְּשֶׁצַּד דָּרוֹם מַתְחִיל לִקְרַב אֵלָיו, וְאָז הַמַּיִם שׁוֹפְעִים. וּבְכֹחַ עֶלְיוֹן זֶה שֶׁשּׁוֹפֵעַ, הַכֹּל הֵם בִּגְדֻלָּה וּבְשִׂמְחָה.</p>\n<p>כְּשֶׁמַּחֲשָׁבָה עוֹלָה בְרָצוֹן (של חדוה) מִטָּמִיר שֶׁל כָּל הַטְּמִירִים, מַגִּיעַ (ושופע) מִתּוֹכוֹ נָהָר אֶחָד (כתר טמיר), וּכְשֶׁמִּתְקָרְבִים זֶה בָּזֶה בִּשְׁבִיל אֶחָד שֶׁלֹּא יָדוּעַ לְמַעְלָה וּלְמַטָּה, וְכָאן הוּא רֵאשִׁית הַכֹּל. וּב' מֶלֶךְ סְתָם, מֵהָרֵאשִׁית הַזֹּאת נִתְקַן וְדוֹמֶה זֶה לָזֶה.</p>\n<p>(ובכח זה) בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם (סתם נקדה נסתרת ששופעים מימיה ויוצאים החוצה) (נ\"א: אחר שיוצאים בזה) (ונ\"א נהר שיוצא בה\"א עליונה) (אור ששופע ויוצא בזה) וּמוֹצִיא קוֹל מִתּוֹכוֹ, וְזֶה נִקְרָא קוֹל הַשּׁוֹפָר. וְהַיְנוּ בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם (והוא) שֶׁהוּא קוֹל הַשּׁוֹפָר (נ\"א: והוא השופר). וְשָׁמַיִם שׁוֹלְטִים בְּחַיֵּי הַמֶּלֶךְ הָעֶלְיוֹן עַל הָאָרֶץ. וְסִימָן לַדָּבָר - בֶּן יִשַׁי חַ\"י עַל הָאֲדָמָה. שֶׁהַחַיִּים תְּלוּיִים בְּבֶן יִשַׁי (ובוא\"ו משפיעים לו). וּבָהֶם שׁוֹלֵט בַּכֹּל, וְהָאָרֶץ נִזּוֹנֵית מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב וְאֵת הָאָרֶץ. וָא\"ו הִתּוֹסְפָה לִשְׁלֹט בַּמְּזוֹנוֹת עַל הָאָרֶץ.</p>\n<p>אֵ\"ת לְמַעְלָה, וְהוּא כֹּחַ שֶׁל כְּלַל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת שֶׁהוֹצִיא אֵ\"ת א' ת' אֱלֹהִים זֶה, וְנָתַן לַשָּׁמַיִם, כְּמוֹ שֶׁנֶּאֱמַר (שיר ג) בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ בְּיוֹם חֲתֻנָּתוֹ. וְהַיְנוּ אֵת הַשָּׁמַיִם - לְהַכְלִיל זֶה בָּזֶה וּלְחַבֵּר אוֹתָם זֶה בָּזֶה לְהִתְקַיֵּם כְּאֶחָד בְּאוֹתָם חַיֵּי הַמֶּלֶךְ, מֶלֶךְ סְתָם, לְהָזִין מִמֶּנּוּ שָׁמַיִם. וְאֵת הָאָרֶץ - חִבּוּר שֶׁל זָכָר וּנְקֵבָה שֶׁנֶּחְקְקוּ בְּאוֹתִיּוֹת רְשׁוּמוֹת, וְחַיֵּי הַמֶּלֶךְ שֶׁנִּשְׁפְּעוּ מֵהַשָּׁמַיִם, שֶׁהַשָּׁמַיִם מַשְׁפִּיעִים לָהֶם לְקַיֵּם אֶת הָאָרֶץ וְכָל אוּכְלוּסֶיהָ.</p>\n<p>וְסוֹד שֶׁל אֱלֹהִים עֶלְיוֹן עָשָׂה שָׁמַיִם וָאָרֶץ לְקִיּוּם. וְהוֹצִיא אוֹתָם כְּאֶחָד בְּכֹחַ שֶׁלְּמַעְלָה הָרֵאשִׁית שֶׁל הַכֹּל. כְּמוֹ זֶה סוֹד עֶלְיוֹן יוֹרֵד לְמַטָּה. וְהָאַחֲרוֹן הַזֶּה עָשָׂה שָׁמַיִם וָאָרֶץ לְמַטָּה.</p>\n<p>וְסוֹד שֶׁל הַכֹּל שְׁנֵי עוֹלָמוֹת הֵם וּבָרְאוּ עוֹלָמוֹת, זֶה הָעוֹלָם הָעֶלְיוֹן וְזֶה הָעוֹלָם הַתַּחְתּוֹן. זֶה כְּמוֹ זֶה. זֶה בָּרָא שָׁמַיִם וָאָרֶץ, וְזֶה בָּרָא שָׁמַיִם וָאָרֶץ. וְעַל זֶה שְׁנֵי עוֹלָמוֹת הֵם. זֶה הוֹצִיא שְׁנֵי עוֹלָמוֹת, וְזֶה הוֹצִיא שְׁנֵי עוֹלָמוֹת, וְהַכֹּל בְּכֹחַ שֶׁל הָרֵאשִׁית הָעֶלְיוֹנָה.</p>\n<p>יוֹרֵד הָעֶלְיוֹן בַּתַּחְתּוֹן וּמִתְמַלֵּא בְּדֶרֶךְ שֶׁל דַּרְגָּה אַחַת שֶׁשּׁוֹרָה עָלֶיהָ. כְּמוֹ שֶׁאוֹתוֹ שְׁבִיל נִסְתָּר וְטָמִיר וְגָנוּז לְמַעְלָה, פְּרָט לִשְׁבִיל אֶחָד דַּקִּיק. וְדֶרֶךְ אַחַת. אוֹתוֹ שֶׁלְּמַטָּה דֶּרֶךְ, כְּמוֹ שֶׁנֶּאֱמַר (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ. וְאוֹתוֹ שֶׁלְּמַעְלָה שְׁבִיל דַּקִּיק, כְּמוֹ שֶׁכָּתוּב (איוב כח) נָתִיב לֹא יְדָעוֹ עָיִט. וְסוֹד שֶׁל הַכֹּל - (ישעיה מג) הַנּוֹתֵן בַּיָּם דֶּרֶךְ וּבְמַיִם עַזִּים נְתִיבָה. וְכָתוּב (תהלים עז) בַּיָּם דַּרְכֶּךְ וּשְׁבִילְךְ בְּמַיִם רַבִּים. הָעוֹלָם הָעֶלְיוֹן, כְּשֶׁמִּתְמַלֵּא וּמִתְעַבֵּר כְּמוֹ נְקֵבָה שֶׁמִּתְעַבֶּרֶת מִן הַזָּכָר, מוֹצִיאָה שְׁנֵי בָנִים כְּאֶחָד, זָכָר וּנְקֵבָה, וְהֵם שָׁמַיִם וָאָרֶץ כְּמוֹ שֶׁלְּמַעְלָה.</p>\n<p>מִמֵּימֵי הַשָּׁמַיִם נִזּוֹנֵית הָאָרֶץ וּמֵימָיו נִשְׁפָּכִים לְתוֹכָהּ, אֶלָּא שֶׁעֶלְיוֹנִים זָכָר וְתַחְתּוֹנִים נְקֵבָה. וְהַתַּחְתּוֹנִים נִזּוֹנִים מִן הַזָּכָר. וּמַיִם תַּחְתּוֹנִים קוֹרְאִים לָעֶלְיוֹנִים כִּנְקֵבָה שֶׁפְּתוּחָה לַזָּכָר וְשׁוֹפֶכֶת מַיִם כְּנֶגֶד מַיִם שֶׁל הַזָּכָר לַעֲשׂוֹת זֶרַע. וְהַנְּקֵבָה נִזּוֹנֵית מִן הַזָּכָר. זֶהוּ שֶׁכָּתוּב וְאֵת הָאָרֶץ, בְּתוֹסֶפֶת וָי\"ו, כְּמוֹ שֶׁנֶּאֱמַר.</p>\n<p>כָּתוּב (ישעיה מ) שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָּרָא אֵלֶּה וְגוֹ'. הָאוֹתִיּוֹת נֶחְקְקוּ בַּמַּעֲשֶׂה שֶׁל הַכֹּל, בַּמַּעֲשֶׂה שֶׁל הָעֶלְיוֹן וּבַמַּעֲשֶׂה שֶׁל הַתַּחְתּוֹן. אַחַר כָּךְ נִרְשְׁמוּ הָאוֹתִיּוֹת וְנֶחְקְקוּ בַּכָּתוּב. ב' בְּרֵאשִׁית בָּרָא. א' אֱלֹהִים אֵת. ב' רֵאשִׁית בָּרָא וַדַּאי, כְּמוֹ שֶׁנֶּאֱמַר בֵּי\"ת בָּרָא, וַדַּאי בְּכֹחַ עֶלְיוֹן. ב' נְקֵבָה. א' זָכָר. כְּמוֹ שֶׁב' בָּרָא וַדַּאי בַּכֹּחַ שֶׁלְּמַעְלָה, כָּךְ א' הוֹצִיא אוֹתִיּוֹת הַשָּׁמַיִם כְּלָלוּת שֶׁל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת. ה' הוֹצִיא שָׁמַיִם לָתֵת לָהֶם חַיִּים (ולהשקות) וּלְהַשְׁרִישׁ אוֹתוֹ.</p>\n<p>וְאֵת הָאָרֶץ - ו' הוֹצִיאָה הָאָרֶץ לָתֵת לָהּ מָזוֹן וּלְהַתְקִינָהּ וְלָתֵת לָהּ סִפּוּק שֶׁרָאוּי לָהּ. וְאֵת הָאָרֶץ - שֶׁלָּקַח וָא\"ו אֵ\"ת כְּלָלוּת שֶׁל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת, וְהָאָרֶץ נִזּוֹנֵית. וְהָאָרֶץ כּוֹלֶלֶת אוֹתָם לְתוֹכָהּ, כְּמוֹ שֶׁנֶּאֱמַר (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶת הַיָּם. וְהַיְנוּ סוֹד וְאֵת הָאָרֶץ. שֶׁכּוֹנֶסֶת הַכֹּל לְתוֹכָהּ וּמְקַבֶּלֶת אוֹתָם הָאָרֶץ, לָקְחָה הָאָרֶץ. וְאֵ\"ת - זֶה שָׁמַיִם וָאָרֶץ כְּאֶחָד. אֵ\"ת הַשָּׁמַיִם - סוֹד שֶׁל שָׁמַיִם וָאָרֶץ כְּאֶחָד.</p>\n<p>וּמְקַבֶּלֶת אוֹתָם לְהָזִין. הַגָּעַת הַדָּבָר בְּהַכָּאָתוֹ מְצוּיִים. הֵיכַל הַקְּטֹרֶת מָצוּי בָּאָרֶץ. כְּשֶׁאֵשׁ לוֹהֶטֶת, שׁוֹפַעַת וּמִתְעוֹרֶרֶת מִשְּׂמֹאל שֶׁאוֹחֵז בָּהּ וְעוֹלֶה עָשָׁן, כְּמוֹ שֶׁנֶּאֱמַר (שמות יט) וְהַר סִינַי עָשַׁן כֻּלּוֹ מִפְּנֵי אֲשֶׁר יָרַד עָלָיו ה' בָּאֵשׁ. זוֹ אֵשׁ וְזֶה עָשָׁן. וְכָתוּב (שם) וְאֶת הָהָר עָשֵׁן. מִתּוֹךְ שֶׁאֵשׁ כְּשֶׁיּוֹרֶדֶת, אֲחוּזִים זֶה בָּזֶה עָשָׁן בָּאֵשׁ, וְאָז הַכֹּל עוֹמֵד בְּצַד הַשְּׂמֹאל, וְהַיְנוּ סוֹד (ישעיה מח) אַף יָדִי יָסְדָה אֶרֶץ. וִימִינִי טִפְּחָה שָׁמָיִם, בְּכֹחַ שֶׁל הַיָּמִין לְמַעְלָה. כְּמוֹ כֵן נַעֲשׂוּ שָׁמַיִם שֶׁהֵם זָכָר. וְזָכָר בָּא מִצַּד הַיָּמִין, וּנְקֵבָה מִצַּד הַשְּׂמֹאל.</p>\n<p>(ישעיה מ) שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָרָא אֵלֶּה. עַד כָּאן עָלוּ הַדְּבָרִים שֶׁלֹּא לִשְׁאֹל כְּשֶׁלְּמַעְלָה. שֶׁחָכְמָה נִתְקְנָה מֵאַיִן וְלֹא עוֹמֶדֶת לִשְׁאֵלָה שֶׁנִּסְתֶּרֶת וַעֲמֻקָּה אֵין שֶׁיַּעֲמֹד בָּהּ. כֵּיוָן שֶׁהִתְפַּשֵּׁט אוֹר עָמֹק, אָז אוֹרוֹ עוֹמֵד לִשְׁאֵלָה אַף עַל גַּב שֶׁהוּא נִסְתָּר מֵהַכֹּל שֶׁלְּמַטָּה, וְקוֹרְאִים לוֹ עַל פִּי שְׁאֵלָה מִי. מִי בָרָא אֵלֶּה.</p>\n<p>וְהַיְנוּ סוֹד שֶׁאָמַרְנוּ (איוב לח) מִבֶּטֶן מִי יָצָא הַקָּרַח. מִבֶּטֶן מִי וַדַּאי (יצא הקרח), אוֹתוֹ שֶׁעוֹמֵד לַשְּׁאֵלָה. וְאֵין לִשְׁאֹל מַה לְמַעְלָה וּמַה לְּמַטָּה, אֶלָּא לִשְׁאֹל מָקוֹם שֶׁיּוֹצְאִים לָדַעַת, וְלֹא לָדַעַת אוֹתוֹ, שֶׁהֲרֵי לֹא יְכוֹלִים. אֶלָּא עוֹמֵד לַשְּׁאֵלָה וְלֹא לָדַעַת בּוֹ.</p>\n<p>בְּרֵאשִׁית ב' רֵאשִׁית, רֵאשִׁית מַאֲמָר הוּא. אוֹ נֹאמַר שֶׁבְּרֵאשִׁית הוּא מַאֲמָר. אֶלָּא עַד שֶׁלֹּא יָצָא וְהִתְפַּשֵּׁט כֹּחוֹ וְהַכֹּל נִסְתָּר בּוֹ, בְּרֵאשִׁית הוּא וּמַאֲמָר הוּא. כֵּיוָן שֶׁיָּצָא וְהִתְפַּשְּׁטוּ מִמֶּנּוּ צְבָאוֹת, נִקְרָא רֵאשִׁית, וְהוּא מַאֲמָר בִּלְבַדּוֹ. מִ\"י שְׁאֵלָה אוֹתוֹ שֶׁבָּרָא אֵלֶּה. אַחַר כְּשֶׁהִתְפַּשֵּׁט וְהִשְׁתַּכְלֵל, נַעֲשָׂה יָ\"ם וּבָרָא לְמַטָּה. וְהַכֹּל עָשָׂה כְּמוֹ אוֹתוֹ מַמָּשׁ שֶׁלְּמַעְלָה. זֶה כְּנֶגֶד זֶה וְזֶה כְּמוֹ זֶה, וּשְׁנֵיהֶם ב'.</p>\n<p>כָּתוּב (שיר א) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ. בִּמְסִבּוֹ - לְהִתְיַשֵּׁב בְּמַלְכוּת תַּחְתּוֹנָה. בְּסוֹד שֶׁל אוֹתָהּ חֲבֵרוּת וְתַפְנוּק שֶׁל אוֹתָהּ חֲבִיבוּת שֶׁבָּעֵדֶן הָעֶלְיוֹן בְּאוֹתוֹ שְׁבִיל שֶׁנִּסְתָּר וְגָנוּז וְלֹא נוֹדָע, וּמִתְמַלֵּא מִמֶּנּוּ וְיוֹצֵא בִּנְחָלִים יְדוּעִים. נִרְדִּי נָתַן רֵיחוֹ - זֶה מֶלֶךְ תַּחְתּוֹן. שֶׁבָּרָא עוֹלָם שֶׁלְּמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, וּמַעֲלֶה רֵיחַ טוֹב עֶלְיוֹן לִשְׁלֹט וְלַעֲשׂוֹת, וְיָכוֹל וְשׁוֹלֵט וּמֵאִיר בְּאוֹר עֶלְיוֹן.</p>\n<p>בִּשְׁנֵי גְוָנִים נִבְרָא הָעוֹלָם, בְּיָמִין וּבִשְׂמֹאל, בְּשִׁשָּׁה יָמִים עֶלְיוֹנִים. שִׁשָּׁה יָמִים נַעֲשׂוּ לְהָאִיר, כְּמוֹ שֶׁנֶּאֱמַר (שמות לא) כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. וְאֵלֶּה חָפְרוּ דְרָכִים וְעָשׂוּ שִׁשִּׁים נְקָבִים לִתְהוֹם רַבָּה, וְאוֹתָם שִׁשִּׁים נְקָבִים לְהַעֲלוֹת מֵי הַנְּחָלִים לְתוֹךְ הַתְּהוֹם. וְעַל זֶה (הרי שנינו) הַשִּׁיתִין מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית נִבְרְאוּ, וְהֵם הָיוּ שְׁלוֹם הָעוֹלָם.</p>\n<p>וְהָאָרֶץ הָיְתָה תֹהוּ וָבהוּ, הַפְּסֹלֶת הַטְּמוּנָה בְּתוֹךְ קְלִיטָתוֹ שֶׁהָיְתָה בַּהַתְחָלָה וְלֹא הִתְקַיְּמָה. הָיְתָה כְּבָר וְאַחַר כָּךְ הִתְקַיְּמָה. בְּאַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת נֶחְקַק הָעוֹלָם וְהִתְקַיֵּם, וְכֻלָּם עִטּוּר שֶׁל הַשֵּׁם הַקָּדוֹשׁ.</p>\n<p>כְּשֶׁמִּצְטָרְפוֹת, עוֹלוֹת בְּאוֹתִיּוֹת אוֹתִיּוֹת לְמַעְלָה וְיוֹרְדוֹת לְמַטָּה, מִתְעַטְּרוֹת בַּעֲטָרוֹת בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם וְיָכוֹל הָעוֹלָם לְהִתְקַיֵּם. וְאֵלֶּה מִתְקַיְּמִים בְּמַעֲשֵׂי הָעוֹלָם (נ\"א: המלך). הַדְּפוּס שֶׁל הַקְּלִיטָה בְּאֵלֶּה מְצוּיִים כְּחוֹתַם הַחוֹתֶמֶת. נִכְנְסוּ וְיָצְאוּ אֵת וְאֵת וְנִבְרָא הָעוֹלָם. נִכְנְסוּ לְתוֹךְ הַחוֹתָם וְהִצְטָרְפוּ וְהִתְקַיֵּם הָעוֹלָם.</p>\n<p>בַּמַּקֵּל שֶׁל הַנָּחָשׁ הַגָּדוֹל הִכּוּ וְנִכְנְסוּ תַּחַת נִקְבֵי הֶעָפָר אֶלֶף וַחֲמֵשׁ מֵאוֹת אַמּוֹת. אַחַר כָּךְ תְּהוֹם רַבָּה הָיָה עוֹלֶה בַּחֹשֶׁךְ, וְהַחֹשֶׁךְ כִּסָּה הַכֹּל, עַד שֶׁיָּצָא אוֹר וּבָקַע בַּחֹשֶׁךְ וְיָצָא וְהֵאִיר, שֶׁכָּתוּב (איוב יב) מְגַלֶּה עֲמֻקוֹת מִנִּי חֹשֶׁךְ וַיֹּצֵא לָאוֹר צַלְמָוֶת.</p>\n<p>מַיִם נִשְׁקְלוּ בְּמִשְׁקַל אֶלֶף וַחֲמֵשׁ מֵאוֹת בָּאֶצְבָּעוֹת. שָׁלֹשׁ נָטְפוּ לְתוֹךְ הַמִּשְׁקָל. חֲצִי מֵהֶם לְקִיּוּם, וַחֲצִי שֶׁנִּכְנְסוּ לְמַטָּה. אֵלּוּ עוֹלִים וְאֵלּוּ יוֹרְדִים. כֵּיוָן שֶׁעָלוּ בַּעֲלִיַּת הַיָּד, עָמַד הַמִּשְׁקָל בְּדֶרֶךְ יָשָׁר וְלֹא סָטָה לְיָמִין וְלֹא לִשְׂמֹאל. זֶהוּ שֶׁכָּתוּב (ישעיה מ) מִי מָדַד בְּשָׁעֳלוֹ מַיִם וְגוֹ'.</p>\n<p>הַכֹּל הָיָה בָּאָרֶץ נִסְתָּר וְלֹא הִתְגַּלָּה, וְכֹחַ וְתֹקֶף וּמַיִם קְפוּאִים בְּתוֹכָהּ, וְלֹא זָרְמוּ וְלֹא הִתְפַּשְּׁטוּ, עַד שֶׁהֵאִיר עָלֶיהָ הָאוֹר שֶׁלְּמַעְלָה, וְהָאוֹר הִכָּה בַּקְּרִישָׁה וְהִפְשִׁירוּ צִבְאוֹתֶיהָ. זֶהוּ שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. זֶהוּ אוֹר רִאשׁוֹן עֶלְיוֹן שֶׁהָיָה מִקֹּדֶם לָכֵן.</p>\n<p>וּמִכָּאן יָצְאוּ כָּל הַצְּבָאוֹת וְהַכֹּחוֹת, וְהָאָרֶץ הִתְבַּשְּׂמָה וְהוֹצִיאָה צִבְאוֹתֶיהָ אַחַר כָּךְ. כֵּיוָן שֶׁהֵאִיר (וירד), הָיָה עוֹלֶה אוֹרוֹ מִסּוֹף הָעוֹלָם עַד סוֹף הָעוֹלָם. כְּשֶׁהִסְתַּכֵּל בְּרִשְׁעֵי הָעוֹלָם, נִגְנַז וְנִטְמַן, וְלֹא יָצָא אֶלָּא בִּשְׁבִילָיו הַנִּסְתָּרִים שֶׁלֹּא הִתְגַּלּוּ.</p>"],[9522011065,"<p>וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. שָׁנִינוּ, כָּל חֲלוֹם שֶׁעוֹמֵד בַּקִּיּוּם שֶׁל כִּי טוֹב, שָׁלוֹם הוּא לְמַעְלָה וּלְמַטָּה. רָאָה אוֹתִיּוֹת, כְּפִי דַרְכּוֹ כָּל אֶחָד וְאֶחָד. רָאָה ט' - טוֹב לוֹ, טוֹב לַחֲלוֹמוֹ, שֶׁהֲרֵי הַתּוֹרָה פָּתְחָה בּוֹ כִּי טוֹב. מֵאִיר מִסּוֹף הָעוֹלָם לְסוֹף הָעוֹלָם. ט' טוֹב. טוֹב הוּא טוֹב אוֹר בִּשְׁלֵמוּת.</p>\n<p>ט' תְּשִׁיעִי שֶׁל הַכֹּל. אוֹת שֶׁמֵּאִיר מֵעֶלְיוֹן רֵאשִׁית וְנִכְלָל בּוֹ וְנַעֲשֶׂה בַּסֵּתֶר שֶׁל נְקֻדָּה סוֹד שֶׁל י' שֶׁהִיא נְקֻדָּה אַחַת. ו' מִכֹּחוֹ יָצָא. בּוֹ נַעֲשׂוּ שָׁמַיִם. כְּשֶׁהִסְתַּיֵּם בִּנְקֻדָּה אַחַת וְנִגְנַז פְּנִימָה, הֵאִירָה ב'. מִמֶּנָּה יָצְאוּ עֶלְיוֹן וְתַחְתּוֹן. עֶלְיוֹן טָמִיר. הַתַּחְתּוֹן גָּלוּי בְּסוֹד שֶׁל שְׁנַיִם, וְעוֹמֵד בַּכֹּחַ שֶׁלְּמַעְלָה.</p>\n<p>וְזְהִוּ טוֹ\"ב. שְׁלֹשׁ הָאוֹתִיּוֹת הַלָּלוּ טוֹ\"ב נִכְלְלוּ אַחַר כָּךְ לְצַדִּיק הָעוֹלָם שֶׁכּוֹלֵל הַכֹּל לְמַעְלָה וּלְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (שם ג) אִמְרוּ צַדִּיק כִּי טוֹב. בִּגְלַל שֶׁאוֹר עֶלְיוֹן כָּלוּל בּוֹ, שֶׁכָּתוּב (תהלים קמה) טוֹב ה' לַכֹּל וְרַחֲמָיו עַל כָּל מַעֲשָׂיו. לַכֹּל כָּתוּב, זֶה סְתָם שֶׁל הַדָּבָר בִּשְׁבִיל לְהָאִיר יוֹם אֶחָד שֶׁמֵּאִיר לַכֹּל, עֶלְיוֹן עַל הַכֹּל. עַד כָּאן סְתַם הַדְּבָרִים.</p>"],[9522011066,"<p>בְּרֵאשִׁית בָּרָא אֱלֹהִים - סוֹד שֶׁל רֵאשִׁית עֲרִיסֹתֵכֶם חַלָּה תָּרִימוּ תְרוּמָה. זוֹ חָכְמָה עֶלְיוֹנָה שֶׁהִיא רֵאשִׁית. ב' בֵּית הָעוֹלָם לִהְיוֹת מֻשְׁקֶה מֵאוֹתוֹ נָהָר שֶׁנִּכְנָס בּוֹ, סוֹד הַכָּתוּב וְנָהָר יצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. וְנָהָר - שֶׁכּוֹנֵס אֶת הַכֹּל מֵהָעֹמֶק הָעֶלְיוֹן וְלֹא פוֹסְקִים מֵימָיו לְעוֹלָמִים לְהַשְׁקוֹת אֶת הַגָּן.</p>\n<p>וְאוֹתוֹ עֹמֶק עֶלְיוֹן בַּיִת רִאשׁוֹן, בְּרֵאשִׁית, הִסְתַּיְּמוּ בוֹ הָאוֹתִיּוֹת בִּשְׁבִיל דַּקִּיק אֶחָד שֶׁגָּנוּז בְּתוֹכוֹ. וּמִתּוֹךְ אוֹתוֹ הָעֹמֶק יָצְאוּ שְׁנֵי כֹּחוֹת, שֶׁכָּתוּב אֵת הַשָּׁמַיִם. לֹא כָתוּב שָׁמַיִם אֶלָּא הַשָּׁמַיִם, מִתּוֹךְ אוֹתוֹ עֹמֶק הַנִּסְתָּר מֵהַכֹּל. וְאֵת הָאָרֶץ - סֵתֶר זֶה הוֹצִיא אֶת הָאָרֶץ הַזֹּאת.</p>\n<p>אֲבָל בִּכְלַל שֶׁל הַשָּׁמַיִם הָיְתָה. וְיָצְאוּ כְּאֶחָד דְּבוּקָה בְּצִדּוֹ זֶה בָּזֶה. כְּשֶׁהֵאִיר רֵאשִׁית הַכֹּל, שָׁמַיִם לָקְחוּ אוֹתָהּ וְהוֹשִׁיבוּ אוֹתָהּ בִּמְקוֹמָהּ, שֶׁכָּתוּב וְאֵת הָאָרֶץ. וְאֵת - כְּלַל הָאוֹתִיּוֹת שֶׁהֵם א\"ת.</p>\n<p>כְּשֶׁחָזְרָה הָאָרֶץ לָשֶׁבֶת בִּמְקוֹמָהּ וְנִפְרְדָה מִצַּד הַשָּׁמַיִם, הָיְתָה תוֹהָה וּבוֹהָה לִדָּבֵק בַּשָּׁמַיִם כְּאֶחָד כְּמוֹ (כבתחלה) בַּהַתְחָלָה, מִשּׁוּם שֶׁרָאֲתָה אֶת הַשָּׁמַיִם מְאִירִים וְהִיא חֲשׁוּכָה. עַד שֶׁאוֹר עֶלְיוֹן יָצָא עָלֶיהָ וְהֵאִיר לָהּ, וְשָׁבָה בִּמְקוֹמָהּ לְהִסְתַּכֵּל בַּשָּׁמַיִם פָּנִים בְּפָנִים. וְאָז הִתְתַּקְּנָה הָאָרֶץ וְהִתְבַּשְּׂמָה.</p>\n<p>יָצָא אוֹר בְּצַד יָמִין וְחֹשֶׁךְ בְּצַד שְׂמֹאל, וְהִפְרִידָם אַחַר כָּךְ כְּדֵי לְהִכָּלֵל זֶה בָּזֶה. זֶהוּ שֶׁכָּתוּב וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ. וְאִם תֹּאמַר שֶׁהָיְתָה מַמָּשׁ הַבְדָּלָה - לֹא! אֶלָּא הַיּוֹם בָּא מִצַּד הָאוֹר שֶׁהוּא יָמִין, וְלַיְלָה מִצַּד הַחֹשֶׁךְ שֶׁהוּא שְׂמֹאל, וּכְשֶׁיָּצְאוּ כְּאֶחָד, הִפְרִיד אוֹתָם. וְהַבְדָּלָה הָיְתָה מִצִּדּוֹ לְהִסְתַּכֵּל פָּנִים בְּפָנִים וּלְהִדָּבֵק זֶה בָּזֶה לִהְיוֹת הַכֹּל אֶחָד.</p>\n<p>וְהוּא נִקְרָא יוֹם וְקוֹרֵא לוֹ יוֹם, וְהִיא נִקְרֵאת לַיְלָה, כְּמוֹ שֶׁנֶּאֱמַר וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם וְגוֹ'. מַה זֶּה וְלַחֹשֶׁךְ? זֶהוּ הַחֹשֶׁךְ שֶׁאוֹחֵז אֶת הַלַּיְלָה שֶׁאֵין לָהּ אוֹר מֵעַצְמָהּ (והיא נקראת לילה, שכתוב ולחשך קרא לילה, בגלל שאוחז בה החשך ואין לה אור מעצמה). וְאַף עַל גַּב שֶׁבָּאָה מִצַּד שֶׁל הָאֵשׁ שֶׁהִיא חֹשֶׁךְ. אֲבָל חֹשֶׁךְ, עַד שֶׁמּוּאָר מִצַּד הַיּוֹם, יוֹם מֵאִיר לַלַּיְלָה, וְלַיְלָה לֹא מֵאִיר עַד זְמַן שֶׁכָּתוּב (תהלים קלט) וְלַיְלָה כַּיּוֹם יָאִיר כַּחֲשֵׁכָה כָּאוֹרָה.</p>"],[9522011067,"<p>רַבִּי אֶלְעָזָר קָפַץ בַּתְּחִלָּה וְדָרַשׁ, (שם כט) קוֹל ה' עַל הַמָּיִם אֵל הַכָּבוֹד הִרְעִים ה' עַל מַיִם רַבִּים. קוֹל ה' - זֶה קוֹל עֶלְיוֹן שֶׁמְּמֻנֶּה עַל הַמַּיִם שֶׁשּׁוֹפְעִים מִדַּרְגָּה לְדַרְגָּה עַד שֶׁמִּתְכַּנְּסִים לְמָקוֹם אֶחָד בְּכִנּוּס אֶחָד. אוֹתוֹ קוֹל עֶלְיוֹן שׁוֹלֵחַ אֶת אוֹתָם הַמַּיִם בְּדַרְכָּם, כָּל אֶחָד וְאֶחָד כְּפִי דַרְכּוֹ. כְּמוֹ בַּעַל הַגָּן הַזֶּה שֶׁמְּמֻנֶּה עַל מַיִם לְשָׁלְחָם לְכָל מָקוֹם וּמָקוֹם כָּרָאוּי לוֹ, כָּךְ קוֹל ה' מְמֻנֶּה עַל הַמַּיִם.</p>\n<p>אֵל הַכָּבוֹד הִרְעִים - כְּמוֹ שֶׁנֶּאֱמַר (איוב כו) וְרַעַם גְּבוּרֹתָו מִי יִתְבּוֹנָן. זֶה צַד שֶׁבָּא מִגְּבוּרָה וְיוֹצֵא מִמֶּנּוּ. דָּבָר אַחֵר אֵל הַכָּבוֹד הִרְעִים - זֶה הַיָּמִין שֶׁיּוֹצֵאת מִמֶּנּוּ שְׂמֹאל. ה' עַל מַיִם רַבִּים - ה' זֶה חָכְמָה עֶלְיוֹנָה שֶׁנִּקְרֵאת יוֹ\"ד. עַל מַיִם רַבִּים - עַל אוֹתוֹ עֹמֶק נִסְתָּר שֶׁיּוֹצֵא מִמֶּנּוּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים עז) וּשְׁבִילְךְ בְּמַיִם רַבִּים.</p>"],[9522011068,"<p>רַבִּי שִׁמְעוֹן פֵּרַשׁ אֶת הַמַּחֲלֹקֶת וְאָמַר, פָּתַח הַפָּסוּק וְאָמַר כָּתוּב (שמות כה) לְעֻמַּת הַמִּסְגֶּרֶת תִּהְיֶיןָ הַטַּבָּעֹת (ל) בָתִּים לְבַדִּים. מִי אוֹתָהּ מִסְגֶּרֶת? זֶהוּ מָקוֹם סָגוּר שֶׁלֹּא פָתוּחַ חוּץ מֵאֲשֶׁר בִּשְׁבִיל דַּקִּיק אֶחָד שֶׁנּוֹדָע בִּגְנִיזוּת אֶצְלוֹ, וּבִגְלָלוֹ הִתְמַלֵּא וְרָשַׁם שְׁעָרִים לְהַדְלִיק נֵרוֹת. וּבִגְלַל שֶׁהוּא מָקוֹם גָּנוּז וְנִסְתָּר, נִקְרָא מִסְגֶּרֶת, וְזֶהוּ הָעוֹלָם הַבָּא. וְאוֹתוֹ הָעוֹלָם הַבָּא נִקְרָא מִסְגֶּרֶת.</p>\n<p>תִּהְיֶין הַטַּבָּעֹת - אֵלּוּ טַבָּעוֹת עֶלְיוֹנוֹת שֶׁנֶּאֶחְזוּ זוֹ בָּזוֹ, מַיִם מֵרוּחַ, וְרוּחַ מֵאֵשׁ, וְאֵשׁ מִמַּיִם. כֻּלָּם נֶאֶחְזוּ זוֹ בָּזוֹ וְיוֹצְאִים זוֹ מִזּוֹ בַּטַּבָּעוֹת הַלָּלוּ, וְכֻלָּם מִסְתַּכְּלִים לְאוֹתָהּ מִסְגֶּרֶת, שֶׁבָּהּ נֶאֱחָז לְאוֹתוֹ אוֹר עֶלְיוֹן לְהַשְׁקוֹתָם וְנֶאֱחָזִים בּוֹ.</p>\n<p>בָּתִּים לְבַדִּים - הַטַּבָּעוֹת הַלָּלוּ הֵם עֶלְיוֹנִים, בָּתִּים וּמְקוֹמוֹת לְבַדִּים שֶׁהֵם מֶרְכָּבוֹת שֶׁלְּמַטָּה, בִּגְלַל שֶׁזֶּה בָּא מִצַּד הָאֵשׁ, וְזֶה מִצַּד הַמַּיִם, וְזֶה מִצַּד הָרוּחַ, וְכֵן כֻּלָּם, כְּדֵי לִהְיוֹת מֶרְכָּבָה לָאָרוֹן. וְעַל זֶה, מִי שֶׁמִּתְקָרֵב, מִתְקָרֵב בַּבַּדִּים הַלָּלוּ וְלֹא בְּמַה שֶּׁלְּפָנִים. לֵךְ לֵךְ אוֹמְרִים לְנָזִיר סָבִיב סָבִיב, לַכֶּרֶם אַל תִּתְקָרֵב. פְּרָט לְאֵלּוּ הָרְאוּיִים לְשַׁמֵּשׁ בִּפְנִים, לָהֶם נִתְּנָה רְשׁוּת לְהַעֲלוֹת, לְשַׁמֵּשׁ וְלִקְרַב, וְעַל זֶה כָּתוּב (במדבר א) וְהַזָּר הַקָּרֵב יוּמָת.</p>"],[9522011069,"<p>ב' שֶׁל בְּרֵאשִׁית הִיא גְדוֹלָה. ר' יוֹסֵי שָׁאַל אוֹתוֹ וְאָמַר, שֵׁשֶׁת יְמֵי בְרֵאשִׁית הַלָּלוּ שֶׁשָּׁנִינוּ מָהֵם? אָמַר לוֹ, הַיְנוּ מַה שֶּׁכָּתוּב (תהלים קד) אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע. כְּמוֹ שֶׁהָאֲרָזִים הַלָּלוּ יוֹצְאִים מִן לְבָנוֹן, כָּךְ גַּם אוֹתָם שִׁשָּׁה יָמִים יוֹצְאִים מִן בְּרֵאשִׁית.</p>\n<p>וְשֵׁשֶׁת הַיָּמִים הָעֶלְיוֹנִים הַלָּלוּ, הַפָּסוּק פֵּרַשׁ אוֹתָם, שֶׁכָּתוּב (דברי הימים א כט) לְךְ ה' הַגְּדֻלָּה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְגוֹ'. כִּי כֹל - זֶה צַדִּיק. בַּשָּׁמַיִם - זוֹ תִפְאֶרֶת. וּבָאָרֶץ - זוֹ כְּנֶסֶת יִשְׂרָאֵל, כְּמוֹ תַרְגּוּמוֹ: שֶׁאוֹחֵז בַּשָּׁמַיִם וּבָאָרֶץ. כְּלוֹמַר, שֶׁיְּסוֹד הָעוֹלָם שֶׁנִּקְרָא כֹּ\"ל, הוּא אוֹחֵז בַּתִּפְאֶרֶת שֶׁנִּקְרָא שָׁמַיִם, וּבָאָרֶץ שֶׁנִּקְרֵאת כְּנֶסֶת יִשְׂרָאֵל.</p>\n<p>וְעַל זֶה בְּרֵאשִׁית. ב' רֵאשִׁית הִיא (חכמה, כמו שתרגם יונתן בראשית בחכמה) בִּגְלַל שֶׁהִיא שְׁנִיָּה לַחֶשְׁבּוֹן, וְנִקְרֵאת רֵאשִׁית בִּגְלַל שֶׁכֶּתֶר עֶלְיוֹן זֶה טָמִיר הוּא רִאשׁוֹן. וְעַל שֶׁלֹּא נִכְנַס בַּחֶשְׁבּוֹן, הָרֵאשִׁית הוּא שֵׁנִי. בִּגְלַל זֶה ב' רֵאשִׁית. וְעוֹד, כְּמוֹ שֶׁחָכְמָה עֶלְיוֹנָה הִיא רֵאשִׁית, גַּם כָּךְ חָכְמָה תַחְתּוֹנָה גַּם הִיא רֵאשִׁית, וְלָכֵן אֵין לְהַפְרִיד ב' מִן רֵאשִׁית.</p>\n<p>לִבְרֵאשִׁית קוֹרְאִים לוֹ מַאֲמָר וְכָךְ זֶה. וְשִׁשָּׁה יָמִים יוֹצְאִים מִמֶּנּוּ וְנִכְלָלִים בּוֹ, וְאֵלֶּה נִקְרָאִים כְּמוֹ שֶׁאֵלֶּה הָאֲחֵרִים.</p>\n<p>בָּרָא אֱלֹהִים - זֶהוּ שֶׁכָּתוּב וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. מַה זֶּה לְהַשְׁקוֹת אֶת הַגָּן? לְהַשְׁקוֹתוֹ וּלְקַיֵּם אוֹתוֹ וּלְהִסְתַּכֵּל בּוֹ בְּכָל מַה שֶּׁצָּרִיךְ. אֱלֹהִים - אֱלֹהִים חַיִּים, שֶׁמַּשְׁמָע בְּרֵאשִׁית בָּרָא אֱלֹהִים וַדַּאי עַל יְדֵי אוֹתוֹ נָהָר כְּדֵי לְהוֹצִיא הַכֹּל וּלְהַשְׁקוֹת הַכֹּל.</p>\n<p>אֵת הַשָּׁמַיִם - חִבּוּר זָכָר וּנְקֵבָה כָּרָאוּי. אַחַר כָּךְ בּוֹ נִבְרָא הָעוֹלָם לְמַטָּה, בּוֹ נָתַן כֹּחַ לַכֹּל. אֵ\"ת הַשָּׁמַיִם, שֶׁמַּשְׁמָע שֶׁהַשָּׁמַיִם הוֹצִיאוּ אֶת, בַּכֹּחַ שֶׁל סוֹד אֱלֹהִים חַיִּים אַחַר שֶׁרֵאשִׁית הוֹצִיא אוֹתוֹ.</p>\n<p>כֵּיוָן שֶׁזֶּה הוֹצִיא הַכֹּל, וְהַכֹּל הִתְיַשֵּׁב בִּמְקוֹמוֹ כְּאֶחָד, טַבַּעַת זוֹ הָאַחֲרוֹנָה נֶעֶשְׂתָה רֵאשִׁית, וּבָרֵאשִׁית הַזּוֹ הוֹצִיא אוֹרוֹת עֶלְיוֹנִים, וְהִשְׁרָה אוֹר וְהִתְחִילוּ מַיִם לְהַשְׁפִּיעַ כְּנֶגֶד לְמַטָּה. וְעַל זֶה בְּרֵאשִׁית וַדַּאי בָּרָא אֱלֹהִים. בּוֹ בָּרָא עוֹלָם הַתַּחְתּוֹן, בּוֹ הוֹצִיא מְאוֹרוֹת, בּוֹ נָתַן כֹּחַ לַכֹּל.</p>\n<p>רַבִּי יְהוּדָה אָמַר, עַל זֶה כָּתוּב (ישעיה י) הֲיִתְפָּאֵר הַגַּרְזֶן עַל הַחֹצֵב בּוֹ. הַשֶּׁבַח שֶׁל מִי - לֹא שֶׁל הָאֻמָּן הוּא? כָּךְ בְּרֵאשִׁית הַ את בָּרָא אֱלֹהִים עֶלְיוֹן אֶת הַשָּׁמַיִם - הַשֶּׁבַח שֶׁל מִי? שֶׁל אֱלֹהִים הוּא!</p>\n<p>אָמַר רַבִּי יוֹסֵי, זֶה שֶׁכָּתוּב (דברים ד) אֲשֶׁר לוֹ אֱלֹהִים קְרֹבִים אֵלָיו. קְרֹבִים? קָרוֹב צָרִיךְ לִהְיוֹת! אֶלָּא אֱלֹהִים עֶלְיוֹן. אֱלֹהִים שֶׁל פַּחַד יִצְחָק. אֱלֹהִים אַחֲרוֹן. וּמִשּׁוּם כָּךְ כָּתוּב קְרֹבִים, וּגְבוּרוֹת רַבּוֹת הֵם שֶׁיּוֹצְאִים מֵאֶחָד וְהַכֹּל אֶחָד.</p>\n<p>בְּרֵאשִׁי\"ת בָּרָ\"א, רֶמֶז לְכֶתֶ\"ר חָכְמָ\"ה. אֱלֹהִים רוֹמֵז לְבִינָ\"ה. אֵ\"ת רוֹמֵז לִגְדֻלָּה וּגְבוּרָ\"ה. הַשָּׁמַיִ\"ם זֶהוּ תִּפְאֶרֶ\"ת. וְאֵ\"ת רוֹמֵז לְנֶצַ\"ח הוֹ\"ד יְסוֹ\"ד. הָאָרֶ\"ץ רוֹמֵז לְמַלְכוּ\"ת: עד כאן התוספתא.</p>"],[9522011070,"<p>וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. (ויאמר אלהים, למי הוא אומר? אינו אומר אלא לאחרים, יהי אור לעולם הזה, ויהי אור לעולם הבא). וְזֶהוּ הָאוֹר שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בַּתְּחִלָּה, וְהוּא אוֹר הָעַיִן, וְהוּא אוֹר שֶׁהֶרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְאָדָם הָרִאשׁוֹן וְהָיָה רוֹאֶה בּוֹ מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם, וְהוּא אוֹר שֶׁהֶרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְדָוִד, וְהָיָה מְשַׁבֵּחַ וְאוֹמֵר (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ. וְהוּא הָאוֹר שֶׁהֶרְאָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה וְרָאָה בּוֹ מִגִּלְעָד וְעַד דָּן.</p>\n<p>וּבְשָׁעָה שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיַּעַמְדוּ שְׁלֹשָׁה דוֹרוֹת שֶׁל רְשָׁעִים, וְהֵם, דּוֹר אֱנוֹשׁ, וְדוֹר הַמַּבּוּל, וְדוֹר הַפְּלַגָּה - גָּנַז אוֹתוֹ כְּדֵי שֶׁלֹּא יִשְׁתַּמְּשׁוּ בוֹ, וְנָתַן אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה וְהִשְׁתַּמֵּשׁ בּוֹ שְׁלֹשָׁה חֳדָשִׁים שֶׁנִּשְׁאֲרוּ לוֹ מִיּוֹם עִבּוּרוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שמות ב) וַתִּצְפְּנֵהוּ שְׁלֹשָׁה יְרָחִים.</p>\n<p>וְאַחַר שְׁלֹשָׁה יְרָחִים נִכְנַס לִפְנֵי פַרְעֹה, לָקַח אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מִמֶּנּוּ, עַד שֶׁעָמַד עַל הַר סִינַי לְקַבֵּל אֶת הַתּוֹרָה, וְהֶחֱזִיר לוֹ אוֹתוֹ הָאוֹר וְהִשְׁתַּמֵּשׁ בּוֹ כָּל יָמָיו. וְלֹא יָכְלוּ בְּנֵי יִשְׂרָאֵל לִקְרַב אֵלָיו, עַד שֶׁנָּתַן מַסְוֶה עַל פָּנָיו, כְּמוֹ שֶׁנֶּאֱמַר (שם לד) וַיִּירְאוּ מִגֶּשֶׁת אֵלָיו. וְהִתְעַטֵּף בּוֹ כְּטַלִּית. זֶהוּ שֶׁכָּתוּב (תהלים קד) עֹטֶה אוֹר כַּשַּׂלְמָה.</p>\n<p>יְהִי אוֹר וַיְהִי אוֹר. כָּל מַה שֶּׁנֶּאֱמַר בּוֹ וַיְהִי - הוּא בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. אָמַר רַבִּי יִצְחָק, אוֹר שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂה בְרֵאשִׁית, הָיָה עוֹלֶה אוֹרוֹ מִסּוֹף הָעוֹלָם וְעַד סוֹף הָעוֹלָם וְנִגְנַז.</p>\n<p>מָה הַטַּעַם שֶׁנִּגְנַז? כְּדֵי שֶׁלֹּא יֵהָנוּ מִמֶּנּוּ רִשְׁעֵי הָעוֹלָם, וְהָעוֹלָמוֹת לֹא יֵהָנוּ בִּגְלָלָם. וְהוּא שָׁמוּר לַצַּדִּיקִים, לַצַּדִּיק דַּוְקָא, שֶׁכָּתוּב (תהלים צז) אוֹר זָרֻעַ לַצַּדִּיק וּלְיִשְׁרֵי לֵב שִׂמְחָה. וְאָז יִתְבַּשְּׂמוּ הָעוֹלָמוֹת וְיִהְיוּ כֻלָּם אֶחָד. וְעַד הַיּוֹם שֶׁיִּהְיֶה הָעוֹלָם הַבָּא, הוּא נִסְתָּר וְגָנוּז.</p>\n<p>אוֹתוֹ אוֹר יָצָא מִתּוֹךְ הַחֹשֶׁךְ שֶׁנֶּחְקָק בַּמַּטֶּה שֶׁנִּסְתָּר מִכֹּל, עַד שֶׁמֵּאוֹתוֹ אוֹר שֶׁנִּגְנַז, נֶחְקַק בִּשְׁבִיל אֶחָד טָמִיר לַחֹשֶׁךְ שֶׁלְּמַטָּה. וְהָאוֹר שָׁרוּי בּוֹ. מִיהוּ הַחֹשֶׁךְ שֶׁלְּמַטָּה? אוֹתוֹ שֶׁנִּקְרָא לַיְלָה, שֶׁכָּתוּב בּוֹ וְלַחֹשֶׁךְ קָרָא לָיְלָה.</p>\n<p>וְעַל זֶה שָׁנִינוּ, מַה זֶּה שֶׁכָּתוּב (איוב יב) מְגַלֶּה עֲמֻקוֹת מִנִּי חֹשֶׁךְ? רַבִּי יוֹסֵי אוֹמֵר, אִם תֹּאמַר מֵחֹשֶׁךְ נִסְתָּר הִתְגַּלּוּ, הֲרֵי רָאִינוּ שֶׁנִּסְתָּרִים הֵם כָּל אוֹתָם כְּתָרִים עֶלְיוֹנִים וְקוֹרְאִים עֲמֻקּוֹת. מַהוּ מְגַלֶּה? אֶלָּא כָּל אוֹתָם נִסְתָּרִים עֶלְיוֹנִים לֹא הִתְגַּלּוּ אֶלָּא מִתּוֹךְ אוֹתוֹ חֹשֶׁךְ שֶׁהוּא בְּסוֹד הַלַּיְלָה (והכל יהיה אחד בסוד של והיה אור הלבנה כאור החמה בדרגה אחת, ועד היום שיבא הוא גנוז וטמון). בֹּא רְאֵה, כָּל אוֹתָם עֳמָקִים נִסְתָּרִים שֶׁיּוֹצְאִים מִתּוֹךְ מַחֲשָׁבָה וְקוֹל לוֹקֵחַ אוֹתָם, לֹא מִתְגַּלִּים עַד שֶׁדִּבּוּר מְגַלֶּה אוֹתָם. מָה הַדָּבָר? הַיְנוּ דִבּוּר.</p>\n<p>וְזְהִ הַדִבּוּר נִקְרָא שַׁבָּת, וּבִגְלַל שֶׁשַׁבָּת נִקְרָא דִּבּוּר, דִּבּוּר שֶׁל חֹל אָסוּר בְּשַׁבָּת. (וכך היה עושה רבי שמעון, כשהיה רואה את אמו שהיתה מדברת, היה אומר לה, ' אמא, שתקי, שבת היום ואסור,) בִּגְלַל שֶׁדִּבּוּר זֶה צָרִיךְ לִשְׁלֹט וְלֹא אַחֵר. וְדִבּוּר זֶה שֶׁהוּא בָּא מִצַּד הַחֹשֶׁךְ, מְגַלֶּה עֲמֻקּוֹת מִתּוֹכוֹ. וּמַשְׁמָע מִנִּי חֹשֶׁךְ, אוֹתוֹ שֶׁבָּא מִצַּד הַחֹשֶׁךְ, שֶׁכָּתוּב מִנִּי דַּוְקָא.</p>\n<p>אָמַר רַבִּי יִצְחָק, אִם כָּךְ, מַהוּ שֶׁכָּתוּב וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ? אָמַר לוֹ, אוֹר הוֹצִיא יוֹם וְחֹשֶׁךְ הוֹצִיא לַיְלָה, אַחַר כָּךְ חִבֵּר אוֹתָם כְּאֶחָד וְהָיוּ אֶחָד, שֶׁכָּתוּב וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. שֶׁלַּיְלָה וָיוֹם נִקְרָאִים אֶחָד. וְזֶה שֶׁכָּתוּב וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ, (שהפריד מחלקת) זוֹ בַּזְּמַן שֶׁל הַגָּלוּת שֶׁנִּמְצָא פֵרוּד.</p>\n<p>אָמַר רַבִּי יִצְחָק, עַד כָּאן זָכָר בָּאוֹר וּנְקֵבָה בַּחֹשֶׁךְ. אַחַר כָּךְ מִתְחַבְּרִים כְּאֶחָד לִהְיוֹת אֶחָד. בַּמֶּה נִפְרָדִים לְהַכִּיר בֵּין אוֹר וּבֵין חֹשֶׁךְ? מִתְפָּרְדוֹת הַדְּרָגוֹת, וּשְׁנֵיהֶם הֵם כְּאֶחָד, שֶׁהֲרֵי אֵין אוֹר אֶלָּא בַּחֹשֶׁךְ, וְאֵין חֹשֶׁךְ אֶלָּא בָּאוֹר. וְאַף עַל גַּב שֶׁהֵם אֶחָד, נִפְרָדִים בִּגְוָנִים, וְעִם כָּל זֶה הֵם אֶחָד, שֶׁכָּתוּב יוֹם אֶחָד.</p>"],[9522011071,"<p>רַבִּי שִׁמְעוֹן אָמַר, עַל הַבְּרִית הָעוֹלָם נִבְרָא וְהִתְקַיֵּם, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. מִי הַבְּרִית? זֶה צַדִּיק יְסוֹד הָעוֹלָם, שֶׁהוּא סוֹד שֶׁל זָכוֹר. וְעַל זֶה הָעוֹלָם עוֹמֵד בִּבְרִית יוֹמָם וָלַיְלָה כְּאֶחָד, שֶׁכָּתוּב אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי. חֻקּוֹת שָׁמַיִם וָאָרֶץ הֵם שֶׁשּׁוֹפְעִים וְיוֹצְאִים מֵעֵדֶן הָעֶלְיוֹן.</p>\n<p>פָּתַח וְאָמַר, (שופטים ה) מִקּוֹל מְחַצְצִים בֵּין מַשְׁאַבִּים שָׁם יְתַנּוּ צִדְקוֹת ה' וְגוֹ'. מִקּוֹל מְחַצְצִים - זֶה קוֹל יַעֲקֹב. מְחַצְצִים - כְּמוֹ שֶׁנֶּאֱמַר (שמואל א יז) אִישׁ הַבֵּינַיִם. בֵּין מַשְׁאַבִּים - שֶׁהוּא יוֹשֵׁב בֵּין אוֹתָם שֶׁשּׁוֹאֲבִים מַיִם מִלְמַעְלָה, וְהוּא נוֹטֵל בִּשְׁנֵי צְדָדִים וְכוֹלֵל אוֹתָם בְּתוֹכוֹ.</p>\n<p>שָׁם יְתַנּוּ צִדְקוֹת ה' - שָׁם הוּא מְקוֹם הָאֱמוּנָה לְהִתְדַּבֵּק. שָׁם יְתַנּוּ צִדְקוֹת ה' - שָׁם יוֹנְקִים צִדְקוֹת ה' וְשׁוֹאֲבִים. צִדְקֹת פִּרְזוֹנוֹ בְּיִשְׂרָאֵל - זֶה צַדִּיק הָעוֹלָם שֶׁהוּא בְּרִית הַקֹּדֶשׁ, וְהוּא שׁוֹאֵב וְנוֹטֵל הַכֹּל וּמְפַזֵּר לַיָּם הַגָּדוֹל אוֹתָם מַיִם עֶלְיוֹנִים. בְּיִשְׂרָאֵל - שֶׁיִּשְׂרָאֵל יָרְשׁוּ בְּרִית הַזֶּה, וְנָתַן לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא יְרֻשַּׁת עוֹלָמִים.</p>\n<p>כֵּיוָן שֶׁיִּשְׂרָאֵל עָזְבוּ אוֹתוֹ, שֶׁהָיוּ מָלִים וְלֹא פוֹרְעִים, מַה כָּתוּב? (שופטים ה) אָז יָרְדוּ לַשְּׁעָרִים עַם ה'. יָרְדוּ לַשְּׁעָרִים - אוֹתָם שַׁעֲרֵי צֶדֶק הָיוּ יוֹשְׁבִים לַשְּׁעָרִים וְלֹא נִכְנָסִים פְּנִימָה. וּבְאוֹתוֹ זְמַן כָּתוּב (שופטים ב) וַיַּעַזְבוּ בְּנֵי יִשְׂרָאֵל אֶת ה' וְגוֹ'. עַד שֶׁבָּאָה דְבוֹרָה וְהִכְרִיחָה אוֹתָם בָּזֶה, כְּמוֹ שֶׁנֶּאֱמַר (שם ה) בִּפְרֹעַ פְּרָעוֹת בְּיִשְׂרָאֵל.</p>\n<p>וְעַל זֶה כָּתוּב חָדְלוּ פְרָזוֹן בְּיִשְׂרָאֵל. חָדְלוּ פְרָזוֹן - זֶהוּ פִרְזוֹנוֹ שֶׁאָמַרְנוּ. חָדְלוּ פְרָזוֹן - בְּרִית הַקֹּדֶשׁ שֶׁלֹּא פָרְעוּ. (שם) עַד שַׁקַּמְתִּי דְּבוֹרָה שַׁקַּמְתִּי אֵם בְּיִשְׂרָאֵל. מַה זֶּה אֵם? אֶלָּא אֲנִי הוֹרַדְתִּי מַיִם עֶלְיוֹנִים מִלְמַעְלָה לְקַיֵּם אֶת הָעוֹלָמוֹת. בְּיִשְׂרָאֵל - סְתָם לְמַעְלָה וּלְמַטָּה. לְהַרְאוֹת שֶׁהָעוֹלָם לֹא מִתְקַיֵּם אֶלָּא עַל בְּרִית זוֹ. וְסוֹד הַכֹּל - (משלי י) וְצַדִּיק יְסוֹד עוֹלָם כָּתוּב.</p>\n<p>שְׁלשָה יוֹצְאִים מֵאֶחָד. אֶחָד בִּשְׁלֹשָׁה עוֹמֵד נִכְנָס בֵּין שְׁנַיִם. שְׁנַיִם מֵינִיקִים לְאֶחָד. אֶחָד מֵינִיק לְכַמָּה צְדָדִים, וְאָז הַכֹּל אֶחָד. זֶהוּ שֶׁכָּתוּב וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. יוֹם שֶׁל עֶרֶב וָבקֶר כּוֹלֵל כְּאֶחָד, הַיְנוּ סוֹד שֶׁל בְּרִית יוֹמָם וָלַיְלָה, וּבוֹ הַכֹּל אֶחָד.</p>\n<p>שָׁנִינוּ, מָל וְלֹא פָרַע אֶת הַמִּילָה, כְּאִלּוּ לֹא מָל. בִּגְלַל שֶׁשְּׁתֵּי דְרָגוֹת הֵן: מִילָה וּפְרִיעָה. זָכוֹר וְשָׁמוֹר. צַדִּיק וְצֶדֶק. זָכָר וּנְקֵבָה. אוֹת בְּרִית זֶה יוֹסֵף, וּבְרִית זוֹ רָחֵל, וְצָרִיךְ לְחַבְּרָם. וּבַמֶּה מְחַבֵּר אוֹתָם? כְּשֶׁהוּא גוֹזֵר וּפוֹרֵעַ. וּמִי שֶׁגּוֹזֵר וְלֹא פוֹרֵעַ, כְּאִלּוּ עָשׂוּ בֵינֵיהֶם פֵּרוּד. (עד כאן התוספתא).</p>"],[9522011072,"<p>וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם. רַבִּי יְהוּדָה אָמַר, שִׁבְעָה רְקִיעִים הֵם לְמַעְלָה, וְכֻלָּם עוֹמְדִים בִּקְדֻשָּׁה עֶלְיוֹנָה, וְהַשֵּׁם הַקָּדוֹשׁ נִתְקָן בָּהֶם. וְרָקִיעַ זֶה הוּא בְּאֶמְצַע הַמַּיִם.</p>\n<p>רָקִיעַ זֶה עוֹמֵד עַל גַּבֵּי חַיּוֹת אֲחֵרוֹת, וְהוּא מַפְרִיד בֵּין מַיִם עֶלְיוֹנִים לְמַיִם תַּחְתּוֹנִים. וּמַיִם תַּחְתּוֹנִים קוֹרְאִים לָעֶלְיוֹנִים. וּמֵהָרָקִיעַ הַזֶּה שׁוֹתִים אוֹתָם. זֶהוּ שֶׁמַּפְרִיד בֵּינֵיהֶם, מִשּׁוּם שֶׁכָּל הַמַּיִם כְּלוּלִים בּוֹ. וְאַחַר כָּךְ מוֹרִיד אוֹתָם לַחַיּוֹת הַלָּלוּ וְשׁוֹאֲבִים מִשָּׁם.</p>\n<p>כָּתוּב (שיר ד) גַּן נָעוּל אֲחוֹתִי כַלָּה גַּל נָעוּל מַעְיָן חָתוּם. גַּן נָעוּל - שֶׁהַכֹּל נִסְתָּר בּוֹ, שֶׁהַכֹּל נִכְלָל בּוֹ. גַּל נָעוּל - שֶׁאוֹתוֹ נָהָר שׁוֹפֵעַ וְיוֹצֵא וְנִכְנָס בּוֹ וְכוֹלֵל וְלֹא מוֹצִיא, וְהַמַּיִם קוֹפְאִים בּוֹ וְעוֹמְדִים. מָה הַטַּעַם? בִּגְלַל שֶׁרוּחַ צָפוֹן נוֹשֶׁבֶת בְּאוֹתָם הַמַּיִם וְקוֹפְאִים, וְלֹא יוֹצְאִים הַחוּצָה עַד שֶׁנַּעֲשֶׂה קֶרַח, וְאִלְמָלֵא צַד הַדָּרוֹם שֶׁמְּשַׁבֵּר כֹּחוֹ שֶׁל הַקֶּרַח הַזֶּה, לֹא יֵצְאוּ מִמֶּנּוּ מַיִם לְעוֹלָמִים.</p>\n<p>וּמַרְאֶה אוֹתוֹ רָקִיעַ עֶלְיוֹן כְּמַרְאֵה הַקֶּרַח הַזֶּה שֶׁקּוֹפֵא וּמַכְנִיס בְּתוֹכוֹ כָּל אוֹתָם הַמַּיִם, כָּךְ אוֹתוֹ עֶלְיוֹן שֶׁעָלָיו כּוֹנֵס כָּל אוֹתָם מַיִם, וּמַפְרִיד בֵּין מַיִם עֶלְיוֹנִים לְמַיִם תַּחְתּוֹנִים. וְזֶה שֶׁאָמַרְנוּ יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם. בָּאֶמְצַע. לֹא כָּךְ, אֶלָּא כָּתוּב יְהִי. אוֹתוֹ שֶׁהָיָה מִמֶּנּוּ, בְּאֶמְצַע הַמַּיִם הָיָה, וְהוּא לְמַעְלָה שֶׁעוֹמֵד עַל רֹאשׁ הַחַיּוֹת.</p>\n<p>אָמַר רַבִּי יִצְחָק, יֵשׁ קְרוּם בְּאֶמְצַע מֵעָיו שֶׁל בֶּן אָדָם שֶׁמַּפְסִיק מִלְּמַטָּה לְמַעְלָה, וְשׁוֹאֵב מִלְמַעְלָה וְנוֹתֵן לְמַטָּה. כָּךְ כָּזֶה הָרָקִיעַ הוּא בָּאֶמְצַע, וְעוֹמֵד עַל אוֹתָן הַחַיּוֹת שֶׁלְּמַטָּה, וְהוּא מַפְרִיד בֵּין מַיִם עֶלְיוֹנִים לַתַּחְתּוֹנִים. בּא רְאֵה, אוֹתָם מַיִם הָרוּ וְהוֹלִידוּ חֹשֶׁךְ, וְעַל סוֹד זֶה כָּתוּב (שמות כו) וְהִבְדִּילָה הַפָּרֹכֶת לָכֶם בֵּין הַקֹּדֶשׁ וּבֵין קֹדֶשׁ הַקְּדָשִׁים.</p>"],[9522011073,"<p>רַבִּי אַבָּא פָּתַח, (תהלים קד) הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו וְגוֹ'. בַּמַּיִם - אֵלּוּ מַיִם עֶלְיוֹנִים שֶׁל הַכֹּל שֶׁבָּהֶם תִּקֵּן בַּיִת, כְּמוֹ שֶׁנֶּאֱמַר (משלי כד) בְּחָכְמָה יִבָּנֶה בָּיִת וּבִתְבוּנָה יִתְכּוֹנָן.</p>\n<p>הַשָּׂם עָבִים רְכוּבוֹ - רַבִּי יֵיסָא הַזָּקֵן חִלֵּק עָבִים עָ\"ב יָ\"ם. עָב שֶׁהוּא חֹשֶׁךְ, שְׂמֹאל שֶׁעוֹמֵד עַל יָם זֶה. הַמְהַלֵּךְ עַל כַּנְפֵי רוּחַ - זוּ רוּחַ שֶׁל הַמִּקְדָּשׁ הָעֶלְיוֹן, וְזֶה סוֹד (שמות כה) שְׁנַיִם כְּרֻבִים זָהָב. כָּתוּב (תהלים יח) וַיִּרְכַּב עַל כְּרוּב וַיָּעֹף וַיֵּדֶא עַל כַּנְפֵי רוּחַ. וַיִּרְכַּב עַל כְּרוּב אֶחָד, אַחַר כָּךְ נִגְלָה עַל כַּנְפֵי רוּחַ. וְעַד שֶׁזֶּה מִתְעוֹרֵר, לֹא מִתְגַּלֶּה בָזֶה.</p>\n<p>רַבִּי יוֹסֵי אָמַר, כָּתוּב (איוב כח) וּמַיִם תִּכֵּן בְּמִדָּה. בְּמִדָּה מַמָּשׁ הִתְקִין אוֹתָם כְּשֶׁהִגִּיעוּ לְתוֹכָהּ, וְהֵם תִּקּוּן הָעוֹלָם כְּשֶׁהִגִּיעוּ מִצַּד הַגְּבוּרָה. אָמַר רַבִּי אַבָּא, כָּךְ הָיוּ הָרִאשׁוֹנִים אוֹמְרִים כְּשֶׁהָיוּ מַגִּיעִים לַמָּקוֹם הַזֶּה, מְרַחֲשׁוֹת שִׂפְתֵי הַחֲכָמִים וְלֹא אוֹמְרִים דָּבָר, כְּדֵי שֶׁלֹּא יֵעָנְשׁוּ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, אוֹת רִאשׁוֹנָה שֶׁל הָאוֹתִיּוֹת הָיְתָה מְשׁוֹטֶטֶת עַל פְּנֵי קֶשֶׁר זַךְ, וּמִתְעַטֶּרֶת מִלְּמַטָּה וּמִלְמַעְלָה, וְעוֹלָה וְיוֹרֶדֶת, וּמַיִם נֶחְקָקִים בַּחֲקִיקָתָם וּמִתְיַשְּׁבִים בִּמְקוֹמָם, וְנִכְלְלוּ אֶחָד בְּאֶחָד. וְכֵן כָּל הָאוֹתִיּוֹת כֻּלָּן כְּלוּלוֹת זוֹ בְּזוֹ וּמִתְעַטְּרוֹת זוֹ בְּזוֹ, עַד שֶׁנִּבְנֶה עֲלֵיהֶן בִּנְיָן וִיסוֹד.</p>\n<p>וּכְשֶׁנִּבְנוּ כֻלָּם וְהִתְעַטְּרוּ, הָיוּ מַיִם עֶלְיוֹנִים מִתְעָרְבִים בְּמַיִם תַּחְתּוֹנִים, וְהוֹצִיאוּ בַיִת שֶׁל הָעוֹלָם (ועל זה הוציאו שני אורות, אחד שנקרא ארץ, ומאור שנקרא שמים), וְעַל זֶה ב' נִרְאֵית בָּרֹאשׁ, וּמַיִם עוֹלִים וְיוֹרְדִים עַד שֶׁהָיָה הָרָקִיעַ הַזֶּה שֶׁהִפְרִיד אוֹתָם. וּמַחֲלֹקֶת הָיְתָה בַּשֵּׁנִי, שֶׁבּוֹ נִבְרָא גֵיהִנֹּם, שֶׁהוּא אֵשׁ שֶׁדּוֹלֵק, כְּמוֹ שֶׁנֶּאֱמַר (דברים ד) אֵשׁ אוֹכְלָה הוּא, וְעָתִיד לִשְׁרוֹת עַל רֹאשׁ הָרְשָׁעִים.</p>\n<p>אָמַר רַבִּי יְהוּדָה, מִכָּאן כָּל מַחֲלֹקֶת שֶׁהִיא לְשֵׁם שָׁמַיִם סוֹפָהּ לְהִתְקַיֵּם. שֶׁהֲרֵי כָּאן מַחֲלֹקֶת שֶׁהִיא לְשֵׁם שָׁמַיִם הָיְתָה, וְהַשָּׁמַיִם בָּזֶה הִתְקַיְּמוּ. לְאַחַר זֶה שֶׁכָּתוּב וַיִּקְרָא אֱלֹהִים לָרָקִיעַ שָׁמָיִם וְגוֹ'. בַּהַבְדָּלוֹת שֶׁבַּמַּעֲלוֹת, בְּמִדָּתָם מְצוּיִים וְהִתְקַיְּמוּ, שֶׁהֲרֵי שָׁנִינוּ, כָּתוּב (שמות כו) וְהִבְדִּילָה הַפָּרֹכֶת לָכֶם בֵּין הַקֹּדֶשׁ וּבֵין קֹדֶשׁ הַקְּדָשִׁים דַּוְקָא, שֶׁהֲרֵי הוּא רָקִיעַ שֶׁמַּפְרִיד בְּתוֹךְ הָאֶמְצַע.</p>\n<p>בֹּא רְאֵה, כָּתוּב אַחַר כָּךְ יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד. מִתַּחַת הַשָּׁמַיִם מַמָּשׁ. אֶל מָקוֹם אֶחָד - לְמָקוֹם שֶׁנִּקְרָא אֶחָד, וְהוּא יָם תַּחְתּוֹן, שֶׁהֲרֵי הוּא מַשְׁלִים לְאֶחָד, וּבִלְעָדָיו לֹא נִקְרָא אֶחָד. וּמַשְׁמָע שֶׁכָּתוּב יִקָּווּ, שֶׁבּוֹ כָּל הַמַּיִם מִתְכַּנְּסִים, כְּמוֹ שֶׁנֶּאֱמַר (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם.</p>\n<p>רַבִּי יֵיסָא אָמַר, אֶל מָקוֹם אֶחָד - זֶהוּ מָקוֹם שֶׁכָּתוּב בּוֹ (ישעיה נד) וּבְרִית שְׁלוֹמִי לֹא תָמוּט. שֶׁהֲרֵי הוּא נוֹטֵל הַכֹּל וְזוֹרֵק בַּיָּם, וּבוֹ מִתְתַּקֶּנֶת הָאָרֶץ, שֶׁכָּתוּב וְתֵרָאֶה הַיַּבָּשָׁה. זוֹהִי אֶרֶץ, כְּמוֹ שֶׁנֶּאֱמַר וַיִּקְרָא אֱלֹהִים לַיַּבָּשָׁה אֶרֶץ.</p>\n<p>לָמָּה נִקְרֵאת יַבָּשָׁה? אָמַר רַבִּי יִצְחָק, הַיְנוּ מַה שֶּׁכָּתוּב (דברים טז) לֶחֶם עֹנִי. לֶחֶם עָנִי כָּתוּב. וּבִגְלַל שֶׁהוּא לֶחֶם עָנִי נִקְרָא יַבָּשָׁה, וְשׁוֹאֵב בְּתוֹכָהּ כָּל מֵימֵי הָעוֹלָם, וְהִיא הָיְתָה יַבָּשָׁה, עַד שֶׁמָּקוֹם זֶה מְמַלֵּא אוֹתָהּ, וְאָז שׁוֹפְעִים מַיִם דֶּרֶךְ אוֹתָם הַמְּקוֹרוֹת.</p>\n<p>וּלְמִקְוִהִ הַמַּיִם קָרָא יַמִּים - זֶהוּ בֵּית כִּנּוּס הַמַּיִם שֶׁלְּמַעְלָה, שֶׁשָּׁם כָּל הַמַּיִם מִתְכַּנְּסִים וּמִשָּׁם שׁוֹפְעִים וְיוֹצְאִים. אָמַר רַבִּי חִיָּיא, מִקְוֵה הַמַּיִם זֶה צַדִּיק. שֶׁכְּשֶׁמַּגִּיעַ לְמִקְוֵה הַמַּיִם, כָּתוּב וַיַּרְא אֱלֹהִים כִּי טוֹב, וְכָתוּב (ישעיה ג) אִמְרוּ צַדִּיק כִּי טוֹב. (וכן אור ראשון נקרא טוב, וכן בכלם כתוב כי טוב, פרט ליום השני שלא כתוב בו כי טוב) רַבִּי יוֹסֵי אָמַר, יִשְׂרָאֵל הוּא מִקְוֶה, שֶׁכָּתוּב (ירמיה יז) מִקְוֵה יִשְׂרָאֵל ה'.</p>\n<p>רַבִּי חִיָּיא אָמַר, זֶה צַדִּיק, הַיְנוּ מַה שֶּׁכָּתוּב קָרָא יַמִּים. מִשּׁוּם שֶׁנְּחָלִים וּמַעְיָנוֹת וּנְהָרוֹת, אֶת כֻּלָּם הוּא נוֹטֵל, וְהוּא הַמָּקוֹר שֶׁל הַכֹּל וְהוּא נוֹטֵל הַכֹּל. מִשּׁוּם כָּךְ יַמִּים. וְעַל זֶה וַיַּרְא אֱלֹהִים כִּי טוֹב, וְכָתוּב (ישעיה יג) אִמְרוּ צַדִּיק כִּי טוֹב.</p>\n<p>וּמִשּׁוּם שֶׁהוּא נִרְשַׁם, הִפְרִיד בֵּין יוֹם רִאשׁוֹן לַשְּׁלִישִׁי וְלֹא נֶאֱמַר כִּי טוֹב בֵּינֵיהֶם, שֶׁהֲרֵי בַּיּוֹם הַשְּׁלִישִׁי עָשְׂתָה הָאָרֶץ פֵּרוֹת מִכֹּחַ הַצַּדִּיק הַזֶּה, שֶׁכָּתוּב וַיֹּאמֶר אֱלֹהִים תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב מַזְרִיעַ זֶרַע עֵץ פְּרִי. מַה זֶּה עֵץ פְּרִי? זֶה עֵץ הַדַּעַת טוֹב וָרָע, שֶׁהוּא עוֹשֶׂה אִבִּים וּפֵרוֹת. עֹשֶׂה פְּרִי - זֶה צַדִּיק יְסוֹד עוֹלָם.</p>\n<p>לְמִינוֹ - שֶׁל כָּל בְּנֵי אָדָם שֶׁיֵּשׁ לָהֶם רוּחַ קְדוֹשָׁה, שֶׁהוּא פְּרִי שֶׁאוֹתוֹ אִילָן רוֹשֵׁם בָּהֶם רִשּׁוּם לְמִינוֹ. וּמָה הָרֹשֶׁם? זֶהוּ בְּרִית קֹדֶשׁ בְּרִית שָׁלוֹם. וּבְנֵי הָאֱמוּנָה לְמִינוֹ, לְמִינוֹ נִכְנָסִים וְלֹא נִפְרָדִים מִמֶּנּוּ, וְצַדִּיק עוֹשֶׂה פְּרִי הוּא. וְאוֹתוֹ אִילָן מִתְעַבֵּר וּמוֹצִיא אוֹתוֹ פְּרִי לְמִינוֹ, לְמִינוֹ שֶׁל אוֹתוֹ עוֹשֶׂה פְּרִי שֶׁיִּהְיֶה כְמוֹתוֹ.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁדּוֹמֶה לְאִמּוֹ וּלְאָבִיו, וְעַל כֵּן רֹשֶׁם הַקָּדוֹשׁ בַּיּוֹם הַשְּׁמִינִי כְּדֵי שֶׁיִּדְמֶה לְאִמּוֹ (בגלל שהיא דרגה שמינית, ואותה נפש שפרחה ממנה צריכה להראות לפניה לשמונה ימים). וּכְשֶׁנִּפְרָע וּמִתְגַּלֶּה רֹשֶׁם הַקָּדוֹשׁ כְּדֵי שֶׁיִּדְמֶה לְאָבִיו. וְעַל זֶה עֵץ פְּרִי - זוֹ אֵם. עֹשֶׂה פְּרִי - זוֹ בְּרִית קֹדֶשׁ אָבִיו. לְמִינוֹ - שֶׁיִּדְמֶה לוֹ וְיֵרָשֵׁם בּוֹ.</p>\n<p>אֲשֶׁר זַרְעוֹ בוֹ עַל הָאָרֶץ - זַרְעוֹ בוֹ? זֶרַע בּוֹ צָרִיךְ לִהְיוֹת! מַה זֶּה זַרְעוֹ בוֹ? אֶלָּא זֶרַע וָא\"ו בּוֹ. עַל הָאָרֶץ - כָּךְ הוּא וַדַּאי, שֶׁהֲרֵי אוֹתוֹ זֶרַע זָרַק עַל הָאָרֶץ. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהֵם קְדוֹשִׁים וְדוֹמִים לִקְדוֹשִׁים, וְעַל זֶה וַדַּאי כָּתוּב (ישעיה סח) וְעַמֵּךְ כֻּלָּם צַדִּיקִים. כֻּלָּם צַדִּיקִים וַדַּאי, שֶׁהֲרֵי מֵאֵלֶּה יָצְאוּ וּלְאֵלֶּה דּוֹמִים. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>אָמַר רַבִּי חִיָּיא, כָּתוּב (ירמיה י ונא) עֹשֵׂה אֶרֶץ בְּכֹחוֹ. מַה זֶּה עֹשֵׂה אֶרֶץ? (בכחו? עשה ארץ צריך להיות, אלא עושה ודאי תמיד, ומתקן הקדוש ברוך הוא את הארץ הזו) זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה. בְּכֹחוֹ - זֶה צַדִּיק. מֵכִין תֵּבֵל בְּחָכְמָתוֹ. תֵּבֵל - זוֹ אֶרֶץ שֶׁלְּמַטָּה. בְּחָכְמָתוֹ - זֶה צֶדֶק, שֶׁכָּתוּב (תהלים ט) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק. עֹשֵׂה אֶרֶץ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁמַּתְקִין אֶרֶץ וּמַתְקִין דְּרָכֶיהָ, וּבַמֶּה? בְּכֹחַ, כְּפִי שֶׁאָמַ רְנוּ.</p>\n<p>רַבִּי יְהוּדָה אָמַר, בְּאוֹתִיּוֹת חֲקוּקוֹת שֶׁל רַבִּי אֶלְעָזָר יֵשׁ קִשְׁרֵי הָאוֹתִיּוֹת עֶשְׂרִים וּשְׁתַּיִם קְשׁוּרִים כְּאֶחָד. שְׁתֵּי אוֹתִיּוֹת, זוֹ עוֹלָה וְזוֹ יוֹרֶדֶת, וְשֶׁעוֹלָה יוֹרֶדֶת וְשֶׁיּוֹרֶדֶת עוֹלָה. וְסִימַן זֶה - (ישעיה מה) אַ\"ךְ בָּ\"ךְ אֵ\"ל.</p>\n<p>רַבִּי יוֹסֵי אָמַר, הַלָּשׁוֹן שֶׁל מִשְׁקָל עוֹמֵד בָּאֶמְצַע, וְסִימָן - (ויקרא יט) בְּמִדָּה בְּמִשְׁקָל וְגוֹ'. מִשְׁקָל - לָשׁוֹן שֶׁעוֹמֵד בָּאֶמְצַע. וְזֶה סוֹד (שמות ל) שֶׁקֶל הַקֹּדֶשׁ כָּתוּב. וּמֹאזְנַיִם עוֹמְדִים בּוֹ וְנִשְׁקְלוּ. אֵיזֶה מֹאזְנַיִם? כְּמוֹ שֶׁנֶּאֱמַר (ויקרא יט) מֹאזְנֵי צֶדֶק, וְכֻלָּם עוֹמְדִים בְּמִשְׁקָל בְּשֶׁקֶל הַקֹּדֶשׁ. רַבִּי יְהוּדָה אָמַר, בְּשֶׁקֶל הַקֹּדֶשׁ - זוֹ רוּחַ הַקֹּדֶשׁ.</p>\n<p>אָמַר רַבִּי יִצְחָק, כָּתוּב (תהלים לג) בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ וּבְרוּחַ פִּיו כָּל צְבָאָם. בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ - אֵלּוּ שָׁמַיִם שֶׁלְּמַטָּה שֶׁנַּעֲשׂוּ בִּדְבַר שָׁמַיִם שֶׁלְּמַעְלָה. בְּרוּחַ - שֶׁהוֹצִיא קוֹל עַד שֶׁהִגִּיעַ לְאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא וְלֹא פוֹסְקִים מֵימָיו לְעוֹלָמִים. וּבְרוּחַ פִּיו כָּל צְבָאָם - כָּל הַתַּחְתּוֹנִים עוֹמְדִים בָּרוּחַ שֶׁהוּא זָכָר.</p>\n<p>(שם קד) מַשְׁקֶה הָרִים מֵעֲלִיּוֹתָיו מִפְּרִי מַעֲשֶׂיךְ תִּשְׂבַּע הָאָרֶץ. מַשְׁקֶה הָרִים מֵעֲלִיּוֹתָיו, מַה זֶּה עֲלִיּוֹתָיו? כְּמוֹ שֶׁאָמַרְנוּ, שֶׁכָּתוּב (שם) הַמְקָרֶה בַמַּיִם עֲלִיּוֹתָיו. מִפְּרִי מַעֲשֶׂיךְ תִּשְׂבַּע הָאָרֶץ - סוֹד שֶׁל אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא לְמַטָּה. זֶהוּ שֶׁכָּתוּב עֹשֶׂה פְּרִי אֲשֶׁר זַרְעוֹ בוֹ וְגוֹ', וַהֲרֵי נִתְבָּאֵר.</p>\n<p>יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמַיִם לְהָאִיר עַל הָאָרֶץ. יְהִי מְאֹרֹת, חָסֵר. רַבִּי חִזְקִיָּה אוֹמֵר, מְאֹרֹת שֶׁשּׁוֹרִים בּוֹ תֹּקֶף הַדִּין, קְלוּטַת הַדִּין. רַבִּי יוֹסֵי אָמַר, יְהִי מְאֹרֹת - לְמַטָּה. הִיא הַלְּבָנָה שֶׁבָּהּ תְּלוּיָה אַסְכָּרָה לְתִינוֹקוֹת הָעוֹלָם, וּבָהּ תָּלוּי מְאֹרֹת, בִּגְלַל שֶׁהִיא מָאוֹר קָטָן מִכָּל הַמְּאוֹרוֹת, וְלִפְעָמִים שֶׁנֶּחְשֶׁכֶת וְלֹא מְקַבֶּלֶת אוֹר.</p>\n<p>בִּרְקִיעַ הַשָּׁמַיִם - זֶהוּ רָקִיעַ שֶׁהוּא כְּלָלוּת שֶׁל כֻּלָּם, בִּגְלַל שֶׁנּוֹטֵל כָּל הַמְּאוֹרוֹת, וְהוּא מֵאִיר לַמָּאוֹר הַזֶּה שֶׁאֵינוֹ מֵאִיר (והיא תלויה בו בגלל שנדבקה בה אותה מארה, ובו תלויים למטה כל אותם מינים אחרים בגלל הקטנת האור).</p>\n<p>רַבִּי יִצְחָק אָמַר, וְהוֹצִיא (ואפלו) אֶת הָרָקִיעַ הַזֶּה שֶׁלֹּא מֵאִיר. וְקוֹרְאִים לוֹ מַלְכוּת שָׁמַיִם וְאֶרֶץ יִשְׂרָאֵל וְאֶרֶץ הַחַיִּים. הַשָּׁמַיִם הוּא (שמאיר) הָרָקִיעַ הַזֶּה, מִשּׁוּם כָּךְ יְהִי מְאֹרֹת חָסֵר ו'. מָה הַטַּעַם? שֶׁזֶּה בְּלִי וָא\"ו מָוֶת הוּא בָּעוֹלָם.</p>\n<p>יְהִי מְאֹרֹת - הַכֹּל תָּלוּי בּוֹ לְהַכְלִיל לִילִית בָּעוֹלָם. כָּתוּב (איוב ג) קָטֹן וְגָדוֹל שָׁם הוּא. וְכָתוּב (ישעיה לג) כִּי אִם שָׁם אַדִּיר ה' לָנוּ. וְעַל זֶה כָּתוּב (שם לד) אַךְ שָׁם הִרְגִּיעָה לִילִית וּמָצְאָה לָהּ מָנוֹחַ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, יְהִי מְאֹרֹת - אַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה מֵעַצְמָהּ, אֶלָּא עַל יְדֵי אוֹרוֹת עֶלְיוֹנִים שֶׁמְּאִירִים לָהּ כְּמוֹ עֲשָׁשִׁית שֶׁמְּקַבֶּלֶת אוֹר שֶׁמֵּאִיר. כָּתוּב (יהושע ג) הִנֵּה אֲרוֹן הַבְּרִית אֲדוֹן כָּל הָאָרֶץ. הִנֵּה אֲרוֹן - זוֹ אַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה. הַבְּרִית - אַסְפַּקְלַרְיָה הַמְּאִירָה. הִנֵּה אֲרוֹן - זוֹהִי מְאֹרֹת. אֲרוֹן - תֵּבָה לְהַכְנִיס בְּתוֹכָהּ תּוֹרָה שֶׁבִּכְתָב. הַבְּרִית - זוֹ הַשֶּׁמֶשׁ שֶׁמְּאִירָה לָהּ, וְהִיא בְּרִית יַחַד עִם אֲרוֹן הַבְּרִית דַּוְקָא. אֲדוֹן כָּל הָאָרֶץ - הַבְּרִית שֶׁהוּא אֲדוֹן כָּל הָאָרֶץ.</p>\n<p>וּמִשּׁוּם שֶׁהָאָרוֹן הַזֶּה הוּא אָדוֹן, בִּגְלַל הַשֶּׁמֶשׁ שֶׁמְּאִירָה לָהּ וּמְאִירָה לְכָל הָעוֹלָם כָּךְ נִקְרֵאת, וּמִמֶּנּוּ לָקְחָה אֶת הַשֵּׁם. וְנִקְרָא הָאָרוֹן הַזֶּה אָדוֹן בַּסּוֹד שֶׁל אָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד. כְּמוֹ שֶׁאָמַרְנוּ צַדִּיק וְצֶדֶק, כָּךְ אָדוֹ\"ן אֲדנָ\"י זֶה בָּזֶה תְּלוּיִים.</p>\n<p>בֹּא רְאֵה, כּוֹכָבִים וּמַזָּלוֹת עוֹמְדִים בִּבְרִית, שֶׁהוּא (שמש שאמרנו וזה) רְקִיעַ הַשָּׁמַיִם, שֶׁרְשׁוּמִים וַחֲקוּקִים בּוֹ כּוֹכָבִים וּמַזָּלוֹת וּבוֹ תְלוּיִים לְהָאִיר. רַבִּי יֵיסָא הַזָּקֵן הָיָה אוֹמֵר כָּךְ, יְהִי מְאֹרֹת שֶׁתְּלוּיִים בִּרְקִיעַ הַשָּׁמַיִם, וְזוֹ הַלְּבָנָה שֶׁתְּלוּיָה בּוֹ. כֵּיוָן שֶׁכָּתוּב וְהָיוּ לִמְאוֹרֹת - הֲרֵי הַשֶּׁמֶשׁ. וּלְמוֹעֲדִים - שֶׁהֲרֵי זְמַנִּים וְחַגִּים חֳדָשִׁים וְשַׁבָּתוֹת תְּלוּיִים בָּהֶם וְהוֹוִים.</p>\n<p>וְהַסֹל בְּמַעֲשֶׂה רִאשׁוֹן עֶלְיוֹן שֶׁשְּׁמוֹ הַקָּדוֹשׁ נֶאֱחָז בּוֹ, וְהוּא הוּא הַכֹּל. שִׁבְעָה כוֹכָבִים הֵם כְּנֶגֶד שִׁבְעָה רְקִיעִים, וְכֻלָּם מַנְהִיגֵי הָעוֹלָם, וְהָעוֹלָם עֶלְיוֹן עֲלֵיהֶם. וּשְׁנֵי עוֹלָמוֹת הֵם - עוֹלָם עֶלְיוֹן וְעוֹלָם תַּחְתּוֹן. תַּחְתּוֹן כְּמוֹ שֶׁלְּמַעְלָה, שֶׁכָּתוּב (דברי הימים א טז) מִן הָעוֹלָם וְעַד הָעוֹלָם. מֶלֶךְ עֶלְיוֹן וּמֶלֶךְ תַּחְתּוֹן.</p>\n<p>(שנינו) כָּתוּב ה' מֶלֶךְ ה' מָלָךְ ה' יִמְלוֹךְ לְעוֹלָם וָעֶד. ה' מֶלֶךְ - לְמַעְלָה. ה' מָלָךְ - בָּאֶמְצַע. ה' יִמְלוֹךְ - לְמַטָּה. רַבִּי אָחָא אָמַר, ה' (נ\"א: זו החכמה העלינה) מֶלֶךְ - זֶה עוֹלָם הָעֶלְיוֹן שֶׁהוּא הָעוֹלָם הַבָּא. ה' מָלָךְ - זוֹ תִפְאֶרֶת יִשְׂרָאֵל. ה' יִמְלוֹךְ - זֶה אֲרוֹן הַבְּרִית (נ\"א: ר' אחא אמר, ה' מלך זו חכמה עליונה, ה' מלך זה עולם העליון שהוא עולם הבא, ה' ימלוך זו תפארת ישראל).</p>\n<p>בָּא זְמַן אַחֵר דָּוִד וְהֶחֱזִיר אוֹתָם מִלְּמַטָּה לְמַעְלָה, וְאָמַר (תהלים י) ה' מֶלֶךְ עוֹלָם וָעֶד. ה' מֶלֶךְ - לְמַטָּה. עוֹלָם - בָּאֶמְצַע. וָעֶד - לְמַעְלָה. שֶׁשָּׁם הִתְוַעֲדוּת וְקִיּוּם וּשְׁלֵמוּת הַכֹּל. מֶלֶךְ - לְמַעְלָה. יִמְלוֹךְ - לְמַטָּה.</p>\n<p>רַבִּי אַבָּא אָמַר, כָּל הַמְּאוֹרוֹת הַלָּלוּ, כֻּלָּם מִתְחַבְּרִים בִּרְקִיעַ הַשָּׁמַיִם. לְהָאִיר עַל הָאָרֶץ - לְהָאִיר עַל הָאָרֶץ. מִיהוּ הָרָקִיעַ שֶׁמֵּאִיר עַל הָאָרֶץ? הֱוֵי אוֹמֵר, זֶה נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן, שֶׁכָּתוּב וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן.</p>\n<p>בֹּא רְאֵה, כֵּיוָן שֶׁהַלְּבָנָה שׁוֹלֶטֶת וּמוּאֶרֶת מֵאוֹתוֹ הָאוֹר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, כָּל אוֹתָם הַשָּׁמַיִם שֶׁלְּמַטָּה וְצִבְאוֹתֵיהֶם, כֻּלָּם נוֹסָפִים בְּאוֹר. וְכוֹכָבִים הַמְמֻנִּים עַל הָאָרֶץ, כֻּלָּם שׁוֹלְטִים וּמְגַדְּלִים צְמָחִים וְעֵצִים, וְהָעוֹלָם מִתְגַּדֵּל בְּכֻלָּם, וַאֲפִלּוּ מַיִם וּדְגֵי הַיָּם כֻּלָּם בְּגַדְלוּת יְתֵרָה. וְכַמָּה שְׁלוּחֵי הַדִּין מְשׁוֹטְטִים בָּעוֹלָם, בִּגְלַל שֶׁכֻּלָּם בְּחֶדְוָה וּבְגַדְלוּת יְתֵרָה. כְּשֶׁהַחֶדְוָה הִיא בְּבֵית הַמֶּלֶךְ, אֲפִלּוּ אוֹתָם מְמֻנֵּי הַשְּׁעָרִים, וַאֲפִלּוּ אוֹתָם מִבֵּית מְמֻנֵּי הַנָּשִׁים (נ\"א מזיקים), כֻּלָּם שְׂמֵחִים וּמְשׁוֹטְטִים בָּעוֹלָם. וְתִינוֹקוֹת הָעוֹלָם צְרִיכִים לְהִשָּׁמֵר.</p>\n<p>רַבִּי אָחָא אָמַר, וַיִּתֵּן אֹתָם אֱלֹהִים בִּרְקִיעַ הַשָּׁמָיִם. וּכְשֶׁכֻּלָּם עוֹמְדִים בּוֹ, אָז חֶדְוָה זֶה עִם זֶה, וְאָז הַלְּבָנָה מַקְטִינָה אוֹרָהּ מִלִּפְנֵי הַשֶּׁמֶשׁ, וְכָל מַה שֶּׁנּוֹטֵל כְּדֵי לְהָאִיר לָהּ. זֶהוּ שֶׁכָּתוּב לְהָאִיר עַל הָאָרֶץ.</p>\n<p>רַבִּי יִצְחָק אָמַר, כָּתוּב (ישעיה ל) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה שִׁבְעָתַיִם כְּאוֹר שִׁבְעַת הַיָּמִים. מַה זֶּה שִׁבְעַת הַיָּמִים? אֵלֶּה אוֹתָם שִׁבְעַת יְמֵי בְרֵאשִׁית. רַבִּי יְהוּדָה אָמַר, אֵלֶּה אוֹתָם שִׁבְעַת יְמֵי הַמִּלּוּאִים.</p>\n<p>מִלּוּאִים וַדַּאי. מִשּׁוּם שֶׁאוֹתוֹ זְמַן הִתְבַּשֵּׂם הָעוֹלָם וְחוֹזֵר בִּשְׁלֵמוּתוֹ, וְלֹא נִפְגֶּמֶת הַלְּבָנָה בִּגְלַל הַנָּחָשׁ הָרָע שֶׁכָּתוּב בּוֹ (משלי טז) וְנִרְגָּן מַפְרִיד אַלּוּף. וּמָתַי יִהְיֶה זֶה? בִּזְמַן שֶׁכָּתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח. וְאָז כָּתוּב (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד.</p>"],[9522011074,"<p>יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ. אָמַר רַבִּי אֶלְעָזָר, אֵלּוּ מַיִם תַּחְתּוֹנִים שֶׁרוֹחֲשִׁים מִינִים כְּמוֹ שֶׁלְּמַעְלָה. אוֹתָם עֶלְיוֹנִים וְאוֹתָם תַּחְתּוֹנִים. רַבִּי חִיָּיא אָמַר, עֶלְיוֹנִים הוֹצִיאוּ נֶפֶשׁ חַיָּה, וּמַה הוּא? זוֹ הַנֶּפֶשׁ שֶׁל אָדָם הָרִאשׁוֹן, כְּמוֹ שֶׁנֶּאֱמַר וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה.</p>\n<p>וְעוֹף יְעוֹפֵף עַל הָאָרֶץ - אֵלּוּ שְׁלִיחִים עֶלְיוֹנִים שֶׁנִּרְאִים לִבְנֵי אָדָם כְּמַרְאֵה אָדָם. מַשְׁמָע שֶׁכָּתוּב יְעוֹפֵף עַל הָאָרֶץ, הֱיוֹת שֶׁיֵּשׁ אֲחֵרִים שֶׁלֹּא נִרְאִים אֶלָּא בְּרוּחַ מַמָּשׁ לְפִי שֵׂכֶל בְּנֵי הָאָדָם.</p>\n<p>לָכֵן לֹא כָתוּב בְּאֵלּוּ לְמִינֵהוּ כְּמוֹ אוֹתָם אֲחֵרִים שֶׁכָּתוּב בָּהֶם וְאֶת כָּל עוֹף כָּנָף לְמִינֵהוּ, הֱיוֹת שֶׁאֵלּוּ לֹא מְשֻׁנִּים מִמִּינֵיהֶם לְעוֹלָמִים כָּאֲחֵרִים הַלָּלוּ שֶׁלֹּא כָתוּב בָּהֶם לְמִינֵהוּ. וְאִם תֹּאמַר, יֵשׁ בָּהֶם שֶׁמְּשֻׁנִּים זֶה מִזֶּה - כָּךְ זֶה בְּוַדַּאי! שֶׁהֲרֵי יֵשׁ בָּהֶם שֶׁמְּשֻׁנִּים אֵלֶּה מֵאֵלֶּה. מִשּׁוּם כָּךְ כָּתוּב וּמִשָּׁם יִפָּרֵד.</p>"],[9522011075,"<p>וַיִּבְרָא אֱלֹהִים אֶת הַתַּנִּינִם הַגְּדלִים - אֵלּוּ לִוְיָתָן וּבַת זוּגוֹ. וְאֵת כָּל נֶפֶשׁ הַחַיָּה הָרֹמֶשֶׂת - זוֹ נֶפֶשׁ אוֹתָהּ הַחַיָּה שֶׁהִיא רוֹמֶשֶׂת לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. וּמִי הִיא הַחַיָּה שֶׁהִיא רוֹמֶשֶׂת? הֱוֵי אוֹמֵר זוֹ לִילִית.</p>\n<p>אֲשֶׁר שָׁרְצוּ הַמַּיִם לְמִינֵהֶם - שֶׁהַמַּיִם מְגַדְּלִים אוֹתָם. שֶׁכְּשֶׁבָּא צַד הַדָּרוֹם, מַפְשִׁירִים הַמַּיִם וְשׁוֹפְעִים לְכָל הַצְּדָדִים, וָאֳנִיּוֹת הַיָּם הוֹלְכִים וְעוֹבְרִים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) שָׁם אֳנִיּוֹת יְהַלֵּכוּן לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ.</p>\n<p>וְאֵת כָּל עוֹף כָּנָף לְמִינֵהוּ - כְּמוֹ שֶׁנֶּאֱמַר (קהלת י) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל וּבַעַל כְּנָפַיִם יַגֵּיד דָּבָר. רַבִּי יוֹסֵי אָמַר, כֻּלָּם מִשֵּׁשׁ כְּנָפַיִם וְלֹא מִשְׁתַּנִּים לְעוֹלָמִים, וּמִשּׁוּם כָּךְ כָּתוּב לְמִינֵהוּ. מַה זֶּה לְמִינֵהוּ? לַמִּין שֶׁלְּמַעְלָה, וְאֵלֶּה טָסִים וּמְשׁוֹטְטִים בָּעוֹלָם בְּשֵׁשׁ, וְרוֹאִים מַעֲשֵׂי בְּנֵי אָדָם וּמַעֲלִים אוֹתָם לְמַעְלָה, וְעַל זֶה כָּתוּב (שם) גַּם בְּמַדָּעֲךְ מֶלֶךְ אַל תְּקַלֵּל וְגוֹ'.</p>\n<p>רַבִּי חִזְקִיָּה אָמַר, הָרֹמֶשֶׂת? הַשּׁוֹרֶצֶת צָרִיךְ לִהְיוֹת! אֶלּא כְּמוֹ שֶׁאָמַרְנוּ, רוֹמֵשׁ לַיְלָה. וְעַל זֶה (תהלים קד) בּוֹ תִרְמֹשׂ כָּל חַיְתוֹ יָעַר. שֶׁכֻּלָּם שׁוֹלְטִים בְּשָׁעָה שֶׁהִיא שּולִטִת, וּפותחיּם שּיּרָה בּשּלשָּה צּדָדיּם שִּל חַצּות הַלַּיּלָה, וּמזַמּריּם שּיּרָה ולא שּוקטיּם, ועַל אלּוּ כָּתוּב הַמַּזכּיּריּם אִת ה' אַל דָּמיּ לָכִם,</p>\n<p>עָמַד רַבִּי שִׁמְעוֹן וְאָמַר, מִסְתַּכֵּל הָיִיתִי, שֶׁכְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אָדָם, הִזְדַּעְזְעוּ כָּל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים, וְיוֹם הַשִּׁשִּׁי הָיָה עוֹלֶה בְּדַרְגוֹתָיו, עַד שֶׁעָלָה רָצוֹן עֶלְיוֹן וְהֵאִיר תְּחִלָּה כָּל הָאוֹרוֹת.</p>\n<p>וּפָתַח שַׁעַר הַמִּזְרָח, שֶׁהֲרֵי מִשָּׁם יוֹצֵא הָאוֹר. וְהַדָּרוֹם הֶרְאָה חָזְקֵי הָאוֹר שֶׁיָּרַשׁ מֵרֹאשׁ וְהִתְחַזֵּק בַּמִּזְרָח. מִזְרָח חִזֵּק אֶת הַצָּפוֹן, וְהַצָּפוֹן הִתְעוֹרֵר וְהִתְפַּשֵּׁט, וְקָרָא בְּחַיִל גָּדוֹל לַמַּעֲרָב לְהִתְקָרֵב וּלְהִשְׁתַּתֵּף עִמּוֹ. אָז מַעֲרָב עָלָה בַּצָּפוֹן וְנִקְשַׁר בּוֹ. אַחַר כָּךְ בָּא הַדָּרוֹם וְאָחַז בַּמַּעֲרָב, וְסוֹבְבוּ אוֹתוֹ דָּרוֹם וְצָפוֹן, שֶׁהֵם גִּדְרֵי הַגָּן. אָז הַמִּזְרָח קָרַב לַמַּעֲרָב, וּמַעֲרָב שָׁרָה בְּחֶדְוָה וּבִקֵּשׁ מִכֻּלָּם, וְאָמַר נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ. שֶׁיִּהְיֶה כְּמוֹ זֶה בְּאַרְבַּעַת הַצְּדָדִים וּמַעְלָה וּמַטָּה. וּמִזְרָח נִדְבַּק בַּמַּעֲרָב וְהוֹצִיא אוֹתוֹ. וְעַל זֶה שָׁנִינוּ, שֶׁאָדָם יָצָא מִמְּקוֹם בֵּית הַמִּקְדָּשׁ.</p>\n<p>עוֹד נַעֲשֶׂה אָדָם, הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לַתַּחְתּוֹנִים הַלָּלוּ שֶׁבָּאוּ מִצַּד שֶׁלְּמַעְלָה. סוֹד הַשֵּׁם הַזֶּה שֶׁעוֹלֶה אָדָם. אָדָם מִסּוֹד נִסְתָּר עֶלְיוֹן. אָדָם סוֹד הָאוֹתִיּוֹת. שֶׁהֲרֵי הָאָדָם כָּלוּל לְמַעְלָה וְכָלוּל לְמַטָּה. אָדָם אֶחָד לְמַעְלָה לְמַעְלָה. ם נִסְתָּר שֶׁהִיא ם מִלְּםַרְבֵּה הַמִּשְׂרָה. ד' תַּחְתּוֹן שֶׁנִּסְתָּר בַּמַּעֲרָב. וְזֶה כְּלָלוּת שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה. נִתְקָן לְמַעְלָה וְנִתְקָן לְמַטָּה.</p>\n<p>כְּשֶׁיָּרְדוּ הָאוֹתִיּוֹת הַלָּלוּ לְמַטָּה כֻּלָּם כְּאֶחָד בִּשְׁלֵמוּתוֹ, נִמְצָא זָכָר וּנְקֵבָה, וּנְקֵבָה נִדְבְּקָה בַאֲחוֹרָיו, עַד שֶׁהִפִּיל עָלָיו תַּרְדֵּמָה וְיָשַׁן, וְהָיָה מֻטָּל בִּמְקוֹם בֵּית הַמִּקְדָּשׁ לְמַטָּה.</p>\n<p>וְנִסֵּר אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְתִקֵּן אוֹתָהּ כְּמוֹ שֶׁמְּתַקְנִים אֶת הַכַּלָּה וְהִכְנִיסָהּ אֵלָיו. זֶהוּ שֶׁכָּתוּב וַיִּקַּח אַחַת מִצַּלְעֹתָיו וַיִּסְגֹּר בָּשָׂר תַּחְתֶּנָּה. וַיִּקַּח אַחַת דַּוְקָא. בְּסִפְרֵי הָרִאשׁוֹנִים מָצָאנוּ, זוֹ לִילִית רִאשׁוֹנָה שִּהָיּתָה עמּו והתעַבּרָה ממִּנּוּ,</p>\n<p>ולא הָיָּה כּנִגדּו עזִר, כּמו שִּכָּתוּב וּלאָדָם לא מָצָּא עזִר כּנִגדּו, מַה זִה עזִר,? סִמִךָ, עַד אותָהּ שָּעָה שִּכָּתוּב לא טוב הִיּות הָאָדָם לבַדּו אִעִשִּה לּו עזִר כּנִגדּו, בּא ראה, אָדָם אַחַרון הַכּל הָיָּה, שִּכָּךָ רָאוּיּ להָביּא שָּלום עַל הָעולָם,</p>"],[9522011076,"<p>עוֹד אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב וְכֹל שִׂיחַ הַשָּׂדֶה טֶרֶם יִהְיֶה בָאָרֶץ וְכָל עֵשֶׂב הַשָּׂדֶה טֶרֶם יִצְמָח כִּי לֹא הִמְטִיר ה' אֱלֹהִים עַל הָאָרֶץ וְגוֹ'. וְכֹל שִׂיחַ הַשָּׂדֶה - אֵלּוּ עֵצִים גְּדוֹלִים שֶׁנִּנְטְעוּ אַחַר כָּךְ וְהָיוּ קְטַנִּים.</p>\n<p>בֹּא רְאֵה, אָדָם וְחַוָּה זֶה בְּצַד זֶה נִבְרְאוּ. מָה הַטַּעַם לֹא נִבְרְאוּ פָּנִים בְּפָנִים? בִּגְלַל שֶׁכָּתוּב כִּי לֹא הִמְטִיר ה' אֱלֹהִים עַל הָאָרֶץ, וְהַזִּוּוּג לֹא נִמְצָא בְתִקּוּנוֹ כָּרָאוּי. וּכְשֶׁנִּתְקְנָה זוֹ שֶׁלְּמַטָּה וְחָזְרוּ לִהְיוֹת פָּנִים בְּפָנִים, כֵּן נִמְצָא לְמַעְלָה.</p>\n<p>מִנַּיִן לָנוּ? מִן הַמִּשְׁכָּן, שֶׁכָּתוּב (שמות מ) הוּקַם הַמִּשְׁכָּן, הֱיוֹת שֶׁמִּשְׁכָּן אַחֵר הוּקַם עִמּוֹ. וְעַד שֶׁלֹּא הוּקַם לְמַטָּה, לֹא הוּקַם לְמַעְלָה. גַּם כָּאן כְּשֶׁהוּקַם לְמַטָּה, הוּקַם לְמַעְלָה. וּמִשּׁוּם שֶׁעַד עַכְשָׁו לֹא הִתְתַּקֵּן לְמַעְלָה, לֹא נִבְרְאוּ פָּנִים בְּפָנִים, וְהַפָּסוּק מוֹכִיחַ, שֶׁכָּתוּב כִּי לֹא הִמְטִיר ה' אֱלֹהִים עַל הָאָרֶץ. וּמִשּׁוּם כָּךְ וְאָדָם אַיִן, שֶׁלֹּא הָיָה בְּתִקּוּנוֹ.</p>\n<p>וּכְשֶׁנִּשְׁלְמָה חַוָּה, נִשְׁלַם אָדָם, וְקֹדֶם לָכֵן לֹא נִשְׁלַם. וְזֶה הַסּוֹד שֶׁעַד עַכְשָׁו אֵין אוֹת סָמֶךְ בַּפָּרָשָׁה, וְאַף עַל גַּב שֶׁהַחֲבֵרִים אָמְרוּ, אֲבָל סָמֶ\"ךְ זֶה עֵזֶר, וְזֶה עֵזֶר שֶׁלְּמַעְלָה שֶׁחָזַר לְמַעְלָה פָּנִים בְּפָנִים זָכָר וּנְקֵבָה, נִסְמָךְ זֶה כְּנֶגֶד זֶה בְּוַדַּאי, (תהלים קיא) סְמוּכִים לָעַד לְעוֹלָם עֲשׂוּיִים בֶּאֱמֶת וְיָשָׁר. סְמוּכִים - זֶה זָכָר וּנְקֵבָה שֶׁהֵם סְמוּכִים כְּאֶחָד (נ\"א: שהם סמוכים עולם תחתון בעולם עליון, שעד שלא נתקן העולם שלמטה, לא נתקן אותו העולם שאמרנו) (העולם הזה שאמרנו תלוי בעולם שלמטה, וכשלא נתקן עולם שלמטה, לא נתקן אותו עולם שאמרנו).</p>\n<p>כִּי לֹא הִמְטִיר ה' אֱלֹהִים עַל הָאָרֶץ, שֶׁהֲרֵי זֶה בָּזֶה סָמוּךְ. וְעוֹלָם זֶה הַתַּחְתּוֹן, כְּשֶׁנִּתְקְנוּ וְחָזְרוּ לִהְיוֹת פָּנִים בְּפָנִים וְנִתְקְנוּ, נִמְצָא סֶמֶךְ לְמַעְלָה, שֶׁהֲרֵי מִקֹּדֶם לָכֵן לֹא הָיָה הַמַּעֲשֶׂה בְּתִקּוּן (נ\"א: עולם בתקונו), מִשּׁוּם שֶׁלֹּא הִמְטִיר ה' אֱלֹהִים עַל הָאָרֶץ, וְזֶה בָּזֶה תְּלוּיִים.</p>\n<p>מַה כָּתוּב אַחֲרָיו? וְאֵד יַעֲלֶה מִן הָאָרֶץ, זֶה תִּקּוּן שֶׁלְּמַטָּה. אַחַר כָּךְ, וְהִשְׁקָה אֶת כָּל פְּנֵי הָאֲדָמָה. וְאֵד יַעֲלֶה מִן הָאָרֶץ - זוֹ הִשְׁתּוֹקְקוּת הַנְּקֵבָה לַזָּכָר. דָּבָר אַחֵר, מָה הַטַּעַם לֹא הִמְטִיר? בִּגְלַל שֶׁלֹּא נִמְצָא תִקּוּן שֶׁיַּעֲלֶה מִן הָאָרֶץ. וְעַל זֶה מִן הָאָרֶץ הַתַּחְתּוֹנָה הִתְעוֹרֵר מַעֲשֶׂה לְמַעְלָה.</p>\n<p>בֹּא רְאֵה, עָשָׁן עוֹלֶה מִן הָאָרֶץ בַּהַתְחָלָה וְעָנָן מִתְעוֹרֵר, וְהַכֹּל מִתְחַבֵּר אַחַר כָּךְ זֶה בָּזֶה. כְּמוֹ זֶה עֲשַׁן הַקָּרְבָּן מִתְעוֹרֵר מִלְּמַטָּה וְעוֹשֶׂה שְׁלֵמוּת לְמַעְלָה, וּמִתְחַבֵּר הַכֹּל זֶה בָּזֶה, וְנִשְׁלָמִים כְּמוֹ זֶה לְמַעְלָה. הִתְעוֹרְרוּת מַתְחִילָה מִלְּמַטָּה, וְאַחַר כָּךְ הַכֹּל נִשְׁלָם. וְאִלְמָלֵא שֶׁכְּנֶסֶת יִשְׂרָאֵל מַתְחִילָה בַּהִתְעוֹרְרוּת בַּהַתְחָלָה, לֹא יִתְעוֹרֵר כְּנֶגְדָּהּ אוֹתוֹ שֶׁלְּמַעְלָה. וּבַהִשְׁתּוֹקְקוּת שֶׁלְּמַטָּה נִשְׁלָם לְמַעְלָה.</p>\n<p>רַבִּי אַבָּא אָמַר, לָמָּה כָּתוּב וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן וְעֵץ הַדַּעַת טוֹב וָרָע? עֵץ הַחַיִּים הֲרֵי שָׁנִינוּ שֶׁמַּהֲלַךְ חֲמֵשׁ מֵאוֹת שָׁנִים הָיָה, וְכָל מֵימֵי בְרֵאשִׁית נֶחֱלָקִים תַּחְתָּיו. עֵץ הַחַיִּים מַמָּשׁ בְּאֶמְצַע הַגָּן, וְהוּא לוֹקֵחַ כָּל מֵימֵי בְרֵאשִׁית וְנֶחֱלָקִים תַּחְתָּיו.</p>\n<p>שֶׁהֲרֵי אוֹתוֹ נָהָר (בינה) שֶׁשּׁוֹפֵעַ וְיוֹצֵא, הוּא שׁוֹרֶה עַל אוֹתוֹ הַגָּן וְנִכְנָס בּוֹ, וּמִשָּׁם נֶחֱלָקִים הַמַּיִם לְכַמָּה צְדָדִים. וְאוֹתוֹ הַגָּן לוֹקֵחַ הַכֹּל, וְאַחַר כָּךְ יוֹצְאִים מִמֶּנָּה וְנֶחֱלָקִים לְכַמָּה נְחָלִים לְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי. כְּמוֹ שֶׁיּוֹצְאִים מֵאוֹתוֹ עוֹלָם עֶלְיוֹן וּמַשְׁקֶה אֶת אוֹתָם הָרִים עֶלְיוֹנִים שֶׁל אֲפַרְסְמוֹן זַךְ. אַחַר כָּךְ כְּשֶׁמַּגִּיעִים לְעֵץ הַחַיִּים, נֶחֱלָקִים תַּחְתָּיו בְּכָל צַד כְּפִי דַרְכּוֹ.</p>\n<p>וְעֵץ הַדַּעַת טוֹב וָרָע - לָמָּה נִקְרָא כָּךְ, שֶׁהֲרֵי עֵץ זֶה אֵינוֹ בָּאֶמְצַע? אֲבָל עֵץ הַדַּעַת טוֹב וָרָע מַהוּ? אֶלָּא בִּגְלַל שֶׁיּוֹנֵק מִשְּׁנֵי צְדָדִים וְיוֹדֵעַ אוֹתָם כְּמִי שֶׁיּוֹנֵק מָתוֹק וּמַר, וּבִגְלַל שֶׁיּוֹנֵק מִשְּׁנֵי צְדָדִים וְיוֹדֵעַ אוֹתָם וְשׁוֹרֶה בְתוֹכָם נִקְרָא כָּךְ טוֹב וָרָע. וְכָל אוֹתָם נְטִיעוֹת שׁוֹרִים עֲלֵיהֶם.</p>\n<p>וּבוֹ אֲחוּזִים נְטִיעוֹת אֲחֵרוֹת עֶלְיוֹנוֹת, וְהֵם נִקְרָאִים אַרְזֵי הַלְּבָנוֹן. מִי הֵם אַרְזֵי לְבָנוֹן? אוֹתָם שִׁשָּׁה יָמִים עֶלְיוֹנִים, שֵׁשֶׁת יְמֵי בְרֵאשִׁית שֶׁאָמַרְנוּ. אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע, נְטִיעוֹת וַדַּאי שֶׁהִתְקַיְּמוּ אַחַר כָּךְ.</p>\n<p>מִכָּאן וָהָלְאָה סָמֶ\"ךְ. מַהִי וַיִּסְגֹּר בָּשָׂר תַּחְתֶּנָּה? בְּצִדּוֹ הָיְתָה, וְהָיָה זֶה בְּצַד זֶה. וַדַּאי עָקַר אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְשָׁתַל אוֹתָם בְּמָקוֹם אַחֵר, וְחָזְרוּ לִהְיוֹת פָּנִים בְּפָנִים לַקִּיּוּם. כְּמוֹ זֶה סְמוּכִים הָעוֹלָמוֹת. עָקַר אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְשָׁתַל אוֹתָם בְּמָקוֹם אַחֵר וְהִתְקַיְּמוּ בְּקִיּוּם שָׁלֵם.</p>\n<p>וְאָמַר רַבִּי אַבָּא, מִנַּיִן לָנוּ שֶׁאָדָם וְחַוָּה הָיוּ נְטוּעִים? שֶׁכָּתוּב (ישעיה ס) נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. דַּוְקָא מַעֲשֵׂה יָדַי, שֶׁלֹּא הִשְׁתַּדְּלוּ בָהֶם בְּרִיּוֹת אֲחֵרוֹת, וְכָתוּב (שם יז) בְּיוֹם נִטְעֵךְ תְּשַׂגְשֵׂגִי. שֶׁבְּאוֹתוֹ יוֹם שֶׁנִּנְטְעוּ בָּעוֹלָם, סָרְחוּ.</p>\n<p>שָׁנִינוּ, הַנְּטִיעוֹת הָיוּ כְּקַרְנֵי חֲגָבִים וְאוֹרָם דַּקִּיק וְלֹא הָיוּ מְאִירִים. כֵּיוָן שֶׁנִּנְטְעוּ וְנִתְקְנוּ, הִתְרַבּוּ בָּאוֹר וְנִקְרְאוּ אַרְזֵי לְבָנוֹן. וְאָדָם וְחַוָּה עַד שֶׁנִּנְטְעוּ, לֹא הִתְרַבּוּ בָּאוֹר וְלֹא הֶעֱלוּ רֵיחַ בְּוַדַּאי. נֶעֶקְרוּ וְנִשְׁתְּלוּ וְנִתְקְנוּ כָּרָאוּי.</p>"],[9522011077,"<p>וַיְצַו ה' אֱלֹהִים. הֲרֵי שָׁנִינוּ, אֵין צַו אֶלָּא עֲבוֹדָה זָרָה. ה' - זוֹ בִּרְכַּת הַשֵּׁם. אֱלֹהִים - אֵלּוּ הַדַּיָּנִים. עַל הָאָדָם - זוֹ שְׁפִיכַת דָּמִים. לֵאמֹר - זוֹ גִּלּוּי עֲרָיוֹת. מִכֹּל עֵץ הַגָּן - וְלֹא גָזֵל. אָכֹל תֹּאכֵל - וְלֹא אֵבָר מִן הַחַי, וְיָפֶה.</p>\n<p>מִכֹּל עֵץ הַגָּן אָכֹל תֹּאכֵל - שֶׁהִתִּיר לוֹ הַכֹּל לְאָכְלָם יַחַד. שֶׁהֲרֵי רָאִינוּ אַבְרָהָם אָכַל, יִצְחָק וְיַעֲקֹב וְכָל הַנְּבִיאִים אָכְלוּ וְחָיוּ. אֲבָל עֵץ זֶה, עֵץ הַמָּוֶת הוּא (כמו שכתוב ומעץ הדעת טוב ורע לא תאכל ממנו). מִי שֶׁנּוֹטְלוֹ לְבַדּוֹ - מֵת, שֶׁהֲרֵי סַם הַמָּוֶת נָטַל (בגלל שהוא מפרידו מהחיים). וְעַל זֶה כִּי בְּיוֹם אֲכָלְךְ מִמֶּנּוּ מוֹת תָּמוּת, בִּגְלַל שֶׁמַּפְרִיד הַנְּטִיעוֹת.</p>\n<p>רַבִּי יְהוּדָה שָׁאַל אֶת רַבִּי שִׁמְעוֹן, זֶה שֶׁשָּׁנִינוּ, אָדָם הָרִאשׁוֹן הָיָה מוֹשֵׁךְ בְּעָרְלָתוֹ, מַה זֶּה? אָמַר לוֹ, שֶׁהִפְרִיד בְּרִית קֹדֶשׁ מִמְּקוֹמוֹ וּמֵחֶלְקוֹ, וַדַּאי שֶׁהָיָה מוֹשֵׁךְ בָּעָרְלָה. וְעָזַב בְּרִית קֹדֶשׁ וְדָבַק בָּעָרְלָה וְהִתְפַּתָּה בִּדְבַר הַנָּחָשׁ.</p>\n<p>וּמִפְּרִי הָעֵץ - זוֹ אִשָּׁה. לֹא תֹאכַל מִמֶּנּוּ - בִּגְלַל שֶׁכָּתוּב (משלי ה) רַגְלֶיהָ יֹרְדוֹת מָוֶת שְׁאוֹל צְעָדֶיהָ יִתְמֹכוּ. וּבָזֶה הָיָה פְרִי, שֶׁהֲרֵי בְּאַחֵר לֹא הָיָה פְרִי. כִּי בְּיוֹם אֲכָלְךְ מִמֶּנּוּ מוֹת תָּמוּת - בִּגְלַל שֶׁעֵץ הַמָּוֶת הָיָה, כְּמוֹ שֶׁאָמַרְנוּ שֶׁכָּתוּב רַגְלֶיהָ יֹרְדוֹת מָוֶת.</p>\n<p>(והנחש היה ערום מכל חית השדה) רַבִּי יוֹסֵי אָמַר, הָאִילָן הַזֶּה שֶׁאָמַרְנוּ הָיָה מֻשְׁקֶה מִלְמַעְלָה, וְהִתְגַּדֵּל וְהָיָה שָׂמֵחַ, כְּמוֹ שֶׁנֶּאֱמַר וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. הַגָּן זוֹ אִשָּׁה. וְנָהָר זֶה הָיָה נִכְנָס בָּהּ וּמַשְׁקֶה אוֹתָהּ וְהָיָה הַכֹּל אֶחָד (ואז ה' אחד ושמו אחד). שֶׁהֲרֵי מִשָּׁם וּלְמַטָּה הוּא פֵרוּד, שֶׁכָּתוּב וּמִשָּׁם יִפָּרֵד.</p>"],[9522011078,"<p>וְהַנָּחָשׁ, רַבִּי יִצְחָק אָמַר זֶה יֵצֶר הָרָע. רַבִּי יְהוּדָה אָמַר נָחָשׁ מַמָּשׁ. בָּאוּ לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר לָהֶם, וַדַּאי הַכֹּל אֶחָד, וְסמא\"ל הָיָה, וְנִרְאָה עַל נָחָשׁ וְצַלְמוֹ. שֶׁנָּחָשׁ זֶה הוּא שָׂטָן, וְהַכֹּל אֶחָד.</p>\n<p>שָׁנִינוּ, בְּאוֹתָהּ שָׁעָה יָרַד סמא\"ל מֵהַשָּׁמַיִם רָכוּב עַל נָחָשׁ זֶה, וְצַלְמוֹ הָיוּ רוֹאִים כָּל הַבְּרִיּוֹת וּבוֹרְחִים מִמֶּנּוּ. וְהִגִּיעוּ לָאִשָּׁה בִּדְבָרִים וְגָרְמוּ מָוֶת לָעוֹלָם. וַדַּאי בְּחָכְמָה הֵבִיא סמא\"ל קְלָלוֹת עַל הָעוֹלָם, וְחִבֵּל אֶת הָאִילָן הַקַּדְמוֹן שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בָּעוֹלָם,</p>\n<p>וְדָבָר זֶה הָיָה תָלוּי עַל סמא\"ל, עַד שֶׁבָּא אִילָן אַחֵר קָדוֹשׁ, שֶׁהוּא יַעֲקֹב, וְנָטַל מִמֶּנּוּ בְּרָכוֹת שֶׁלֹּא יִתְבָּרֵךְ סמא\"ל לְמַעְלָה וְעֵשָׂו לְמַטָּה. שֶׁהֲרֵי יַעֲקֹב דֻּגְמַת אָדָם הָרִאשׁוֹן הָיָה (ויפיו), שֶׁיַּעֲקֹב יָפְיוֹ שֶׁל אָדָם הָרִאשׁוֹן הָיָה. וְעַל זֶה, כְּמוֹ שֶׁמָּנַע סמא\"ל בְּרָכוֹת מֵהָאִילָן הָרִאשׁוֹן, כָּךְ גַּם מָנַע יַעֲקֹב שֶׁהוּא אִילָן, דֻּגְמַת אָדָם מִסמא\"ל, בְּרָכוֹת מִלְמַעְלָה וּמִלְּמַטָּה. וְיַעֲקֹב לָקַח אֶת שֶׁלּוֹ בַּכֹּל, וְעַל זֶה (בראשית לב) וַיֵּאָבֵק אִישׁ עִמּוֹ.</p>\n<p>כָּתוּב וְהַנָּחָשׁ הָיָה עָרוּם, זֶה יֵצֶר הָרָע, זֶה מַלְאַךְ הַמָּוֶת. וּמִשּׁוּם שֶׁהַנָּחָשׁ הוּא מַלְאַךְ הַמָּוֶת, גָּרַם מָוֶת לְכָל הָעוֹלָם. וְזֶהוּ סוֹד שֶׁכָּתוּב (שם ו) קֵץ כָּל בָּשָׂר בָּא לְפָנַי. זֶהוּ קֵץ שֶׁל כָּל בָּשָׂר שֶׁנּוֹטֵל הַנְּשָׁמָה לְכָל בָּשָׂר, וְנִקְרָא כָּךְ.</p>\n<p>וַיֹּאמֶר אֶל הָאִשָּׁה אַף. רַבִּי יוֹסֵי אָמַר, בְּאַף פָּתַח וְאַף הִטִּיל בָּעוֹלָם. אָמַר לָהּ לָאִשָּׁה, בְּאִילָן זֶה בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא וַדַּאי אֶת הָעוֹלָם, אִכְלוּ מִמֶּנּוּ וִהְיִיתֶם כֵּאלֹהִים יוֹדְעֵי טוֹב וָרָע. שֶׁהֲרֵי הוּא כָּךְ הוּא אֱלֹהִים שְׁמוֹ עֵץ הַדַּעַת טוֹב וָרָע, וְעַל זֶה וִהְיִיתֶם כֵּאלֹהִים יֹדְעֵי וְגוֹ'.</p>\n<p>אָמַר רַבִּי יְהוּדָה, לֹא אָמַר כָּךְ, שֶׁאִלּוּ אָמַר בְּאִילָן זֶה בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, נָאֶה הָיָה, כִּי הוּא כַּגַּרְזֶן בְּיַד הַחוֹצֵב בּוֹ. אֲבָל לֹא אָמַר אֶלָּא, מֵאִילָן זֶה אָכַל הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָז בָּרָא אֶת הָעוֹלָם, וְכָל אֻמָּן שׂוֹנֵא אֶת חֲבֵרוֹ, אִכְלוּ מִמֶּנּוּ וְאַתֶּם תִּהְיוּ בּוֹרְאֵי עוֹלָמוֹת. וְעַל זֶה כִּי יֹדֵעַ אֱלֹהִים כִּי בְּיוֹם אֲכָלְכֶם מִמֶּנּוּ וְגוֹ', וּמִשּׁוּם שֶׁהוּא יָדַע אֶת זֶה, צִוָּה אֶתְכֶם עָלָיו שֶׁלֹּא תֹאכְלוּ מִמֶּנּוּ.</p>\n<p>אָמַר רַבִּי יִצְחָק, בַּכֹּל דִּבְּרוּ שֶׁקֶר. בַּתְּחִלָּה שֶׁאָמְרוּ שֶׁקֶר הָיָה - שֶׁכָּתוּב אַף כִּי אָמַר אֱלֹהִים לֹא תֹאכְלוּ מִכֹּל עֵץ הַגָּן, וְלֹא כָּךְ, שֶׁהֲרֵי כָּתוּב מִכֹּל עֵץ הַגָּן אָכֹל תֹּאכֵל, וְכֻלָּם הִתִּיר לוֹ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, הֲרֵי שָׁנִינוּ שֶׁצִּוָּה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עַל עֲבוֹדָה זָרָה, שֶׁכָּתוּב וַיְצַו. ה' - עַל בִּרְכַּת הַשֵּׁם. אֱלֹהִים - עַל הַדִּינִים. עַל הָאָדָם - עַל שְׁפִיכוּת דָּמִים. לֵאמֹר - עַל גִּלּוּי עֲרָיוֹת. וְכִי כַּמָּה אֲנָשִׁים הָיוּ בָּעוֹלָם שֶׁהוּא צָרִיךְ זֶה? אֶלָּא וַדַּאי הַכֹּל עַל הָאִילָן הַזֶּה הָיָה.</p>\n<p>מִשּׁוּם שֶׁבּוֹ אֲחוּזִים כָּל הַמִּצְווֹת הַלָּלוּ. שֶׁכָּל מִי שֶׁנּוֹטֵל אוֹתוֹ בִּלְבַדּוֹ, עוֹשֶׂה פֵרוּד. וְנוֹטֵל אוֹתוֹ בָּאוּכְלוּסִים שֶׁלְּמַטָּה שֶׁאֲחוּזִים בּוֹ, וְנָטַל עֲבוֹדָה זָרָה וּשְׁפִיכוּת דָּמִים וְגִלּוּי עֲרָיוֹת. עֲבוֹדָה זָרָה בְּאוֹתָם גְּדוֹלִים מְמֻנִּים. שְׁפִיכוּת דָּמִים תְּלוּיִים בָּאִילָן הַזֶּה שֶׁהוּא בְּצַד גְּבוּרָה. וְסמא\"ל מְמֻנֶּה עַל זֶה. גִּלּוּי עֲרָיוֹת אִשָּׁה הִיא, וְאִשָּׁה נִקְרֵאת, וְאָסוּר לְזַמֵּן אֶת הָאִשָּׁה בִּלְבַדָּהּ אֶלָּא עִם בַּעְלָהּ שֶׁלֹּא יִהְיֶה חָשׁוּד בְּגִלּוּי עֲרָיוֹת. וְעַל זֶה בְּכֻלָּם הִצְטַוָּה בָּאִילָן הַזֶּה. כֵּיוָן שֶׁאָכַל מִמֶּנּוּ, עָבַר בְּכֻלָּם, שֶׁהֲרֵי הַכֹּל אָחוּז בּוֹ.</p>\n<p>רַבִּי יְהוּדָה אָמַר, וַדַּאי דָּבָר זֶה כָּךְ הוּא, שֶׁאָסוּר לְהִתְיַחֵד עִם אִשָּׁה בִּלְבַדָּהּ אֶלָּא אִם כֵּן בַּעְלָהּ עִמָּהּ. מֶה עָשָׂה אוֹתוֹ רָשָׁע? אָמַר, הֲרֵי הִגַּעְתִּי לָאִילָן הַזֶּה וְלֹא מַתְתִּי, גַּם אַתְּ קִרְבִי וּגְעִי בְּיָדֵךְ וְלֹא תָמוּתִי. וְדָבָר זֶה הוּא הוֹסִיף לָהּ מֵעַצְמוֹ.</p>\n<p>מִיָּד וַתֵּרֶא הָאִשָּׁה כִּי טוֹב וְגוֹ'. בַּמָּה רָאֲתָה? אָמַר רַבִּי יִצְחָק, אוֹתוֹ אִילָן (שדה) הֶעֱלָה רֵיחוֹת, כְּמוֹ שֶׁנֶּאֱמַר (בראשית כז) כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה'. וּבִגְלַל אוֹתוֹ רֵיחַ שֶׁהָיָה עוֹלֶה, חָמְדָה אוֹתוֹ לֶאֱכֹל מִמֶּנּוּ. רַבִּי יוֹסֵי אָמַר, רְאִיָּה הָיְתָה. אָמַר לוֹ רַבִּי יְהוּדָה, וַהֲרֵי כָּתוּב וַתִּפָּקַחְנָה עֵינֵי שְׁנֵיהֶם? אָמַר לוֹ, רְאִיָּה זוֹ בַּשִּׁעוּר שֶׁל הָאִילָן לָקְחָה אוֹתוֹ (נ\"א: שעור הלב היתה), שֶׁכָּתוּב וַתֵּרֶא הָאִשָּׁה דַּוְקָא.</p>\n<p>וַתֵּרֶא הָאִשָּׁה כִּי טוֹב - רָאֲתָה וְלֹא רָאֲתָה. כִּי טוֹב - רָאֲתָה כִּי טוֹב וְלֹא הִתְיַשְּׁבָה בּוֹ. מַה כָּתוּב אַחַר כָּךְ? וַתִּקַּח מִפִּרְיוֹ, וְלֹא כָתוּב וַתִּקַּח מִמֶּנּוּ. וְהִיא נִדְבְּקָה בִּמְקוֹם הַמָּוֶת, וְגָרְמָה לְכָל הָעוֹלָם מָוֶת. וְהִפְרִידָה חַיִּים מִמָּוֶת, וּבְחֵטְא זֶה גָּרַם פֵּרוּד לְהַפְרִיד אִשָּׁה מִבַּעְלָהּ, שֶׁהֲרֵי קוֹל מִדִּבּוּר לֹא נִפְרָדִים לְעוֹלָמִים. וּמִי שֶׁמַּפְרִיד קוֹל מִדִּבּוּר, מִתְאַלֵּם וְלֹא יָכוֹל לְדַבֵּר. וְכֵיוָן שֶׁנִּטָּל מִמֶּנּוּ דִּבּוּר, נִתָּן לֶעָפָר.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב (תהלים לט) נֶאֱלַמְתִּי דוּמִיָּה הֶחֱשֵׁיתִי מִטּוֹב וּכְאֵבִי נֶעְכָּר. נֶאֱלַמְתִּי דוּמִיָּה, פָּסוּק זֶה אָמְרָה אוֹתוֹ כְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת. מָה הַטַּעַם? בִּגְלַל שֶׁקּוֹל מַנְהִיג אֶת הַדִּבּוּר, כֵּיוָן שֶׁהִיא בַּגָּלוּת. קוֹל נִפְרָד מִמֶּנָּה, וְדִבּוּר לֹא נִשְׁמָע, וְעַל זֶה נֶאֱלַמְתִּי דוּמִיָּה וְגוֹ'. מָה הַטַּעַם? בִּגְלַל שֶׁהֶחֱשֵׁיתִי מִטּוֹב, שֶׁלֹּא הוֹלֵךְ קוֹל אִתָּהּ. וְיִשְׂרָאֵל אוֹמְרִים (שם סה) לְךְ דוּמִיָּה תְהִלָּה. מַה זֶּה דּוּמִיָּה? זוֹ תְהִלָּה לְדָוִד, שֶׁהִיא דוּמִיָּה בַּגָּלוּת וְשׁוֹתֶקֶת בְּלִי קוֹל. אָמַר רַבִּי יִצְחָק, מַה זֶּה לְךְ? בִּגְלָלְךְ הִיא דוּמִיָּה וְשׁוֹתֶקֶת שֶׁהִסְתַּלֵּק מִמֶּנָּה קוֹל.</p>\n<p>וַתִּקַּח מִפִּרְיוֹ, הֲרֵי שָׁנִינוּ שֶׁסָּחֲטָה עֲנָבִים וְנָתְנָה לוֹ, וְגָרְמוּ מָוֶת לְכָל הָעוֹלָם. שֶׁהֲרֵי אִילָן זֶה בּוֹ שׁוֹרֶה הַמָּוֶת, וְהוּא אִילָן שֶׁשּׁוֹלֵט בַּלַּיְלָה. וּכְשֶׁהִיא שׁוֹלֶטֶת, כָּל בְּנֵי הָעוֹלָם טוֹעֲמִים טַעַם מָוֶת. אֶלָּא אוֹתָם בְּנֵי הָאֱמוּנָה מַקְדִּימִים וְנוֹתְנִים לָהּ נַפְשָׁם בְּפִקָּדוֹן. וּבִגְלַל שֶׁהוּא בְּפִקָּדוֹן, חוֹזְרוֹת הַנְּפָשׁוֹת לִמְקוֹמָם, וְעַל זֶה (תהלים צב) וֶאֱמוּנָתְךְ בַּלֵּילוֹת כָּתוּב.</p>\n<p>וַתִּפָּקַֹחְנָה עֵינֵי שְׁנֵיהֶם. רַבִּי חִיָּא אָמַר, שֶׁהֲרֵי נִפְקְחוּ לָדַעַת רָעוֹת הָעוֹלָם מַה שֶּׁלֹּא יָדְעוּ עַד עַכְשָׁו. כֵּיוָן שֶׁיָּדְעוּ וְנִפְקְחוּ לָדַעַת רַע, אָז יָדְעוּ כִּי עֵירֻמִּם הֵם, שֶׁאִבְּדוּ זֹהַר עֶלְיוֹן שֶׁהָיָה מְכַסֶּה עֲלֵיהֶם וְהִסְתַּלֵּק מֵהֶם, וְנִשְׁאֲרוּ עֲרֻמִּים מִמֶּנּוּ.</p>\n<p>וַיִּתְפְּרוּ עֲלֵה תְאֵנָה - נִדְבְּקוּ לְהִתְכַּסּוֹת בְּאוֹתָם צְלָמִים שֶׁל אוֹתוֹ אִילָן שֶׁאָכְלוּ מִמֶּנּוּ שֶׁנִּקְרָאִים עָלִים שֶׁל הָאִילָן. וַיַּעֲשׂוּ לָהֶם חֲגֹרֹת - רַבִּי יוֹסֵי אָמַר, כֵּיוָן שֶׁיָּדְעוּ מֵהָעוֹלָם הַזֶּה וְנִדְבְּקוּ בוֹ, רָאוּ שֶׁהָעוֹלָם הַזֶּה מֻנְהָג עַל יְדֵי אוֹתָם עָלִים שֶׁל הָאִילָן, וְעָשׂוּ לָהֶם חֹזֶק לְהִתְחַזֵּק בָּהֶם בָּעוֹלָם הַזֶּה. וְאָז יָדְעוּ כָּל מִינֵי כְשָׁפִים שֶׁל הָעוֹלָם, וְרָצוּ לַחְגֹּר כְּלֵי זַיִן בְּאוֹתָם עָלִים שֶׁל הָאִילָן כְּדֵי לְהָגֵן עֲלֵיהֶם.</p>\n<p>רַבִּי יְהוּדָה אָמַר, אָז נִכְנְסוּ שְׁלֹשָׁה בַּדִּין וְנִדּוֹנוּ, וְהָעוֹלָם הַתַּחְתּוֹן הִתְקַלֵּל וְלֹא עָמַד בְּקִיּוּמוֹ בִּגְלַל זֻהֲמַת הַנָּחָשׁ, עַד שֶׁעָמְדוּ יִשְׂרָאֵל בְּהַר סִינַי.</p>\n<p>אַחַר כָּךְ הִלְבִּישׁ אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא בִּלְבוּשִׁים שֶׁהָעוֹר נֶהֱנֶה מֵהֶם. זֶהוּ שֶׁכָּתוּב כָּתְנוֹת עוֹר. בַּתְּחִלָּה הָיוּ כָּתְנוֹת אוֹר שֶׁהָיוּ מִשְׁתַּמְּשִׁים בָּהֶם בָּעֶלְיוֹנִים שֶׁלְּמַעְלָה, מִשּׁוּם שֶׁמַּלְאֲכֵי הַשָּׁרֵת הָיוּ בָּאִים לֵהָנוֹת מֵאוֹתוֹ הָאוֹר. זֶהוּ שֶׁכָּתוּב (שם ח) וַתְּחַסְּרֵהוּ מְּעַט מֵאֱלֹהִים וְכָבוֹד וְהָדָר תְּעַטְּרֵהוּ. וְכָעֵת שֶׁחָטְאוּ - כָּתְנוֹת עוֹר, שֶׁהָעוֹר נֶהֱנֶה מֵהֶם וְלֹא הַנֶּפֶשׁ.</p>\n<p>אַחַר כָּךְ הוֹלִידוּ בֵּן רִאשׁוֹן. בֵּן שֶׁל הַזֻּהֲמָה הָיָה. שְׁנַיִם בָּאוּ עַל חַוָּה וְהִתְעַבְּרָה מֵהֶם וְהוֹלִידָה שְׁנַיִם, זֶה יָצָא לְמִינוֹ וְזֶה יָצָא לְמִינוֹ, וְרוּחַ שֶׁלָּהֶם נִפְרְדוּ זֶה לְצַד זֶה וְזֶה לְצַד זֶה. זֶה דּוֹמֶה לַצַּד שֶׁלּוֹ, וְזֶה דּוֹמֶה לַצַּד שֶׁלּוֹ.</p>\n<p>מִצַּד שֶׁל קַיִן כָּל הַמְּדוֹרִים שֶׁל צַד שֶׁל הַמִּינִים הָרָעִים וְרוּחוֹת וְשֵׁדִים וּכְשָׁפִים בָּאִים, וּמִצַּד שֶׁל הֶבֶל שֶׁל רַחֲמִים יוֹתֵר וְלֹא בִשְׁלֵמוּת. יַיִן טוֹב בְּיַיִן רַע. וְלֹא נִתְקַן עִמּוֹ עַד שֶׁבָּא שֵׁת וְהִתְיַחֲסוּ מִמֶּנּוּ כָּל אוֹתָם דּוֹרוֹת שֶׁל צַדִּיקֵי עוֹלָם, וּבוֹ נִשְׁתַּל הָעוֹלָם. וּמִקַּיִן בָּאוּ כָּל אוֹתָם חֲצוּפִים וּרְשָׁעִים וְרִשְׁעֵי הָעוֹלָם.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, בְּשָׁעָה שֶׁחָטָא קַיִן, הָיָה פוֹחֵד, בִּגְלַל שֶׁרָאָה לְפָנָיו מִינֵי מַחֲנוֹת מְזֻיָּנִים וּבָאִים לַהֲרֹג אוֹתוֹ. וּכְשֶׁחָזַר בִּתְשׁוּבָה, מָה אָמַר? הֵן גֵּרַשְׁתָּ אֹתִי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה וּמִפָּנֶיךְ אֶסָּתֵר. מַה זֶּה וּמִפָּנֶיךְ אֶסָּתֵר? אֶלָּא אֶהְיֶה נִסְתָּר מֵהַבִּנְיָן שֶׁלִּי. רַבִּי אַבָּא אָמַר, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כב) וְלֹא הִסְתִּיר פָּנָיו מִמֶּנּוּ. (שמות ג) וַיַּסְתֵּר מֹשֶׁה פָּנָיו. וְעַל זֶה וּמִפָּנֶיךְ אֶסָּתֵר, מֵאוֹתָם הַפָּנִים שֶׁלְּךְ אֶהְיֶה נִסְתָּר שֶׁלֹּא יַשְׁגִּיחוּ בִי. וְעַל זֶה וְהָיָה כָּל מֹצְאִי יַהַרְגֵנִי.</p>"],[9522011079,"<p>וַיָּשֶׂם ה' לְקַיִן אוֹת לְבִלְתִּי וְגוֹ'. מַה זֶּה אוֹת? אוֹת אַחַת מֵעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת הַתּוֹרָה נָתַן עָלָיו לְהָגֵן עָלָיו. אָמַר רַבִּי יְהוּדָה, מַה זֶּה שֶׁכָּתוּב וַיְהִי בִּהְיוֹתָם בַּשָּׂדֶה, מַה זֶּה בַּשָּׂדֶה? זוֹ הָאִשָּׁה. וְעַל זֶה קָם וְהָרַג אוֹתוֹ. שֶׁהֲרֵי מִצַּד זֶה יָרַשׁ לַהֲרֹג מִצַּד שֶׁל סמא\"ל שֶׁגָּרַם מָוֶת לְכָל הָעוֹלָם. וְקִנֵּא קַיִן בְּהֶבֶל עַל הַנְּקֵבָה שֶׁלּוֹ. רַבִּי חִיָּיא אָמַר, הֲרֵי רָאִינוּ שֶׁכָּתוּב וַיִּחַר לְקַיִן מְאֹד וַיִּפְּלוּ פָּנָיו, עַל שֶׁלֹּא הִתְקַבֵּל קָרְבָּנוֹ. אָמַר לוֹ, כָּךְ הוּא, וְהַכֹּל הָיָה לְנֶגְדּוֹ.</p>\n<p>וְאָמַר רַבִּי יְהוּדָה, מַה זֶּה שֶׁכָּתוּב הֲלֹא אִם תֵּיטִיב שְׂאֵת וְאִם לֹא תֵיטִיב לַפֶּתַח חַטָּאת רֹבֵץ? אֶלָּא כָּךְ אָמַר, הֲלֹא אִם תֵּיטִיב מַעֲשֶׂיךְ, אָז שְׂאֵת. מַה זֶּה שְׂאֵת? כְּמוֹ שֶׁכָּתוּב (בראשית מט) יֶתֶר שְׂאֵת. שֶׁהֲרֵי לַבְּכוֹר יֵשׁ שֶׁבַח יָתֵר בַּכֹּל תָּמִיד, וְתָלוּי בְּמַעֲשָׂיו. וְעַל זֶה אִם תֵּיטִיב שְׂאֵת, וְאִם לֹא תֵיטִיב לַפֶּתַח חַטָּאת רֹבֵץ.</p>"],[9522011080,"<p>מַה זֶּה לַפֶּתַח? זֶהוּ פֶּתַח שֶׁלְּמַעְלָה שֶׁמִּמֶּנּוּ יוֹצְאִים דִּינִים עַל מַעֲשִׂים רָעִים שֶׁל הָעוֹלָם. פֶּתַח, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק. וּלְאוֹתוֹ פֶּתַח - חַטָּאת רֹבֵץ, זֶה מַלְאַךְ הַמָּוֶת, וְהוּא עָתִיד לְהִפָּרַע מִמְּךְ.</p>\n<p>בֹּא רְאֵה, בְּרֹאשׁ הַשָּׁנָה נוֹלַד אָדָם. בְּרֹאשׁ הַשָּׁנָה וַדַּאי סוֹד לְמַעְלָה וּלְמַטָּה. רֹאשׁ הַשָּׁנָה לְמַעְלָה. רֹאשׁ הַשָּׁנָה לְמַטָּה. בְּרֹאשׁ הַשָּׁנָה עֲקָרוֹת נִפְקָדוֹת. מִנַּיִן לָנוּ שֶׁבְּרֹאשׁ הַשָּׁנָה זֶה הָיָה? שֶׁכָּתוּב (בראשית כא) וַה' פָּקַד אֶת שָׂרָה. וַה' דַּוְקָא זֶה רֹאשׁ הַשָּׁנָה. וּמִשּׁוּם שֶׁאָדָם יָצָא בְּרֹאשׁ הַשָּׁנָה (ויצא) בְדִין, וְהָעוֹלָם עוֹמֵד בְּדִין, וּמִשּׁוּם כָּךְ לַפֶּתַח וַדַּאי. חַטָּאת רֹבֵץ - כְּדֵי לְהִפָּרַע מִמְּךְ. וְאֵלֶיךְ תְּשׁוּקָתוֹ - עַד שֶׁתֻּשְׁמַד.</p>\n<p>וְאַתָּה תִּמְשָׁל בּוֹ - סוֹד הוּא, שֶׁכָּתוּב (נחמיה ט) וְאַתָּה מְחַיֶּה אֶת כֻּלָּם. מִכָּאן אָמְרוּ, לֹא שׁוֹלֵט הַקָּדוֹשׁ בָּרוּךְ הוּא אֶלָּא בִּזְמַן שֶׁיֻּשְׁמְדוּ רִשְׁעֵי הָעוֹלָם. וְעַל זֶה, כֵּיוָן שֶׁמַּלְאַךְ הַמָּוֶת יַשְׁמִיד אוֹתָם, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵט עָלָיו שֶׁלֹּא יֵצֵא לְהָרַע לָעוֹלָם, שֶׁכָּתוּב וְאַתָּה תִּמְשָׁל בּוֹ (בתשובה). וְאַתָּה דַּוְקָא.</p>\n<p>אָמַר רַבִּי יִצְחָק, בַּקֶּשֶׁר שֶׁל הַמַּחֲלֹקֶת הַמּוֹשֵׁל מָצוּי. רַבִּי יְהוּדָה אָמַר, וְאַתָּה תִּמְשָׁל בּוֹ - בִּתְשׁוּבָה.</p>"],[9522011081,"<p>רַבִּי יוֹסֵי אָמַר, כְּשֶׁהָיוּ אוֹתָם דּוֹרוֹת שֶׁל קַיִן הוֹלְכִים בָּעוֹלָם, הָיוּ מְחַלְּקִים אֶת הָאָרֶץ, וְהָיוּ דוֹמִים לְעֶלְיוֹנִים וְתַחְתּוֹנִים. אָמַר רַבִּי יִצְחָק, עֲזָ\"א וַעֲזָאֵ\"ל, כְּשֶׁנָּפְלוּ מִמְּקוֹם קְדֻשָּׁתָם מִלְמַעְלָה, רָאוּ בְּנוֹת בְּנֵי אָדָם וְחָטְאוּ וְהוֹלִידוּ בָנִים. וְאֵלֶּה הָיוּ נְפִילִים, שֶׁכָּתוּב וְהַנְּפִלִים הָיוּ בָאָרֶץ.</p>\n<p>רַבִּי חִיָּיא אָמַר, בְּנֵי קַיִן הָיוּ בְּנֵי אֱלֹהִים, שֶׁהֲרֵי כְּשֶׁבָּא סמא\"ל עַל חַוָּה, הִטִּיל בָּהּ זֻהֲמָה וְהִתְעַבְּרָה וְהוֹלִידָה אֶת קַיִן, וְהַמַּרְאֶה שֶׁלּוֹ לֹא הָיָה דוֹמֶה לִשְׁאָר בְּנֵי אָדָם, וְכָל אוֹתָם שֶׁבָּאוּ מֵהַצַּד שֶׁלּוֹ, לֹא הָיוּ נִקְרָאִים אֶלָּא בְּנֵי הָאֱלֹהִים.</p>\n<p>רַבִּי יְהוּדָה אָמַר, וַאֲפִלּוּ אוֹתָם (בני) נְפִילִים כָּךְ נִקְרָאִים, הֵמָּה הַגִּבֹּרִים. שִׁשִּׁים הָיוּ בָּאָרֶץ כַּחֶשְׁבּוֹן שֶׁלְּמַעְלָה. כָּתוּב כָּאן הֵמָּה הַגִּבֹּרִים אֲשֶׁר מֵעוֹלָם, וְכָתוּב שָׁם (שיר ג) שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ. רַבִּי יוֹסֵי אוֹמֵר, הֵמָּה הַגִּבּוֹרִים אֲשֶׁר מֵעוֹלָם מַמָּשׁ. מֵעוֹלָם דַּוְקָא. אַנְשֵׁי הַשֵּׁם, מַהוּ שֵׁם זֶה? הוּא עוֹלָם שֶׁאָמַרְנוּ. אַנְשֵׁי הַשֵּׁם דַּוְקָא. כָּתוּב כָּאן אַנְשֵׁי הַשֵּׁם, וְכָתוּב שָׁם (ויקרא כד) בְּנָקְבוֹ שֵׁם, וְכָתוּב (שם) וַיִּקֹּב בֶּן הָאִשָּׁה הַיִּשְׂרְאֵלִית אֶת הַשֵּׁם.</p>\n<p>רַבִּי חִיָּיא אָמַר, מֵעוֹלָם מַמָּשׁ הָיוּ, וּמֵעוֹלָם שֶׁלְּמַטָּה לָקַח אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (זה היו, וגברים גבורים של צד הרע היו, שכתוב אנשי שם, ולא כתוב אנשי השם, אלא אנשי שם, כמו זה כתוב) (תהלים כה) זְכֹר רַחֲמֶיךְ ה' וַחֲסָדֶיךְ כִּי מֵעוֹלָם הֵמָּה. מֵעוֹלָם וַדַּאי. וּמֵעוֹלָם שֶׁלְּמַטָּה לָקַח אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא. וְהֵם אָבוֹת רִאשׁוֹנִים לִהְיוֹת מֶרְכָּבָה קְדוֹשָׁה לְמַעְלָה. גַּם כָּאן הֵמָּה הַגִּבֹּרִים אֲשֶׁר מֵעוֹלָם. מֵעוֹלָם וַדַּאי לָקַח אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי יִצְחָק אָמַר, מֵעוֹלָם (ומהו)? זוֹ מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, שֶׁכָּתוּב (שיר ג) שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ. רַבִּי אָחָא אָמַר, כֻּלָּם נִקְרְאוּ בְּנֵי הָאֱלֹהִים (שהרי עדין לא התבשמה).</p>\n<p>אָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה, בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם, בָּרָא אוֹתוֹ בְּגַן עֵדֶן וְצִוָּה אוֹתוֹ עַל שֶׁבַע מִצְווֹת. חָטָא וְגֹרַשׁ מִגַּן עֵדֶן, וּשְׁנֵי מַלְאֲכֵי שָׁמַיִם, עֲזָ\"א וַעֲזָאֵ\"ל, אָמְרוּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: אִלּוּ הָיִינוּ אָנוּ בָּאָרֶץ, הָיִינוּ צַדִּיקִים. אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא: וְכִי אַתֶּם יְכוֹלִים עַל יֵצֶר הָרָע? אָמְרוּ לְפָנָיו: יְכוֹלִים. מִיָּד הִפִּיל אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר הַנְּפִלִים הָיוּ בָאָרֶץ, וְכָתוּב הַגִּבּרִים. וּבְשָׁעָה שֶׁיָּרְדוּ לָאָרֶץ נִכְנַס בָּהֶם יֵצֶר הָרָע, שֶׁנֶּאֱמַר וַיִּקְחוּ לָהֶם נָשִׁים מִכֹּל אֲשֶׁר בָּחָרוּ. חָטְאוּ וְנֶעֶקְרוּ מִקְּדֻשָּׁתָם. ע\"כ התוספתא.</p>\n<p>בֹּא רְאֵה, כָּל הַנְּטִיעוֹת הָיוּ נִסְתָּרִים רְשׁוּמִים דַּקִּיקִים בְּמָקוֹם אֶחָד. אַחַר כָּךְ עָקַר אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא וְשָׁתַל אוֹתָם בְּמָקוֹם אַחֵר וְהִתְקַיְּמוּ.</p>"],[9522011082,"<p>רַבֵּי יֵיסָא שָׁאַל, מַה זֶּה שֶׁכָּתוּב זֶה סֵפר תּוֹלְדת אָדָם בְּיוֹם בְּרֹא אֱלֹהִים אָדָם בִּדְמוּת אֱלֹהִים עָשָׂה אֹתוֹ זָכָר וּנְקֵבָה בְּרָאָם וַיְבָרֶךְ אֹתָם? אָמַר לוֹ רַבִּי אַבָּא, זֶה סוֹד עֶלְיוֹן. שָׁנִינוּ, שְׁלֹשָׁה סְפָרִים נִפְתָּחִים בְּרֹאשׁ הַשָּׁנָה, אֶחָד שֶׁל צַדִּיקִים גְּמוּרִים וְכוּ'. סֵפֶר עֶלְיוֹן שֶׁהֲרֵי מִמֶּנּוּ יוֹצֵא הַכֹּל, מִמֶּנּוּ יוֹצֵאת כְּתִיבָה. סֵפֶר אֶמְצָעִי כְּלָלוּת שֶׁל מַעְלָה וּמַטָּה (ספר שהוא כללות שלמעלה ולמטה ואוחז לכל הצדדים סוד וכו') (ואוחז לכל הצדדים סוד של אדם הראשון, ספר שלישי שנקרא (נ\"א ונקרָא) תורה) שֶׁתּוֹרָה שֶׁבִּכְתָב אָדָם הָרִאשׁוֹן. סֵפֶר שלישי שֶׁנִּקְרָא תּוֹלְדת אָדָם, וְזֶהוּ שֶׁל צַדִּיקִים גְּמוּרִים. זֶהוּ שֶׁכָּתוּב זֶה סֵפֶר תּוֹלְדֹת אָדָם, זֶה צַדִּיק (יסוד), וַדַּאי שֶׁעוֹשֶׂה תוֹלָדוֹת. בְּיוֹם בְּרֹא אֱלֹהִים אָדָם בִּדְמוּת אֱלֹהִים, שֶׁהֲרֵי וַדַּאי אָז נִתְקַן הַכֹּל לְמַעְלָה וּמַטָּה, וְהִתְקַיְּמוּ בְּדֻגְמָה אַחַת. זָכָר וּנְקֵבָה בְּרָאָם, סְתָם אֶחָד נִכְלָל בְּאֶחָד.</p>\n<p>מִשְׁנָה, כָּתוּב (משלי יח) מִגְדַּל עֹז שֵׁם ה' בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב. זֶהוּ סֵפֶר תּוֹלְדוֹת אָדָם שֶׁרָץ בְּאוֹתוֹ מִגְדָּל. הַמִּגְדָּל הַזֶּה מַה מַּעֲשֵׂהוּ? אֶלָּא זֶהוּ מִגְדַּל דָּוִד, וְזֶהוּ מִגְדַּל עֹז שֵׁם ה', וְהַכֹּל אֶחָד. כָּאן יָדוּעַ לִבְנֵי הָאֱמוּנָה זֶהוּ וַדַּאי סֵפֶר תּוֹלְדוֹת ((יש שלא גורסים) אדם. לבני האמונה סודו מגדל עז שם ה' בו ירוץ צדיק ונשגב. יהו\"ה צדיק) אָדָם לִבְנֵי הָאֱמוּנָה. (ראה ציור למעלה).</p>\n<p>וְאָמַר רַבִּי אַבָּא, סֵפֶר וַדַּאי יָרַד לוֹ לְאָדָם הָרִאשׁוֹן, וּבוֹ הָיָה יוֹדֵעַ חָכְמָה עֶלְיוֹנָה. וְסֵפֶר זֶה הִגִּיעַ לִבְנֵי אֱלֹהִים חַכְמֵי הַדּוֹר, וּמִי שֶׁזָּכָה לְהִתְבּוֹנֵן בּוֹ, יָדַע בּוֹ חָכְמָה עֶלְיוֹנָה. וּמִתְבּוֹנְנִים בּוֹ וְיוֹדְעִים בּוֹ. וְסֵפֶר זֶה הוֹרִיד אוֹתוֹ בַּעַל הַסּוֹדוֹת וּשְׁלֹשָׁה שְׁלִיחִים מְמֻנִּים לְפָנָיו.</p>\n<p>וּבְשָׁעָה שֶׁיָּצָא אָדָם מִגַּן עֵדֶן, אָחַז בְּאוֹתוֹ סֵפֶר. כְּשֶׁיָּצָא (ממנו) טַס מִמֶּנּוּ (לשער), הִתְפַּלֵּל וּבָכָה לִפְנֵי רִבּוֹנוֹ, וְהֵשִׁיבוּ לוֹ אוֹתוֹ כְּמוֹ מִקֹּדֶם, כְּדֵי שֶׁלֹּא תִשָּׁכַח חָכְמָה מִבְּנֵי אָדָם וְיִשְׁתַּדְּלוּ לָדַעַת אֶת רִבּוֹנָם.</p>\n<p>וְכֵן שָׁנִינוּ, סֵפֶר הָיָה לוֹ לַחֲנוֹךְ, וְזֶה סֵפֶר מִמָּקוֹם שֶׁל סֵפֶר שֶׁל תּוֹלְדוֹת אָדָם הָיָה, וְזֶהוּ סוֹד הַחָכְמָה, שֶׁהֲרֵי מֵהָאָרֶץ נִטַּל. זֶהוּ שֶׁכָּתוּב וְאֵינֶנּוּ כִּי לָקַח אֹתוֹ אֱלֹהִים. וְהוּא הַנַּעַר, שֶׁכָּתוּב (משלי כב) חֲנֹךְ לַנַּעַר עַל פִּי דַרְכּוֹ.</p>\n<p>וְכָל גְּנָזִים עֶלְיוֹנִים נִמְסְרוּ בְיָדוֹ. וְזֶה מָסַר וְנָתַן וְעָשָׂה שְׁלִיחוּת, וְאֶלֶף מַפְתְּחוֹת נִמְסְרוּ בְיָדוֹ. וּמֵאָה בְרָכוֹת לוֹקֵחַ בְּכָל יוֹם וְקוֹשֵׁר קְשָׁרִים לְרִבּוֹנוֹ. הַקָּדוֹשׁ בָּרוּךְ הוּא לָקַח אוֹתוֹ מֵהָעוֹלָם לְשַׁמֵּשׁ אוֹתוֹ. זֶהוּ שֶׁכָּתוּב כִּי לָקַח אֹתוֹ אֱלֹהִים.</p>\n<p>וּמִזֶּה נִמְסַר סֵפֶר שֶׁנִּקְרָא סִפְרוֹ שֶׁל חֲנוֹךְ. בְּשָׁעָה שֶׁאָחַז אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, הֶרְאָה לוֹ כָּל גְּנָזִים עֶלְיוֹנִים. הֶרְאָה לוֹ עֵץ הַחַיִּים בְּאֶמְצַע הַגָּן וְהֶעָלִים שֶׁלּוֹ וַעֲנָפָיו, וְהַכֹּל רָאִינוּ בְּסִפְרוֹ. אַשְׁרֵי אוֹתָם חֲסִידִים עֶלְיוֹנִים שֶׁחָכְמָה עֶלְיוֹנָה הִתְגַּלְּתָה לָהֶם וְלֹא נִשְׁכְּחָה מֵהֶם לְעוֹלָמִים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כה) סוֹד ה' לִירֵאָיו וּבְרִיתוֹ לְהוֹדִיעָם.</p>"],[9522011083,"<p>וַיֹּאמֶר ה' לֹא יָדוֹן רוּחִי בָאָדָם לְעֹלָם בְּשַׁגַּם הוּא בָשָׂר וְגוֹ'. רַבִּי אָחָא אָמַר, בְּאוֹתוֹ זְמַן הָיָה אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, מוֹצִיא רוּחַ עֶלְיוֹנָה מֵעֵץ הַחַיִּים וּמוֹרִיק בָּאִילָן (ששורה בו המות) (מעץ המות), וְנִמְשָׁכוֹת רוּחוֹת לְתוֹךְ בְּנֵי אָדָם יָמִים (זמגים) רַבִּים, עַד שֶׁעָלוּ רָעוֹת וְהִתְיַצְּבוּ לַפֶּתַח. אָז הִסְתַּלְּקָה רוּחַ עֶלְיוֹנָה מֵאוֹתוֹ אִילָן בְּשָׁעָה שֶׁפָּרְחוּ נְשָׁמוֹת בִּבְנֵי (מבני) אָדָם. זֶהוּ שֶׁכָּתוּב לֹא יָדוֹן רוּחִי בָאָדָם לְעֹלָם. לָתֵת לְעוֹלָם בְּשָׁעָה שֶׁפָּרְחוּ נְשָׁמוֹת בִּבְנֵי אָדָם.</p>\n<p>בְּשַׁגַּם הוּא בָשָׂר, רַבִּי אֶלְעָזָר אָמַר, (בישיבתו של רבי אלעזר אמרו) בְּשַׁגַּם זֶה מֹשֶׁה, שֶׁהוּא מֵאִיר לַלְּבָנָה, וּמִכֹּחַ זֶה עוֹמְדִים בְּנֵי אָדָם בָּעוֹלָם יָמִים (זמגים) רַבִּים. וְהָיוּ יָמָיו מֵאָה וְעֶשְׂרִים שָׁנָה - רֶמֶז לְמֹשֶׁה, שֶׁעַל יָדוֹ נִתְּנָה תּוֹרָה. וְאָז מוֹרִיק (זורק) חַיִּים לִבְנֵי אָדָם מֵאוֹתוֹ עֵץ הַחַיִּים. וְכָךְ הָיָה. אִלְמָלֵא שֶׁחָטְאוּ יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב (שמות לב) חָרוּת עַל הַלֻּחוֹת. חֵרוּת מִמַּלְאַךְ הַמָּוֶת. שֶׁהֲרֵי עֵץ הַחַיִּים הָיָה מוֹשֵׁךְ לְמַטָּה.</p>\n<p>וְעַל בְּשַׁגַּ\"ם שֶׁהוּא בָשָׂר עוֹמֵד הַדָּבָר לְהָרִיק (להרחיק) רוּחַ שֶׁל חַיִּים. בְּשַׁגַּם אָחוּז לְמַטָּה, אָחוּז לְמַעְלָה. וְעַל זֶה שָׁנִינוּ מֹשֶׁה לֹא מֵת, אֶלָּא הִתְכַּנֵּס מִן הָעוֹלָם וְהָיָה מֵאִיר לַלְּבָנָה, שֶׁהֲרֵי הַשֶּׁמֶשׁ, אַף עַל גַּב שֶׁמִּתְכַּנֵּס מִן הָעוֹלָם, לֹא מֵת, אֶלָּא נִכְנָס וּמֵאִיר לַלְּבָנָה, כָּךְ מֹשֶׁה.</p>\n<p>דָּבָר אַחֵר בְּשַׁגַּם הוּא בָשָׂר - בִּמְשִׁיכַת הָרוּחַ בִּבְנֵי אָדָם זְמַן רַב, חוֹזֵר לִהְיוֹת הַבָּשָׂר לְהִמָּשֵׁךְ אַחַר הַגּוּף וּלְהִשְׁתַּדֵּל בְּמַעֲשֵׂי הָעוֹלָם הַזֶּה.</p>\n<p>אָמַר רַבִּי יִצְחָק, כָּל (הדורות שגתקנו משת, כלם צדיקים וחסידים. אחר כך התפשטו והולידו, ולמדו אמנות (וחכמה)) הָעוֹלָם לַהֲרֹג בִּרְמָחִים וּבַחֲרָבוֹת. עַד שֶׁבָּא נֹחַ וְהִתְקִין לָהֶם תִּקּוּן הָעוֹלָם וְלַעֲבֹד וּלְתַקֵּן אֶת הָאָרֶץ. שֶׁהֲרֵי בַּהַתְחָלָה לֹא הָיוּ זוֹרְעִים וְקוֹצְרִים, אַחַר כָּךְ הִצְטָרְכוּ אֶת זֶה, שֶׁכָּתוּב עוֹד כָּל יְמֵי הָאָרֶץ וְגוֹ'.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְתַקֵּן עוֹלָם וּלְהַתְקִין רוּחַ בִּבְנֵי אָדָם כְּדֵי שֶׁיַּאֲרִיכוּ יָמִים לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב (ישעיה סה) כִּי כִּימֵי הָעֵץ יְמֵי עַמִּי וְגוֹ'. וְכָתוּב (שם כה) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְחֶרְפַּת עַמּוֹ יָסִיר מֵעַל כָּל הָאָרֶץ כִּי ה' דִּבֵּר. עֵד כָּאן נִתְקְנוּ הַדְּבָרִים. מִכָּאן וָהָלְאָה תִּקּוּן הַפָּרָשָׁה. בְּרֵאשִׁית</p>"],[9522011084,"<p>אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי שָׁנִינוּ, שֶׁכְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, חָקַק בַּחֲקִיקוֹת שֶׁל סוֹד הָאֱמוּנָה תּוֹךְ אוֹרוֹת בְּסוֹדוֹת עֶלְיוֹנִים וְחָקַק לְמַעְלָה וְחָקַק לְמַטָּה, וְהַכֹּל בְּסוֹד אֶחָד. וְעָשָׂה עוֹלָם תַּחְתּוֹן כְּמוֹ שֶׁעוֹלָם הָעֶלְיוֹן. וְזֶה עוֹמֵד כְּנֶגֶד זֶה לִהְיוֹת הַכֹּל אֶחָד בְּיִחוּד אֶחָד. וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא חָקַק חֲקִיקוֹת שֶׁל אוֹתִיּוֹת לְמַעְלָה וּלְמַטָּה, וּבָהֶם בָּרָא אֶת הָעוֹלָמוֹת.</p>\n<p>וּבֹא וּרְאֵה, כְּמוֹ שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, כָּךְ גַּם בָּרָא אֶת אָדָם הָרִאשׁוֹן. פָּתַח וְאָמַר, (הושע ו) וְהֵמָּה כְּאָדָם עָבְרוּ בְרִית. שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עִטֵּר אוֹתוֹ בַּעֲטָרוֹת עֶלְיוֹנוֹת, וּבָרָא אוֹתוֹ בְּשִׁשָּׁה צְדָדִים שֶׁל הָעוֹלָם לִהְיוֹת שָׁלֵם בַּכֹּל, וְכֻלָּם זָעוּ וּפָחֲדוּ מִלְּפָנָיו. שֶׁהֲרֵי כְּשֶׁנִּבְרָא אָדָם, נִבְרָא בִּדְמוּת עֶלְיוֹנָה, וְהָיוּ מִסְתַּכְּלִים בְּאוֹתָהּ דְּמוּת וְזָעִים וּפוֹחֲדִים מִלְּפָנָיו. וְאַחַר כָּךְ הִכְנִיסוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַן עֵדֶן לְהִתְעַדֵּן שָׁם בְּעִדּוּנִים עֶלְיוֹנִים, וְהָיוּ מַלְאָכִים עֶלְיוֹנִים מְשַׁמְּשִׁים לְפָנָיו וְסוֹבְבִים אוֹתוֹ, וְסוֹדוֹת רִבּוֹנָם הָיוּ מוֹדִיעִים לוֹ.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁהִכְנִיס אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְגַן עֵדֶן, הָיָה רוֹאֶה וּמִסְתַּכֵּל מִשָּׁם כָּל הַסּוֹדוֹת הָעֶלְיוֹנִים וְכָל הַחָכְמָה כְּדֵי לָדַעַת וּלִהִסְתַּכֵּל בִּכְבוֹדוֹ רִבּוֹנוֹ.</p>\n<p>שִׁבְעָֹה הֵיכָלוֹת מְדוֹרִים הֵם לְמַעְלָה, שֶׁהֵם סוֹד הָאֱמוּנָה הָעֶלְיוֹנָה. וְשִׁבְעָה הֵיכָלוֹת הֵם לְמַטָּה (כמו שהם אחד כנגד אחד, שבעה מדורים של היכלות הם למטה) כְּמוֹ שֶׁלְּמַעְלָה. וְהֵם שִׁשָּׁה כְּדֻגְמָא עֶלְיוֹנָה, וְאֶחָד טָמִיר וְגָנוּז הוּא לְמַעְלָה. וְכָל אֵלֶּה הֵם בְּסוֹד עֶלְיוֹן, מִשּׁוּם שֶׁכָּל הַהֵיכָלוֹת הַלָּלוּ יֵשׁ בָּהֶם כְּמוֹ שֶׁלְּמַעְלָה, וְיֵשׁ בָּהֶם כְּמוֹ שֶׁלְּמַטָּה, לִהְיוֹת כּוֹלֵל בִּדְמוּת שֶׁל הַסּוֹד שֶׁלְּמַעְלָה וּבִדְמוּת שֶׁל הַסּוֹד שֶׁלְּמַטָּה, וּבָהֶם הָיָה דִיּוּרוֹ שֶׁל אָדָם.</p>\n<p>וּלְאַחַר שֶׁגֹּרַשׁ מִגַּן עֵדֶן, הִתְקִין אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לְנִשְׁמוֹת הַצַּדִּיקִים לְהִשְׁתַּעֲשֵׁעַ בָּהֶם כָּרָאוּי מִזִּיו שֶׁל הַכָּבוֹד הָעֶלְיוֹן, וְכָל אֶחָד וְאֶחָד הִתְתַּקֵּן כְּמוֹ שֶׁלְּמַעְלָה וּכְמוֹ שֶׁלְּמַטָּה כְּמוֹ שֶׁפֵּרַשְׁנוּ.</p>"],[9522011085,"<p>הֵיכָל רִאשׁוֹן - מָקוֹם שֶׁהוּא נִתְקָן לְמַטָּה לִהְיוֹת כְּמוֹ שֶׁלְּמַעְלָה. וַהֲרֵי הֵעִירוּ הַחֲבֵרִים הַנְהָגוֹת גַּן עֵדֶן כְּמוֹ שֶׁהוּא בְּסוֹד עֶלְיוֹן (שהוא נתקן לבפנים תוך סתר של הסוד שלמטה גנוז ונסתר מכל) (נ\"א: והוא נתקן לבפנים ונסתר מהכל) וְלֹא שׁוֹלֶטֶת בּוֹ הָעַיִן, פְּרָט לְנִשְׁמוֹת הַצַּדִּיקִים, לִהְיוֹת חֲקוּקִים לְמַעְלָה וּלְמַטָּה וּלְהִסְתַּכֵּל מִשָּׁם בְּסוֹד רִבּוֹנָם וּבָעִנּוּג שֶׁלְּמַעְלָה.</p>\n<p>וְאֵלֶּה אוֹתָם צַדִּיקִים שֶׁלֹּא הֶחְלִיפוּ כְּבוֹד רִבּוֹנָם בִּשְׁבִיל יִרְאָה אַחֶרֶת. כָּתוּב (משלי יב) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ, סוֹד הָאֱמוּנָה לְהִדָּבֵק בֶּן אָדָם (ברבונו) וְלִפְחֹד מִמֶּנּוּ תָמִיד וְלֹא יִסְטֶה לְיָמִין וְלִשְׂמֹאל. וַהֲרֵי בֵּאַרְנוּ שֶׁלֹּא יֵלֵךְ בֶּן אָדָם אַחַר יִרְאָה אַחֶרֶת שֶׁנִּקְרֵאת אֵשֶׁ\"ת זְנוּנִי\"ם. וְלָכֵן כָּתוּב (שם ז) לִשְׁמָרְךְ מֵאִשָּׁה זָרָה מִנָּכְרִיָּה אֲמָרֶיהָ הֶחֱלִיקָה.</p>\n<p>הֵיכָל זֶה עוֹמֵד בַּדְּמוּת שֶׁל סוֹד עֶלְיוֹן, הֱיוֹת שֶׁכְּשֶׁנִּשְׁמוֹת הַצַּדִּיקִים יוֹצְאוֹת מִן הָעוֹלָם הַזֶּה, נִכְנָסִים לְתוֹךְ הַהֵיכָלוֹת הַלָּלוּ שֶׁבְּגַן עֵדֶן שֶׁלְּמַטָּה, וְשָׁם (נכנסים) יוֹשְׁבִים כָּל אֶחָד וְאֶחָד כָּל אוֹתוֹ זְמַן שֶׁצְּרִיכָה הַנְּשָׁמָה לָשֶׁבֶת שָׁם.</p>\n<p>וּבְכָל הֵיכָל וְהֵיכָל יֵשׁ דְּמֻיּוֹת כְּמוֹ (עליון) שֶׁלְּמַעְלָה וּדְמֻיּוֹת כְּמוֹ (למטה) שֶׁלְּמַטָּה. וְשָׁם מִתְלַבֶּשֶׁת הַנְּשָׁמָה בִּלְבוּשִׁים כְּמוֹ שֶׁל הָעוֹלָם הַזֶּה, וּמִתְעַדֶּנֶת שָׁם כָּל אוֹתוֹ זְמַן שֶׁצְּרִיכָה, עַד שֶׁמַּגִּיעַ הַזְּמַן לַעֲלוֹת לְמָקוֹם עֶלְיוֹן כְּמוֹ שֶׁצָּרִיךְ. וּמִתּוֹךְ אוֹתוֹ בֶּגֶד שֶׁהִתְלַבְּשָׁה בּוֹ, רוֹאָה דְמֻיּוֹת עֶלְיוֹנוֹת לְהִסְתַּכֵּל בִּכְבוֹד רִבּוֹנָם.</p>\n<p>בַּהֵיכָל הַזֶּה יֵשׁ מְאוֹרוֹת עֶלְיוֹנִים לְהִסְתַּכֵּל, וְנִשְׁמוֹת אוֹתָם הַגֵּרִים שֶׁהִתְגַּיְּרוּ עוֹמְדוֹת שָׁם וְנִכְנָסוֹת שָׁם לְהִסְתַּכֵּל בַּכָּבוֹד הָעֶלְיוֹן, וּמִתְלַבְּשׁוֹת שָׁם בִּלְבוּשׁ אֶחָד שֶׁל אוֹר שֶׁמֵּאִיר וְלֹא מֵאִיר. וְאוֹתוֹ הֵיכָל מְצֻפֶּה מֵאֶבֶן טוֹבָה וְזָהָב.</p>\n<p>וְשָׁם הוּא פֶּתַח אֶחָד שֶׁיּוֹרֵד כְּנֶגֶד פֶּתַח הַגֵּיהִנֹּם. מִשָּׁם מִסְתַּכְּלִים בְּכָל אוֹתָם רְשָׁעִים (של ישראל) (של עובדי עבודה זרה) שֶׁלֹּא נִכְנְסוּ בַּבְּרִית הַקְּדוֹשָׁה וְגֹרְשׁוּ בְּאוֹתָם מַלְאֲכֵי חַבָּלָה שֶׁטּוֹרְדִים אוֹתָם בְּאֵשׁ שֶׁדּוֹלֶקֶת. וְהֵם רוֹאִים וּשְׂמֵחִים עַל שֶׁהִ תְגַּיְּרוּ.</p>\n<p>וְשָׁלש פְּעָמִים בַּיּוֹם מוּאָרִים מִתּוֹךְ אוֹר עֶלְיוֹן וּמִשְׁתַּעְשְׁעִים שָׁם. וּמֵעֲלֵיהֶם עוֹבַדְיָה וְאוּנְקְלוּס הַגֵּר וּשְׁאָר הַגֵּרִים שֶׁהִתְגַּיְּרוּ. כְּמוֹ זֶה לְמַעְלָה כְּשֶׁזּוֹכִים לְהַעֲלוֹת נִשְׁמָתָם לְהִתְעַטֵּר שָׁם.</p>"],[9522011086,"<p>הֵיכָל שֵׁנִי. הֵיכָל זֶה עוֹמֵד לִפְנִים מֵהַהֵיכָל הָרִאשׁוֹן הַזֶּה, וְזֶה (הפתח הוא סמוך לתוך המערה) (נ\"א: היכל סמוך למערה) שֶׁל הָאָבוֹת. וְהַהֵיכָל הַזֶּה מֵאִיר יוֹתֵר מֵהָרִאשׁוֹן. כָּאן יֵשׁ כָּל אֲבָנִים יְקָרוֹת שֶׁמְּצַפּוֹת אוֹתוֹ.</p>\n<p>בְּתוֹךָ הַהֵיכָל הַזֶּה יֵשׁ אוֹר אֶחָד כָּלוּל מִכָּל הַגְּוָנִים, וְהוּא מֵאִיר מִלְמַעְלָה לְמַטָּה. בַּהֵיכָל הַזֶּה עוֹמְדִים (כל) אֵלּוּ שֶׁסָּבְלוּ יִסּוּרִים וָחֳלָאִים בָּעוֹלָם הַזֶּה כְּדֵי לְהִתְתַּקֵּן, וְהָיוּ מוֹדִים וּמְשַׁבְּחִים לְרִבּוֹנָם בְּכָל יוֹם, וְלֹא הָיוּ מְבַטְּלִים תְּפִלּוֹתֵיהֶם לְעוֹלָמִים.</p>\n<p>לִפְנִים מֵהַהֵיכָל הַזֶּה עוֹמְדִים כָּל אֵלּוּ שֶׁמְּקַדְּשִׁים (בכל יום) בְּכָל הַכֹּחַ שֵׁם רִבּוֹנָם, וְעוֹנִים אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ בְּכל הַכֹּחַ. וְאֵלֶּה הֵם עוֹמְדִים לִפְנַי וְלִפְנִים בַּהֵיכָל הַזֶּה. וְאוֹתוֹ אוֹר שֶׁכּוֹלֵל כָּל הַגְּוָנִים מֵאִיר לָהֶם. מֵאוֹתוֹ הָאוֹר עוֹמְדִים וְרוֹאִים מְאוֹרוֹת אֲחֵרִים שֶׁנֶּאֱחָזִים וְלֹא נֶאֱחָזִים בְּתוֹכָם. וּמֵעֲלֵיהֶם מָשִׁיחַ, שֶׁהוּא נִכְנָס וְעוֹמֵד בֵּינֵיהֶם וּמְנַחֵם אוֹתָם.</p>"],[9522011087,"<p>הוּא נוֹסֵעַ מֵהַהֵיכָל הַזֶּה וְנִכְנָס. בַּהֵיכָל הַשְּׁלִישִׁי, וְשָׁם כָּל אוֹתָם בְּנֵי חֳלָאִים וּכְאֵבִים קָשִׁים, וְכָל אוֹתָם תִּינוֹקוֹת שֶׁל בֵּית רַבָּן שֶׁלֹּא הִשְׁלִימוּ יְמֵיהֶם, וְכָל אוֹתָם הָעֲצוּבִים עַל חֻרְבַּן בֵּית הַמִּקְדָּשׁ (ושפכו) וְהָיוּ שׁוֹפְכִים דְּמָעוֹת. כֻּלָּם עוֹמְדִים בְּאוֹתוֹ הֵיכָל, וְהוּא מְנַחֵם אוֹתָם.</p>"],[9522011088,"<p>וְנוֹסֵעַ מֵהַהֵיכָל הַזֶּה וְנִכְנָס. בַּהֵיכָל הָרְבִיעִי, וְשָׁם כָּל אוֹתָם אֲבֵלֵי צִיּוֹן וִירוּשָׁלַיִם וְכָל אוֹתָם שֶׁנֶּהֶרְגוּ עַל יְדֵי שְׁאָר הָעַמִּים עוֹבְדֵי עַכּוּ\"ם. וְהוּא שׁוֹהֶה וּבוֹכֶה. וְאָז כָּל אוֹתָם נְשִׂיאִים שֶׁל זֶרַע דָּוִד, כֻּלָּם אוֹחֲזִים בּוֹ וּמְנַחֲמִים אוֹתוֹ.</p>\n<p>מַתְחִיל פַּעַם שְׁנִיָּה וּבוֹכֶה, עַד שֶׁיּוֹצֵא קוֹל, וְנֶאֱחָז בְּאוֹתוֹ קוֹל וְעוֹלֶה לְמַעְלָה וְשׁוֹהֶה שָׁם עַד רֹאשׁ חֹדֶשׁ. וּכְשֶׁיּוֹרֵד, יוֹרְדִים עִמּוֹ כַּמָּה אוֹרוֹת וְזִיוִים מְאִירִים לְכָל אוֹתָם הֵיכָלוֹת וּרְפוּאָה וְאוֹר לְכָל אוֹתָם הַהֲרוּגִים וּבְנֵי חֳלָאִים וּמַכְאוֹבִים שֶׁסָּבְלוּ עִם הַמָּשִׁיחַ.</p>\n<p>וְאָז לוֹבֵשׁ לְבוּשׁ מַלְכוּת. וְשָׁם חֲקוּקִים וּרְשׁוּמִים כָּל אוֹתָם הֲרוּגִים שֶׁל שְׁאָר הָעַמִּים עוֹבְדֵי עַכּוּ\"ם בְּאוֹתָהּ פּוּרְפִירָה, וְעוֹלָה אוֹתָהּ פּוּרְפִירָה לְמַעְלָה, וְנֶחְקָק שָׁם תּוֹךְ הַפּוּרְפִירָה הָעֶלְיוֹנָה שֶׁל הַמֶּלֶךְ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לִלְבֹּשׁ אוֹתָהּ פּוּרְפִירָה וְלָדוּן עַמִּים, שֶׁכָּתוּב (תהלים קי) יָדִין בַּגּוֹיִם מָלֵא גְוִיּוֹת. עַד שֶׁבָּא וּמְנַחֵם אוֹתָם, וְיוֹרְדִים עִמּוֹ (כמה) מְאוֹרוֹת וְעִדּוּנִים לְהִתְעַדֵּן, וְכַמָּה מַלְאָכִים וּמֶרְכָּבוֹת עִמּוֹ. כָּל אֶחָד וְאֶחָד בְּמַלְבּוּשׁ (נ\"א: וביד כל אחד ואחד מלבוש) לְהִתְלַבֵּשׁ בָּהֶם כָּל אוֹתָם נִשְׁמוֹת הַהֲרוּגִים, וְשָׁם מִתְעַדְּנִים כָּל אוֹתוֹ זְמַן שֶׁהוּא עוֹלֶה וְיוֹרֵד.</p>\n<p>לִפְנִים מֵהַהֵיכָל הַזֶּה עוֹמְדִים תּוֹךְ דַּרְגָּה עֶלְיוֹנָה אוֹתָם עֲשָׂרָה גְדוֹלִים מְמֻנִּים (כמו) רַבִּי עֲקִיבָא וַחֲבֵרָיו. וְכֻלָּם עוֹלִים בַּעֲלִיָּה תּוֹךְ אַסְפַּקְלַרְיָה שֶׁלְּמַעְלָה וּמְאִירִים בְּזִיו כָּבוֹד עֶלְיוֹן. עֲלֵיהֶם כָּתוּב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ.</p>"],[9522011089,"<p>בַּהֵיכָל הַחֲמִישִׁי קַיָּמִים כָּל אוֹתָם בַּעֲלֵי הַתְּשׁוּבָה הַשְּׁלֵמָה שֶׁשָּׁבוּ מֵחֲטָאֵיהֶם וְהִתְנַחֲמוּ בָהֶם וְנִשְׁמָתָם יָצְאָה בְּטָהֳרָה, (וכל אותם בעלי תשובה) וְכָל אֵלּוּ שֶׁקִּדְּשׁוּ שֵׁם רִבּוֹנָם וְקִבְּלוּ עֲלֵיהֶם מָוֶת. וּבְשַׁעַר הַהֵיכָל הַזֶּה (פתח) עוֹמֵד מְנַשֶּׁה מֶלֶךְ יְהוּדָה שֶׁקִּבְּלוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בִּתְשׁוּבָה שְׁלֵמָה וְחָתַר לוֹ חֲתִירָה לְקַבְּלוֹ.</p>\n<p>וְלִפְנִים מֵהֵיכָל זֶה עוֹמְדִים כָּל אוֹתָם בַּעֲלֵי תְשׁוּבָה שְׁלֵמָה, שֶׁנִּשְׁמָתָם יָצְאָה בְּשָׁעָה שֶׁהִתְמַרְמְרוּ עַל מַעֲשֵׂיהֶם. וְאֵלּוּ מִתְעַדְּנִים בְּעִדּוּן עֶלְיוֹן בְּכָל יוֹם וָיוֹם. וְשָׁלֹשׁ פְּעָמִים בְּיוֹם אוֹר נִכְנָס בְּאוֹתוֹ הֵיכָל שֶׁמִּתְעַדְּנִים בּוֹ כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, וְכָל אֶחָד נִכְוֶה מֵאוֹר שֶׁל הַחֻפָּה שֶׁל חֲבֵרוֹ, בֵּין לְמַטָּה בֵּין לְמַעְלָה.</p>\n<p>הַהֵיכָל הַזֶּה עוֹמֵד עַל אוֹתָם הֵיכָלוֹת תַּחְתּוֹנִים, וַאֲפִלּוּ צַדִּיקִים גְּמוּרִים לֹא יְכוֹלִים לְהִכָּנֵס לְתוֹךְ (ההוא) הַהֵיכָל הַזֶּה וְלַעֲמֹד בּוֹ. וְזוֹהִי דַּרְגָּה עֶלְיוֹנָה עַל הַכֹּל (בו), פְּרָט לְדַרְגַּת הַחֲסִידִים שֶׁהִיא דַרְגָּה עֶלְיוֹנָה עַל הַכֹּל.</p>"],[9522011090,"<p>הֵיכָל שִׁשִּׁי. הֵיכָל זֶה הוּא הֵיכַל הַחֲסִידִים. הֵיכָל זֶה הוּא עֶלְיוֹן עַל הַכֹּל. וְזֶהוּ הֵיכָל שֶׁעוֹמֵד עַל הַכֹּל. הֵיכַל הַיָּמִין אֵין מִי שֶׁיַּעֲמֹד בּוֹ, אֶלָּא אוֹתָם חֲסִידִים קְדוֹשִׁים וְכָל אוֹתָם שֶׁאוֹהֲבִים אֶת רִבּוֹנָם בְּאַהֲבָה רַבָּה. וּלְפֶתַח הַהֵיכָל הַזֶּה עוֹמְדִים כָּל אֵלּוּ שֶׁמְּיַחֲדִים יִחוּד שֶׁל רִבּוֹנָם בְּכָל יוֹם. וְאֵלֶּה נִכְנָסִים בַּהֵיכָל הַזֶּה וַעֲתִידִים לַעֲלוֹת בָּרִאשׁוֹנָה.</p>\n<p>וּמֵעַל הַפֶּתַח הַזֶּה אַבְרָהָם, יְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא. וּלְפֶתַח אַחֵר עוֹמֵד יִצְחָק שֶׁנֶּעֱקַד עַל גַּבֵּי הַמִּזְבֵּחַ וְהָיָה קָרְבָּן שָׁלֵם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וּלְפֶתַח אַחֵר לְבִפְנִים עוֹמֵד יַעֲקֹב הַשָּׁלֵם, וּשְׁנֵים עָשָׂר שְׁבָטִים סְבִיבוֹ, וּשְׁכִינָה עַל רָאשֵׁיהֶם.</p>\n<p>וּכְשֶׁיִּשְׂרָאֵל בְּצָרָה, מִתְעוֹרְרִים שְׁלֹשֶׁת הָאָבוֹת וּמְעוֹרְרִים אֶת הַשְּׁכִינָה לְהָגֵן עֲלֵיהֶם. וְאָז הִיא עוֹלָה וּמִתְעַטֶּרֶת לְמַעְלָה וּמְגִנָּה עַל יִשְׂרָאֵל. וּכְמוֹ שֶׁיֵּשׁ הֵיכָלוֹת לְמַטָּה בְּגַן עֵדֶן, כָּךְ גַּם לְמַעְלָה יֵשׁ הֵיכָלוֹת מְתֻקָּנִים שֶׁהֵם סוֹד הָאֱמוּנָה. וְכָל (אותם) הַהֵיכָלוֹת הַלָּלוּ מִתְקַשְּׁרִים וּמִתְעַטְּרִים בְּהֵיכָל אֶחָד שֶׁהוּא:</p>"],[9522011091,"<p>הֵיכָל הַשְּׁבִיעִי. וְהֵיכָל זֶה גָּנוּז וְנִסְתָּר מִכָּל שְׁאָר הַהֵיכָלוֹת. בְּאֶמְצַע הַהֵיכָל הַזֶּה עוֹמֵד עַמּוּד אֶחָד שֶׁהוּא בִּגְוָנִים רַבִּים: יָרֹק, לָבָן, אָדם, שָׁחֹר. וּכְשֶׁנְּשָׁמוֹת עוֹלוֹת, הֵן עוֹלוֹת לְתוֹךְ הַהֵיכָל הַזֶּה. מִי שֶׁרָאוּי לַגָּוֶן הַזֶּה עוֹלֶה בּוֹ, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ.</p>\n<p>וְשֵׁשֶׁת הַהֵיכָלוֹת הַלָּלוּ הֵם לַמָּדוֹר כְּפִי שֶׁאָמַרְנוּ, וְהַשְּׁבִיעִי אֵינוֹ לְמָדוֹר. וְשֵׁשׁ הַכֹּל בְּסוֹד שֶׁל שֵׁשׁ. וְעַל זֶה כָּתוּב בָּרָא שִׁית. שֵׁשׁ דְּרָגוֹת לְמַעְלָה וְשֵׁשׁ דְּרָגוֹת לְמַטָּה, וְהַכֹּל סוֹד אֶחָד</p>"],[9522011092,"<p>בֹּא רְאֵה, בְּרֵאשִׁית. רַבִּי יְהוּדָה אָמַר, שְׁנֵי בָּתִּים הָיוּ, בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי. זֶה עֶלְיוֹן וְזֶה תַּחְתּוֹן. שְׁנֵי הֵהִי\"ן הֵם. זֶה עֶלְיוֹן וְזֶה תַּחְתּוֹן, וְכֻלָּם אֶחָד. ב' הָעֶלְיוֹן פּוֹתֵחַ שְׁעָרִים לְכָל צַד. שֶׁכָּךְ הוּא - שֶׁכּוֹלֵל זֶה בָּזֶה. רֵאשִׁית. אָז הוּא רֵאשִׁית לְהִכָּנֵס בְּחֶשְׁבּוֹן הַבִּנְיָן. רַבִּי יִצְחָק אָמַר רַבִּי אֶלְעָזָר, בְּרֵאשִׁית זֶה כְּלָלוּת הַדְּמוּת (של הדמות) שֶׁכָּל הַדְּמֻיּוֹת כְּלוּלוֹת בּוֹ. זֶהוּ סוֹד הַכָּתוּב (יחזקאל א) הוּא מַרְאֵה דְּמוּת כְּבוֹד ה'. מַרְאֶה שֶׁנִּרְאִים בּוֹ שִׁשָּׁה אֲחֵרִים. וְזֶהוּ בְּרֵאשִׁית בָּרָא שִׁית.</p>\n<p>בֹּא רְאֵה, כְּשֶׁנִּכְנָסִים בַּמַּרְאֶה הַזֶּה שִׁשָּׁה גְוָנִים, הִיא מַתְקִינָה עַצְמָהּ לְגַלּוֹתָם וְלִפְעֹל בָּהֶם אֻמָּנוּת הָעוֹלָם. וְאִם תֹּאמַר שֶׁהָאֻמָּנוּת הַזּוֹ שֶׁל הָעוֹלָם הִיא מִדַּרְגָּה זוֹ - כָּתוּב בָּרָא שִׁית. שֶׁבַח שֶׁל הַשִּׁשָּׁה הוּא שֶׁעוֹשִׂים אֻמָּנוּת בָּזֶה.</p>\n<p>רַבִּי יוֹסֵי פָּתַח, (שם ב) הַנִּצָּנִים נִרְאוּ בָאָרֶץ עֵת הַזָּמִיר הִגִּיעַ וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ. הַנִּצָּנִים (נראו בארץ) - זֶהוּ סוֹד שֶׁל שֵׁשׁ דְּרָגוֹת (עליה והיא שביעית, ואלו הם שש דרגות', דרגת אברהם, דרגת יצחק ודרגת יעקב, ויכי\"ן ובע\"ז ויוס\"ף, כלן נראות בארץ, שכתוב נראו בארץ, בארץ זוהי קריה קדושה של ארץ ישראל). נִרְאוּ בָאָרֶץ - מִשּׁוּם שֶׁאוֹתָן דְּמֻיּוֹת לְהִגָּלוֹת בַּדַּרְגָּה הַזּוֹ. עֵת הַזָּמִיר הִגִּיעַ - שֶׁהֲרֵי אָז מְשַׁבֵּחַ וְחוֹזֵר, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ל) לְמַעַן יְזַמֶּרְךְ כָבוֹד וְלֹא יִדּם. וְלָכֵן נִקְרָא מִזְמוֹר, כְּמוֹ שֶׁשָּׁנִינוּ שֶׁכָּתוּב מִזְמוֹר לְדָוִד, שֶׁשָּׁרְתָה עָלָיו שְׁכִינָה בָּרֹאשׁ. וְזֶהוּ עֵת הַזָּמִיר הִגִּיעַ. רַבִּי חִיָּיא אָמַר, שֶׁהֲרֵי אָז הִגִּיעַ זְמַן לְשַׁבֵּחַ.</p>\n<p>רַבִּי אַבָּא אָמַר, עוֹלָם הָעֶלְיוֹן נִסְתָּר וְכָל דְּבָרָיו נִסְתָּרִים, מִשּׁוּם שֶׁעוֹמֵד בְּסוֹד עֶלְיוֹן יוֹם שֶׁל כָּל הַיָּמִים (הרום של כל הרומים). וּכְשֶׁבָּרָא וְהוֹצִיא, הוֹצִיא אֶת הַשִּׁשָּׁה הָאֵלּוּ. וּבִגְלַל שֶׁהוּא נִסְתָּר, שֶׁכָּל דְּבָרָיו נִסְתָּרִים, אָמַר בְּרֵאשִׁית, בָּרָא שִׁשָּׁה יָמִים עֶלְיוֹנִים. וְלֹא אָמַר מִי בָרָא אוֹתָם, מִשּׁוּם שֶׁהוּא עוֹלָם עֶלְיוֹן נִסְתָּר.</p>\n<p>וְאַחַר כָּךְ גִּלָּה וְאָמַר (להם) הַמַּעֲשֶׂה הַתַּחְתּוֹן, וְאָמַר מִי בָרָא אוֹתוֹ, מִשּׁוּם שֶׁהוּא עוֹלָם שֶׁעוֹמֵד בְּהִתְגַּלּוּת. וְאָמַר, בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, וְלֹא כָתוּב בָּרָא נִסְתָּר (בדרך נסתר) בָּרָא אֶת הַשָּׁמַיִם, מִשּׁוּם שֶׁהוּא עוֹלָם בְּהִתְגַּלּוּת. וְאָמַר בָּרָא אֱלֹהִים, אֱלֹהִים וַדַּאי שֵׁם בְּהִתְגַּלּוּת. הָרִאשׁוֹן בְּנִסְתָּר שֶׁהוּא עֶלְיוֹן. הַתַּחְתּוֹן בְּהִתְגַּלּוּת. לִהְיוֹת תָּמִיד מַעֲשֵׂה הַקָּדוֹשׁ בָּרוּךְ הוּא נִסְתָּר וְנִגְלֶה. וְסוֹד שֶׁל הַשֵּׁם הַקָּדוֹשׁ כָּךְ הוּא נִסְתָּר וְנִגְלֶה.</p>\n<p>אֵת הַשָּׁמַיִם - לְרַבּוֹת שָׁמַיִם תַּחְתּוֹנִים לְמַטָּה. וְאֵת הָאָרֶץ - לְהַכְלִיל אֶרֶץ שֶׁלְּמַטָּה וּלְרַבּוֹת כָּל מַעֲשֶׂיהָ כְּמוֹ שֶׁלְּמַעְלָה.</p>"],[9522011093,"<p>וְהָאָרֶץ הָיְתָה תֹהוּ וָבהוּ, כְּמוֹ שֶׁאָמַרְנוּ. וְהָאָרֶץ - זוֹ אֶרֶץ הָעֶלְיוֹנָה שֶׁאֵין לָהּ אוֹר מִשֶּׁל עַצְמָהּ. הָיְתָה - בַּהַתְחָלָה כְּבָר הָיְתָה כָּרָאוּי, וְעַכְשָׁו תֹּהוּ וָבֹהוּ וְחֹשֶׁךְ. הָיְתָה דַּוְקָא. אַחַר כָּךְ הִקְטִינָה אֶת עַצְמָהּ וְהִקְטִינָה אֶת אוֹרָהּ. תֹּהוּ וָבֹהוּ וְחֹשֶׁךְ וְרוּחַ - אַרְבָּעָה יְסוֹדוֹת הָעוֹלָם שֶׁנִּתְקְנוּ בָהּ.</p>"],[9522011094,"<p>דָּבָר אַחֵר וְאֵת הָאָרֶץ - כְּפִי שֶׁאָמַרְנוּ, לְרַבּוֹת אֶרֶץ שֶׁלְּמַטָּה שֶׁהִיא נֶעֶשְׂתָה בְּכַמָּה מְדוֹרִים (אורות) הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. וְזֶהוּ וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְחֹשֶׁךְ וְרוּחַ. אֵלּוּ אוֹתָם מְדוֹרֵי הָאָרֶץ: אֶרֶץ, אֲדָמָה, גַּיְא, נְשִׁיָּה, צִיָּה, אַרְקָא, תֵּבֵל. וְגָדוֹל שֶׁבְּכֻלָּם תֵּבֵל, שֶׁכָּתוּב (תהלים ט) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מַהִי צִיָּה? אָמַר לוֹ, זֶהוּ מְקוֹם הַגֵּיהִנֹּם, כְּמוֹ שֶׁנֶּאֱמַר צִיָּה וְצַלְמָוֶת. וְסוֹד זֶה כָּתוּב (שכתוב) (במלת) וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם. זֶה סוֹד מְקוֹם הַגֵּיהִנֹּם. זֶהוּ צִיָּה, הַמָּקוֹם שֶׁל מַלְאַךְ הַמָּוֶת, כְּפִי שֶׁאָמַרְנוּ, שֶׁהוּא מַחְשִׁיךְ אֶת פְּנֵי הַבְּרִיּוֹת. וְזֶהוּ מָקוֹם שֶׁל חֹשֶׁךְ עֶלְיוֹן.</p>\n<p>תֹּה\"וּ זֶה נְשִׁיָּ\"ה שֶׁלֹּא נִרְאֶה בָהּ מַרְאֶה כְּלָל עַד שֶׁנִּשְׁכָּח מֵהַכֹּל, וְעַל זֶה נִקְרֵאת נְשִׁיָּה. וּבהוּ זוֹ אַרְקָא, מָקוֹם שֶׁלֹּא נִשְׁכָּח. רַבִּי חִיָּיא אָמַר, זֶה גַּיְא. וְרוּחַ אֱלֹהִים מְרַחֶפֶת - זֶה כְּנֶגֶד תֵּבֵל שֶׁנִּזּוֹן מֵרוּחַ אֱלֹהִים, וְהַכֹּל הוּא כְּאֶחָד.</p>"],[9522011095,"<p>כְּמוֹ זֶה יֵשׁ לָאָרֶץ הָעֶלְיוֹנָה, שִׁבְעָה מְדוֹרִים הֵם לְמַעְלָה דַּרְגָּה עַל דַּרְגָּה, וּבְכָל הַמְּדוֹרִים מַלְאָכִים עֶלְיוֹנִים אֵלֶּה עַל אֵלֶּה. כָּךְ גַּם לְמַטָּה. וְהַכֹּל אָחוּז זֶה בָּזֶה לִהְיוֹת הַכֹּל אֶחָד. שִׁבְעָה מְדוֹרִים הֵם לְמַעְלָה, וַהֲרֵי אֶרֶץ הָעֶלְיוֹנָה אוֹחֶזֶת אוֹתָם וְכֻלָּם עוֹמְדִים בָּהּ, וּבְכֻלָּם נִמְצֵאת תִּשְׁבַּחַת לְהַקָּדוֹשׁ בָּרוּךְ הוּא. דְּרָגוֹת נִפְרָדוֹת זוֹ מִזּוֹ, וּמְקוֹמוֹת נִפְרָדִים זֶה מִזֶּה.</p>\n<p>מָדוֹר רִאשׁוֹן לְמַטָּה הוּא מְקוֹם בַּיִת חָשׁוּךְ שֶׁלֹּא מֵאִיר, וְהוּא מְתֻקָּן לִמְדוֹרֵי רוּחוֹת וּסְעָרוֹת חֲזָקוֹת שֶׁלֹּא נִרְאִים. וְאֵין בּוֹ אוֹר וְלֹא חֹשֶׁךְ וְלֹא דְמוּת כְּלָל. וְשָׁם לֹא יוֹדְעִים בּוֹ יְדִיעָה כְּלָל, שֶׁאֵין בּוֹ צוּרָה תּוֹךְ כְּלַל הַכִּסֵּא (הרשם).</p>\n<p>וְעַל אוֹתוֹ מָקוֹם מְמֻנֶּה מַלְאָךְ אֶחָד וּשְׁמוֹ טַהֲרִיאֵ\"ל. וְעִמּוֹ שִׁבְעִים מְמֻנִּים מְעוֹפְפִים. וְנִמְחִים מַזִּיקֵי הַשַּׁלְהָבוֹת (שעליהם) וְלֹא עוֹמְדִים וְלֹא נִרְאִים וְלֹא נִמְצָאִים. וּכְשֶׁבָּא הַבֹּקֶר, כֻּלָּם מִתְחַדְּשִׁים וְלֹא עוֹמְדִים. כְּשֶׁמַּגִּיעִים לְאוֹתוֹ מָקוֹם, אוֹבְדִים וְלֹא נִמְצָאִים, וְנִכְנָסִים בְּנֶקֶב אֶחָד שֶׁל הַתְּהוֹם וְלֹא נִרְאִים. כְּשֶׁנֶּחְשָׁךְ הַלַּיְלָה, נִמְחִים מֵאוֹתָן שַׁלְהָבוֹת עַד שֶׁמַּגִּיעַ הַבֹּקֶר.</p>\n<p>מָדוֹר הַשֵּׁנִי הוּא מָקוֹם שֶׁמֵּאִיר יוֹתֵר וְהוּא חָשׁוּךְ, אֲבָל לֹא חָשׁוּךְ כְּמוֹ אוֹתוֹ רִאשׁוֹן. וְהוּא מְתֻקָּן לְמָדוֹרִים שֶׁל מַלְאָכִים עֶלְיוֹנִים שֶׁמְּמֻנִּים עַל מַעֲשֵׂי בְּנֵי הָאָדָם וְלַהֲסִיטָם (להסטותם) בְּאוֹתָהּ דֶּרֶךְ רָעָה שֶׁהֵם הוֹלְכִים. וְאוֹתוֹ מָקוֹם נִרְאָה יוֹתֵר מִן הָרִאשׁוֹן. וְלַמַּלְאָכִים הַלָּלוּ יֵשׁ קְרָב (קרבה) עִם בְּנֵי אָדָם וְנִזּוֹנִים (ונהנים) מֵרֵיחַ וּבֹשֶׂם שֶׁלְּמַטָּה לַעֲלוֹת בְּתוֹעֶלֶת וּלְהָאִיר יוֹתֵר.</p>\n<p>וַעָלֵיהֶם מְמֻנֶּה אֶחָד שֶׁשְּׁמוֹ קְדוּמִיאֵ\"ל. וְאֵלֶּה פוֹתְחִים בְּשִׁירָה וְשׁוֹכְכִים וְהוֹלְכִים לָהֶם, וְלֹא נִרְאִים עַד שֶׁיִּשְׂרָאֵל לְמַטָּה פּוֹתְחִים וְאוֹמְרִים שִׁירָה, וְאָז עוֹמְדִים בִּמְקוֹמָם וְנִרְאִים מְאִירִים יוֹתֵר. שָׁלֹשׁ פְּעָמִים בְּיוֹם מְקַדְּשִׁים קְדֻשָּׁה. וּכְשֶׁיִּשְׂרָאֵל עוֹסְקִים בַּתּוֹרָה, כֻּלָּם טָסִים וּמְעִידִים (הם) עֵדוּת לְמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְרַחֵם עֲלֵיהֶם.</p>\n<p>מָדוֹר שְׁלִישִׁי הוּא מָקוֹם שֶׁל לֶהָבוֹת וְתִמְרוֹת עָשָׁן, וְשָׁם הַשְׁפָּעָה שֶׁל נְהַר דִּינוּר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, שֶׁהוּא בֵּית הַמּוֹקֵד לְנַפְשׁוֹת הָרְשָׁעִים, שֶׁמִּשָּׁם יוֹרֶדֶת אֵשׁ עַל רָאשֵׁי הָרְשָׁעִים, וְשָׁם מַלְאֲכֵי חַבָּלָה שֶׁטּוֹרְדִים אוֹתָם.</p>\n<p>וְשָׁם נִמְצֵאת לָשׁוֹן הָרָע עַל יִשְׂרָאֵל לִפְעָמִים וּלְהַסְטוֹת אוֹתָם, פְּרָט לִזְמַן שֶׁלּוֹקְחִים רְפוּאָה לִדְחוֹת אוֹתוֹ. וּמְמֻנֶּה אֶחָד עֲלֵיהֶם מִצַּד הַשְּׂמֹאל, כֻּלָּם מִצַּד הַחֹשֶׁךְ, כְּמוֹ שֶׁנֶּאֱמַר וְחֹשֶׁךְ עַל פְּנֵי תְהוֹם. וְסָמָאֵ\"ל הָרָשָׁע נִמְצָא שָׁם.</p>\n<p>מָדוֹר רְבִיעִי הוּא מָקוֹם שֶׁמֵּאִיר, וְשָׁם הוּא אוֹר לְמַלְאָכִים עֶלְיוֹנִים שֶׁבְּצַד יְמִין, וּפוֹתְחִים בְּשִׁירָה וּמְסַיְּמִים, וְלֹא הוֹלְכִים לַעֲבוֹר כְּאֵלוּ רִאשׁוֹנִים שֶׁפּוֹתְחִים בְּשִׁירָה וְנִשְׂרָפִים וְעוֹבְרִים בְּאֵשׁ דּוֹלֶקֶת, וְשָׁבִים וּמִתְחַדְּשִׁים כְּמִקֹּדֶם. וְאֵלֶּה עוֹמְדִים בִּמְקוֹמָם וְלֹא מִתְבַּטְּלִים. וְאֵלֶּה מַלְאֲכֵי רַחמִים שֶׁלֹּא מִשְׁתַּנִּים לְעוֹלָמִים.</p>\n<p>וַעָֹלֵיהֶם כָּתוּב (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת וְגוֹ'. וְאֵלֶּה עוֹשִׂים שְׁלִיחוּתָם בָּעוֹלָם וְלֹא נִרְאִים לִבְנֵי אָדָם, פְּרָט לְמַרְאֶה אוֹ בְּצַד אַחֵר בְּשֵׂכֶל רַב. וּמַלְאָךְ אֶחָד מְמֻנֶּה עֲלֵיהֶם, שֶׁשְּׁמוֹ פדא\"ל. וּבוֹ פּוֹתְחִים מַפְתְּחוֹת הָרַחֲמִים לְאוֹתָם שֶׁשָּׁבִים לְרִבּוֹנָם, וּפוֹתְחִים שְׁעָרִים לְהַעֲבִיר תְּפִלּוֹתֵיהֶם וּבַקָּשׁוֹתֵיהֶ ם.</p>\n<p>מָדוֹר חֲמִישִׁי הוּא מָדוֹר שֶׁמֵּאִיר בְּאוֹר יוֹתֵר מִכָּל הַקּוֹדְמִים, וְיֵשׁ בּוֹ מַלְאָכִים, מֵהֶם אֵשׁ וּמֵהֶם מַיִם. לִפְעָמִים הֵם נִמְצָאִים בְּרַחֲמִים, וְלִפְעָמִים נִמְצָאִים בְּדִין. אֵלֶּה בְּצַד זֶה וְאֵלֶּה בְּצַד זֶה. לִפְעָמִים אֵלֶּה מְאִירִים וְאֵלֶּה חֲשׁוּכִים, וְאֵלֶּה מְמֻנִּים לְזַמֵּר לְרִבּוֹנָם. אֵלֶּה בַּחֲצוֹת הַלַּיְלָה, וְאֵלֶּה כְּשֶׁעוֹלֶה הָאוֹר. וּמְמֻנֶּה אֶחָד עֲלֵיהֶם שֶׁשְּׁמוֹ קדשיא\"ל.</p>\n<p>כְּשֶׁנֶּחֱלָק הַלַּיְלָה בַּחֲצוֹת וּמִתְעוֹרֵר רוּחַ צָפוֹן וְהַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן, אָז רוּחַ צָפוֹן מַקִּישָׁה וּמַגִּיעָה לְאוֹתָם הַמְמֻנִּים בַּחֲצוֹת הַלַּיְלָה לְזַמֵּר, וְכֻלָּם מְזַמְּרִים וּפוֹתְחִים בְּשִׁירָה. וּכְשֶׁמַּגִּיעַ הַבֹּקֶר וּמִתְחַבֶּרֶת קַדְרוּת הַבֹּקֶר בָּאוֹר, אָז כָּל הָאֲחֵרִים אוֹמְרִים שִׁירָה, וְכָל כּוֹכְבֵי הָרָקִיעַ וְכָל שְׁאָר הַמַּלְאָכִים (שלמטה) מְסַיְּעִים לָהֶם, כְּמוֹ שֶׁכָּתוּב (איוב לח) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. עַד שֶׁיִּשְׂרָאֵל נוֹשְׂאִים שִׁירָה וְתִשְׁבָּחוֹת אַחֲרֵיהֶם.</p>\n<p>מָדוֹר שִׁשִּׁי הוּא מָדוֹר עֶלְיוֹן קָרוֹב לְמַלְכוּת הַשָּׁמַיִם, וּבֵין אֳנִיּוֹת וּנְהָרוֹת וּנְחָלִים שֶׁנֶּחֱלָקִים מִן הַיָּם וְכַמָּה דָגִים הֵם שֶׁמְּרַחֲשִׁים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. וּמֵעֲלֵיהֶם שָׂרִים מְמֻנִּים, וּמְמֻנֶּה אֶחָד עֲלֵיהֶם וּשְׁמוֹ אוֹרִיאֵ\"ל, וְהוּא מְמֻנֶּה עַל כָּל אֵלֶּה הַתַּחְתּוֹנִים.</p>\n<p>וְכֻלָּם נוֹסְעִים בְּשָׁעוֹת וּרְגָעִים כְּשֶׁנּוֹסְעוֹת אֳנִיּוֹת לְצַד זֶה וּלְצַד זֶה. כְּשֶׁנּוֹסְעוֹת אֳנִיּוֹת לְצַד (דרום) מִזְרָח, הַמְמֻנֶּה שֶׁעוֹמֵד עֲלֵיהֶם לְאוֹתוֹ צַד הוּא מִיכָאֵ\"ל שֶׁבָּא מִיָּמִין. וּכְשֶׁנּוֹסְעוֹת אֳנִיּוֹת לְצַד צָפוֹן, הַמְמֻנֶּה שֶׁעוֹמֵד עֲלֵיהֶן לְאוֹתוֹ צַד הוּשּׂ גַּבְרִיאֵל שֶׁבָּא מִצַּד הַשְּׁמֹאל. וּכְשֶׁנּוֹסְעוֹת אֳנִיּוֹת לְצַד (מזרח) דָּרוֹם, הֲרֵי שָׁם הוּא הַמְמֻנֶּה שֶׁעוֹמֵד עֲלֵיהֶם לְאוֹתוֹ צַד רְפָאֵ\"ל (נ\"א: אוריא\"ל) שְׁמוֹ, וְהוּא לְיָמִין. וּכְשֶׁנּוֹסְעוֹת אֳנִיּוֹת לְצַד מַעֲרָב, הַמְמֻנֶּה שֶׁעוֹמֵד עֲלֵיהֶם לְאוֹתוֹ הַצַּד הוּא אוֹרִיאֵ\"ל (נ\"א רפא\"ל) וְהוּא לָאַחֲרוֹנָה.</p>\n<p>מָדוֹר שְׁבִיעִי הוּא מָדוֹר עֶלְיוֹן עַל הַכֹּל, וְשָׁם לֹא נִמְצָאִים, רַק נִשְׁמוֹת הַצַּדִּיקִים שֶׁשָּׁם מִתְעַדְּנִים בְּאוֹתוֹ זֹהַר עֶלְיוֹן, וּמִתְעַדְּנִים בְּעִדּוּנִים וְתַפְנוּקִים עֶלְיוֹנִים. וְשָׁם לֹא נִמְצָאִים, רַק אוֹתָם זַכָּאִים, וְגִנְזֵי שָׁלוֹם וּבְרָכָה וּנְדָבָה. הַכֹּל הוּא כְּגוֹן עֶלְיוֹן, וַהֲרֵי אָמְרוּ הַחֲבֵרִים.</p>\n<p>אָז הוּא בָּאָרֶץ שֶׁלְּמַטָּה בְּשִׁבְעָה מְדוֹרִים, וְכֻלָּם כְּמוֹ שֶׁלְּמַעְלָה. וּבְכֻלָּם יֵשׁ מִינִים כְּמַרְאֵה בְּנֵי אָדָם, וְכֻלָּם מוֹדִים וּמְשַׁבְּחִים לַקָּדוֹשׁ- בָּרוּךְ-הוּא, וְאֵין מִי שֶׁיּוֹדֵעַ אֶת כְּבוֹדוֹ כְּאוֹתָם שֶׁהֵם בַּמָּדוֹר הָעֶלְיוֹן. וְאֵלֶּה רוֹאִים אֶת כְּבוֹדוֹ כָּרָאוּי לְעָבְדוֹ וּלְשַׁבְּחוֹ וּלְהַכִּיר אֶת כְּבוֹדוֹ.</p>\n<p>וְעוֹלָם הָעֶלְיוֹן הַזֶּה, שֶׁהוּא תֵבֵל, לֹא עוֹמֵד בְּקִיּוּמוֹ, אֶלָּא רַק בִּשְׁבִיל הַצַּדִּיקִים שֶׁהֵם גּוּפִים קְדוֹשִׁים כְּמוֹ שֶׁלְּמַעְלָה לֹא עוֹמֵד אוֹתוֹ מָדוֹר שְׁבִיעִי אֶלָּא לְנִשְׁמוֹת הַצַּדִּיקִים. כָּךְ גַּם הַמָּדוֹר הַשְּׁבִיעִי הַזֶּה לְמַטָּה לֹא עוֹמֵד אֶלָּא לְגוּפֵיהֶם שֶׁל הַצַּדִּיקִים, לִהְיוֹת הַכֹּל אֶחָד זֶה כְּמוֹ זֶה.</p>"],[9522011096,"<p>בֹּא רְאֵה, אָמַר רַבִּי שִׁמְעוֹן, שִׁבְעָה מְדוֹרִים הֵם שֶׁאָמַרְנוּ, וּבְתוֹכָם יֵשׁ שִׁבְעָה הֵיכָלוֹת מֵאוֹתָם סוֹדוֹת הָאֱמוּנָה כְּנֶגֶד שִׁבְעָה רְקִיעִים עֶלְיוֹנִים. וּבְכָל הֵיכָל וְהֵיכָל יֵשׁ רוּחוֹת עֶלְיוֹנוֹת. הֵיכָל רִאשׁוֹן, כָּאן יֵשׁ רוּחַ שֶׁהִתְמַנָּה עַל נִשְׁמוֹת הַגֵּרִים שֶׁהִתְגַּיְּרוּ וּשְׁמוֹ רחמיא\"ל, וְהוּא נוֹשֵׂא אוֹתָם וְנֶהֱנִים מִזִּיו הַכָּבוֹד שֶׁלְּמַעְלָה.</p>\n<p>הֵיכָל שֵׁנִי, יֵשׁ רוּחַ אֶחָד שֶׁשְּׁמוֹ אהינא\"ל, וְזֶה עוֹמֵד עַל כָּל אוֹתָם נִשְׁמוֹת הַתִּינוֹקוֹת שֶׁלֹּא זָכוּ בָּעוֹלָם הַזֶּה לַעֲסֹק בַּתּוֹרָה, וְהוּא עוֹמֵד עֲלֵיהֶם וּמְלַמֵּד אוֹתָם.</p>\n<p>בַּהֵיכָל הַשְּׁלִישִׁי יֵשׁ רוּחַ אֶחָד בְּשֵׁם אדרהינא\"ל, וְהוּא עוֹמֵד עַל נִשְׁמוֹת אוֹתָם שֶׁחָזְרוּ בִּתְשׁוּבָה וְלֹא חָזְרוּ. כְּגוֹן שֶׁחָשְׁבוּ, וּבְטֶרֶם חָזְרוּ בָהֶם מֵתוּ. אֵלֶּה טוֹרְדִים אוֹתָם בַּגֵּיהִנֹּם, וְאַחַר כָּךְ מַעֲלִים אוֹתָם לָרוּחַ הַמְמֻנֶּה הַזֶּה וְנוֹשֵׂא אוֹתָם. וְחוֹמְדִים לֵהָנוֹת מִזִּיו כְּבוֹד רִבּוֹנָם וְלֹא נֶהֱנִים. וְאֵלֶּה נִקְרָאִים בְּנֵי בָשָׂר, וַעֲלֵיהֶם כָּתוּב (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ יָבא כָל בָּשָׂר לְהִשְׁתַּחֲווֹת לְפָנַי אָמַר ה'.</p>\n<p>הֵיכָל רְבִיעִי, כָּאן עוֹמֵד רוּחַ אֶחָד וּשְׁמוֹ גדריהא\"ל (נ\"א: גהדהא\"ל). זֶה עוֹמֵד עַל כָּל אוֹתָן נְשָׁמוֹת שֶׁל הֲרוּגֵי שְׁאָר הָעַמִּים (עובדי עכו\"ם) לְהַעֲלוֹתָם לְתוֹךְ לְבוּשׁ מַלְכוּת שֶׁל הַמֶּלֶךְ, וְנִרְשָׁמִים שָׁם עַד הַיּוֹם שֶׁיִּנְקֹם אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (תהלים קי) יָדִין בַּגּוֹיִם מָלֵא גְוִיּוֹת מָחַץ רֹאשׁ עַל אֶרֶץ רַבָּה.</p>\n<p>הֵיכָל חֲמִישִׁי, כָּאן עוֹמֵד רוּחַ אֶחָד שֶׁנִּקְרָא אדיריא\"ל, וְזֶה עוֹמֵד עַל כָּל הַנְּשָׁמוֹת הַלָּלוּ. (נ\"א: של חסידים שאחזו בתשובה) שֶׁעָמְדוּ בְּאוֹתוֹ הַצַּד, וְאֵלֶּה הֵם מֵעַל כֻּלָּם שֶׁבַּמָּדוֹר הַזֶּה הָעֶלְיוֹן עַל הַכֹּל, וּמִיכָאֵ\"ל (שמו) מְמֻנֶּה גָדוֹל (עליהם) עַל כֻּלָּם עוֹמֵד (שעומדים) בּוֹ. וְכַמָּה אֲלָפִים וּרְבָבוֹת כֻּלָּם עוֹמְדִים תַּחְתָּיו בְּאוֹתוֹ הַצַּד. וְשָׁם מִתְעַדְּנוֹת אוֹתָן נִשְׁמוֹת הַחֲסִידִים בְּאוֹתוֹ אוֹר עֶלְיוֹן שֶׁשּׁוֹפֵעַ מֵהָעוֹלָם הַבָּא.</p>"],[9522011097,"<p>בֹּא רְאֵה, אָמַר רַבִּי שִׁמְעוֹן, מִיהוּ שֶׁיּוֹדֵעַ לְסַדֵּר תְּפִלַּת רִבּוֹנוֹ כְּמוֹ מֹשֶׁה? בְּשָׁעָה שֶׁהִצְטָרֵךְ לוֹ לְסַדֵּר תְּפִלָּתוֹ בַּאֲרִיכוּת - סִדֵּר. וּבְשָׁעָה שֶׁהִצְטָרֵךְ לוֹ לְקַצֵּר - גַּם כֵּן. אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי מָצָאנוּ בְּסִפְרֵי הַקַּדְמוֹנִים סִדּוּר שֶׁל סוֹדֵי הַסּוֹדוֹת בְּקֶשֶׁר אֶחָד. לִפְעָמִים שֶׁצָּרִיךְ לְסַדֵּר תְּפִלָּתוֹ כָּרָאוּי וְלִקְשֹׁר קְשָׁרִים לְבַשֵּׂם אֶת רִבּוֹנוֹ כָּרָאוּי, וְלָדַעַת לְיַחֵד יִחוּד שָׁלֵם לִקְרֹעַ רְקִיעִים וְלִפְתֹּחַ שְׁעָרִים וּפְתָחִים שֶׁלֹּא יִהְיֶה מִי שֶׁיִּמְחֶה בְיָדוֹ.</p>\n<p>אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיּוֹדְעִים לְפַתּוֹת אֶת רִבּוֹנָם וּלְבַטֵּל גְּזֵרוֹת וּלְהַשְׁרוֹת שְׁכִינָה בָּעוֹלָם וּלְהוֹרִיד בְּרָכוֹת, וּלְהָסִיר אֶת בַּעֲלֵי הַדִּין שֶׁלֹּא יִשְׁלְטוּ בָעוֹלָם. קָם רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים קו) מִי יְמַלֵּל גְּבוּרוֹת ה' וְגוֹ'. מִי יְגַלֶּה עָפָר מֵעֵינֶיךְ אַבְרָהָם הֶחָסִיד, יְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁגִּלָּה לְךְ סוֹד הַסּוֹדוֹת וְהִתְחַלְתָּ תְּפִלּוֹת בָּעוֹלָם, וְהִתְגַּלּוּ לְךְ הֵיכְלוֹת הַמֶּלֶךְ הָעֶלְיוֹן.</p>\n<p>שִׁבְעָה הֵיכָלוֹת קְדוֹשִׁים הֵם, וְהֵם עוֹמְדִים בַּשְּׁעָרִים בְּקִיּוּם. וּבְכָל אֶחָד וְאֶחָד נִכְנֶסֶת תְּפִלַּת הַיִּחוּד (של רבונו) שֶׁל מִי שֶׁיּוֹדֵעַ לְבַשֵּׂם לְרִבּוֹנוֹ וּלְיַחֵד יִחוּד בִּשְׁלֵמוּת, שֶׁיּוֹדֵעַ לְהִכָּנֵס בְּכָל הַהֵיכָלוֹת וְלִקְשֹׁר קְשָׁרִים אֵלּוּ בְּאֵלּוּ, רוּחַ בְּרוּחַ, רוּחַ תַּחְתּוֹנָה בְּרוּחַ עֶלְיוֹנָה. כָּתוּב (ישעיה כו) ה' בַּצַּר פְּקָדוּךְ צָקוּן לַחַשׁ מוּסָרְךְ לָמוֹ.</p>"],[9522011098,"<p>הֵיכָל הָרִאשׁוֹן. כָּתוּב (שמות כד) וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר וּכְעֶצֶם הַשָּׁמַיִם לָטֹהַר. סוֹד הַסּוֹדוֹת רוּחַ שֶׁנִּקְרֵאת סַפִּיר. כְּסַפִּיר שֶׁל אֶבֶן טוֹבָה נוֹצֶצֶת לִשְׁנֵי צְדָדִים. אוֹר אֶחָד עוֹלֶה וְיוֹרֵד. וְאוֹתוֹ אוֹר לָבָן נוֹצֵץ לְכָל צַד לְמַעְלָה וּלְמַטָּה וּלְאַרְבַּעַת צִדְדֵי הָעוֹלָם. אוֹרוֹ תָלוּי נִסְתָּר וְגָלוּי.</p>\n<p>מֵהָאוֹר הַזֶּה נִפְרָדִים אַרְבָּעָה אוֹרוֹת לְאַרְבָּעָה צְדָדִים, וְכֻלָּם מְאִירִים אוֹר אֶחָד כִּמְנוֹרַת הַנֵּר שֶׁדּוֹלֵק וְנוֹצֵץ אוֹרוֹת לְמַרְאֵה עֵינֵי בְּנֵי אָדָם. וְאוֹתָם אוֹרוֹת הַנֵּר עוֹלִים וְיוֹרְדִים, הוֹלְכִים וְשָׁבִים מִתּוֹךְ אוֹתָהּ אֵשׁ שֶׁל אוֹר הַנֵּר שֶׁדּוֹלֵק, וְכֻלָּם אוֹר אֶחָד. כָּךְ גַּם אֵלֶּה. וְכָל הַמְּאוֹרוֹת נוֹצְצִים כְּמוֹ מַרְאֶה שֶׁל נְחֹשֶׁת מְלֻטֶּשֶׁת בְּאָדם, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל א) וְנֹצְצִים כְּעֵין נְחֹשֶׁת קָלָל. זֶהוּ לְיָמִין.</p>\n<p>וְלִשְׂמֹאל יֵשׁ רוּחַ שֶׁנִּקְרָא לְבָנָה, וְזֶה נִכְלָל בָּרוּחַ הָרִאשׁוֹן וְנִכְנָס זֶה בָּזֶה. אוֹרוֹ אָדם וְלָבָן כְּאֶחָד, מִשּׁוּם שֶׁיּוֹצֵא מֵאוֹתָם מְאוֹרוֹת רִאשׁוֹנִים. כְּשֶׁבָּאִים הַמְּאוֹרוֹת שֶׁל זֶה, מַגִּיעִים בָּאוֹרוֹת הָרִאשׁוֹנִים וְנִכְלָלִים בּוֹ וְהֵם אֶחָד. וְנִרְאִים הַמְּאוֹרוֹת הָרִאשׁוֹנִים לְבַדָּם, וְלֹא מִתְגַּלִּים הָאֲחֵרִים הַלָּלוּ וְלֹא נוֹדְעוּ שֶׁנִּכְנְסוּ לְתוֹכָם וְנִסְתַּתְּרוּ בוֹ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מא) וְלֹא נוֹדַע כִּי בָאוּ אֶל קִרְבֶּנָּה וְגוֹ'. וְזֶהוּ רוּחַ בְּרוּחַ שֶׁהֵם אֶחָד. מְאוֹרוֹת בִּמְאוֹרוֹת שֶׁהֵם אֶחָד. וְכָאן הֵם שְׁנֵי שְׁעָרִים (רקיעים) תַּחְתּוֹנִים מֵאוֹתָם רְקִיעִים שֶׁנִּקְרָאִים שְׁמֵי הַשָּׁמַיִם (רקיע).</p>\n<p>מִשְּׁנֵי הָרוּחוֹת הַמְנַצְנְצִים הַלָּלוּ נִבְרְאוּ אוֹתָם הָאוֹפַנִּים שֶׁהֵם קְדוֹשִׁים, שֶׁדְּמוּתָם כִּדְמוּת הַחַיּוֹת, כְּמוֹ שֶׁכָּתוּב (יחזקאל א) מַרְאֵה הָאוֹפַנִּים וּמַעֲשֵׂיהֶם וְגוֹ'. וְזֶהוּ שֶׁכָּתוּב וּדְמוּת הַחַיּוֹת מַרְאֵיהֶם כְּגַחֲלֵי אֵשׁ בֹּעֲרוֹת כְּמַרְאֵה הַלַּפִּדִים הִיא מִתְהַלֶּכֶת בֵּין הַחַיּוֹת. מִי הִיא? זוֹ רוּחַ קְדוֹשָׁה, מָקוֹם שֶׁיָּצְאוּ מִמֶּנּוּ וְהִיא מְאִירָה לָהֶם, שֶׁכָּתוּב וְנֹגַהּ לָאֵשׁ וּמִן הָאֵשׁ יוֹצֵא בָרָק.</p>\n<p>כְּשֶׁנִּכְלָל רוּחַ בְּרוּחַ, יוֹצֵא מֵהֶם אוֹר שֶׁל חַיָּה אַחַת רָמוּז (מטל) עַל אַרְבָּעָה אוֹפַנִּים. וַהֲרֵי דְמוּתוֹ כְּאַרְיֵה שׁוֹלֵט עַל אֶלֶף וּשְׁלֹשׁ מֵאוֹת רִבּוֹא שֶׁל אוֹפַנִּים אֲחֵרִים. כַּנְפֵי הַנֶּשֶׁר הַזֶּה הִתְמַנָּה עַל כָּל אוֹתָם אוֹפַנִּים. בְּאַרְבָּעָה גַלְגַּלִּים נוֹסְעִים כָּל אֶחָד וְאֶחָד מֵאוֹתָם אַרְבָּעָה. בְּכָל גַּלְגַּל וְגַלְגַּל שְׁלֹשָׁה עַמּוּדִים. וְהֵם שְׁנֵים עָשָׂר עַמּוּדִים בְּאַרְבָּעָה גַלְגַּלִּים. רוּחַ זוֹ שׁוֹלֶטֶת עַל הַכֹּל. מִכָּאן יָצְאוּ. וְרוּחַ זוֹ עוֹמֶדֶת לְכֻלָּם, וַהֲרֵי מִמֶּנָּה נִזּוֹנִים.</p>\n<p>אַרְבָּעָה (האופנים) הַלָּלוּ, אַרְבַּע פָּנִים לְכָל אֶחָד וְאֶחָד. וְכָל אוֹתָם פָּנִים מִסְתַּכְּלִים לְאַרְבָּעָה צְדָדִים שֶׁל אוֹתָהּ הַחַיָּה שֶׁעוֹמֶדֶת עֲלֵיהֶם. כְּשֶׁנּוֹסְעִים הָאַרְבָּעָה הַלָּלוּ תַּחַת אוֹתָהּ הַחַיָּה, נִכְנָסִים זֶה בָּזֶה וּמְשֻׁלָּבִים זֶה בָּזֶה, כְּמוֹ שֶׁנֶּאֱמַר (שמות כו ולא) מַקְבִּילֹת הַלֻּלָאֹת אִשָּׁה אֶל אֲחֹתָהּ, לְהִתְכַּלֵּל אַחַת בְּאַחַת וּלְהִכָּנֵס זוֹ בָּזוֹ. כְּשֶׁנּוֹסְעִים אוֹתָם גַּלְגַּלִּים, נִשְׁמָע קוֹל נְעִימוּת בְּכָל אוֹתָם צְבָאוֹת שֶׁלְּמַטָּה לְמִינֵיהֶם.</p>\n<p>תַּחַת הֵיכָל זֶה נִפְרָדִים צְבָאוֹת הַחוּצָה לְכַמָּה צְדָדִים שֶׁל רְקִיעִים שֶׁלְּמַטָּה, עַד שֶׁמַּגִּיעִים לַכּוֹכָב שֶׁל שַׁבְּתַאי. כֻּלָּם מִסְתַּכְּלִים לְהֵיכָל זֶה. מִשָּׁם נִזּוֹנִים. כָּל אֵלֶּה שֶׁבְּהֵיכָל זֶה כֻּלָּם מִסְתַּכְּלִים לְאוֹתָהּ רוּחַ, שֶׁכָּתוּב (יחזקאל א) אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ לֹא יִסַּבּוּ בְּלֶכְתָּן. וְזֶהוּ הֵיכָל שֶׁנִּקְרָא לִבְנַת הַסַּפִּיר.</p>\n<p>רוּחַ זוֹ הַכּוֹלֶלֶת רוּחַ אַחֶרֶת שְׁנִיָּה עוֹלָה וְיוֹרֶדֶת, אוֹרָהּ שֶׁלֹּא שׁוֹכֵךְ (עוזב) לְעוֹלָמִים כְּאוֹר הַשֶּׁמֶשׁ בְּתוֹךְ הַמַּיִם. אֵין מִי שֶׁעוֹמֵד עָלֶיהָ, פְּרָט לְרָצוֹן שֶׁל אִישׁ צַדִּיק בְּאוֹתָהּ תְּפִלָּה שֶׁנִּכְנֶסֶת בְּאוֹתוֹ הֵיכָל וְעוֹלָה לִקְשֹׁר קְשָׁרִים בִּשְׁלֵמוּת בַּתְּחִלָּה שֶׁל הָרוּחַ (האור) הַזּוֹ כָּרָאוּי. אָז הָאוֹר מִתְעַטֵּף בָּהּ וְשָׂמֵחַ בָּהּ, וְעוֹלֶה עִמָּהּ לְהִתְקַשֵּׁר בַּקֶּשֶׁר שֶׁל הַהֵיכָל הַשֵּׁנִי, לְהִתְכַּלֵּל רוּחַ שֶׁכָּלוּל בְּרוּחַ אַחֶרֶת עֶלְיוֹנָה שֶׁעָלָיו.</p>\n<p>וְרוּחַ זוֹ שֶׁכּוֹלֶלֶת, כּוֹלֶלֶת בָּהּ אוֹתָהּ חַיָּה וְכָל אוֹתָם אוֹפַנִּים וְגַלְגַּלִּים, וְנֶאֱחָזִים בּוֹ כְּמוֹ שֶׁנֶּאֱחָזִים אֵשׁ בְּמַיִם וּמַיִם בְּאֵשׁ, דָּרוֹם בְּצָפוֹן, צָפוֹן בְּדָרוֹם, מִזְרָח בְּמַעֲרָב, וּמַעֲרָב בְּמִזְרָח. כָּךְ נֶאֱחָזִים כֻּלָּם זֶה בָּזֶה וְנִקְשָׁרִים זֶה בָּזֶה. אוֹתָהּ רוּחַ עוֹלָה לְהִתְקַשֵּׁר, וְאוֹתָהּ חַיָּה מִסְתַּכֶּלֶת לְמַעְלָה אֶל הַהֵיכָל הַשֵּׁנִי, וּמִסְתַּכְּלִים זֶה בָּזֶה.</p>\n<p>בְּאֶמְצַע הַהֵיכָל הַזֶּה נָעוּץ עַמּוּד אֶחָד שֶׁעוֹלֶה עַד אֶמְצַע הַהֵיכָל הָאַחֵר, וְהוּא נָקוּב וְנָעוּץ (נ\"א: נתיב נעוץ) מִלְּמַטָּה לְמַעְלָה לְהִדָּבֵק רוּחַ בְּרוּחַ, וְכֵן עַד לְמַעְלָה מִכֻּלָּם לִהְיוֹת כֻּלָּם רוּחַ אַחַת, שֶׁנֶּאֱמַר (קהלת ג) וְרוּחַ אֶחָד לַכֹּל.</p>"],[9522011099,"<p>הֵיכָל שֵׁנִי. כָּתוּב (שמות כד) וּכְעֶצֶם הַשָּׁמַיִם לָטֹהַר. כָּאן הוּא אוֹתוֹ רוּחַ שֶׁנִּקְרָא זֹהַר, וְעוֹמֵד בְּלֹבֶן תָּמִיד שֶׁלֹּא יִתְעָרְבוּ גְוָנָיו בְּאַחֵר, וְהוּא עֶצֶם שֶׁלֹּא מִשְׁתַּנֶּה לְעוֹלָמִים. זֶה אֵינוֹ בְּהִתְגַּלּוּת כָּךְ לְהִתְנוֹצֵץ כְּמוֹ הָאַחֵר. זֶה קָשֶׁה לְהִתְגַּלּוּת. כְּמוֹ סֵתֶר הָעַיִן שֶׁכְּשֶׁמִּתְגַּלְגֶּלֶת, זוֹהֶרֶת וְנוֹצֶצֶת בְּגִלְגּוּל. וְגַם זֶה כָּךְ. מִשּׁוּם שֶׁכְּשֶׁאוֹתוֹ רוּחַ רִאשׁוֹן עוֹלֶה, מְגַלְגֵּל בַּגַּלְגַּל וּמְגַלֶּה אוֹתוֹ, וְנִקְשָׁר יַחַד אִתּוֹ בְּקֶשֶׁר שֶׁל לֹבֶן הָעַיִן תּוֹךְ גָּוֶן אַחֵר שֶׁהוּא דַקִּיק מִמֶּנּוּ שֶׁשּׁוֹרֶה עָלָיו.</p>\n<p>רוּחַ זוֹ מִתְגַּלְגֶּלֶת מִתּוֹךְ רוּחַ שֶׁלְּמַטָּה. הָאוֹר שֶׁלְּמַטָּה סוֹבֵב לַגַּלְגַּל (וגלגל) הָאוֹר הַזֶּה וּמֵאִיר. וְלֹא יָכוֹל לְהָאִיר עַד שֶׁאוֹחֵז בּוֹ הַתַּחְתּוֹן וְנִקְשָׁר עִמּוֹ וְאָז מֵאִיר, וְאוֹחֵז בָּאוֹר שֶׁלְּמַטָּה (שהיה מאיר) שֶׁהוּא כָּלוּל וְלֹא מִשְׁתַּנֶּה בִּכְלָל, אֶלָּא מִתְגַּלֶּה בִּגְלָלוֹ בַּגִּלְגּוּל שֶׁלּוֹ.</p>\n<p>וּכְשֶׁאוֹר זֶה מִתְגַּלְגֵּל, נוֹטֵל אוֹר אַחֵר לְצַד שְׂמֹאל וּמִתְגַּלְגֵּל עִמּוֹ וּמִסְתּוֹבֵב עִמּוֹ. וְזֶה סוֹד הַכָּתוּב (שיר ז) חַמּוּקֵי יְרֵכַיִךְ כְּמוֹ חֲלָאִים מַעֲשֵׂה יְדֵי אָמָּן. אַשְׁרֵי מִי שֶׁיּוֹדֵעַ לְגַלּוֹת (לגלגל) מְאוֹרוֹת.</p>\n<p>רוּחַ אַחֶרֶת נִכְלֶלֶת עִמּוֹ וּמִסְתּוֹבֵב (ומאיר) וּמֵאִיר סְבִיבוֹ בְּגָוֶן תְּכֵלֶת וְלָבָן. אוֹתוֹ לָבָן נִקְשָׁר בַּלָּבָן הַזֶּה, וְאוֹתוֹ תְכֵלֶת נִקְשָׁר בָּאָדם שֶׁל הָאוֹר הַתַּחְתּוֹן שֶׁלְּצַד שְׂמֹאל, וְנִכְלָלִים זֶה בָּזֶה וְנִהְיִים אֶחָד, וְנִקְרָאִים עֶצֶם הַשָּׁמַיִם. וְכָל מַה שֶּׁלְּמַטָּה וְאוֹתוֹ הֵיכָל שֶׁלְּמַטָּה, הַכֹּל נִכְלָל כָּאן. וֶהֱיוֹת שֶׁהַכֹּל נִכְלָל כָּאן, נִקְרָא עֶצֶם הַשָּׁמַיִם.</p>\n<p>מִכְּלָל שֶׁאוֹרוֹת הַלָּלוּ נִבְרְאוּ אוֹתָם שְׂרָפִים שֶׁל שֵׁשׁ כְּנָפַיִם, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ו) שְׂרָפִים עֹמְדִים מִמַּעַל לוֹ שֵׁשׁ כְּנָפַיִם שֵׁשׁ כְּנָפַיִם לָאֶחָד. כֻּלָּם בְּשֵׁשׁ, מִשּׁוּם שֶׁכֻּלָּם מֵעֶצֶם הַשָּׁמַיִם. אֵלֶּה הֵם שֶׁשּׂוֹרְפִים אֶת אֵלֶּה שֶׁלֹּא חוֹשְׁשִׁים עַל כְּבוֹד רִבּוֹנָם. וְסוֹד שֶׁהַמִּשְׁתַּמֵּשׁ בְּכֶתֶר חוֹלֵף. מִי שֶׁקּוֹרֵא וְשׁוֹנֶה שִׁשָּׁה סִדְרֵי מִשְׁנָה, זֶהוּ מִי שֶׁיּוֹדֵעַ לְסַדֵּר וְלִקְשֹׁר קִשּׁוּר שֶׁל יִחוּד שֶׁל רִבּוֹנוֹ כָּרָאוּי. אֵלֶּה אוֹתָם שֶׁמְּקַדְּשִׁים הַשֵּׁם הַקָּדוֹשׁ שֶׁל רִבּוֹנָם בְּכָל יוֹם תָּמִיד.</p>\n<p>כְּשֶׁמִּתְגַּלְגְּלִים הָאוֹרוֹת, יוֹצֵא מֵהֶם אוֹר שֶׁל חַיָּה אַחַת, שֶׁהִיא עוֹמֶדֶת וּמֻטֶּלֶת עַל אַרְבַּע חַיּוֹת הַשַּׁלִּיטוֹת עַל הָרִאשׁוֹנוֹת שֶׁכּוֹלְלוֹת אוֹתָם בְּתוֹכָם. וּבְאֵלֶּה כְּשֶׁנּוֹסְעִים, כּוֹפִים הַשְּׂרָפִים תַּחְתּוֹנִים נְחָשִׁים שֶׁיּוֹצְאִים מִתּוֹךְ אוֹתוֹ נָחָשׁ שָׂרָף שֶׁגּוֹרֵם מָוֶת לְכָל הָעוֹלָם.</p>\n<p>אֵלֶּה הַחַיּוֹת פְּנֵי נֶשֶׁר, מִסְתַּכְּלוֹת אֶל אוֹתָהּ חַיָּה הַנֶּשֶׁר עֶלְיוֹן שֶׁעֲלֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר (משלי ל) דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמָיִם. רוּחַ זוֹ שׁוֹלֶטֶת עַל הַכֹּל. אוֹתוֹ הַחַיָּה שֶׁרוֹמֶזֶת (נ\"א שמטלת) עַל כֻּלָּם, מִסְתַּכֶּלֶת לְמַעְלָה, וְכֻלָּם אֵלֶיהָ (נ\"א: אצלה).</p>\n<p>כְּשֶׁכֻּלָּם נוֹסְעִים, מִזְדַּעְזְעִים כַּמָּה צְבָאוֹת. מֵהֶם מְאִירִים, מֵהֶם מִשְׁתַּבְּרִים (נ\"א: מסתכרים מלפניהם) מִקִּיּוּמָם (מימיהם) וְשׂוֹרְפִים אוֹתָם בָּאֵשׁ, וּבָאִים וּמִתְחַדְּשִׁים כְּמִקֹּדֶם. כֻּלָּם נִכְנָסִים תַּחַת אוֹתָהּ חַיָּה, וּמִסְתַּתְּרִים תַּחַת כְּנָפֶיהָ לְהַכְלִילָם לְמַעְלָה.</p>\n<p>אוֹתָן אַרְבַּע חַיּוֹת עוֹלוֹת כְּשֶׁרוּחַ זוֹהֶרֶת לְתוֹךְ אוֹתָהּ הַחַיָּה. אַרְבָּעָה גַלְגַּלִּים לְכָל אַחַת וְאַחַת. גַּלְגַּל אֶחָד מִסְתַּכֵּל לְצַד מִזְרָח, וּשְׁלֹשָׁה עַמּוּדִים נוֹשְׂאִים אוֹתוֹ וּמִסְתַּכְּלִים לָאֶמְצַע. וְגַלְגַּל אֶחָד מִסְתַּכֵּל לְצַד מַעֲרָב, וּשְׁלֹשָׁה עַמּוּדִים נוֹשְׂאִים אוֹתוֹ וּמִסְתַּכְּלִים לָאֶמְצַע. וְגַלְגַּל אַחֵר מִסְתַּכֵּל לְצַד דָּרוֹם, וּשְׁלֹשָׁה עַמּוּדִים נוֹשְׂאִים אוֹתוֹ וּמִסְתַּכְּלִים לָאֶמְצַע. וְגַלְגַּל אַחֵר מִסְתַּכֵּל לְצַד צָפוֹן וּשְׁלֹשָׁה עַמּוּדִים נוֹשְׂאִים אוֹתוֹ וּמִסְתַּכְּלִים לָאֶמְצַע. וְכָל שְׁנֵים עָשָׂר הָעַמּוּדִים נוֹשְׂאִים מִתּוֹךְ הָאֶמְצַע, וְאוֹתוֹ הָאֶמְצַע סָגוּר וּפָתוּחַ. וְכָל גַּלְגַּל וְגַלְגַּל כְּשֶׁנּוֹסֵעַ, קוֹל נִשְׁמָע בְּכָל הָרְקִיעִים.</p>\n<p>אֵלּוּ הָאַרְבַּע חַיּוֹת (שלמעלה) כֻּלָּם מִתְלַבְּשׁוֹת (משתלבות) זוֹ בָּזוֹ, וְנִכְנָסִים אוֹתָם אוֹפַנִּים שֶׁלְּמַטָּה לְתוֹךְ הַחַיּוֹת הַלָּלוּ שֶׁלְּמַעְלָה כְּלוּלִים אֵלֶּה בְּאֵלֶּה. רוּחַ זוֹ שֶׁנִּכְלְלָה בְּאוֹתָן רוּחוֹת, לוֹהֶטֶת וְעוֹלָה לְהֵאָחֵז לְמַעְלָה וְעוֹמֶדֶת לְהִתְאַחֵד ולהתקשר ברצון האיש הצדיק באותה תפלה שמתפלל. שכשעולה ונכנסת באותו היכל, לוקח הכל, וכלם נוטלים יחד עמה ונכללו זה בזה עד שנכללים באותה רוח. ואותה רוח נוטלת ברצון של קשר היחוד של התפלה שמיחדת הכל, עד שכלם מגיעים להיכל השלישי כלולים זה בזה, כמו הראשונים אש במים, ומים באש, רוח בעפר, ועפר ברוח. מזרח במערב, מערב במזרח, צפון בדרום, ודרום בצפון. וכך כל הללו מתקשרים זה בזה, ונאחזים זה בזה ומשלבים זה בזה. וכך כמה צבאות ומחנות שנאחזו (נ\"א: שירדו) למטה והתערבו באותם תחתונים עד שהגיעו לכוכב צדק, ושם כמה ממנים על העולם.</p>\n<p>וּכְשֶׁרוּחַ זֶה שֶׁנִּכְלָל מִכֻּלָּם וְכֻלָּם כְּלוּלִים בּוֹ, עוֹלֶה וְנֶאֱחָז וְנִכְנָס לְתוֹךְ הַהֵיכָל הַשְּׁלִישִׁי עַד שֶׁנֶּאֱחָז בָּרוּחַ שֶׁל שָׁם בְּתוֹךְ אוֹתוֹ הָעַמּוּד שֶׁעוֹמֵד בָּאֶמְצַע, וְאָז הַכֹּל בִּשְׁלֵמוּת עַד כָּאן כָּרָאוּי. וְכֻלָּם רוּחַ אֶחָד כָּלוּל מֵהַכֹּל וְשָׁלֵם מֵהַכֹּל, כְּמוֹ שֶׁנֶּאֱמַר וְרוּחַ אֶחָד לְהֵנָּה (לכל). כָּאן הַכְרִיעָה לְהִדָּבֵק בְּרִבּוֹנוֹ.</p>"],[9522011100,"<p>הֵיכָל שְׁלִישִׁי. הֵיכָל זֶה הוּא הֵיכָל שֶׁל אוֹתוֹ רוּחַ שֶׁנִּקְרָא נֹגַהּ. רוּחַ זֶה הוּא טָהוֹר, בָּרוּר מִכֻּלָּם. אֵין בּוֹ גָּוֶן שֶׁנִּרְאֶה בּוֹ, לֹא לָבָן וְלֹא יָרֹק וְלֹא שָׁחֹר וְלֹא אָדם, וְלָכֵן נִקְרָא טֹהַר. טָהֳרָה בְּרוּרָה מִכָּל הַתַּחְתּוֹנִים הַלָּלוּ. וְאַף עַל גַּב שֶׁהוּא טָהוֹר מֵהַכֹּל, לֹא נִרְאֶה עַד שֶׁהַתַּחְתּוֹנִים הַלָּלוּ מִתְגַּלְגְּלִים וְאוֹחֲזִים (נ\"א: וכורים) בּוֹ וְנִכְנָסִים בְּתוֹכוֹ (בו). כֵּיוָן שֶׁנִּכְנָסִים בְּתוֹכוֹ, אָז מַרְאֶה אֶת אוֹרוֹ, וְלֹא גָוֶן אֶחָד מִכֻּלָּם.</p>\n<p>כְּשֶׁנִּשְׁלָם רוּחַ זֶה מִכָּל הַתַּחְתּוֹנִים, יוֹצֵא מִמֶּנּוּ אוֹר שֶׁכָּלוּל בִּשְׁלֹשָׁה מְאוֹרוֹת. אוֹתָם שְׁנֵי מְאוֹרוֹת עוֹלִים וְיוֹרְדִים וְנוֹצְצִים. בְּאוֹתוֹ נִצְנוּץ נִרְאִים עֶשְׂרִים וּשְׁנַיִם אוֹרוֹת מְשֻׁנִּים זֶה מִזֶּה, וְכֻלָּם אוֹר אֶחָד. וְנִכְנָסִים בְּאוֹתוֹ הָאוֹר הָאֶחָד. וְאוֹתוֹ הָאוֹר כּוֹלֵל אוֹתָם.</p>\n<p>וְלֹא מֵאִיר פְּרָט לַזְּמַן שֶׁהָאוֹרוֹת הַלָּלוּ שֶׁלְּמַטָּה עוֹלִים. וְאוֹתוֹ רָצוֹן שֶׁל הַתְּפִלָּה נוֹשֵׂא אֶת כֻּלָּם. אָז אוֹתוֹ אוֹר יוֹצֵא מִתּוֹךְ אוֹתָהּ רוּחַ. מֵאִיר אוֹתוֹ הָאוֹר וּמוֹצִיא שְׁנֵי הָאוֹרוֹת הַנּוֹצְצִים הַלָּלוּ, וְנִרְאִים כְּחֶשְׁבּוֹן עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת הַתּוֹרָה. אַחַר כָּךְ חוֹזְרִים וְנִכְלָלִים בְּאוֹתוֹ הָאוֹר.</p>\n<p>כָּל אוֹתָם הָאוֹרוֹת תַּחְתּוֹנִים (באותם אורות), כֻּלָּם כְּלוּלִים בָּאוֹרוֹת הַלָּלוּ (תחתונים), וְכֻלָּם בָּאוֹר הַזֶּה. הָאוֹר הַזֶּה כָּלוּל בְּתוֹךְ אוֹתוֹ הָרוּחַ, וְאוֹתוֹ הָרוּחַ עוֹמֵד בַּהֵיכָל הַשְּׁלִישִׁי הַזֶּה, וְלֹא עוֹמֵד לְהִתְיַשֵּׁב אֶלָּא בְּתוֹךְ הַהֵיכָל הָרְבִיעִי שֶׁהִשְׁתּוֹקְקוּתוֹ לַעֲלוֹת לְתוֹכוֹ.</p>\n<p>הַמְּאוֹרוֹת הַלָּלוּ שֶׁיָּצְאוּ מִתּוֹךְ אוֹתָהּ הָרוּחַ, כְּשֶׁנּוֹצְצִים מִתְחַבְּרִים כָּל הַמְּאוֹרוֹת הַנּוֹצְצִים. בְּשָׁעָה שֶׁיּוֹצְאִים מִתּוֹךְ אוֹתוֹ אוֹר אֶחָד וְדוֹחֲקִים וְדוֹחִים לְהִתְנוֹצֵץ. יוֹצֵאת מֵהֶם חַיָּה אַחַת קְדוֹשָׁה גְּדוֹלָה, דְּמוּתָהּ כַּמַּרְאֶה שֶׁל כָּל אֵלּוּ שְׁאָר הַחַיּוֹת. דְּמוּת אַרְיֵה וּדְמוּת נֶשֶׁר כְּלוּלִים כְּאֶחָד, וְנַעֲשׂוּ בָהּ דְּמוּת אַחַת מֵהֶם.</p>\n<p>תַּחַת הַחַיָּה הַ את יֵשׁ אַרְבָּעָה אוֹפַנִּים עֶלְיוֹנִים כְּמַרְאֵה תַרְשִׁישׁ מְרֻקָּם בִּכְלִילוּת כָּל הַגְּוָנִים. וְשֵׁשׁ מֵאוֹת אֶלֶף רִבּוֹא (גדולים) כֻּלָּם בְּתוֹכָם. וְאַרְבָּעָה הָאוֹפַנִּים הַלָּלוּ כֻּלָּם בִּשְׁמוֹנֶה כְנָפַיִם, וְכֻלָּם יוֹצְאִים מִתּוֹךְ אוֹר אוֹתָהּ הַחַיָּה שֶׁשּׁוֹלֶטֶת עֲלֵיהֶם. בְּשָׁעָה שֶׁנּוֹצֵץ אוֹתוֹ הָאוֹר, מוֹצִיאָה צְבָאוֹת צְבָאוֹת הַלָּלוּ.</p>\n<p>וְאַרְבָּעָה אֵלֶּה שֶׁתַּחְתֶּיהָ עוֹמְדִים בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם בְּאַרְבַּע פָּנִים כָּל אֶחָד וְאֶחָד. שְׁתֵּי פָנִים מִסְתַּכְּלוֹת לְאוֹתָהּ הַחַיָּה, וּשְׁתֵּי פָנִים מְכֻסּוֹת בְּכַנְפֵיהֶם מֵאוֹתָם אוֹרוֹת שֶׁנּוֹצְצִים שֶׁלֹּא יְכוֹלִים לְהִסְתַּכֵּל.</p>\n<p>בְּכָל פַּעַם שֶׁנּוֹסְעִים אֵלֶּה בְּאַרְבָּעָה גַלְגַּלִּים (ד\"א ושנים עשר) (ושנים) עַמּוּדִים כָּרִאשׁוֹנִים נַעֲשֶׂה מֵאוֹתָהּ הַזֵּעָה שֶׁלָּהֶם כַּמָּה צְבָאוֹת וּמַחֲנוֹת שֶׁכֻּלָּם מְשַׁבְּחִים וּמְזַמְּרִים שֶׁלֹּא שׁוֹקְטִים לְעוֹלָמִים. וּלְאֵלֶּה אֵין לָהֶם שִׁעוּר.</p>\n<p>אַרְבָּעָה פְתָחִים יֵשׁ לַהֵיכָל הַזֶּה לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. עֲשָׂרָה מְמֻנִּים בְּכָל פֶּתַח וּפֶתַח. וּבִזְמַן שֶׁכֻּלָּם שֶׁבְּתוֹךְ הַהֵיכָלוֹת שֶׁלְּמַטָּה, וְאוֹתָם הֵיכָלוֹת עוֹלִים בְּרָצוֹן שֶׁל תְּפִלָּה זַכָּה, כֻּלָּם פּוֹתְחִים פְּתָחִים עַד שֶׁנִּכְלָלִים כֻּלָּם אֵלֶּה בְּאֵלֶּה, וּמְשֻׁלָּבִים אֵלֶּה בְּאֵלֶּה, וְנִכְנָסִים כָּל הַמְמֻנִּים לְתוֹךְ מְמֻנִּים, מַחֲנוֹת בְּתוֹךְ מַחֲנוֹת, אוֹפַנִּים בְּחַיּוֹת וְחַיּוֹת בְּאוֹפַנִּים. בָּאוֹפַנִּים הַלָּלוּ מְאוֹרוֹת בִּמְאוֹרוֹת, רוּחַ בְּרוּחַ, עַד שֶׁנִּכְנָסִים בְּרוּחַ זוֹ.</p>\n<p>בַּהֵיכָל הַזֶּה יֵשׁ מָקוֹם אֶחָד כְּמַרְאֵה זָהָב שֶׁנּוֹצֵץ, וְשָׁם גְּנוּזִים כַּמָּה צְבָאוֹת וּמַחֲנוֹת שֶׁלֹּא עוֹלִים וְלֹא מִתְעַטְּרִים לְמַעְלָה, אֶלָּא רַק בְּשָׁעָה שֶׁכָּל אֵלֶּה קוֹשְׁרִים קְשָׁרִים, וְהַהֵיכָל נוֹסֵעַ לְהִתְעַטֵּר. כֻּלָּם יוֹצְאִים מְלֵאִים בְּדִין, וְנִקְרָאִם מַחֲזִיקֵי מָגִנִּים. שְׁלוּחִים בָּעוֹלָם מִתּוֹךְ בַּעֲלֵי הַדִּין שֶׁבַּהֵיכָל הָרְבִיעִי. בְּמָקוֹם זֶה תְּלוּיִים בְּאַרְבָּעָה צְדָדִים שֵׁשׁ מֵאוֹת אֶלֶף רִבּוֹא מָגִנִּים שֶׁל זָהָב לְכָל צַד וְצַד. וְכֵן לְמַטָּה מֵהֶם חוֹמוֹת מַקִּיפוֹת, וְהֵם שִׁשִּׁים.</p>\n<p>וְכָל הַמָּגִנִּים הַלָּלוּ נִלְחָמִים קְרָבוֹת בַּחֲרָבוֹת וּרְמָחִים, פְּרָט לְכָל אוֹתָם שְׁלוּחֵי הַדִּין שֶׁל הָעוֹלָם, עַד שֶׁמַּגִּיעִים דְּרָגוֹת בִּדְרָגוֹת לְכוֹכָב מַאְדִּים. וְאָז הַהֵיכָל עוֹלֶה וּמִתְעַטֵּר בְּאוֹתָהּ רוּחַ בְּכָל אוֹתָם צְבָאוֹת, וְנִשְׁאָר אוֹתוֹ מָקוֹם בִּמְקוֹמוֹ. וְאוֹתוֹ מָקוֹם נִקְרָא תָּא הָרָצִים. אוֹתָם הַשְּׁלוּחִים רָצִים לְהַשְׁלִים דִּינִים וּפֻרְעָנֻיּוֹת בְּכָל צִדְדֵי הָעוֹלָם.</p>\n<p>כְּשֶׁעוֹלָה תְפִלָּה, נוֹשֵׂאת כָּל הַמְּאוֹרוֹת הַלָּלוּ וְהַמַּחֲנוֹת, וְקוֹשֶׁרֶת קְשָׁרִים וְנִכְלָלִים כֻּלָּם כְּאֶחָד, עַד שֶׁנִּקְשָׁר רוּחַ בְּרוּחַ וְהֵם אֶחָד. וְנִכְנָסִים לְתוֹךְ אוֹתוֹ עַמּוּד לְהִכָּלֵל בָּרוּחַ שֶׁל הַהֵיכָל הָרְבִיעִי. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁיּוֹדֵעַ סוֹד רִבּוֹנוֹ וּמֵרִים דִּגְלוֹ בְּמָקוֹם שֶׁצָּרִיךְ.</p>\n<p>וּבֹא וּרְאֵה, הַכֹּל צָרִיךְ זֶה לָזֶה וְזֶה לָזֶה לְהַשְׁלִים זֶה עִם זֶה וּלְהָאִיר זֶה בָּזֶה, עַד שֶׁעוֹלֶה הַכֹּל לְמָקוֹם שֶׁצָּרִיךְ שְׁלֵמוּת. מִלְּמַטָּה בַּהַתְחָלָה, וְאַחַר כָּךְ מִלְמַעְלָה, וְאָז הַשְּׁלֵמוּת הִיא בְּכָל הַצְּדָדִים וְנִשְׁלָם הַכֹּל כָּרָאוּי.</p>\n<p>מִי שֶׁיּוֹדֵעַ הַסּוֹדוֹת הַלָּלוּ וְעוֹשֶׂה שְׁלֵמוּת, זֶהוּ שֶׁמִּתְדַּבֵּק בְּרִבּוֹנוֹ וּמְבַטֵּל כָּל הַגְּזֵרוֹת הַקָּשׁוֹת, וְהוּא מְעַטֵּר אֶת רִבּוֹנוֹ וּמוֹשֵׁךְ בְּרָכוֹת עַל הָעוֹלָם. וְזֶהוּ אָדָם שֶׁנִּקְרָא צַדִּיק עַמּוּד הָעוֹלָם, וּתְפִלָּתוֹ לֹא חוֹזֶרֶת רֵיקָם, וְחֶלְקוֹ בָּעוֹלָם הַבָּא, וְהוּא בְּחֶשְׁבּוֹן בְּנֵי הָאֱמוּנָה.</p>\n<p>בֹּא רְאֵה, כָּל הַהֵיכָלוֹת הַלָּלוּ וְכָל הַחַיּוֹת הַלָּלוּ וְכָל הַצְּבָאוֹת הַלָּלוּ וְכָל הָאוֹרוֹת הַלָּלוּ וְכָל הָרוּחוֹת הַלָּלוּ צְרִיכִים זֶה לָזֶה, כְּדֵי לְהִשְׁתַּלֵּם מִלְּמַטָּה וּלְהִשְׁתַּלֵּם אַחַר כָּךְ מִלְמַעְלָה. הַהֵיכָלוֹת הַלָּלוּ הֵם מִתְדַּבְּקִים זֶה בָּזֶה.</p>\n<p>וְכֻלָּם כְּמוֹ הַגְּוָנִים שֶׁלְּמַעְלָה (של העין) דְּבוּקִים זֶה עִם זֶה. כָּל מַה שֶּׁבְּתוֹכָם הֵם כְּאוֹתוֹ מַרְאֶה שֶׁנִּרְאֶה בַּסֵּתֶר כְּשֶׁמִּתְגַּלְגֶּלֶת הָעַיִן וְנִרְאֶה אוֹתוֹ זֹהַר נוֹצֵץ. וְאוֹתוֹ מַה שֶּׁלֹּא נִרְאֶה בְּאוֹתוֹ גִלְגּוּל, הוּא אוֹתָהּ רוּחַ שֶׁשּׁוֹלֶטֶת עַל הַכֹּל. וְלָכֵן עוֹמֵד זֶה בָּזֶה דְּרָגוֹת עַל דְּרָגוֹת עַד שֶׁמִּתְעַטֵּר הַכֹּל כָּרָאוּי.</p>\n<p>וּבֹא וּרְאֵה, אִלְמָלֵא כָּל אוֹתָם גְּוָנִים שֶׁל הָעַיִן שֶׁנִּרְאִים, כְּשֶׁנִּסְתֶּמֶת הָעַיִן וּמִתְגַּלְגֶּלֶת בְּגַלְגַּל, לֹא נִרְאִים אוֹתָם הַגְּוָנִים שֶׁזּוֹהֲרִים, וְאִלְמָלֵא אוֹתָם גְּוָנִים לֹא נִדְבָּק אוֹתוֹ הַנִּסְתָּר שֶׁשּׁוֹלֵט עֲלֵיהֶם. נִמְצָא שֶׁהַכֹּל תָּלוּי זֶה בָּזֶה וְנִקְשָׁר זֶה בָּזֶה</p>\n<p>כְּשֶׁנִּכְלָל הַכֹּל כְּאֶחָד בַּהֵיכָל הַשְּׁלִישִׁי. וּרְצוֹן הַתְּפִלָּה עוֹלֶה לְהִתְעַטֵּר בַּהֵיכָל הָרְבִיעִי. וְאָז הַכֹּל אֶחָד וְרָצוֹן אֶחָד וְקֶשֶׁר אֶחָד. כָּאן הִשְׁתַּחֲוָאָה לְהִתְרַצּוֹת לְרִבּוֹנוֹ.</p>"],[9522011101,"<p>הֵיכָל הָרְבִיעִי. הֵיכָל זֶה הוּא מְשֻׁנֶּה מִכֻּלָּם. אַרְבָּעָה הֵיכָלוֹת לָזֶה, זֶה לִפְנִים מִזֶּה, וְכֻלָּם הֵיכָל אֶחָד. כָּאן הוּא רוּחַ שֶׁנִּקְרָא זְכוּת. בְּמָקוֹם זֶה מִתְהַפֵּךְ הַזְּכוּת שֶׁל כָּל הָעוֹלָם. רוּחַ זוֹ נוֹשֵׂאת הַכֹּל.</p>\n<p>מִמֶּנָּה יוֹצְאִים שִׁבְעִים אוֹרוֹת כֻּלָּם נוֹצְצִים. וְכֻלָּם בְּעִגּוּל שֶׁלֹּא מִתְפַּשְּׁטִים כְּמוֹ הָאֲחֵרִים הַלָּלוּ. מִתְדַּבְּקִים זֶה בָּזֶה וּמְאִירִים זֶה בָּזֶה, אֲחוּזִים זֶה בָּזֶה. כָּל זְכֻיּוֹת הָעוֹלָם עוֹמְדוֹת לִפְנֵי הַמְּאוֹרוֹת הַלָּלוּ. מִכֻּלָּם יוֹצְאִים שְׁנֵי מְאוֹרוֹת שְׁקוּלִים כְּאֶחָד שֶׁעוֹמְדִים לִפְנֵיהֶם תָּמִיד.</p>\n<p>כְּנֶגֶד אֵלֶּה שִׁבְעִים מְמֻנִּים גְּדוֹלִים שֶׁבַּחוּץ שֶׁסּוֹבְבִים אֶת כָּל אַרְבַּעַת הַהֵיכָלוֹת הַלָּלוּ. שִׁבְעִים אוֹרוֹת אֵלּוּ וּשְׁנֵי אוֹרוֹת שֶׁעוֹמְדִים לִפְנֵיהֶם, כֻּלָּם פְּנִימִיִּים לִפְנִים וְלִפְנִים, וְזֶה סוֹד הַכָּתוּב (שיר ז) בִּטְנֵךְ עֲרֵמַת חִטִּים סוּגָה בַּשּׁוֹשַׁנִּים.</p>\n<p>לִפְנֵי הָאוֹרוֹת הַלָּלוּ נִכְנָסִים כָּל הַזְּכֻיּוֹת וְעַל כָּל מַעֲשֵׂי הָעוֹלָם לְהִדּוֹן. שְׁנֵי הָאוֹרוֹת הַלָּלוּ מְעִידִים עֵדוּת, מִשּׁוּם (שהם) שֶׁיֵּשׁ שֶׁבַע עֵינֵי ה' שֶׁמְּשׁוֹטְטִים בְּכָל הָאָרֶץ, (כן כל) וְכָל מַה שֶּׁנַּעֲשֶׂה בָּעוֹלָם נִרְשָׁם בְּאוֹתוֹ מַעֲשֶׂה מַמָּשׁ וְאוֹתָהּ זְכוּת מַמָּשׁ וְעוֹמְדִים בְּקִיּוּמָם. וּשְׁנֵי הָאוֹרוֹת הַלָּלוּ רוֹאִים בָּהֶם וּמִסְתַּכְּלִים וּמְעִידִים לִפְנֵי שִׁבְעִים אוֹרוֹת הָאֵלֶּה. אֵלֶּה שִׁבְעִים גּוֹזְרֵי גְזֵרוֹת וְדָנִים דִּינִים, הֵן לְטוֹב הֵן לְרַע. וְכָאן הוּא מְקוֹם הַזְּכוּת.</p>\n<p>רוּחַ זוֹ בָּהּ נִרְשְׁמוּ שָׁלֹשׁ אוֹתִיּוֹת שֶׁהֵם יה\"ו. שֶׁכְּשֶׁהָאוֹתִיּוֹת הַלָּלוּ נִדְבָּקוֹת בַּמָּקוֹם הַזֶּה בְּהִדָּבְקוּת שֶׁל זָכָר וּנְקֵבָה, אָז נִרְשָׁמִים בּוֹ וְלֹא מִסְתַּלְּקִים מִשָּׁם. אַחַר כָּךְ יוֹצֵא אוֹר אֶחָד שֶׁמֵּאִיר לְאַרְבָּעָה צְדָדִים. הָאוֹר הַזֶּה מוֹצִיא שְׁלֹשָׁה אֲחֵרִים שֶׁהֵם שְׁלֹשָׁה בָּתֵּי דִין שֶׁדָּנִים דִּינִים אֲחֵרִים בְּדִבְרֵי הָעוֹלָם - בְּעֹשֶׁר, בְּעֹנִי, בְּמַחֲלוֹת, בִּשְׁלֵמוּת בְּכָל אוֹתָם שְׁאָר דְּבָרִים שֶׁהָעוֹלָם נִדּוֹן בָּהֶם. הֵיכָל אֶחָד לְאוֹתָם שִׁבְעִים רִאשׁוֹנִים לֵפְנִים. שְׁלֹשָׁה לְאוֹתָם שְׁלֹשָׁה הָאֲחֵרִים.</p>\n<p>עוֹלָה הָרוּחַ הַזּוֹ וְכוֹלֶלֶת כָּל אֵלּוּ שֶׁלְּמַטָּה, וּמוֹצִיאָה חַיָּה קְדוֹשָׁה אַחַת מִתְלַהֶטֶת, וְיֵשׁ לָהּ עֵינַיִם כְּמוֹ עֵינֵי אָדָם לְהַשְׁגִּיחַ בְּאֶלֶף אֲלָפִים וְרִבּוֹא רִבְבוֹת צְבָאוֹת בַּעֲלֵי הַדִּין. כֻּלָּם לוֹקְחִים פְּתָקִים וּפוֹתְחִים וְסוֹגְרִים בָּעוֹלָם וּמַשְׁלִימִים דִּין.</p>\n<p>תַּחַת הַחַיָּה הַזּוֹ אַרְבָּעָה שְׂרָפִים לוֹהֲטִים, כֻּלָּם כְּכַפְתּוֹר וָפֶרַח וּשְׁבִיבֵי אֵשׁ. עוֹלִים שִׁבְעִים וּשְׁנַיִם גַּלְגַּלִּים לְכָל אֶחָד מְלֹהָטִים בְּאֵשׁ. כְּשֶׁנּוֹסְעִים, נַעֲשֶׂה נָהָר אֶחָד שֶׁל אֵשׁ. אֶלֶף אֲלָפִים מְשַׁמְּשִׁים לְאוֹתָהּ הָאֵשׁ, וּמִשָּׁם יוֹצְאִים כַּמָּה צְבָאוֹת. כְּשֶׁהַגַּלְגַּלִּים נוֹסְעִים, כַּמָּה הֵם רִבּוֹא רְבָבוֹת שֶׁיַּעַמְדוּ מֵהֶם בְּתוֹךְ אוֹתָהּ הָאֵשׁ. תַּחַת הַהֵיכָל הַשֵּׁנִי יוֹצְאִים צְבָאוֹת שֶׁמְּזַמְּרִים וּבָאִים לְהִתְקָרֵב כָּאן וְכֻלָּם נִשְׂרָפִים.</p>\n<p>כָּל אוֹתָם מְמֻנֵּי הָעוֹלָם שֶׁהִתְמַנּוּ לִשְׁלֹט, מִכָּאן יוֹצֵא דִינָם לִשְׁלֹט מִתּוֹךְ אוֹתָהּ הָרוּחַ שֶׁנִּרְשְׁמָה בְּשָׁלֹשׁ אוֹתִיּוֹת. וּמִכָּאן מַעֲבִירִים קִיּוּמָם מֵהָעוֹלָם וְנִדּוֹנִים בָּאֵשׁ הַזּוֹ שֶׁשּׁוֹפַעַת וְיוֹצֵאת. הַכֹּל נִמְסָר בַּהֵיכָל הַזֶּה. מִשּׁוּם שֶׁנִּרְשְׁמוּ בְּשָׁלֹשׁ אוֹתִיּוֹת כָּאן, הָרוּחַ הַזּוֹ נִכְלֶלֶת בָּהֶם. אוֹתָהּ הַחַיָּה מוֹצִיאָה צְבָאוֹת וּמַחֲנוֹת שֶׁאֵין לָהֶם חֶשְׁבּוֹן.</p>\n<p>כָּל דִּינֵי הָעוֹלָם יוֹצְאִים מֵהַהֵיכָל הַזֶּה, הֵן טוֹב וְהֵן לְרַע, פְּרָט לִשְׁלֹשָׁה - בָּנִים, חַיִּים וּמְזוֹנוֹת, שֶׁלֹּא נִתְּנָה רְשׁוּת בַּמָּקוֹם הַזֶּה. שֶׁהֲרֵי בְּאוֹתוֹ נָהָר עֶלְיוֹן שֶׁכָּל הָאוֹרוֹת שׁוֹפְעִים מִמֶּנּוּ הַדָּבָר עוֹמֵד. בְּאֶמְצַע הַהֵיכָל הַזֶּה הוּא מָקוֹם מְתֻקָּן כְּנֶגֶד הָרוּחַ שֶׁלְּמַעְלָה בְּתוֹךְ הָרוּחַ הַזּוֹ, וְזוֹ עוֹלָה בָהֶם.</p>\n<p>שְׁנֵים עָשָׂר פְּתָחִים הֵם לַהֵיכָל הַזֶּה. בְּכָל פֶּתַח וּפֶתַח כָּל אוֹתָם שָׂרִים וּמְמֻנִּים שֶׁמַּכְרִיזִים לְהוֹדִיעַ לְמַטָּה כָּל אוֹתָם הַדִּינִים הָעֲתִידִים לָרֶדֶת לְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (דניאל ד) קוֹרֵא בְחַיִל וְכֵן אוֹמֵר קַצְּצוּ הָאִילָן.</p>\n<p>וּמִתּוֹךָ הַכְּרוּזִים הַלָּלוּ לוֹקְחִים דָּבָר כָּל בַּעֲלֵי הַכְּנָפַיִם, עַד שֶׁמּוֹדִיעִים הַדָּבָר לָרָקִיעַ שֶׁל חַמָּה. וּמִשָּׁם, כְּשֶׁיּוֹצֵאת הַשֶּׁמֶשׁ, יוֹצֵא דָבָר וּמְשׁוֹטֵט בָּעוֹלָם עַד שֶׁמַּגִּיעַ לְאוֹתוֹ הַנָּחָשׁ שֶׁל הָרָקִיעַ שֶׁכָּל כּוֹכְבֵי הָרָקִיעַ קְפוּאִים בּוֹ, שֶׁהוּא בְּאֶמְצַע הָרָקִיעַ.</p>\n<p>וְשׁוֹמְעִים הַדָּבָר, וְלוֹקְחִים אוֹתוֹ הַשָּׂרִים שֶׁתַּחַת (השמים) הַשֶּׁמֶשׁ, וְאוֹתָם שֶׁמְּמֻנִּים עַל אוֹתוֹ הַנָּחָשׁ, וּמִשָּׁם זֶה מִתְפַּשֵּׁט לָעוֹלָם. וַאֲפִלּוּ רוּחוֹת וְשֵׁדִים וַאֲפִלּוּ עוֹפוֹת הַשָּׁמַיִם מוֹדִיעִים אוֹתוֹ בָּעוֹלָם. הַכְּרוּזִים שָׁבִים וְסוֹתְמִים פְּתָחִים. לֹא עוֹלָה (להסתלק) רוּחַ בְּרוּחַ עַד שֶׁכָּל הָרוּחוֹת הַתַּחְתּוֹנוֹת כֻּלָּם אֶחָד יַחַד עִם (הרוח אחרי) הָרוּחַ הַזּוֹ, וְכֻלָּם נִכְלָלִים וְנִכְנָסִים זֶה בָּזֶה עַד שֶׁנַּעֲשָׂה הַכֹּל אֶחָד.</p>\n<p>כְּשֶׁבֶּן אָדָם נִמְצָא בְּבֵית חָלְיוֹ, כָּאן נִדּוֹן הֵן לְחַיִּים הֵן לְמָוֶת. הַחַיִּים תְּלוּיִים לְמַעְלָה. אִם נִדּוֹן כָּאן לְחַיִּים - נוֹתְנִים חַיִּים מִלְמַעְלָה. וְאִם לֹא - אָז לֹא נוֹתְנִים. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁנִּדְבָּק בְּרִבּוֹנוֹ וְנִכְנָס וְיוֹצֵא. כָּאן קִידָה עַל אַפַּיִם בָּאָרֶץ לְהִתְגַּבֵּר עַל הַדִּין. עַל הַהֵיכָל הַזֶּה נֶאֱמַר (דברים לב) אֵל אֱמוּנָה וְאֵין עָוֶל וְגוֹ'.</p>"],[9522011102,"<p>הֵיכָל הַחֲמִישִׁי. הֵיכָל זֶה הֵיכַל הַבָּרָק שֶׁזּוֹהֵר, שֶׁהוּא רוּחַ שֶׁמַּזְהִיר וּמֵאִיר לְאוֹתָם הַתַּחְתּוֹנִים. רוּחַ זוֹ הִיא כְּלוּלָה וּפוֹתַחַת וְסוֹגֶרֶת, מְאִירָה וְנוֹצֶצֶת לְכָל הַצְּדָדִים. מִנִּצְנוּץ זֶה מֵאִיר אוֹר אֶחָד כְּעֵין הָאַרְגָּמָן. הָאוֹר הַזֶּה כּוֹלֵל כָּל (כלל) הַגְּוָנִים שֶׁמְּאִירִים. אוֹר לָבָן וְשָׁחֹר, אָדֹם וְיָרֹק. נִכְלָלִים אֵלֶּה בְּאֵלֶּה. נִרְקָם לָבָן בְּאָדם, שָׁחֹר בְּיָרֹק. אַחַר כָּךְ לָבָן בְּשָׁחֹר. וְנַעֲשֵׂית חַיָּה אַחַת מְרֻקֶּמֶת, וְנִכְלָל בָּהּ יָרֹק וְאָדם. דְּמוּתָהּ כִּדְמוּת אָדָם שֶׁכּוֹלֵל כָּל הַדְּמֻיּוֹת.</p>\n<p>מִמֶּנָּה יָצְאוּ אַרְבָּעָה עַמּוּדִים שֶׁהֵם חַיּוֹת גְּדוֹלוֹת עַל אֵלֶּה שֶׁלְּמַטָּה. אֶחָד נִקְרָא אוֹפַן שֶׁהוּא שְׁנַיִם. מִשּׁוּם שֶׁכְּשֶׁנִּרְאֶה זֶה, מֵאִיר אַחֵר בְּתוֹכוֹ. דָּבוּק זֶה בָּזֶה. נִכְנָס זֶה בָּזֶה. אַחַר כָּךְ נִכְנָס אַחֵר זֶה בָּזֶה, וְנִרְאִים אַרְבָּעָה רָאשִׁים לְאַרְבָּעָה רוּחוֹת הָעוֹלָם, וְכֻלָּם גּוּף אֶחָד. וְאֵלֶּה הֵם שֶׁכָּתוּב בָּהֶם (יחזקאל א) כַּאֲשֶׁר יִהְיֶה הָאוֹפַן בְּתוֹךְ הָאוֹפָן. וְכָל אֵלֶּה קְשׁוּרִים זֶה בָּזֶה, כְּמַרְאֵה הַחַיּוֹת הָעֶלְיוֹנוֹת שֶׁלֹּא נִפְרָדוֹת לְעוֹלָמִים. הַחַיָּה הַזּוֹ שֶׁל אַרְבָּעָה גְוָנִים מְרֻקָּמִים אֲחוּזִים אֵלֶּה בְאֵלֶּה לְאַרְבָּעָה רוּחוֹת. מִכָּאן שֶׁכְּשֶׁנּוֹסַעַת הַחַיָּה הַזּוֹ, הִיא נוֹסַעַת לִשְׁנֵי רוּחוֹת.</p>\n<p>הָרוּחַ הַזּוֹ שֶׁל הַבָּרָק נִכְלֶלֶת בִּשְׁתֵּי רוּחוֹת. רוּחַ זוֹ שֶׁל הַבָּרָק מוֹצִיאָה חַיָּה אַחַת וְכָל אוֹתָם הָאוֹרוֹת. רוּחַ אַחֶרֶת מְאִירָה מִמֶּנָּה, שֶׁנִּקְרֵאת רוּחַ מְלַהֶטֶת,</p>\n<p>מְאִירִים מִמֶּנָּה שְׁנֵי אוֹרוֹת שֶׁהֵם אַרְבָּעָה. וְהָאוֹרוֹת הַלָּלוּ מִתְהַפְּכִים בִּגְוָנִים. וְכָאן הוּא (בראשית ג) לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת. אֵלּוּ אוֹתָם מְאוֹרוֹת שֶׁמְּהַפְּכִים שְׁנִינוּת הַחֶרֶב, (ואלה חוקקים) וְאֵלֶּה עוֹמְדִים עַל הַהֵיכָל שֶׁלְּמַטָּה, מִשּׁוּם שֶׁלַּהַט הַחֶרֶב הַזֹּאת עוֹמֶדֶת עַל אוֹתָם שִׁבְעִים אוֹרוֹת שֶׁל בֵּית הַדִּין. מִכָּאן, כָּל אוֹתָם דַּיָּנִים שֶׁדָּנִים דִּין, חֶרֶב תְּלוּיָה עַל רֹאשָׁם מִלְמַעְלָה.</p>\n<p>לַהַט הַחֶרֶב הַזּוֹ שֶׁל אֵלֶּה הֵם אוֹתָם אוֹרוֹת שֶׁלְּצַד שְׂמֹאל הוֹצִיאוּ חַיָּה אַחַת אַחֶרֶת שֶׁעוֹמֶדֶת עַל אַרְבַּע שֶׁלֹּא עוֹמְדִים בְּקִיּוּמָם, שְׁנַיִם מִיָּמִין וּשְׁנַיִם מִשְּׂמֹאל. כְּשֶׁרוּחַ הַחַיָּה הַזּוֹ נִכְנֶסֶת בְּאֵלֶּה, נוֹצֵץ מֵהֶם שְׁנֵי נִיצוֹצוֹת לוֹהֲטִים, וְיוֹצְאִים מֵהַהֵיכָל הַזֶּה הַחוּצָה וּמִתְהַפְּכִים תָּמִיד. הַנִּיצוֹצוֹת הַלָּלוּ לוֹהֲטִים. לִפְעָמִים נְקֵבוֹת לִפְעָמִים זְכָרִים. לִפְעָמִים רוּחוֹת וְלִפְעָמִים מַלְאָכִים קְדוֹשִׁים.</p>\n<p>מָה הַטַּעַם? מִשּׁוּם שֶׁכְּשֶׁנִּכְלֶלֶת הַחַיָּה הַזּוֹ בַּחַיָּה הָרִאשׁוֹנָה, מִתּוֹךְ הַחֹזֶק שֶׁנִּכְלָלִים זֶה בָּזֶה יוֹצֵא נִיצוֹץ אֶחָד לוֹהֵט תָּמִיד שֶׁלֹּא דוֹעֵךְ לְעוֹלָמִים, וְשָׁט וְהוֹלֵךְ אַחֲרֵיהֶם שֶׁל אוֹתָם שְׁנֵי נִיצוֹצוֹת.</p>\n<p>וְעַכְשָׁו הֵם זְכָרִים וְעוֹשִׂים שְׁלִיחוּת בָּעוֹלָם. וְעַד שֶׁלֹּא מְסַיְּמִים, מִתְדַּעֲכִים (אז), וְהַנִּיצוֹץ הַזֶּה מַכֶּה בָהֶם וּמֵאִיר לָהֶם, וּמִתְחַדְּשִׁים כְּמִקֹּדֶם, וְהֵם נְקֵבוֹת, וְהוֹלְכוֹת וּמְשׁוֹטְטוֹת. וְטֶרֶם שֶׁמְּסַיְּמוֹת הֵן דּוֹעֲכוֹת. וְנִיצוֹץ זֶה מַכֶּה בָהֶם וּמֵאִיר לָהֶם וְחוֹזְרִים כְּמִקֹּדֶם, מִשּׁוּם שֶׁאוֹתוֹ נִיצוֹץ כָּלוּל מֵהַכֹּל, כָּלוּל מֵאַרְבָּעָה גְוָנִים, וְלָכֵן הֵם מִתְהַפְּכִים לְכָל הַגְּוָנִים הַלָּלוּ.</p>\n<p>רוּחַ זֶה נִכְלָל בְּרוּחַ אַחֵר, כְּמוֹ שֶׁאָמַרְנוּ, וְנִרְאִים שְׁנַיִם כְּאֶחָד, וְלֹא כָּאֲחֵרִים הָרִאשׁוֹנִים שֶׁכְּשֶׁנִּכְלָלִים זֶה בָּזֶה לֹא נִרְאִים פְּרָט לְאֶחָד. וְכָאן נִרְאִים שְׁנַיִם, וְעוֹמְדִים בַּחֲבִיבוּת כְּלוּלִים מִכָּל הַתַּחְתּוֹנִים. וְאַף עַל גַּב שֶׁהֵם שְׁנַיִם, הֵם אֶחָד. כַּאֲשֶׁר מִתְפַּשֵּׁט (פרט כשהתפשטו) רוּחַ בְּרוּחַ וְנִרְאִים בַּחֲבִיבוּת כְּלוּלִים מִכָּל הַתַּחְתּוֹנִים, וְזֶהוּ (וזה) סוֹד שֶׁכָּתוּב (שיר ד) שְׁנֵי שָׁדַיִךְ כִּשְׁנֵי עֳפָרִים תְּאוֹמֵי צְבִיָּה הָרֹעִים בַּשּׁוֹשַׁנִּים.</p>\n<p>וּכְשֶׁשְּׁנֵי רוּחוֹת מִתְפַּשְּׁטִים זֶה בָּזֶה בַּחֲבִיבוּת, אָז חוֹזֵר הֵיכָל זֶה וְנִקְרָא הֵיכַל אַהֲבָה, הֵיכַל הָאַהֲבָה. הֵיכָל זֶה עוֹמֵד תָּמִיד בְּקִיּוּמוֹ, וְנִגְנַז בְּסוֹד הַסּוֹדוֹת לְמִי שֶׁצָּרִיךְ לְהִתְדַּבֵּק בּוֹ. וְכָאן כָּתוּב (שם ז) אֶתֵּן אֶת דֹּדַי לָךְ.</p>\n<p>אַחַר כָּךְ, כַּאֲשֶׁר מְאִירִים שְׁנֵי רוּחוֹת שֶׁהֵם אֶחָד, יוֹצְאִים כַּמָּה צְבָאוֹת לְכַמָּה רוּחוֹת, אֲלָפִים וּרְבָבוֹת שֶׁאֵין לָהֶם שִׁעוּר. מֵהֶם נִקְרָאִים דּוּדָאִים, מֵהֶם גְּפָנִים, מֵהֶם רִמּוֹנִים, עַד שֶׁמַּגִּיעִים כַּמָּה צְבָאוֹת הַחוּצָה עַד אוֹתוֹ כּוֹכָב שֶׁנִּקְרָא נֹגַהּ. וְכֻלָּם בַּחֲבִיבוּת שֶׁלֹּא נִפְרָדִים לְעוֹלָמִים. וְכָאן כָּתוּב (שם ח) אִם יִתֵּן אִישׁ אֶת כָּל הוֹן בֵּיתוֹ בָּאַהֲבָה בּוֹז יָבוּזוּ לוֹ. כָּאן (כתוב) הִשְׁתַּחֲוָאָה וּפְרִישַׂת יָדַיִם לְהִתְדַּבֵּק בְּאַהֲבַת רִבּוֹנוֹ.</p>"]]});
